window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JOS"]={"book":"JOS","editions":{"hbo-source":[[1,1,"וַ⁠יְהִ֗י אַחֲרֵ֛י מ֥וֹת מֹשֶׁ֖ה עֶ֣בֶד יְהוָ֑ה וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־יְהוֹשֻׁ֣עַ בִּן־נ֔וּן מְשָׁרֵ֥ת מֹשֶׁ֖ה לֵ⁠אמֹֽר׃","wa⁠yĕhi֗y ʼaẖàré֛y m֥wòţ mòşě֖h ʻe֣bed yĕhwá֑h wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-yĕhwòşǔ֣ʻa bi̇n-n֔ẇn mĕşá̌ré֥ţ mòşě֖h lé⁠ʼmòֽr׃"],[1,2,"מֹשֶׁ֥ה עַבְדִּ֖⁠י מֵ֑ת וְ⁠עַתָּה֩ ק֨וּם עֲבֹ֜ר אֶת־הַ⁠יַּרְדֵּ֣ן הַ⁠זֶּ֗ה אַתָּה֙ וְ⁠כָל־הָ⁠עָ֣ם הַ⁠זֶּ֔ה אֶל־הָ⁠אָ֕רֶץ אֲשֶׁ֧ר אָנֹכִ֛י נֹתֵ֥ן לָ⁠הֶ֖ם לִ⁠בְנֵ֥י יִשְׂרָאֵֽל׃","mòşě֥h ʻabĕdi֖̇⁠y mé֑ţ wĕ⁠ʻaţá̇h֩ q֨ẇm ʻàbò֜r ʼeţ-ha⁠yȧrĕdé֣̇n ha⁠zė֗h ʼaţá̇h֙ wĕ⁠kál-há⁠ʻá֣m ha⁠zė֔h ʼel-há⁠ʼá֕reẕ ʼàşě֧r ʼánòki֛y nòţé֥n lá⁠he֖m li⁠bĕné֥y yişĕ̂ráʼéֽl׃"],[1,3,"כָּל־מָק֗וֹם אֲשֶׁ֨ר תִּדְרֹ֧ךְ כַּֽף־רַגְלְ⁠כֶ֛ם בּ֖⁠וֹ לָ⁠כֶ֣ם נְתַתִּ֑י⁠ו כַּ⁠אֲשֶׁ֥ר דִּבַּ֖רְתִּי אֶל־מֹשֶֽׁה׃","ká̇l-máq֗wòm ʼàşě֨r ţi̇dĕrò֧kĕ kȧֽp-ragĕlĕ⁠ke֛m ḃ֖⁠wò lá⁠ke֣m nĕţaţi֑̇y⁠w kȧ⁠ʼàşě֥r di̇bȧ֖rĕţi̇y ʼel-mòşěֽh׃"],[1,4,"מֵ⁠הַ⁠מִּדְבָּר֩ וְ⁠הַ⁠לְּבָנ֨וֹן הַ⁠זֶּ֜ה וְֽ⁠עַד־הַ⁠נָּהָ֧ר הַ⁠גָּד֣וֹל נְהַר־פְּרָ֗ת כֹּ֚ל אֶ֣רֶץ הַֽ⁠חִתִּ֔ים וְ⁠עַד־הַ⁠יָּ֥ם הַ⁠גָּד֖וֹל מְב֣וֹא הַ⁠שָּׁ֑מֶשׁ יִֽהְיֶ֖ה גְּבוּלְ⁠כֶֽם׃","mé⁠ha⁠mi̇dĕbá̇r֩ wĕ⁠ha⁠lĕ̇bán֨wòn ha⁠zė֜h wĕֽ⁠ʻad-ha⁠ná̇há֧r ha⁠gá̇d֣wòl nĕhar-pĕ̇rá֗ţ kò֚̇l ʼe֣reẕ haֽ⁠ẖiţi̇֔ym wĕ⁠ʻad-ha⁠yá֥̇m ha⁠gá̇d֖wòl mĕb֣wòʼ ha⁠şá֑̇̌meş̌ yiֽhĕye֖h gĕ̇bẇlĕ⁠keֽm׃"],[1,5,"לֹֽא־יִתְיַצֵּ֥ב אִישׁ֙ לְ⁠פָנֶ֔י⁠ךָ כֹּ֖ל יְמֵ֣י חַיֶּ֑י⁠ךָ כַּֽ⁠אֲשֶׁ֨ר הָיִ֤יתִי עִם־מֹשֶׁה֙ אֶהְיֶ֣ה עִמָּ֔⁠ךְ לֹ֥א אַרְפְּ⁠ךָ֖ וְ⁠לֹ֥א אֶעֶזְבֶֽ⁠ךָּ׃","lòֽʼ-yiţĕyaẕé֥̇b ʼiyş̌֙ lĕ⁠páne֔y⁠ká kò֖̇l yĕmé֣y ẖayė֑y⁠ká kֽ̇a⁠ʼàşě֨r háyi֤yţiy ʻim-mòşěh֙ ʼehĕye֣h ʻimá̇֔⁠kĕ lò֥ʼ ʼarĕpĕ̇⁠ká֖ wĕ⁠lò֥ʼ ʼeʻezĕbeֽ⁠ká̇׃"],[1,6,"חֲזַ֖ק וֶ⁠אֱמָ֑ץ כִּ֣י אַתָּ֗ה תַּנְחִיל֙ אֶת־הָ⁠עָ֣ם הַ⁠זֶּ֔ה אֶת־הָ⁠אָ֕רֶץ אֲשֶׁר־נִשְׁבַּ֥עְתִּי לַ⁠אֲבוֹתָ֖⁠ם לָ⁠תֵ֥ת לָ⁠הֶֽם׃","ẖàza֖q we⁠ʼèmá֑ẕ ki֣̇y ʼaţá̇֗h ţȧnĕẖiyl֙ ʼeţ-há⁠ʻá֣m ha⁠zė֔h ʼeţ-há⁠ʼá֕reẕ ʼàşěr-nişĕ̌bȧ֥ʻĕţi̇y la⁠ʼàbwòţá֖⁠m lá⁠ţé֥ţ lá⁠heֽm׃"],[1,7,"רַק֩ חֲזַ֨ק וֶֽ⁠אֱמַ֜ץ מְאֹ֗ד לִ⁠שְׁמֹ֤ר לַ⁠עֲשׂוֹת֙ כְּ⁠כָל־הַ⁠תּוֹרָ֗ה אֲשֶׁ֤ר צִוְּ⁠ךָ֙ מֹשֶׁ֣ה עַבְדִּ֔⁠י אַל־תָּס֥וּר מִמֶּ֖⁠נּוּ יָמִ֣ין וּ⁠שְׂמֹ֑אול לְמַ֣עַן תַּשְׂכִּ֔יל בְּ⁠כֹ֖ל אֲשֶׁ֥ר תֵּלֵֽךְ׃","raq֩ ẖàza֨q weֽ⁠ʼèma֜ẕ mĕʼò֗d li⁠şĕ̌mò֤r la⁠ʻàş̂wòţ֙ kĕ̇⁠kál-ha⁠ţ̇wòrá֗h ʼàşě֤r ẕiwĕ̇⁠ká֙ mòşě֣h ʻabĕdi̇֔⁠y ʼal-ţá̇s֥ẇr mimė֖⁠ṅẇ yámi֣yn ẇ⁠şĕ̂mò֑ʼwl lĕma֣ʻan ţȧşĕ̂ki̇֔yl bĕ̇⁠kò֖l ʼàşě֥r ţé̇léֽkĕ׃"],[1,8,"לֹֽא־יָמ֡וּשׁ סֵפֶר֩ הַ⁠תּוֹרָ֨ה הַ⁠זֶּ֜ה מִ⁠פִּ֗י⁠ךָ וְ⁠הָגִ֤יתָ בּ⁠וֹ֙ יוֹמָ֣ם וָ⁠לַ֔יְלָה לְמַ֨עַן֙ תִּשְׁמֹ֣ר לַ⁠עֲשׂ֔וֹת כְּ⁠כָל־הַ⁠כָּת֖וּב בּ֑⁠וֹ כִּי־אָ֛ז תַּצְלִ֥יחַ אֶת־דְּרָכֶ֖⁠ךָ וְ⁠אָ֥ז תַּשְׂכִּֽיל׃","lòֽʼ-yám֡ẇş̌ séper֩ ha⁠ţ̇wòrá֨h ha⁠zė֜h mi⁠pi̇֗y⁠ká wĕ⁠hági֤yţá ḃ⁠wò֙ ywòmá֣m wá⁠la֔yĕláh lĕma֨ʻan֙ ţi̇şĕ̌mò֣r la⁠ʻàş̂֔wòţ kĕ̇⁠kál-ha⁠ká̇ţ֖ẇb ḃ֑⁠wò ki̇y-ʼá֛z ţȧẕĕli֥yẖa ʼeţ-dĕ̇ráke֖⁠ká wĕ⁠ʼá֥z ţȧşĕ̂kiֽ̇yl׃"],[1,9,"הֲ⁠ל֤וֹא צִוִּיתִ֨י⁠ךָ֙ חֲזַ֣ק וֶ⁠אֱמָ֔ץ אַֽל־תַּעֲרֹ֖ץ וְ⁠אַל־תֵּחָ֑ת כִּ֤י עִמְּ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּ⁠כֹ֖ל אֲשֶׁ֥ר תֵּלֵֽךְ׃פ","hà⁠l֤wòʼ ẕiwi̇yţi֨y⁠ká֙ ẖàza֣q we⁠ʼèmá֔ẕ ʼaֽl-ţȧʻàrò֖ẕ wĕ⁠ʼal-ţé̇ẖá֑ţ ki֤̇y ʻimĕ̇⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇⁠kò֖l ʼàşě֥r ţé̇léֽkĕ׃p"],[1,10,"וַ⁠יְצַ֣ו יְהוֹשֻׁ֔עַ אֶת־שֹׁטְרֵ֥י הָ⁠עָ֖ם לֵ⁠אמֹֽר׃","wa⁠yĕẕa֣w yĕhwòşǔ֔ʻa ʼeţ-şò̌tĕré֥y há⁠ʻá֖m lé⁠ʼmòֽr׃"],[1,11,"עִבְר֣וּ ׀ בְּ⁠קֶ֣רֶב הַֽ⁠מַּחֲנֶ֗ה וְ⁠צַוּ֤וּ אֶת־הָ⁠עָם֙ לֵ⁠אמֹ֔ר הָכִ֥ינוּ לָ⁠כֶ֖ם צֵידָ֑ה כִּ֞י בְּ⁠ע֣וֹד ׀ שְׁלֹ֣שֶׁת יָמִ֗ים אַתֶּם֙ עֹֽבְרִים֙ אֶת־הַ⁠יַּרְדֵּ֣ן הַ⁠זֶּ֔ה לָ⁠בוֹא֙ לָ⁠רֶ֣שֶׁת אֶת־הָ⁠אָ֔רֶץ אֲשֶׁר֙ יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם נֹתֵ֥ן לָ⁠כֶ֖ם לְ⁠רִשְׁתָּֽ⁠הּ׃ס","ʻibĕr֣ẇ ׀ bĕ̇⁠qe֣reb haֽ⁠mȧẖàne֗h wĕ⁠ẕaẇ֤ẇ ʼeţ-há⁠ʻám֙ lé⁠ʼmò֔r háki֥ynẇ lá⁠ke֖m ẕéydá֑h ki̇֞y bĕ̇⁠ʻ֣wòd ׀ şĕ̌lò֣şěţ yámi֗ym ʼaţėm֙ ʻòֽbĕriym֙ ʼeţ-ha⁠yȧrĕdé֣̇n ha⁠zė֔h lá⁠bwòʼ֙ lá⁠re֣şěţ ʼeţ-há⁠ʼá֔reẕ ʼàşěr֙ yĕhwá֣h ʼèlòֽhéy⁠ke֔m nòţé֥n lá⁠ke֖m lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃s"],[1,12,"וְ⁠לָ⁠רֽאוּבֵנִי֙ וְ⁠לַ⁠גָּדִ֔י וְ⁠לַ⁠חֲצִ֖י שֵׁ֣בֶט הַֽ⁠מְנַשֶּׁ֑ה אָמַ֥ר יְהוֹשֻׁ֖עַ לֵ⁠אמֹֽר׃","wĕ⁠lá⁠rֽʼẇbéniy֙ wĕ⁠la⁠gá̇di֔y wĕ⁠la⁠ẖàẕi֖y şé֣̌bet haֽ⁠mĕnaşė֑̌h ʼáma֥r yĕhwòşǔ֖ʻa lé⁠ʼmòֽr׃"],[1,13,"זָכוֹר֙ אֶת־הַ⁠דָּבָ֔ר אֲשֶׁ֨ר צִוָּ֥ה אֶתְ⁠כֶ֛ם מֹשֶׁ֥ה עֶֽבֶד־יְהוָ֖ה לֵ⁠אמֹ֑ר יְהוָ֤ה אֱלֹהֵי⁠כֶם֙ מֵנִ֣יחַ לָ⁠כֶ֔ם וְ⁠נָתַ֥ן לָ⁠כֶ֖ם אֶת־הָ⁠אָ֥רֶץ הַ⁠זֹּֽאת׃","zákwòr֙ ʼeţ-ha⁠dá̇bá֔r ʼàşě֨r ẕiwá֥̇h ʼeţĕ⁠ke֛m mòşě֥h ʻeֽbed-yĕhwá֖h lé⁠ʼmò֑r yĕhwá֤h ʼèlòhéy⁠kem֙ méni֣yẖa lá⁠ke֔m wĕ⁠náţa֥n lá⁠ke֖m ʼeţ-há⁠ʼá֥reẕ ha⁠zòֽ̇ʼţ׃"],[1,14,"נְשֵׁי⁠כֶ֣ם טַפְּ⁠כֶם֮ וּ⁠מִקְנֵי⁠כֶם֒ יֵשְׁב֕וּ בָּ⁠אָ֕רֶץ אֲשֶׁ֨ר נָתַ֥ן לָ⁠כֶ֛ם מֹשֶׁ֖ה בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֑ן וְ⁠אַתֶּם֩ תַּעַבְר֨וּ חֲמֻשִׁ֜ים לִ⁠פְנֵ֣י אֲחֵי⁠כֶ֗ם כֹּ֚ל גִּבּוֹרֵ֣י הַ⁠חַ֔יִל וַ⁠עֲזַרְתֶּ֖ם אוֹתָֽ⁠ם׃","nĕşé̌y⁠ke֣m tapĕ̇⁠kem֮ ẇ⁠miqĕnéy⁠kem֒ yéşĕ̌b֕ẇ bá̇⁠ʼá֕reẕ ʼàşě֨r náţa֥n lá⁠ke֛m mòşě֖h bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé֑̇n wĕ⁠ʼaţėm֩ ţȧʻabĕr֨ẇ ẖàmuşǐ֜ym li⁠pĕné֣y ʼàẖéy⁠ke֗m kò֚̇l gi̇ḃwòré֣y ha⁠ẖa֔yil wa⁠ʻàzarĕţė֖m ʼwòţáֽ⁠m׃"],[1,15,"עַ֠ד אֲשֶׁר־יָנִ֨יחַ יְהוָ֥ה ׀ לַֽ⁠אֲחֵי⁠כֶם֮ כָּ⁠כֶם֒ וְ⁠יָרְשׁ֣וּ גַם־הֵ֔מָּה אֶת־הָ⁠אָ֕רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹֽהֵי⁠כֶ֖ם נֹתֵ֣ן לָ⁠הֶ֑ם וְ⁠שַׁבְתֶּ֞ם לְ⁠אֶ֤רֶץ יְרֻשַּׁתְ⁠כֶם֙ וִֽ⁠ירִשְׁתֶּ֣ם אוֹתָ֔⁠הּ אֲשֶׁ֣ר ׀ נָתַ֣ן לָ⁠כֶ֗ם מֹשֶׁה֙ עֶ֣בֶד יְהוָ֔ה בְּ⁠עֵ֥בֶר הַ⁠יַּרְדֵּ֖ן מִזְרַ֥ח הַ⁠שָּֽׁמֶשׁ׃","ʻa֠d ʼàşěr-yáni֨yẖa yĕhwá֥h ׀ lֽa⁠ʼàẖéy⁠kem֮ ká̇⁠kem֒ wĕ⁠yárĕş֣̌ẇ gam-hé֔má̇h ʼeţ-há⁠ʼá֕reẕ ʼàşěr-yĕhwá֥h ʼèlòֽhéy⁠ke֖m nòţé֣n lá⁠he֑m wĕ⁠şǎbĕţė֞m lĕ⁠ʼe֤reẕ yĕruşȧ̌ţĕ⁠kem֙ wiֽ⁠yrişĕ̌ţė֣m ʼwòţá֔⁠ḣ ʼàşě֣r ׀ náţa֣n lá⁠ke֗m mòşěh֙ ʻe֣bed yĕhwá֔h bĕ̇⁠ʻé֥ber ha⁠yȧrĕdé֖̇n mizĕra֥ẖ ha⁠şáֽ̇̌meş̌׃"],[1,16,"וַֽ⁠יַּעֲנ֔וּ אֶת־יְהוֹשֻׁ֖עַ לֵ⁠אמֹ֑ר כֹּ֤ל אֲשֶׁר־צִוִּיתָ֨⁠נוּ֙ נַֽעֲשֶׂ֔ה וְ⁠אֶֽל־כָּל־אֲשֶׁ֥ר תִּשְׁלָחֵ֖⁠נוּ נֵלֵֽךְ׃","waֽ⁠yȧʻàn֔ẇ ʼeţ-yĕhwòşǔ֖ʻa lé⁠ʼmò֑r kò֤̇l ʼàşěr-ẕiwi̇yţá֨⁠nẇ֙ nֽaʻàşê֔h wĕ⁠ʼeֽl-ká̇l-ʼàşě֥r ţi̇şĕ̌láẖé֖⁠nẇ néléֽkĕ׃"],[1,17,"כְּ⁠כֹ֤ל אֲשֶׁר־שָׁמַ֨עְנוּ֙ אֶל־מֹשֶׁ֔ה כֵּ֖ן נִשְׁמַ֣ע אֵלֶ֑י⁠ךָ רַ֠ק יִֽהְיֶ֞ה יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ עִמָּ֔⁠ךְ כַּ⁠אֲשֶׁ֥ר הָיָ֖ה עִם־מֹשֶֽׁה׃","kĕ̇⁠kò֤l ʼàşěr-şá̌ma֨ʻĕnẇ֙ ʼel-mòşě֔h ké֖̇n nişĕ̌ma֣ʻ ʼéle֑y⁠ká ra֠q yiֽhĕye֞h yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʻimá̇֔⁠kĕ kȧ⁠ʼàşě֥r háyá֖h ʻim-mòşěֽh׃"],[1,18,"כָּל־אִ֞ישׁ אֲשֶׁר־יַמְרֶ֣ה אֶת־פִּ֗י⁠ךָ וְ⁠לֹֽא־יִשְׁמַ֧ע אֶת־דְּבָרֶ֛י⁠ךָ לְ⁠כֹ֥ל אֲשֶׁר־תְּצַוֶּ֖⁠נּוּ יוּמָ֑ת רַ֖ק חֲזַ֥ק וֶ⁠אֱמָֽץ׃פ","ká̇l-ʼi֞yş̌ ʼàşěr-yamĕre֣h ʼeţ-pi̇֗y⁠ká wĕ⁠lòֽʼ-yişĕ̌ma֧ʻ ʼeţ-dĕ̇báre֛y⁠ká lĕ⁠kò֥l ʼàşěr-ţĕ̇ẕawė֖⁠ṅẇ yẇmá֑ţ ra֖q ẖàza֥q we⁠ʼèmáֽẕ׃p"],[2,1,"וַ⁠יִּשְׁלַ֣ח יְהוֹשֻׁ֣עַ־בִּן־נ֠וּן מִֽן־הַ⁠שִּׁטִּ֞ים שְׁנַֽיִם־אֲנָשִׁ֤ים מְרַגְּלִים֙ חֶ֣רֶשׁ לֵ⁠אמֹ֔ר לְכ֛וּ רְא֥וּ אֶת־הָ⁠אָ֖רֶץ וְ⁠אֶת־יְרִיח֑וֹ וַ⁠יֵּ֨לְכ֜וּ וַ֠⁠יָּבֹאוּ בֵּית־אִשָּׁ֥ה זוֹנָ֛ה וּ⁠שְׁמָ֥⁠הּ רָחָ֖ב וַ⁠יִּשְׁכְּבוּ־שָֽׁמָּ⁠ה׃","wa⁠yi̇şĕ̌la֣ẖ yĕhwòşǔ֣ʻa-bi̇n-n֠ẇn miֽn-ha⁠şi̇̌ti̇֞ym şĕ̌naֽyim-ʼànáşǐ֤ym mĕragĕ̇liym֙ ẖe֣reş̌ lé⁠ʼmò֔r lĕk֛ẇ rĕʼ֥ẇ ʼeţ-há⁠ʼá֖reẕ wĕ⁠ʼeţ-yĕriyẖ֑wò wa⁠yé̇֨lĕk֜ẇ wa֠⁠yá̇bòʼẇ bé̇yţ-ʼişá֥̇̌h zwòná֛h ẇ⁠şĕ̌má֥⁠ḣ ráẖá֖b wa⁠yi̇şĕ̌kĕ̇bẇ-şáֽ̌má̇⁠h׃"],[2,2,"וַ⁠יֵּ֣אָמַ֔ר לְ⁠מֶ֥לֶךְ יְרִיח֖וֹ לֵ⁠אמֹ֑ר הִנֵּ֣ה אֲ֠נָשִׁים בָּ֣אוּ הֵ֧נָּה הַ⁠לַּ֛יְלָה מִ⁠בְּנֵ֥י יִשְׂרָאֵ֖ל לַ⁠חְפֹּ֥ר אֶת־הָ⁠אָֽרֶץ׃","wa⁠yé֣̇ʼáma֔r lĕ⁠me֥lekĕ yĕriyẖ֖wò lé⁠ʼmò֑r hiné֣̇h ʼà֠náşǐym bá֣̇ʼẇ hé֧ná̇h ha⁠lȧ֛yĕláh mi⁠bĕ̇né֥y yişĕ̂ráʼé֖l la⁠ẖĕpò֥̇r ʼeţ-há⁠ʼáֽreẕ׃"],[2,3,"וַ⁠יִּשְׁלַח֙ מֶ֣לֶךְ יְרִיח֔וֹ אֶל־רָחָ֖ב לֵ⁠אמֹ֑ר ה֠וֹצִיאִי הָ⁠אֲנָשִׁ֨ים הַ⁠בָּאִ֤ים אֵלַ֨יִ⁠ךְ֙ אֲשֶׁר־בָּ֣אוּ לְ⁠בֵיתֵ֔⁠ךְ כִּ֛י לַ⁠חְפֹּ֥ר אֶת־כָּל־הָ⁠אָ֖רֶץ בָּֽאוּ׃","wa⁠yi̇şĕ̌laẖ֙ me֣lekĕ yĕriyẖ֔wò ʼel-ráẖá֖b lé⁠ʼmò֑r h֠wòẕiyʼiy há⁠ʼànáşǐ֨ym ha⁠bá̇ʼi֤ym ʼéla֨yi⁠kĕ֙ ʼàşěr-bá֣̇ʼẇ lĕ⁠béyţé֔⁠kĕ ki֛̇y la⁠ẖĕpò֥̇r ʼeţ-ká̇l-há⁠ʼá֖reẕ báֽ̇ʼẇ׃"],[2,4,"וַ⁠תִּקַּ֧ח הָֽ⁠אִשָּׁ֛ה אֶת־שְׁנֵ֥י הָ⁠אֲנָשִׁ֖ים וַֽ⁠תִּצְפְּנ֑⁠וֹ וַ⁠תֹּ֣אמֶר ׀ כֵּ֗ן בָּ֤אוּ אֵלַ⁠י֙ הָֽ⁠אֲנָשִׁ֔ים וְ⁠לֹ֥א יָדַ֖עְתִּי מֵ⁠אַ֥יִן הֵֽמָּה׃","wa⁠ţi̇qȧ֧ẖ hֽá⁠ʼişá֛̇̌h ʼeţ-şĕ̌né֥y há⁠ʼànáşǐ֖ym waֽ⁠ţi̇ẕĕpĕ̇n֑⁠wò wa⁠ţò֣̇ʼmer ׀ ké̇֗n bá֤̇ʼẇ ʼéla⁠y֙ hֽá⁠ʼànáşǐ֔ym wĕ⁠lò֥ʼ yáda֖ʻĕţi̇y mé⁠ʼa֥yin héֽmá̇h׃"],[2,5,"וַ⁠יְהִ֨י הַ⁠שַּׁ֜עַר לִ⁠סְגּ֗וֹר בַּ⁠חֹ֨שֶׁךְ֙ וְ⁠הָ⁠אֲנָשִׁ֣ים יָצָ֔אוּ לֹ֣א יָדַ֔עְתִּי אָ֥נָה הָלְכ֖וּ הָֽ⁠אֲנָשִׁ֑ים רִדְפ֥וּ מַהֵ֛ר אַחֲרֵי⁠הֶ֖ם כִּ֥י תַשִּׂיגֽוּ⁠ם׃","wa⁠yĕhi֨y ha⁠şȧ̌֜ʻar li⁠sĕġ֗wòr bȧ⁠ẖò֨şěkĕ֙ wĕ⁠há⁠ʼànáşǐ֣ym yáẕá֔ʼẇ lò֣ʼ yáda֔ʻĕţi̇y ʼá֥náh hálĕk֖ẇ hֽá⁠ʼànáşǐ֑ym ridĕp֥ẇ mahé֛r ʼaẖàréy⁠he֖m ki֥̇y ţaşi̇̂ygֽẇ⁠m׃"],[2,6,"וְ⁠הִ֖יא הֶעֱלָ֣תַ⁠ם הַ⁠גָּ֑גָ⁠ה וַֽ⁠תִּטְמְנֵ⁠ם֙ בְּ⁠פִשְׁתֵּ֣י הָ⁠עֵ֔ץ הָ⁠עֲרֻכ֥וֹת לָ֖⁠הּ עַל־הַ⁠גָּֽג׃","wĕ⁠hi֖yʼ heʻèlá֣ţa⁠m ha⁠gá֑̇gá⁠h waֽ⁠ţi̇tĕmĕné⁠m֙ bĕ̇⁠pişĕ̌ţé֣̇y há⁠ʻé֔ẕ há⁠ʻàruk֥wòţ lá֖⁠ḣ ʻal-ha⁠gáֽ̇g׃"],[2,7,"וְ⁠הָ⁠אֲנָשִׁ֗ים רָדְפ֤וּ אַֽחֲרֵי⁠הֶם֙ דֶּ֣רֶךְ הַ⁠יַּרְדֵּ֔ן עַ֖ל הַֽ⁠מַּעְבְּר֑וֹת וְ⁠הַ⁠שַּׁ֣עַר סָגָ֔רוּ אַחֲרֵ֕י כַּ⁠אֲשֶׁ֛ר יָצְא֥וּ הָ⁠רֹדְפִ֖ים אַחֲרֵי⁠הֶֽם׃","wĕ⁠há⁠ʼànáşǐ֗ym rádĕp֤ẇ ʼֽaẖàréy⁠hem֙ dė֣rekĕ ha⁠yȧrĕdé̇֔n ʻa֖l haֽ⁠mȧʻĕbĕ̇r֑wòţ wĕ⁠ha⁠şȧ֣̌ʻar ságá֔rẇ ʼaẖàré֕y kȧ⁠ʼàşě֛r yáẕĕʼ֥ẇ há⁠ròdĕpi֖ym ʼaẖàréy⁠heֽm׃"],[2,8,"וְ⁠הֵ֖מָּה טֶ֣רֶם יִשְׁכָּב֑וּ⁠ן וְ⁠הִ֛יא עָלְתָ֥ה עֲלֵי⁠הֶ֖ם עַל־הַ⁠גָּֽג׃","wĕ⁠hé֖má̇h te֣rem yişĕ̌ká̇b֑ẇ⁠n wĕ⁠hi֛yʼ ʻálĕţá֥h ʻàléy⁠he֖m ʻal-ha⁠gáֽ̇g׃"],[2,9,"וַ⁠תֹּ֨אמֶר֙ אֶל־הָ֣⁠אֲנָשִׁ֔ים יָדַ֕עְתִּי כִּֽי־נָתַ֧ן יְהוָ֛ה לָ⁠כֶ֖ם אֶת־הָ⁠אָ֑רֶץ וְ⁠כִֽי־נָפְלָ֤ה אֵֽימַתְ⁠כֶם֙ עָלֵ֔י⁠נוּ וְ⁠כִ֥י נָמֹ֛גוּ כָּל־יֹשְׁבֵ֥י הָ⁠אָ֖רֶץ מִ⁠פְּנֵי⁠כֶֽם׃","wa⁠ţò̇֨ʼmer֙ ʼel-há֣⁠ʼànáşǐ֔ym yáda֕ʻĕţi̇y kiֽ̇y-náţa֧n yĕhwá֛h lá⁠ke֖m ʼeţ-há⁠ʼá֑reẕ wĕ⁠kiֽy-nápĕlá֤h ʼéֽymaţĕ⁠kem֙ ʻálé֔y⁠nẇ wĕ⁠ki֥y námò֛gẇ ká̇l-yòşĕ̌bé֥y há⁠ʼá֖reẕ mi⁠pĕ̇néy⁠keֽm׃"],[2,10,"כִּ֣י שָׁמַ֗עְנוּ אֵ֠ת אֲשֶׁר־הוֹבִ֨ישׁ יְהוָ֜ה אֶת־מֵ֤י יַם־סוּף֙ מִ⁠פְּנֵי⁠כֶ֔ם בְּ⁠צֵאתְ⁠כֶ֖ם מִ⁠מִּצְרָ֑יִם וַ⁠אֲשֶׁ֣ר עֲשִׂיתֶ֡ם לִ⁠שְׁנֵי֩ מַלְכֵ֨י הָ⁠אֱמֹרִ֜י אֲשֶׁ֨ר בְּ⁠עֵ֤בֶר הַ⁠יַּרְדֵּן֙ לְ⁠סִיחֹ֣ן וּ⁠לְ⁠ע֔וֹג אֲשֶׁ֥ר הֶחֱרַמְתֶּ֖ם אוֹתָֽ⁠ם׃","ki֣̇y şá̌ma֗ʻĕnẇ ʼé֠ţ ʼàşěr-hwòbi֨yş̌ yĕhwá֜h ʼeţ-mé֤y yam-sẇp֙ mi⁠pĕ̇néy⁠ke֔m bĕ̇⁠ẕéʼţĕ⁠ke֖m mi⁠mi̇ẕĕrá֑yim wa⁠ʼàşě֣r ʻàşîyţe֡m li⁠şĕ̌néy֩ malĕké֨y há⁠ʼèmòri֜y ʼàşě֨r bĕ̇⁠ʻé֤ber ha⁠yȧrĕdé̇n֙ lĕ⁠siyẖò֣n ẇ⁠lĕ⁠ʻ֔wòg ʼàşě֥r heẖèramĕţė֖m ʼwòţáֽ⁠m׃"],[2,11,"וַ⁠נִּשְׁמַע֙ וַ⁠יִּמַּ֣ס לְבָבֵ֔⁠נוּ וְ⁠לֹא־קָ֨מָה ע֥וֹד ר֛וּחַ בְּ⁠אִ֖ישׁ מִ⁠פְּנֵי⁠כֶ֑ם כִּ֚י יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם ה֤וּא אֱלֹהִים֙ בַּ⁠שָּׁמַ֣יִם מִ⁠מַּ֔עַל וְ⁠עַל־הָ⁠אָ֖רֶץ מִ⁠תָּֽחַת׃","wa⁠ni̇şĕ̌maʻ֙ wa⁠yi̇mȧ֣s lĕbábé֔⁠nẇ wĕ⁠lòʼ-qá֨máh ʻ֥wòd r֛ẇẖa bĕ̇⁠ʼi֖yş̌ mi⁠pĕ̇néy⁠ke֑m ki֚̇y yĕhwá֣h ʼèlòֽhéy⁠ke֔m h֤ẇʼ ʼèlòhiym֙ bȧ⁠şá̇̌ma֣yim mi⁠mȧ֔ʻal wĕ⁠ʻal-há⁠ʼá֖reẕ mi⁠ţáֽ̇ẖaţ׃"],[2,12,"וְ⁠עַתָּ֗ה הִשָּֽׁבְעוּ־נָ֥א לִ⁠י֙ בַּֽ⁠יהוָ֔ה כִּי־עָשִׂ֥יתִי עִמָּ⁠כֶ֖ם חָ֑סֶד וַ⁠עֲשִׂיתֶ֨ם גַּם־אַתֶּ֜ם עִם־בֵּ֤ית אָבִ⁠י֙ חֶ֔סֶד וּ⁠נְתַתֶּ֥ם לִ֖⁠י א֥וֹת אֱמֶֽת׃","wĕ⁠ʻaţá̇֗h hişáֽ̇̌bĕʻẇ-ná֥ʼ li⁠y֙ bȧֽ⁠yhwá֔h ki̇y-ʻáşî֥yţiy ʻimá̇⁠ke֖m ẖá֑sed wa⁠ʻàşîyţe֨m gȧm-ʼaţė֜m ʻim-bé֤̇yţ ʼábi⁠y֙ ẖe֔sed ẇ⁠nĕţaţė֥m li֖⁠y ʼ֥wòţ ʼèmeֽţ׃"],[2,13,"וְ⁠הַחֲיִתֶ֞ם אֶת־אָבִ֣⁠י וְ⁠אֶת־אִמִּ֗⁠י וְ⁠אֶת־אַחַ⁠י֙ וְ⁠אֶת־אחות⁠י וְ⁠אֵ֖ת כָּל־אֲשֶׁ֣ר לָ⁠הֶ֑ם וְ⁠הִצַּלְתֶּ֥ם אֶת־נַפְשֹׁתֵ֖י⁠נוּ מִ⁠מָּֽוֶת׃","wĕ⁠haẖàyiţe֞m ʼeţ-ʼábi֣⁠y wĕ⁠ʼeţ-ʼimi̇֗⁠y wĕ⁠ʼeţ-ʼaẖa⁠y֙ wĕ⁠ʼeţ-ʼẖwţ⁠y wĕ⁠ʼé֖ţ ká̇l-ʼàşě֣r lá⁠he֑m wĕ⁠hiẕȧlĕţė֥m ʼeţ-napĕşò̌ţé֖y⁠nẇ mi⁠máֽ̇weţ׃"],[2,14,"וַ⁠יֹּ֧אמְרוּ לָ֣⁠הּ הָ⁠אֲנָשִׁ֗ים נַפְשֵׁ֤⁠נוּ תַחְתֵּי⁠כֶם֙ לָ⁠מ֔וּת אִ֚ם לֹ֣א תַגִּ֔ידוּ אֶת־דְּבָרֵ֖⁠נוּ זֶ֑ה וְ⁠הָיָ֗ה בְּ⁠תֵת־יְהוָ֥ה לָ֨⁠נוּ֙ אֶת־הָ⁠אָ֔רֶץ וְ⁠עָשִׂ֥ינוּ עִמָּ֖⁠ךְ חֶ֥סֶד וֶ⁠אֱמֶֽת׃","wa⁠yò֧̇ʼmĕrẇ lá֣⁠ḣ há⁠ʼànáşǐ֗ym napĕşé֤̌⁠nẇ ţaẖĕţé̇y⁠kem֙ lá⁠m֔ẇţ ʼi֚m lò֣ʼ ţagi̇֔ydẇ ʼeţ-dĕ̇báré֖⁠nẇ ze֑h wĕ⁠háyá֗h bĕ̇⁠ţéţ-yĕhwá֥h lá֨⁠nẇ֙ ʼeţ-há⁠ʼá֔reẕ wĕ⁠ʻáşî֥ynẇ ʻimá֖̇⁠kĕ ẖe֥sed we⁠ʼèmeֽţ׃"],[2,15,"וַ⁠תּוֹרִדֵ֥⁠ם בַּ⁠חֶ֖בֶל בְּעַ֣ד הַֽ⁠חַלּ֑וֹן כִּ֤י בֵיתָ⁠הּ֙ בְּ⁠קִ֣יר הַֽ⁠חוֹמָ֔ה וּ⁠בַֽ⁠חוֹמָ֖ה הִ֥יא יוֹשָֽׁבֶת׃","wa⁠ţ̇wòridé֥⁠m bȧ⁠ẖe֖bel bĕ̇ʻa֣d hֽa⁠ẖal֑̇wòn ki֤̇y béyţá⁠ḣ֙ bĕ̇⁠qi֣yr haֽ⁠ẖwòmá֔h ẇ⁠baֽ⁠ẖwòmá֖h hi֥yʼ ywòşáֽ̌beţ׃"],[2,16,"וַ⁠תֹּ֤אמֶר לָ⁠הֶם֙ הָ⁠הָ֣רָ⁠ה לֵּ֔כוּ פֶּֽן־יִפְגְּע֥וּ בָ⁠כֶ֖ם הָ⁠רֹדְפִ֑ים וְ⁠נַחְבֵּתֶ֨ם שָׁ֜מָּ⁠ה שְׁלֹ֣שֶׁת יָמִ֗ים עַ֚ד שׁ֣וֹב הָ⁠רֹֽדְפִ֔ים וְ⁠אַחַ֖ר תֵּלְכ֥וּ לְ⁠דַרְכְּ⁠כֶֽם׃","wa⁠ţò֤̇ʼmer lá⁠hem֙ há⁠há֣rá⁠h lé̇֔kẇ pėֽn-yipĕgĕ̇ʻ֥ẇ bá⁠ke֖m há⁠ròdĕpi֑ym wĕ⁠naẖĕbé̇ţe֨m şá̌֜má̇⁠h şĕ̌lò֣şěţ yámi֗ym ʻa֚d ş֣̌wòb há⁠ròֽdĕpi֔ym wĕ⁠ʼaẖa֖r ţé̇lĕk֥ẇ lĕ⁠darĕkĕ̇⁠keֽm׃"],[2,17,"וַ⁠יֹּאמְר֥וּ אֵלֶ֖י⁠הָ הָ⁠אֲנָשִׁ֑ים נְקִיִּ֣ם אֲנַ֔חְנוּ מִ⁠שְּׁבֻעָתֵ֥⁠ךְ הַ⁠זֶּ֖ה אֲשֶׁ֥ר הִשְׁבַּעְתָּֽ⁠נוּ׃","wa⁠yò̇ʼmĕr֥ẇ ʼéle֖y⁠há há⁠ʼànáşǐ֑ym nĕqiyi֣̇m ʼàna֔ẖĕnẇ mi⁠şĕ̇̌buʻáţé֥⁠kĕ ha⁠zė֖h ʼàşě֥r hişĕ̌bȧʻĕţáֽ̇⁠nẇ׃"],[2,18,"הִנֵּ֛ה אֲנַ֥חְנוּ בָאִ֖ים בָּ⁠אָ֑רֶץ אֶת־תִּקְוַ֡ת חוּט֩ הַ⁠שָּׁנִ֨י הַ⁠זֶּ֜ה תִּקְשְׁרִ֗י בַּֽ⁠חַלּוֹן֙ אֲשֶׁ֣ר הוֹרַדְתֵּ֣⁠נוּ ב֔⁠וֹ וְ⁠אֶת־אָבִ֨י⁠ךְ וְ⁠אֶת־אִמֵּ֜⁠ךְ וְ⁠אֶת־אַחַ֗יִ⁠ךְ וְ⁠אֵת֙ כָּל־בֵּ֣ית אָבִ֔י⁠ךְ תַּאַסְפִ֥י אֵלַ֖יִ⁠ךְ הַ⁠בָּֽיְתָ⁠ה׃","hiné֛̇h ʼàna֥ẖĕnẇ báʼi֖ym bá̇⁠ʼá֑reẕ ʼeţ-ţi̇qĕwa֡ţ ẖẇt֩ ha⁠şá̇̌ni֨y ha⁠zė֜h ţi̇qĕşĕ̌ri֗y bȧֽ⁠ẖal̇wòn֙ ʼàşě֣r hwòradĕţé֣̇⁠nẇ b֔⁠wò wĕ⁠ʼeţ-ʼábi֨y⁠kĕ wĕ⁠ʼeţ-ʼimé̇֜⁠kĕ wĕ⁠ʼeţ-ʼaẖa֗yi⁠kĕ wĕ⁠ʼéţ֙ ká̇l-bé֣̇yţ ʼábi֔y⁠kĕ ţȧʼasĕpi֥y ʼéla֖yi⁠kĕ ha⁠báֽ̇yĕţá⁠h׃"],[2,19,"וְ⁠הָיָ֡ה כֹּ֣ל אֲשֶׁר־יֵצֵא֩ מִ⁠דַּלְתֵ֨י בֵיתֵ֧⁠ךְ ׀ הַ⁠ח֛וּצָ⁠ה דָּמ֥⁠וֹ בְ⁠רֹאשׁ֖⁠וֹ וַ⁠אֲנַ֣חְנוּ נְקִיִּ֑ם וְ֠⁠כֹל אֲשֶׁ֨ר יִֽהְיֶ֤ה אִתָּ⁠ךְ֙ בַּ⁠בַּ֔יִת דָּמ֣⁠וֹ בְ⁠רֹאשֵׁ֔⁠נוּ אִם־יָ֖ד תִּֽהְיֶה־בּֽ⁠וֹ׃","wĕ⁠háyá֡h kò֣̇l ʼàşěr-yéẕéʼ֩ mi⁠dȧlĕţé֨y béyţé֧⁠kĕ ׀ ha⁠ẖ֛ẇẕá⁠h dá̇m֥⁠wò bĕ⁠ròʼş֖̌⁠wò wa⁠ʼàna֣ẖĕnẇ nĕqiyi֑̇m wĕ֠⁠kòl ʼàşě֨r yiֽhĕye֤h ʼiţá̇⁠kĕ֙ bȧ⁠bȧ֔yiţ dá̇m֣⁠wò bĕ⁠ròʼşé̌֔⁠nẇ ʼim-yá֖d ţiֽ̇hĕyeh-ḃֽ⁠wò׃"],[2,20,"וְ⁠אִם־תַּגִּ֖ידִי אֶת־דְּבָרֵ֣⁠נוּ זֶ֑ה וְ⁠הָיִ֣ינוּ נְקִיִּ֔ם מִ⁠שְּׁבֻעָתֵ֖⁠ךְ אֲשֶׁ֥ר הִשְׁבַּעְתָּֽ⁠נוּ׃","wĕ⁠ʼim-ţȧgi֖̇ydiy ʼeţ-dĕ̇báré֣⁠nẇ ze֑h wĕ⁠háyi֣ynẇ nĕqiyi̇֔m mi⁠şĕ̇̌buʻáţé֖⁠kĕ ʼàşě֥r hişĕ̌bȧʻĕţáֽ̇⁠nẇ׃"],[2,21,"וַ⁠תֹּ֨אמֶר֙ כְּ⁠דִבְרֵי⁠כֶ֣ם כֶּן־ה֔וּא וַֽ⁠תְּשַׁלְּחֵ֖⁠ם וַ⁠יֵּלֵ֑כוּ וַ⁠תִּקְשֹׁ֛ר אֶת־תִּקְוַ֥ת הַ⁠שָּׁנִ֖י בַּ⁠חַלּֽוֹן׃","wa⁠ţò̇֨ʼmer֙ kĕ̇⁠dibĕréy⁠ke֣m kėn-h֔ẇʼ waֽ⁠ţĕ̇şǎlĕ̇ẖé֖⁠m wa⁠yé̇lé֑kẇ wa⁠ţi̇qĕşò֛̌r ʼeţ-ţi̇qĕwa֥ţ ha⁠şá̇̌ni֖y bȧ⁠ẖalֽ̇wòn׃"],[2,22,"וַ⁠יֵּלְכוּ֙ וַ⁠יָּבֹ֣אוּ הָ⁠הָ֔רָ⁠ה וַ⁠יֵּ֤שְׁבוּ שָׁם֙ שְׁלֹ֣שֶׁת יָמִ֔ים עַד־שָׁ֖בוּ הָ⁠רֹדְפִ֑ים וַ⁠יְבַקְשׁ֧וּ הָ⁠רֹדְפִ֛ים בְּ⁠כָל־הַ⁠דֶּ֖רֶךְ וְ⁠לֹ֥א מָצָֽאוּ׃","wa⁠yé̇lĕkẇ֙ wa⁠yá̇bò֣ʼẇ há⁠há֔rá⁠h wa⁠yé֤̇şĕ̌bẇ şá̌m֙ şĕ̌lò֣şěţ yámi֔ym ʻad-şá֖̌bẇ há⁠ròdĕpi֑ym wa⁠yĕbaqĕş֧̌ẇ há⁠ròdĕpi֛ym bĕ̇⁠kál-ha⁠dė֖rekĕ wĕ⁠lò֥ʼ máẕáֽʼẇ׃"],[2,23,"וַ⁠יָּשֻׁ֜בוּ שְׁנֵ֤י הָֽ⁠אֲנָשִׁים֙ וַ⁠יֵּרְד֣וּ מֵֽ⁠הָ⁠הָ֔ר וַ⁠יַּעַבְרוּ֙ וַ⁠יָּבֹ֔אוּ אֶל־יְהוֹשֻׁ֖עַ בִּן־נ֑וּן וַ⁠יְסַ֨פְּרוּ־ל֔⁠וֹ אֵ֥ת כָּל־הַ⁠מֹּצְא֖וֹת אוֹתָֽ⁠ם׃","wa⁠yá̇şǔ֜bẇ şĕ̌né֤y háֽ⁠ʼànáşǐym֙ wa⁠yé̇rĕd֣ẇ méֽ⁠há⁠há֔r wa⁠yȧʻabĕrẇ֙ wa⁠yá̇bò֔ʼẇ ʼel-yĕhwòşǔ֖ʻa bi̇n-n֑ẇn wa⁠yĕsa֨pĕ̇rẇ-l֔⁠wò ʼé֥ţ ká̇l-ha⁠mò̇ẕĕʼ֖wòţ ʼwòţáֽ⁠m׃"],[2,24,"וַ⁠יֹּאמְרוּ֙ אֶל־יְהוֹשֻׁ֔עַ כִּֽי־נָתַ֧ן יְהוָ֛ה בְּ⁠יָדֵ֖⁠נוּ אֶת־כָּל־הָ⁠אָ֑רֶץ וְ⁠גַם־נָמֹ֛גוּ כָּל־יֹשְׁבֵ֥י הָ⁠אָ֖רֶץ מִ⁠פָּנֵֽי⁠נוּ׃ס","wa⁠yò̇ʼmĕrẇ֙ ʼel-yĕhwòşǔ֔ʻa kiֽ̇y-náţa֧n yĕhwá֛h bĕ̇⁠yádé֖⁠nẇ ʼeţ-ká̇l-há⁠ʼá֑reẕ wĕ⁠gam-námò֛gẇ ká̇l-yòşĕ̌bé֥y há⁠ʼá֖reẕ mi⁠pá̇néֽy⁠nẇ׃s"],[3,1,"וַ⁠יַּשְׁכֵּם֩ יְהוֹשֻׁ֨עַ בַּ⁠בֹּ֜קֶר וַ⁠יִּסְע֣וּ מֵֽ⁠הַ⁠שִּׁטִּ֗ים וַ⁠יָּבֹ֨אוּ֙ עַד־הַ⁠יַּרְדֵּ֔ן ה֖וּא וְ⁠כָל־בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יָּלִ֥נוּ שָׁ֖ם טֶ֥רֶם יַעֲבֹֽרוּ׃","wa⁠yȧşĕ̌ké̇m֩ yĕhwòşǔ֨ʻa bȧ⁠bò̇֜qer wa⁠yi̇sĕʻ֣ẇ méֽ⁠ha⁠şi̇̌ti̇֗ym wa⁠yá̇bò֨ʼẇ֙ ʻad-ha⁠yȧrĕdé̇֔n h֖ẇʼ wĕ⁠kál-bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yá̇li֥nẇ şá֖̌m te֥rem yaʻàbòֽrẇ׃"],[3,2,"וַ⁠יְהִ֕י מִ⁠קְצֵ֖ה שְׁלֹ֣שֶׁת יָמִ֑ים וַ⁠יַּעַבְר֥וּ הַ⁠שֹּׁטְרִ֖ים בְּ⁠קֶ֥רֶב הַֽ⁠מַּחֲנֶֽה׃","wa⁠yĕhi֕y mi⁠qĕẕé֖h şĕ̌lò֣şěţ yámi֑ym wa⁠yȧʻabĕr֥ẇ ha⁠şò̇̌tĕri֖ym bĕ̇⁠qe֥reb haֽ⁠mȧẖàneֽh׃"],[3,3,"וַ⁠יְצַוּוּ֮ אֶת־הָ⁠עָ֣ם לֵ⁠אמֹר֒ כִּ⁠רְאֽוֹתְ⁠כֶ֗ם אֵ֣ת אֲר֤וֹן בְּרִית־יְהוָה֙ אֱלֹ֣הֵי⁠כֶ֔ם וְ⁠הַ⁠כֹּֽהֲנִים֙ הַ⁠לְוִיִּ֔ם נֹשְׂאִ֖ים אֹת֑⁠וֹ וְ⁠אַתֶּ֗ם תִּסְעוּ֙ מִ⁠מְּק֣וֹמְ⁠כֶ֔ם וַ⁠הֲלַכְתֶּ֖ם אַחֲרָֽי⁠ו׃","wa⁠yĕẕaẇẇ֮ ʼeţ-há⁠ʻá֣m lé⁠ʼmòr֒ ki̇⁠rĕʼֽwòţĕ⁠ke֗m ʼé֣ţ ʼàr֤wòn bĕ̇riyţ-yĕhwáh֙ ʼèlò֣héy⁠ke֔m wĕ⁠ha⁠kòֽ̇hàniym֙ ha⁠lĕwiyi̇֔m nòşĕ̂ʼi֖ym ʼòţ֑⁠wò wĕ⁠ʼaţė֗m ţi̇sĕʻẇ֙ mi⁠mĕ̇q֣wòmĕ⁠ke֔m wa⁠hàlakĕţė֖m ʼaẖàráֽy⁠w׃"],[3,4,"אַ֣ךְ ׀ רָח֣וֹק יִהְיֶ֗ה בֵּֽינֵי⁠כֶם֙ ו⁠בינ⁠ו כְּ⁠אַלְפַּ֥יִם אַמָּ֖ה בַּ⁠מִּדָּ֑ה אַֽל־תִּקְרְב֣וּ אֵלָ֗י⁠ו לְמַ֤עַן אֲשֶׁר־תֵּֽדְעוּ֙ אֶת־הַ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר תֵּֽלְכוּ־בָ֔⁠הּ כִּ֣י לֹ֧א עֲבַרְתֶּ֛ם בַּ⁠דֶּ֖רֶךְ מִ⁠תְּמ֥וֹל שִׁלְשֽׁוֹם׃ס","ʼa֣kĕ ׀ ráẖ֣wòq yihĕye֗h béֽ̇ynéy⁠kem֙ w⁠byn⁠w kĕ̇⁠ʼalĕpȧ֥yim ʼamá֖̇h bȧ⁠mi̇dá֑̇h ʼaֽl-ţi̇qĕrĕb֣ẇ ʼélá֗y⁠w lĕma֤ʻan ʼàşěr-ţéֽ̇dĕʻẇ֙ ʼeţ-ha⁠dė֨rekĕ֙ ʼàşě֣r ţéֽ̇lĕkẇ-bá֔⁠ḣ ki֣̇y lò֧ʼ ʻàbarĕţė֛m bȧ⁠dė֖rekĕ mi⁠ţĕ̇m֥wòl şǐlĕşֽ̌wòm׃s"],[3,5,"וַ⁠יֹּ֧אמֶר יְהוֹשֻׁ֛עַ אֶל־הָ⁠עָ֖ם הִתְקַדָּ֑שׁוּ כִּ֣י מָחָ֗ר יַעֲשֶׂ֧ה יְהוָ֛ה בְּ⁠קִרְבְּ⁠כֶ֖ם נִפְלָאֽוֹת׃","wa⁠yò֧̇ʼmer yĕhwòşǔ֛ʻa ʼel-há⁠ʻá֖m hiţĕqadá֑̇ş̌ẇ ki֣̇y máẖá֗r yaʻàşê֧h yĕhwá֛h bĕ̇⁠qirĕbĕ̇⁠ke֖m nipĕláʼֽwòţ׃"],[3,6,"וַ⁠יֹּ֤אמֶר יְהוֹשֻׁ֨עַ֙ אֶל־הַ⁠כֹּהֲנִ֣ים לֵ⁠אמֹ֔ר שְׂאוּ֙ אֶת־אֲר֣וֹן הַ⁠בְּרִ֔ית וְ⁠עִבְר֖וּ לִ⁠פְנֵ֣י הָ⁠עָ֑ם וַ⁠יִּשְׂאוּ֙ אֶת־אֲר֣וֹן הַ⁠בְּרִ֔ית וַ⁠יֵּלְכ֖וּ לִ⁠פְנֵ֥י הָ⁠עָֽם׃ס","wa⁠yò֤̇ʼmer yĕhwòşǔ֨ʻa֙ ʼel-ha⁠kò̇hàni֣ym lé⁠ʼmò֔r şĕ̂ʼẇ֙ ʼeţ-ʼàr֣wòn ha⁠bĕ̇ri֔yţ wĕ⁠ʻibĕr֖ẇ li⁠pĕné֣y há⁠ʻá֑m wa⁠yi̇şĕ̂ʼẇ֙ ʼeţ-ʼàr֣wòn ha⁠bĕ̇ri֔yţ wa⁠yé̇lĕk֖ẇ li⁠pĕné֥y há⁠ʻáֽm׃s"],[3,7,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־יְהוֹשֻׁ֔עַ הַ⁠יּ֣וֹם הַ⁠זֶּ֗ה אָחֵל֙ גַּדֶּלְ⁠ךָ֔ בְּ⁠עֵינֵ֖י כָּל־יִשְׂרָאֵ֑ל אֲשֶׁר֙ יֵֽדְע֔וּ⁠ן כִּ֗י כַּ⁠אֲשֶׁ֥ר הָיִ֛יתִי עִם־מֹשֶׁ֖ה אֶהְיֶ֥ה עִמָּֽ⁠ךְ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-yĕhwòşǔ֔ʻa ha⁠ẏ֣wòm ha⁠zė֗h ʼáẖél֙ gȧdėlĕ⁠ká֔ bĕ̇⁠ʻéyné֖y ká̇l-yişĕ̂ráʼé֑l ʼàşěr֙ yéֽdĕʻ֔ẇ⁠n ki̇֗y kȧ⁠ʼàşě֥r háyi֛yţiy ʻim-mòşě֖h ʼehĕye֥h ʻimáֽ̇⁠kĕ׃"],[3,8,"וְ⁠אַתָּ֗ה תְּצַוֶּה֙ אֶת־הַ⁠כֹּ֣הֲנִ֔ים נֹשְׂאֵ֥י אֲרֽוֹן־הַ⁠בְּרִ֖ית לֵ⁠אמֹ֑ר כְּ⁠בֹאֲ⁠כֶ֗ם עַד־קְצֵה֙ מֵ֣י הַ⁠יַּרְדֵּ֔ן בַּ⁠יַּרְדֵּ֖ן תַּעֲמֹֽדוּ׃פ","wĕ⁠ʼaţá̇֗h ţĕ̇ẕawėh֙ ʼeţ-ha⁠kò֣̇hàni֔ym nòşĕ̂ʼé֥y ʼàrֽwòn-ha⁠bĕ̇ri֖yţ lé⁠ʼmò֑r kĕ̇⁠bòʼà⁠ke֗m ʻad-qĕẕéh֙ mé֣y ha⁠yȧrĕdé̇֔n bȧ⁠yȧrĕdé֖̇n ţȧʻàmòֽdẇ׃p"],[3,9,"וַ⁠יֹּ֥אמֶר יְהוֹשֻׁ֖עַ אֶל־בְּנֵ֣י יִשְׂרָאֵ֑ל גֹּ֣שׁוּ הֵ֔נָּה וְ⁠שִׁמְע֕וּ אֶת־דִּבְרֵ֖י יְהוָ֥ה אֱלֹֽהֵי⁠כֶֽם׃","wa⁠yò֥̇ʼmer yĕhwòşǔ֖ʻa ʼel-bĕ̇né֣y yişĕ̂ráʼé֑l gò֣̇ş̌ẇ hé֔ná̇h wĕ⁠şǐmĕʻ֕ẇ ʼeţ-di̇bĕré֖y yĕhwá֥h ʼèlòֽhéy⁠keֽm׃"],[3,10,"וַ⁠יֹּ֣אמֶר יְהוֹשֻׁ֔עַ בְּ⁠זֹאת֙ תֵּֽדְע֔וּ⁠ן כִּ֛י אֵ֥ל חַ֖י בְּ⁠קִרְבְּ⁠כֶ֑ם וְ⁠הוֹרֵ֣שׁ יוֹרִ֣ישׁ מִ֠⁠פְּנֵי⁠כֶם אֶת־הַ⁠כְּנַעֲנִ֨י וְ⁠אֶת־הַ⁠חִתִּ֜י וְ⁠אֶת־הַ⁠חִוִּ֗י וְ⁠אֶת־הַ⁠פְּרִזִּי֙ וְ⁠אֶת־הַ⁠גִּרְגָּשִׁ֔י וְ⁠הָ⁠אֱמֹרִ֖י וְ⁠הַ⁠יְבוּסִֽי׃","wa⁠yò֣̇ʼmer yĕhwòşǔ֔ʻa bĕ̇⁠zòʼţ֙ ţéֽ̇dĕʻ֔ẇ⁠n ki֛̇y ʼé֥l ẖa֖y bĕ̇⁠qirĕbĕ̇⁠ke֑m wĕ⁠hwòré֣ş̌ ywòri֣yş̌ mi֠⁠pĕ̇néy⁠kem ʼeţ-ha⁠kĕ̇naʻàni֨y wĕ⁠ʼeţ-ha⁠ẖiţi̇֜y wĕ⁠ʼeţ-ha⁠ẖiwi̇֗y wĕ⁠ʼeţ-ha⁠pĕ̇rizi̇y֙ wĕ⁠ʼeţ-ha⁠gi̇rĕgá̇şǐ֔y wĕ⁠há⁠ʼèmòri֖y wĕ⁠ha⁠yĕbẇsiֽy׃"],[3,11,"הִנֵּה֙ אֲר֣וֹן הַ⁠בְּרִ֔ית אֲד֖וֹן כָּל־הָ⁠אָ֑רֶץ עֹבֵ֥ר לִ⁠פְנֵי⁠כֶ֖ם בַּ⁠יַּרְדֵּֽן׃","hiné̇h֙ ʼàr֣wòn ha⁠bĕ̇ri֔yţ ʼàd֖wòn ká̇l-há⁠ʼá֑reẕ ʻòbé֥r li⁠pĕnéy⁠ke֖m bȧ⁠yȧrĕdéֽ̇n׃"],[3,12,"וְ⁠עַתָּ֗ה קְח֤וּ לָ⁠כֶם֙ שְׁנֵ֣י עָשָׂ֣ר אִ֔ישׁ מִ⁠שִּׁבְטֵ֖י יִשְׂרָאֵ֑ל אִישׁ־אֶחָ֥ד אִישׁ־אֶחָ֖ד לַ⁠שָּֽׁבֶט׃","wĕ⁠ʻaţá̇֗h qĕẖ֤ẇ lá⁠kem֙ şĕ̌né֣y ʻáşá֣̂r ʼi֔yş̌ mi⁠şi̇̌bĕté֖y yişĕ̂ráʼé֑l ʼiyş̌-ʼeẖá֥d ʼiyş̌-ʼeẖá֖d la⁠şáֽ̇̌bet׃"],[3,13,"וְ⁠הָיָ֡ה כְּ⁠נ֣וֹחַ כַּפּ֣וֹת רַגְלֵ֣י הַ⁠כֹּהֲנִ֡ים נֹשְׂאֵי֩ אֲר֨וֹן יְהוָ֜ה אֲד֤וֹן כָּל־הָ⁠אָ֨רֶץ֙ בְּ⁠מֵ֣י הַ⁠יַּרְדֵּ֔ן מֵ֤י הַ⁠יַּרְדֵּן֙ יִכָּ֣רֵת֔וּ⁠ן הַ⁠מַּ֥יִם הַ⁠יֹּרְדִ֖ים מִ⁠לְ⁠מָ֑עְלָ⁠ה וְ⁠יַעַמְד֖וּ נֵ֥ד אֶחָֽד׃","wĕ⁠háyá֡h kĕ̇⁠n֣wòẖa kȧṗ֣wòţ ragĕlé֣y ha⁠kò̇hàni֡ym nòşĕ̂ʼéy֩ ʼàr֨wòn yĕhwá֜h ʼàd֤wòn ká̇l-há⁠ʼá֨reẕ֙ bĕ̇⁠mé֣y ha⁠yȧrĕdé̇֔n mé֤y ha⁠yȧrĕdé̇n֙ yiká֣̇réţ֔ẇ⁠n ha⁠mȧ֥yim ha⁠yò̇rĕdi֖ym mi⁠lĕ⁠má֑ʻĕlá⁠h wĕ⁠yaʻamĕd֖ẇ né֥d ʼeẖáֽd׃"],[3,14,"וַ⁠יְהִ֗י בִּ⁠נְסֹ֤עַ הָ⁠עָם֙ מֵ⁠אָ֣הֳלֵי⁠הֶ֔ם לַ⁠עֲבֹ֖ר אֶת־הַ⁠יַּרְדֵּ֑ן וְ⁠הַ⁠כֹּהֲנִ֗ים נֹֽשְׂאֵ֛י הָ⁠אָר֥וֹן הַ⁠בְּרִ֖ית לִ⁠פְנֵ֥י הָ⁠עָֽם׃","wa⁠yĕhi֗y bi̇⁠nĕsò֤ʻa há⁠ʻám֙ mé⁠ʼá֣holéy⁠he֔m la⁠ʻàbò֖r ʼeţ-ha⁠yȧrĕdé֑̇n wĕ⁠ha⁠kò̇hàni֗ym nòֽşĕ̂ʼé֛y há⁠ʼár֥wòn ha⁠bĕ̇ri֖yţ li⁠pĕné֥y há⁠ʻáֽm׃"],[3,15,"וּ⁠כְ⁠ב֞וֹא נֹשְׂאֵ֤י הָֽ⁠אָרוֹן֙ עַד־הַ⁠יַּרְדֵּ֔ן וְ⁠רַגְלֵ֤י הַ⁠כֹּֽהֲנִים֙ נֹשְׂאֵ֣י הָֽ⁠אָר֔וֹן נִטְבְּל֖וּ בִּ⁠קְצֵ֣ה הַ⁠מָּ֑יִם וְ⁠הַ⁠יַּרְדֵּ֗ן מָלֵא֙ עַל־כָּל־גְּדוֹתָ֔י⁠ו כֹּ֖ל יְמֵ֥י קָצִֽיר׃","ẇ⁠kĕ⁠b֞wòʼ nòşĕ̂ʼé֤y háֽ⁠ʼárwòn֙ ʻad-ha⁠yȧrĕdé̇֔n wĕ⁠ragĕlé֤y ha⁠kòֽ̇hàniym֙ nòşĕ̂ʼé֣y háֽ⁠ʼár֔wòn nitĕbĕ̇l֖ẇ bi̇⁠qĕẕé֣h ha⁠má֑̇yim wĕ⁠ha⁠yȧrĕdé̇֗n máléʼ֙ ʻal-ká̇l-gĕ̇dwòţá֔y⁠w kò֖̇l yĕmé֥y qáẕiֽyr׃"],[3,16,"וַ⁠יַּעַמְד֡וּ הַ⁠מַּיִם֩ הַ⁠יֹּרְדִ֨ים מִ⁠לְ⁠מַ֜עְלָ⁠ה קָ֣מוּ נֵד־אֶחָ֗ד הַרְחֵ֨ק מְאֹ֜ד ב⁠אדם הָ⁠עִיר֙ אֲשֶׁר֙ מִ⁠צַּ֣ד צָֽרְתָ֔ן וְ⁠הַ⁠יֹּרְדִ֗ים עַ֣ל יָ֧ם הָ⁠עֲרָבָ֛ה יָם־הַ⁠מֶּ֖לַח תַּ֣מּוּ נִכְרָ֑תוּ וְ⁠הָ⁠עָ֥ם עָבְר֖וּ נֶ֥גֶד יְרִיחֽוֹ׃","wa⁠yȧʻamĕd֡ẇ ha⁠mȧyim֩ ha⁠yò̇rĕdi֨ym mi⁠lĕ⁠ma֜ʻĕlá⁠h qá֣mẇ néd-ʼeẖá֗d harĕẖé֨q mĕʼò֜d b⁠ʼdm há⁠ʻiyr֙ ʼàşěr֙ mi⁠ẕȧ֣d ẕáֽrĕţá֔n wĕ⁠ha⁠yò̇rĕdi֗ym ʻa֣l yá֧m há⁠ʻàrábá֛h yám-ha⁠mė֖laẖ ţȧ֣ṁẇ nikĕrá֑ţẇ wĕ⁠há⁠ʻá֥m ʻábĕr֖ẇ ne֥ged yĕriyẖֽwò׃"],[3,17,"וַ⁠יַּעַמְד֣וּ הַ⁠כֹּהֲנִ֡ים נֹ֠שְׂאֵי הָ⁠אָר֨וֹן בְּרִית־יְהוָ֜ה בֶּ⁠חָֽרָבָ֛ה בְּ⁠ת֥וֹךְ הַ⁠יַּרְדֵּ֖ן הָכֵ֑ן וְ⁠כָל־יִשְׂרָאֵ֗ל עֹֽבְרִים֙ בֶּ⁠חָ֣רָבָ֔ה עַ֤ד אֲשֶׁר־תַּ֨מּוּ֙ כָּל־הַ⁠גּ֔וֹי לַ⁠עֲבֹ֖ר אֶת־הַ⁠יַּרְדֵּֽן׃","wa⁠yȧʻamĕd֣ẇ ha⁠kò̇hàni֡ym nò֠şĕ̂ʼéy há⁠ʼár֨wòn bĕ̇riyţ-yĕhwá֜h bė⁠ẖֽárábá֛h bĕ̇⁠ţ֥wòkĕ ha⁠yȧrĕdé֖̇n háké֑n wĕ⁠kál-yişĕ̂ráʼé֗l ʻòֽbĕriym֙ bė⁠ẖá֣rábá֔h ʻa֤d ʼàşěr-ţȧ֨ṁẇ֙ ká̇l-ha⁠ġ֔wòy la⁠ʻàbò֖r ʼeţ-ha⁠yȧrĕdéֽ̇n׃"],[4,1,"וַ⁠יְהִי֙ כַּ⁠אֲשֶׁר־תַּ֣מּוּ כָל־הַ⁠גּ֔וֹי לַ⁠עֲב֖וֹר אֶת־הַ⁠יַּרְדֵּ֑ן פ וַ⁠יֹּ֣אמֶר יְהוָ֔ה אֶל־יְהוֹשֻׁ֖עַ לֵ⁠אמֹֽר׃","wa⁠yĕhiy֙ kȧ⁠ʼàşěr-ţȧ֣ṁẇ kál-ha⁠ġ֔wòy la⁠ʻàb֖wòr ʼeţ-ha⁠yȧrĕdé֑̇n p wa⁠yò֣̇ʼmer yĕhwá֔h ʼel-yĕhwòşǔ֖ʻa lé⁠ʼmòֽr׃"],[4,2,"קְח֤וּ לָ⁠כֶם֙ מִן־הָ⁠עָ֔ם שְׁנֵ֥ים עָשָׂ֖ר אֲנָשִׁ֑ים אִישׁ־אֶחָ֥ד אִישׁ־אֶחָ֖ד מִ⁠שָּֽׁבֶט׃","qĕẖ֤ẇ lá⁠kem֙ min-há⁠ʻá֔m şĕ̌né֥ym ʻáşá֖̂r ʼànáşǐ֑ym ʼiyş̌-ʼeẖá֥d ʼiyş̌-ʼeẖá֖d mi⁠şáֽ̇̌bet׃"],[4,3,"וְ⁠צַוּ֣וּ אוֹתָ⁠ם֮ לֵ⁠אמֹר֒ שְׂאֽוּ־לָ⁠כֶ֨ם מִ⁠זֶּ֜ה מִ⁠תּ֣וֹךְ הַ⁠יַּרְדֵּ֗ן מִ⁠מַּצַּב֙ רַגְלֵ֣י הַ⁠כֹּהֲנִ֔ים הָכִ֖ין שְׁתֵּים־עֶשְׂרֵ֣ה אֲבָנִ֑ים וְ⁠הַעֲבַרְתֶּ֤ם אוֹתָ⁠ם֙ עִמָּ⁠כֶ֔ם וְ⁠הִנַּחְתֶּ֣ם אוֹתָ֔⁠ם בַּ⁠מָּל֕וֹן אֲשֶׁר־תָּלִ֥ינוּ ב֖⁠וֹ הַ⁠לָּֽיְלָה׃ס","wĕ⁠ẕaẇ֣ẇ ʼwòţá⁠m֮ lé⁠ʼmòr֒ şĕ̂ʼֽẇ-lá⁠ke֨m mi⁠zė֜h mi⁠ţ֣̇wòkĕ ha⁠yȧrĕdé̇֗n mi⁠mȧẕȧb֙ ragĕlé֣y ha⁠kò̇hàni֔ym háki֖yn şĕ̌ţé̇ym-ʻeşĕ̂ré֣h ʼàbáni֑ym wĕ⁠haʻàbarĕţė֤m ʼwòţá⁠m֙ ʻimá̇⁠ke֔m wĕ⁠hinȧẖĕţė֣m ʼwòţá֔⁠m bȧ⁠má̇l֕wòn ʼàşěr-ţá̇li֥ynẇ b֖⁠wò ha⁠láֽ̇yĕláh׃s"],[4,4,"וַ⁠יִּקְרָ֣א יְהוֹשֻׁ֗עַ אֶל־שְׁנֵ֤ים הֶֽ⁠עָשָׂר֙ אִ֔ישׁ אֲשֶׁ֥ר הֵכִ֖ין מִ⁠בְּנֵ֣י יִשְׂרָאֵ֑ל אִישׁ־אֶחָ֥ד אִישׁ־אֶחָ֖ד מִ⁠שָּֽׁבֶט׃","wa⁠yi̇qĕrá֣ʼ yĕhwòşǔ֗ʻa ʼel-şĕ̌né֤ym heֽ⁠ʻáşá̂r֙ ʼi֔yş̌ ʼàşě֥r héki֖yn mi⁠bĕ̇né֣y yişĕ̂ráʼé֑l ʼiyş̌-ʼeẖá֥d ʼiyş̌-ʼeẖá֖d mi⁠şáֽ̇̌bet׃"],[4,5,"וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ יְהוֹשֻׁ֔עַ עִ֠בְרוּ לִ⁠פְנֵ֨י אֲר֧וֹן יְהוָ֛ה אֱלֹֽהֵי⁠כֶ֖ם אֶל־תּ֣וֹךְ הַ⁠יַּרְדֵּ֑ן וְ⁠הָרִ֨ימוּ לָ⁠כֶ֜ם אִ֣ישׁ אֶ֤בֶן אַחַת֙ עַל־שִׁכְמ֔⁠וֹ לְ⁠מִסְפַּ֖ר שִׁבְטֵ֥י בְנֵי־יִשְׂרָאֵֽל׃","wa⁠yò֤̇ʼmer lá⁠hem֙ yĕhwòşǔ֔ʻa ʻi֠bĕrẇ li⁠pĕné֨y ʼàr֧wòn yĕhwá֛h ʼèlòֽhéy⁠ke֖m ʼel-ţ֣̇wòkĕ ha⁠yȧrĕdé֑̇n wĕ⁠hári֨ymẇ lá⁠ke֜m ʼi֣yş̌ ʼe֤ben ʼaẖaţ֙ ʻal-şǐkĕm֔⁠wò lĕ⁠misĕpȧ֖r şǐbĕté֥y bĕnéy-yişĕ̂ráʼéֽl׃"],[4,6,"לְמַ֗עַן תִּֽהְיֶ֛ה זֹ֥את א֖וֹת בְּ⁠קִרְבְּ⁠כֶ֑ם כִּֽי־יִשְׁאָל֨וּ⁠ן בְּנֵי⁠כֶ֤ם מָחָר֙ לֵ⁠אמֹ֔ר מָ֛ה הָ⁠אֲבָנִ֥ים הָ⁠אֵ֖לֶּה לָ⁠כֶֽם׃","lĕma֗ʻan ţiֽ̇hĕye֛h zò֥ʼţ ʼ֖wòţ bĕ̇⁠qirĕbĕ̇⁠ke֑m kiֽ̇y-yişĕ̌ʼál֨ẇ⁠n bĕ̇néy⁠ke֤m máẖár֙ lé⁠ʼmò֔r má֛h há⁠ʼàbáni֥ym há⁠ʼé֖lėh lá⁠keֽm׃"],[4,7,"וַ⁠אֲמַרְתֶּ֣ם לָ⁠הֶ֗ם אֲשֶׁ֨ר נִכְרְת֜וּ מֵימֵ֤י הַ⁠יַּרְדֵּן֙ מִ⁠פְּנֵי֙ אֲר֣וֹן בְּרִית־יְהוָ֔ה בְּ⁠עָבְר⁠וֹ֙ בַּ⁠יַּרְדֵּ֔ן נִכְרְת֖וּ מֵ֣י הַ⁠יַּרְדֵּ֑ן וְ֠⁠הָיוּ הָ⁠אֲבָנִ֨ים הָ⁠אֵ֧לֶּה לְ⁠זִכָּר֛וֹן לִ⁠בְנֵ֥י יִשְׂרָאֵ֖ל עַד־עוֹלָֽם׃","wa⁠ʼàmarĕţė֣m lá⁠he֗m ʼàşě֨r nikĕrĕţ֜ẇ méymé֤y ha⁠yȧrĕdé̇n֙ mi⁠pĕ̇néy֙ ʼàr֣wòn bĕ̇riyţ-yĕhwá֔h bĕ̇⁠ʻábĕr⁠wò֙ bȧ⁠yȧrĕdé̇֔n nikĕrĕţ֖ẇ mé֣y ha⁠yȧrĕdé֑̇n wĕ֠⁠háyẇ há⁠ʼàbáni֨ym há⁠ʼé֧lėh lĕ⁠ziká̇r֛wòn li⁠bĕné֥y yişĕ̂ráʼé֖l ʻad-ʻwòláֽm׃"],[4,8,"וַ⁠יַּעֲשׂוּ־כֵ֣ן בְּנֵי־יִשְׂרָאֵ֘ל כַּ⁠אֲשֶׁ֣ר צִוָּ֣ה יְהוֹשֻׁעַ֒ וַ⁠יִּשְׂא֡וּ שְׁתֵּֽי־עֶשְׂרֵ֨ה אֲבָנִ֜ים מִ⁠תּ֣וֹךְ הַ⁠יַּרְדֵּ֗ן כַּ⁠אֲשֶׁ֨ר דִּבֶּ֤ר יְהוָה֙ אֶל־יְהוֹשֻׁ֔עַ לְ⁠מִסְפַּ֖ר שִׁבְטֵ֣י בְנֵֽי־יִשְׂרָאֵ֑ל וַ⁠יַּעֲבִר֤וּ⁠ם עִמָּ⁠ם֙ אֶל־הַ⁠מָּל֔וֹן וַ⁠יַּנִּח֖וּ⁠ם שָֽׁם׃","wa⁠yȧʻàş̂ẇ-ké֣n bĕ̇néy-yişĕ̂ráʼé֘l kȧ⁠ʼàşě֣r ẕiwá֣̇h yĕhwòşǔʻa֒ wa⁠yi̇şĕ̂ʼ֡ẇ şĕ̌ţéֽ̇y-ʻeşĕ̂ré֨h ʼàbáni֜ym mi⁠ţ֣̇wòkĕ ha⁠yȧrĕdé̇֗n kȧ⁠ʼàşě֨r di̇bė֤r yĕhwáh֙ ʼel-yĕhwòşǔ֔ʻa lĕ⁠misĕpȧ֖r şǐbĕté֣y bĕnéֽy-yişĕ̂ráʼé֑l wa⁠yȧʻàbir֤ẇ⁠m ʻimá̇⁠m֙ ʼel-ha⁠má̇l֔wòn wa⁠yȧni̇ẖ֖ẇ⁠m şáֽ̌m׃"],[4,9,"וּ⁠שְׁתֵּ֧ים עֶשְׂרֵ֣ה אֲבָנִ֗ים הֵקִ֣ים יְהוֹשֻׁעַ֮ בְּ⁠ת֣וֹךְ הַ⁠יַּרְדֵּן֒ תַּ֗חַת מַצַּב֙ רַגְלֵ֣י הַ⁠כֹּהֲנִ֔ים נֹשְׂאֵ֖י אֲר֣וֹן הַ⁠בְּרִ֑ית וַ⁠יִּ֣הְיוּ שָׁ֔ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","ẇ⁠şĕ̌ţé֧̇ym ʻeşĕ̂ré֣h ʼàbáni֗ym héqi֣ym yĕhwòşǔʻa֮ bĕ̇⁠ţ֣wòkĕ ha⁠yȧrĕdé̇n֒ ţȧ֗ẖaţ maẕȧb֙ ragĕlé֣y ha⁠kò̇hàni֔ym nòşĕ̂ʼé֖y ʼàr֣wòn ha⁠bĕ̇ri֑yţ wa⁠yi֣̇hĕyẇ şá̌֔m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[4,10,"וְ⁠הַ⁠כֹּהֲנִ֞ים נֹשְׂאֵ֣י הָ⁠אָר֗וֹן עֹמְדִים֮ בְּ⁠ת֣וֹךְ הַ⁠יַּרְדֵּן֒ עַ֣ד תֹּ֣ם כָּֽל־הַ֠⁠דָּבָר אֲשֶׁר־צִוָּ֨ה יְהוָ֤ה אֶת־יְהוֹשֻׁ֨עַ֙ לְ⁠דַבֵּ֣ר אֶל־הָ⁠עָ֔ם כְּ⁠כֹ֛ל אֲשֶׁר־צִוָּ֥ה מֹשֶׁ֖ה אֶת־יְהוֹשֻׁ֑עַ וַ⁠יְמַהֲר֥וּ הָ⁠עָ֖ם וַֽ⁠יַּעֲבֹֽרוּ׃","wĕ⁠ha⁠kò̇hàni֞ym nòşĕ̂ʼé֣y há⁠ʼár֗wòn ʻòmĕdiym֮ bĕ̇⁠ţ֣wòkĕ ha⁠yȧrĕdé̇n֒ ʻa֣d ţò֣̇m káֽ̇l-ha֠⁠dá̇bár ʼàşěr-ẕiwá̇֨h yĕhwá֤h ʼeţ-yĕhwòşǔ֨ʻa֙ lĕ⁠dabé֣̇r ʼel-há⁠ʻá֔m kĕ̇⁠kò֛l ʼàşěr-ẕiwá֥̇h mòşě֖h ʼeţ-yĕhwòşǔ֑ʻa wa⁠yĕmahàr֥ẇ há⁠ʻá֖m wֽa⁠yȧʻàbòֽrẇ׃"],[4,11,"וַ⁠יְהִ֛י כַּֽ⁠אֲשֶׁר־תַּ֥ם כָּל־הָ⁠עָ֖ם לַֽ⁠עֲב֑וֹר וַ⁠יַּעֲבֹ֧ר אֲרוֹן־יְהוָ֛ה וְ⁠הַ⁠כֹּהֲנִ֖ים לִ⁠פְנֵ֥י הָ⁠עָֽם׃","wa⁠yĕhi֛y kֽ̇a⁠ʼàşěr-ţȧ֥m ká̇l-há⁠ʻá֖m lֽa⁠ʻàb֑wòr wa⁠yȧʻàbò֧r ʼàrwòn-yĕhwá֛h wĕ⁠ha⁠kò̇hàni֖ym li⁠pĕné֥y há⁠ʻáֽm׃"],[4,12,"וַ֠⁠יַּעַבְרוּ בְּנֵי־רְאוּבֵ֨ן וּ⁠בְנֵי־גָ֜ד וַ⁠חֲצִ֨י שֵׁ֤בֶט הַֽ⁠מְנַשֶּׁה֙ חֲמֻשִׁ֔ים לִ⁠פְנֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר אֲלֵי⁠הֶ֖ם מֹשֶֽׁה׃","wa֠⁠yȧʻabĕrẇ bĕ̇néy-rĕʼẇbé֨n ẇ⁠bĕnéy-gá֜d wa⁠ẖàẕi֨y şé֤̌bet haֽ⁠mĕnaşė̌h֙ ẖàmuşǐ֔ym li⁠pĕné֖y bĕ̇né֣y yişĕ̂ráʼé֑l kȧ⁠ʼàşě֛r di̇bė֥r ʼàléy⁠he֖m mòşěֽh׃"],[4,13,"כְּ⁠אַרְבָּעִ֥ים אֶ֖לֶף חֲלוּצֵ֣י הַ⁠צָּבָ֑א עָבְר֞וּ לִ⁠פְנֵ֤י יְהוָה֙ לַ⁠מִּלְחָמָ֔ה אֶ֖ל עַֽרְב֥וֹת יְרִיחֽוֹ׃ס","kĕ̇⁠ʼarĕbá̇ʻi֥ym ʼe֖lep ẖàlẇẕé֣y ha⁠ẕá̇bá֑ʼ ʻábĕr֞ẇ li⁠pĕné֤y yĕhwáh֙ la⁠mi̇lĕẖámá֔h ʼe֖l ʻaֽrĕb֥wòţ yĕriyẖֽwò׃s"],[4,14,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא גִּדַּ֤ל יְהוָה֙ אֶת־יְהוֹשֻׁ֔עַ בְּ⁠עֵינֵ֖י כָּל־יִשְׂרָאֵ֑ל וַ⁠יִּֽרְא֣וּ אֹת֔⁠וֹ כַּ⁠אֲשֶׁ֛ר יָרְא֥וּ אֶת־מֹשֶׁ֖ה כָּל־יְמֵ֥י חַיָּֽי⁠ו׃פ","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ gi̇dȧ֤l yĕhwáh֙ ʼeţ-yĕhwòşǔ֔ʻa bĕ̇⁠ʻéyné֖y ká̇l-yişĕ̂ráʼé֑l wa⁠yiֽ̇rĕʼ֣ẇ ʼòţ֔⁠wò kȧ⁠ʼàşě֛r yárĕʼ֥ẇ ʼeţ-mòşě֖h ká̇l-yĕmé֥y ẖayáֽ̇y⁠w׃p"],[4,15,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה אֶל־יְהוֹשֻׁ֖עַ לֵ⁠אמֹֽר׃","wa⁠yò֣̇ʼmer yĕhwá֔h ʼel-yĕhwòşǔ֖ʻa lé⁠ʼmòֽr׃"],[4,16,"צַוֵּה֙ אֶת־הַ⁠כֹּ֣הֲנִ֔ים נֹשְׂאֵ֖י אֲר֣וֹן הָ⁠עֵד֑וּת וְ⁠יַעֲל֖וּ מִן־הַ⁠יַּרְדֵּֽן׃","ẕawé̇h֙ ʼeţ-ha⁠kò֣̇hàni֔ym nòşĕ̂ʼé֖y ʼàr֣wòn há⁠ʻéd֑ẇţ wĕ⁠yaʻàl֖ẇ min-ha⁠yȧrĕdéֽ̇n׃"],[4,17,"וַ⁠יְצַ֣ו יְהוֹשֻׁ֔עַ אֶת־הַ⁠כֹּהֲנִ֖ים לֵ⁠אמֹ֑ר עֲל֖וּ מִן־הַ⁠יַּרְדֵּֽן׃","wa⁠yĕẕa֣w yĕhwòşǔ֔ʻa ʼeţ-ha⁠kò̇hàni֖ym lé⁠ʼmò֑r ʻàl֖ẇ min-ha⁠yȧrĕdéֽ̇n׃"],[4,18,"וַ֠⁠יְהִי ב⁠עלות הַ⁠כֹּהֲנִ֜ים נֹשְׂאֵ֨י אֲר֤וֹן בְּרִית־יְהוָה֙ מִ⁠תּ֣וֹךְ הַ⁠יַּרְדֵּ֔ן נִתְּק֗וּ כַּפּוֹת֙ רַגְלֵ֣י הַ⁠כֹּהֲנִ֔ים אֶ֖ל הֶ⁠חָרָבָ֑ה וַ⁠יָּשֻׁ֤בוּ מֵֽי־הַ⁠יַּרְדֵּן֙ לִ⁠מְקוֹמָ֔⁠ם וַ⁠יֵּלְכ֥וּ כִ⁠תְמוֹל־שִׁלְשׁ֖וֹם עַל־כָּל־גְּדוֹתָֽי⁠ו׃","wa֠⁠yĕhiy b⁠ʻlwţ ha⁠kò̇hàni֜ym nòşĕ̂ʼé֨y ʼàr֤wòn bĕ̇riyţ-yĕhwáh֙ mi⁠ţ֣̇wòkĕ ha⁠yȧrĕdé̇֔n niţĕ̇q֗ẇ kȧṗwòţ֙ ragĕlé֣y ha⁠kò̇hàni֔ym ʼe֖l he⁠ẖárábá֑h wa⁠yá̇şǔ֤bẇ méֽy-ha⁠yȧrĕdé̇n֙ li⁠mĕqwòmá֔⁠m wa⁠yé̇lĕk֥ẇ ki⁠ţĕmwòl-şǐlĕş֖̌wòm ʻal-ká̇l-gĕ̇dwòţáֽy⁠w׃"],[4,19,"וְ⁠הָ⁠עָ֗ם עָלוּ֙ מִן־הַ⁠יַּרְדֵּ֔ן בֶּ⁠עָשׂ֖וֹר לַ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֑וֹן וַֽ⁠יַּחֲנוּ֙ בַּ⁠גִּלְגָּ֔ל בִּ⁠קְצֵ֖ה מִזְרַ֥ח יְרִיחֽוֹ׃","wĕ⁠há⁠ʻá֗m ʻálẇ֙ min-ha⁠yȧrĕdé̇֔n bė⁠ʻáş֖̂wòr la⁠ẖò֣deş̌ há⁠riʼş֑̌wòn waֽ⁠yȧẖànẇ֙ bȧ⁠gi̇lĕgá̇֔l bi̇⁠qĕẕé֖h mizĕra֥ẖ yĕriyẖֽwò׃"],[4,20,"וְ⁠אֵת֩ שְׁתֵּ֨ים עֶשְׂרֵ֤ה הָֽ⁠אֲבָנִים֙ הָ⁠אֵ֔לֶּה אֲשֶׁ֥ר לָקְח֖וּ מִן־הַ⁠יַּרְדֵּ֑ן הֵקִ֥ים יְהוֹשֻׁ֖עַ בַּ⁠גִּלְגָּֽל׃","wĕ⁠ʼéţ֩ şĕ̌ţé̇֨ym ʻeşĕ̂ré֤h háֽ⁠ʼàbániym֙ há⁠ʼé֔lėh ʼàşě֥r láqĕẖ֖ẇ min-ha⁠yȧrĕdé֑̇n héqi֥ym yĕhwòşǔ֖ʻa bȧ⁠gi̇lĕgáֽ̇l׃"],[4,21,"וַ⁠יֹּ֛אמֶר אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר אֲשֶׁר֩ יִשְׁאָל֨וּ⁠ן בְּנֵי⁠כֶ֤ם מָחָר֙ אֶת־אֲבוֹתָ֣⁠ם לֵ⁠אמֹ֔ר מָ֖ה הָ⁠אֲבָנִ֥ים הָ⁠אֵֽלֶּה׃","wa⁠yò֛̇ʼmer ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r ʼàşěr֩ yişĕ̌ʼál֨ẇ⁠n bĕ̇néy⁠ke֤m máẖár֙ ʼeţ-ʼàbwòţá֣⁠m lé⁠ʼmò֔r má֖h há⁠ʼàbáni֥ym há⁠ʼéֽlėh׃"],[4,22,"וְ⁠הוֹדַעְתֶּ֖ם אֶת־בְּנֵי⁠כֶ֣ם לֵ⁠אמֹ֑ר בַּ⁠יַּבָּשָׁה֙ עָבַ֣ר יִשְׂרָאֵ֔ל אֶת־הַ⁠יַּרְדֵּ֖ן הַ⁠זֶּֽה׃","wĕ⁠hwòdaʻĕţė֖m ʼeţ-bĕ̇néy⁠ke֣m lé⁠ʼmò֑r bȧ⁠yȧbá̇şá̌h֙ ʻába֣r yişĕ̂ráʼé֔l ʼeţ-ha⁠yȧrĕdé֖̇n ha⁠zėֽh׃"],[4,23,"אֲשֶׁר־הוֹבִישׁ֩ יְהוָ֨ה אֱלֹהֵי⁠כֶ֜ם אֶת־מֵ֧י הַ⁠יַּרְדֵּ֛ן מִ⁠פְּנֵי⁠כֶ֖ם עַֽד־עָבְרְ⁠כֶ֑ם כַּ⁠אֲשֶׁ֣ר עָשָׂה֩ יְהוָ֨ה אֱלֹהֵי⁠כֶ֧ם לְ⁠יַם־ס֛וּף אֲשֶׁר־הוֹבִ֥ישׁ מִ⁠פָּנֵ֖י⁠נוּ עַד־עָבְרֵֽ⁠נוּ׃","ʼàşěr-hwòbiyş̌֩ yĕhwá֨h ʼèlòhéy⁠ke֜m ʼeţ-mé֧y ha⁠yȧrĕdé֛̇n mi⁠pĕ̇néy⁠ke֖m ʻaֽd-ʻábĕrĕ⁠ke֑m kȧ⁠ʼàşě֣r ʻáşá̂h֩ yĕhwá֨h ʼèlòhéy⁠ke֧m lĕ⁠yam-s֛ẇp ʼàşěr-hwòbi֥yş̌ mi⁠pá̇né֖y⁠nẇ ʻad-ʻábĕréֽ⁠nẇ׃"],[4,24,"לְ֠מַעַן דַּ֜עַת כָּל־עַמֵּ֤י הָ⁠אָ֨רֶץ֙ אֶת־יַ֣ד יְהוָ֔ה כִּ֥י חֲזָקָ֖ה הִ֑יא לְמַ֧עַן יְרָאתֶ֛ם אֶת־יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם כָּל־הַ⁠יָּמִֽים׃ס","lĕ֠maʻan dȧ֜ʻaţ ká̇l-ʻamé֤̇y há⁠ʼá֨reẕ֙ ʼeţ-ya֣d yĕhwá֔h ki֥̇y ẖàzáqá֖h hi֑yʼ lĕma֧ʻan yĕráʼţe֛m ʼeţ-yĕhwá֥h ʼèlòhéy⁠ke֖m ká̇l-ha⁠yá̇miֽym׃s"],[5,1,"וַ⁠יְהִ֣י כִ⁠שְׁמֹ֣עַ כָּל־מַלְכֵ֣י הָ⁠אֱמֹרִ֡י אֲשֶׁר֩ בְּ⁠עֵ֨בֶר הַ⁠יַּרְדֵּ֜ן יָ֗מָּ⁠ה וְ⁠כָל־מַלְכֵ֤י הַֽ⁠כְּנַעֲנִי֙ אֲשֶׁ֣ר עַל־הַ⁠יָּ֔ם אֵ֠ת אֲשֶׁר־הוֹבִ֨ישׁ יְהוָ֜ה אֶת־מֵ֧י הַ⁠יַּרְדֵּ֛ן מִ⁠פְּנֵ֥י בְנֵֽי־יִשְׂרָאֵ֖ל עַד־עבר⁠נו וַ⁠יִּמַּ֣ס לְבָבָ֗⁠ם וְ⁠לֹא־הָ֨יָה בָ֥⁠ם עוֹד֙ ר֔וּחַ מִ⁠פְּנֵ֖י בְּנֵֽי־יִשְׂרָאֵֽל׃ס","wa⁠yĕhi֣y ki⁠şĕ̌mò֣ʻa ká̇l-malĕké֣y há⁠ʼèmòri֡y ʼàşěr֩ bĕ̇⁠ʻé֨ber ha⁠yȧrĕdé̇֜n yá֗má̇⁠h wĕ⁠kál-malĕké֤y haֽ⁠kĕ̇naʻàniy֙ ʼàşě֣r ʻal-ha⁠yá̇֔m ʼé֠ţ ʼàşěr-hwòbi֨yş̌ yĕhwá֜h ʼeţ-mé֧y ha⁠yȧrĕdé֛̇n mi⁠pĕ̇né֥y bĕnéֽy-yişĕ̂ráʼé֖l ʻad-ʻbr⁠nw wa⁠yi̇mȧ֣s lĕbábá֗⁠m wĕ⁠lòʼ-há֨yáh bá֥⁠m ʻwòd֙ r֔ẇẖa mi⁠pĕ̇né֖y bĕ̇néֽy-yişĕ̂ráʼéֽl׃s"],[5,2,"בָּ⁠עֵ֣ת הַ⁠הִ֗יא אָמַ֤ר יְהוָה֙ אֶל־יְהוֹשֻׁ֔עַ עֲשֵׂ֥ה לְ⁠ךָ֖ חַֽרְב֣וֹת צֻרִ֑ים וְ⁠שׁ֛וּב מֹ֥ל אֶת־בְּנֵֽי־יִשְׂרָאֵ֖ל שֵׁנִֽית׃","bá̇⁠ʻé֣ţ ha⁠hi֗yʼ ʼáma֤r yĕhwáh֙ ʼel-yĕhwòşǔ֔ʻa ʻàşé֥̂h lĕ⁠ká֖ ẖaֽrĕb֣wòţ ẕuri֑ym wĕ⁠ş֛̌ẇb mò֥l ʼeţ-bĕ̇néֽy-yişĕ̂ráʼé֖l şé̌niֽyţ׃"],[5,3,"וַ⁠יַּעַשׂ־ל֥⁠וֹ יְהוֹשֻׁ֖עַ חַֽרְב֣וֹת צֻרִ֑ים וַ⁠יָּ֨מָל֙ אֶת־בְּנֵ֣י יִשְׂרָאֵ֔ל אֶל־גִּבְעַ֖ת הָ⁠עֲרָלֽוֹת׃","wa⁠yȧʻaş̂-l֥⁠wò yĕhwòşǔ֖ʻa ẖaֽrĕb֣wòţ ẕuri֑ym wa⁠yá̇֨mál֙ ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֔l ʼel-gi̇bĕʻa֖ţ há⁠ʻàrálֽwòţ׃"],[5,4,"וְ⁠זֶ֥ה הַ⁠דָּבָ֖ר אֲשֶׁר־מָ֣ל יְהוֹשֻׁ֑עַ כָּל־הָ⁠עָ֣ם הַ⁠יֹּצֵא֩ מִ⁠מִּצְרַ֨יִם הַ⁠זְּכָרִ֜ים כֹּ֣ל ׀ אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֗ה מֵ֤תוּ בַ⁠מִּדְבָּר֙ בַּ⁠דֶּ֔רֶךְ בְּ⁠צֵאתָ֖⁠ם מִ⁠מִּצְרָֽיִם׃","wĕ⁠ze֥h ha⁠dá̇bá֖r ʼàşěr-má֣l yĕhwòşǔ֑ʻa ká̇l-há⁠ʻá֣m ha⁠yò̇ẕéʼ֩ mi⁠mi̇ẕĕra֨yim ha⁠zĕ̇kári֜ym kò֣̇l ׀ ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֗h mé֤ţẇ ba⁠mi̇dĕbá̇r֙ bȧ⁠dė֔rekĕ bĕ̇⁠ẕéʼţá֖⁠m mi⁠mi̇ẕĕráֽyim׃"],[5,5,"כִּֽי־מֻלִ֣ים הָי֔וּ כָּל־הָ⁠עָ֖ם הַ⁠יֹּֽצְאִ֑ים וְ⁠כָל־הָ֠⁠עָם הַ⁠יִּלֹּדִ֨ים בַּ⁠מִּדְבָּ֥ר בַּ⁠דֶּ֛רֶךְ בְּ⁠צֵאתָ֥⁠ם מִ⁠מִּצְרַ֖יִם לֹא־מָֽלוּ׃","kiֽ̇y-muli֣ym háy֔ẇ ká̇l-há⁠ʻá֖m ha⁠yòֽ̇ẕĕʼi֑ym wĕ⁠kál-há֠⁠ʻám ha⁠yi̇lò̇di֨ym bȧ⁠mi̇dĕbá֥̇r bȧ⁠dė֛rekĕ bĕ̇⁠ẕéʼţá֥⁠m mi⁠mi̇ẕĕra֖yim lòʼ-máֽlẇ׃"],[5,6,"כִּ֣י ׀ אַרְבָּעִ֣ים שָׁנָ֗ה הָלְכ֣וּ בְנֵֽי־יִשְׂרָאֵל֮ בַּ⁠מִּדְבָּר֒ עַד־תֹּ֨ם כָּל־הַ⁠גּ֜וֹי אַנְשֵׁ֤י הַ⁠מִּלְחָמָה֙ הַ⁠יֹּצְאִ֣ים מִ⁠מִּצְרַ֔יִם אֲשֶׁ֥ר לֹֽא־שָׁמְע֖וּ בְּ⁠ק֣וֹל יְהוָ֑ה אֲשֶׁ֨ר נִשְׁבַּ֤ע יְהוָה֙ לָ⁠הֶ֔ם לְ⁠בִלְתִּ֞י הַרְאוֹתָ֣⁠ם אֶת־הָ⁠אָ֗רֶץ אֲשֶׁר֩ נִשְׁבַּ֨ע יְהוָ֤ה לַֽ⁠אֲבוֹתָ⁠ם֙ לָ֣⁠תֶת לָ֔⁠נוּ אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָֽשׁ׃","ki֣̇y ׀ ʼarĕbá̇ʻi֣ym şá̌ná֗h hálĕk֣ẇ bĕnéֽy-yişĕ̂ráʼél֮ bȧ⁠mi̇dĕbá̇r֒ ʻad-ţò̇֨m ká̇l-ha⁠ġ֜wòy ʼanĕşé֤̌y ha⁠mi̇lĕẖámáh֙ ha⁠yò̇ẕĕʼi֣ym mi⁠mi̇ẕĕra֔yim ʼàşě֥r lòֽʼ-şá̌mĕʻ֖ẇ bĕ̇⁠q֣wòl yĕhwá֑h ʼàşě֨r nişĕ̌bȧ֤ʻ yĕhwáh֙ lá⁠he֔m lĕ⁠bilĕţi̇֞y harĕʼwòţá֣⁠m ʼeţ-há⁠ʼá֗reẕ ʼàşěr֩ nişĕ̌bȧ֨ʻ yĕhwá֤h lֽa⁠ʼàbwòţá⁠m֙ lá֣⁠ţeţ lá֔⁠nẇ ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbáֽş̌׃"],[5,7,"וְ⁠אֶת־בְּנֵי⁠הֶם֙ הֵקִ֣ים תַּחְתָּ֔⁠ם אֹתָ֖⁠ם מָ֣ל יְהוֹשֻׁ֑עַ כִּי־עֲרֵלִ֣ים הָי֔וּ כִּ֛י לֹא־מָ֥לוּ אוֹתָ֖⁠ם בַּ⁠דָּֽרֶךְ׃","wĕ⁠ʼeţ-bĕ̇néy⁠hem֙ héqi֣ym ţȧẖĕţá̇֔⁠m ʼòţá֖⁠m má֣l yĕhwòşǔ֑ʻa ki̇y-ʻàréli֣ym háy֔ẇ ki֛̇y lòʼ-má֥lẇ ʼwòţá֖⁠m bȧ⁠dáֽ̇rekĕ׃"],[5,8,"וַ⁠יְהִ֛י כַּ⁠אֲשֶׁר־תַּ֥מּוּ כָל־הַ⁠גּ֖וֹי לְ⁠הִמּ֑וֹל וַ⁠יֵּשְׁב֥וּ תַחְתָּ֛⁠ם בַּֽ⁠מַּחֲנֶ֖ה עַ֥ד חֲיוֹתָֽ⁠ם׃פ","wa⁠yĕhi֛y kȧ⁠ʼàşěr-ţȧ֥ṁẇ kál-ha⁠ġ֖wòy lĕ⁠hiṁ֑wòl wa⁠yé̇şĕ̌b֥ẇ ţaẖĕţá֛̇⁠m bȧֽ⁠mȧẖàne֖h ʻa֥d ẖàywòţáֽ⁠m׃p"],[5,9,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־יְהוֹשֻׁ֔עַ הַ⁠יּ֗וֹם גַּלּ֛וֹתִי אֶת־חֶרְפַּ֥ת מִצְרַ֖יִם מֵ⁠עֲלֵי⁠כֶ֑ם וַ⁠יִּקְרָ֞א שֵׁ֣ם הַ⁠מָּק֤וֹם הַ⁠הוּא֙ גִּלְגָּ֔ל עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-yĕhwòşǔ֔ʻa ha⁠ẏ֗wòm gȧl֛̇wòţiy ʼeţ-ẖerĕpȧ֥ţ miẕĕra֖yim mé⁠ʻàléy⁠ke֑m wa⁠yi̇qĕrá֞ʼ şé֣̌m ha⁠má̇q֤wòm ha⁠hẇʼ֙ gi̇lĕgá̇֔l ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[5,10,"וַ⁠יַּחֲנ֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל בַּ⁠גִּלְגָּ֑ל וַ⁠יַּעֲשׂ֣וּ אֶת־הַ⁠פֶּ֡סַח בְּ⁠אַרְבָּעָה֩ עָשָׂ֨ר י֥וֹם לַ⁠חֹ֛דֶשׁ בָּ⁠עֶ֖רֶב בְּ⁠עַֽרְב֥וֹת יְרִיחֽוֹ׃","wa⁠yȧẖàn֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l bȧ⁠gi̇lĕgá֑̇l wa⁠yȧʻàş֣̂ẇ ʼeţ-ha⁠pė֡saẖ bĕ̇⁠ʼarĕbá̇ʻáh֩ ʻáşá̂֨r y֥wòm la⁠ẖò֛deş̌ bá̇⁠ʻe֖reb bĕ̇⁠ʻaֽrĕb֥wòţ yĕriyẖֽwò׃"],[5,11,"וַ⁠יֹּ֨אכְל֜וּ מֵ⁠עֲב֥וּר הָ⁠אָ֛רֶץ מִ⁠מָּֽחֳרַ֥ת הַ⁠פֶּ֖סַח מַצּ֣וֹת וְ⁠קָל֑וּי בְּ⁠עֶ֖צֶם הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yò̇֨ʼkĕl֜ẇ mé⁠ʻàb֥ẇr há⁠ʼá֛reẕ mi⁠máֽ̇ẖora֥ţ ha⁠pė֖saẖ maẕ֣̇wòţ wĕ⁠qál֑ẇy bĕ̇⁠ʻe֖ẕem ha⁠ẏ֥wòm ha⁠zėֽh׃"],[5,12,"וַ⁠יִּשְׁבֹּ֨ת הַ⁠מָּ֜ן מִֽ⁠מָּחֳרָ֗ת בְּ⁠אָכְלָ⁠ם֙ מֵ⁠עֲב֣וּר הָ⁠אָ֔רֶץ וְ⁠לֹא־הָ֥יָה ע֛וֹד לִ⁠בְנֵ֥י יִשְׂרָאֵ֖ל מָ֑ן וַ⁠יֹּאכְל֗וּ מִ⁠תְּבוּאַת֙ אֶ֣רֶץ כְּנַ֔עַן בַּ⁠שָּׁנָ֖ה הַ⁠הִֽיא׃ס","wa⁠yi̇şĕ̌bò̇֨ţ ha⁠má̇֜n miֽ⁠má̇ẖorá֗ţ bĕ̇⁠ʼákĕlá⁠m֙ mé⁠ʻàb֣ẇr há⁠ʼá֔reẕ wĕ⁠lòʼ-há֥yáh ʻ֛wòd li⁠bĕné֥y yişĕ̂ráʼé֖l má֑n wa⁠yò̇ʼkĕl֗ẇ mi⁠ţĕ̇bẇʼaţ֙ ʼe֣reẕ kĕ̇na֔ʻan bȧ⁠şá̇̌ná֖h ha⁠hiֽyʼ׃s"],[5,13,"וַ⁠יְהִ֗י בִּֽ⁠הְי֣וֹת יְהוֹשֻׁעַ֮ בִּ⁠ירִיחוֹ֒ וַ⁠יִּשָּׂ֤א עֵינָי⁠ו֙ וַ⁠יַּ֔רְא וְ⁠הִנֵּה־אִישׁ֙ עֹמֵ֣ד לְ⁠נֶגְדּ֔⁠וֹ וְ⁠חַרְבּ֥⁠וֹ שְׁלוּפָ֖ה בְּ⁠יָד֑⁠וֹ וַ⁠יֵּ֨לֶךְ יְהוֹשֻׁ֤עַ אֵלָי⁠ו֙ וַ⁠יֹּ֣אמֶר ל֔⁠וֹ הֲ⁠לָ֥⁠נוּ אַתָּ֖ה אִם־לְ⁠צָרֵֽי⁠נוּ׃","wa⁠yĕhi֗y biֽ̇⁠hĕy֣wòţ yĕhwòşǔʻa֮ bi̇⁠yriyẖwò֒ wa⁠yi̇şá֤̇̂ʼ ʻéynáy⁠w֙ wa⁠yȧ֔rĕʼ wĕ⁠hiné̇h-ʼiyş̌֙ ʻòmé֣d lĕ⁠negĕḋ֔⁠wò wĕ⁠ẖarĕḃ֥⁠wò şĕ̌lẇpá֖h bĕ̇⁠yád֑⁠wò wa⁠yé̇֨lekĕ yĕhwòşǔ֤ʻa ʼéláy⁠w֙ wa⁠yò֣̇ʼmer l֔⁠wò hà⁠lá֥⁠nẇ ʼaţá֖̇h ʼim-lĕ⁠ẕáréֽy⁠nẇ׃"],[5,14,"וַ⁠יֹּ֣אמֶר ׀ לֹ֗א כִּ֛י אֲנִ֥י שַׂר־צְבָֽא־יְהוָ֖ה עַתָּ֣ה בָ֑אתִי וַ⁠יִּפֹּל֩ יְהוֹשֻׁ֨עַ אֶל־פָּנָ֥י⁠ו אַ֨רְצָ⁠ה֙ וַ⁠יִּשְׁתָּ֔חוּ וַ⁠יֹּ֣אמֶר ל֔⁠וֹ מָ֥ה אֲדֹנִ֖⁠י מְדַבֵּ֥ר אֶל־עַבְדּֽ⁠וֹ׃","wa⁠yò֣̇ʼmer ׀ lò֗ʼ ki֛̇y ʼàni֥y şâr-ẕĕbáֽʼ-yĕhwá֖h ʻaţá֣̇h bá֑ʼţiy wa⁠yi̇pò̇l֩ yĕhwòşǔ֨ʻa ʼel-pá̇ná֥y⁠w ʼa֨rĕẕá⁠h֙ wa⁠yi̇şĕ̌ţá̇֔ẖẇ wa⁠yò֣̇ʼmer l֔⁠wò má֥h ʼàdòni֖⁠y mĕdabé֥̇r ʼel-ʻabĕḋֽ⁠wò׃"],[5,15,"וַ⁠יֹּאמֶר֩ שַׂר־צְבָ֨א יְהוָ֜ה אֶל־יְהוֹשֻׁ֗עַ שַׁל־נַֽעַלְ⁠ךָ֙ מֵ⁠עַ֣ל רַגְלֶ֔⁠ךָ כִּ֣י הַ⁠מָּק֗וֹם אֲשֶׁ֥ר אַתָּ֛ה עֹמֵ֥ד עָלָ֖י⁠ו קֹ֣דֶשׁ ה֑וּא וַ⁠יַּ֥עַשׂ יְהוֹשֻׁ֖עַ כֵּֽן׃","wa⁠yò̇ʼmer֩ şâr-ẕĕbá֨ʼ yĕhwá֜h ʼel-yĕhwòşǔ֗ʻa şǎl-naֽʻalĕ⁠ká֙ mé⁠ʻa֣l ragĕle֔⁠ká ki֣̇y ha⁠má̇q֗wòm ʼàşě֥r ʼaţá֛̇h ʻòmé֥d ʻálá֖y⁠w qò֣deş̌ h֑ẇʼ wa⁠yȧ֥ʻaş̂ yĕhwòşǔ֖ʻa kéֽ̇n׃"],[6,1,"וִֽ⁠ירִיחוֹ֙ סֹגֶ֣רֶת וּ⁠מְסֻגֶּ֔רֶת מִ⁠פְּנֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל אֵ֥ין יוֹצֵ֖א וְ⁠אֵ֥ין בָּֽא׃ס","wiֽ⁠yriyẖwò֙ sòge֣reţ ẇ⁠mĕsugė֔reţ mi⁠pĕ̇né֖y bĕ̇né֣y yişĕ̂ráʼé֑l ʼé֥yn ywòẕé֖ʼ wĕ⁠ʼé֥yn báֽ̇ʼ׃s"],[6,2,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־יְהוֹשֻׁ֔עַ רְאֵה֙ נָתַ֣תִּי בְ⁠יָֽדְ⁠ךָ֔ אֶת־יְרִיח֖וֹ וְ⁠אֶת־מַלְכָּ֑⁠הּ גִּבּוֹרֵ֖י הֶ⁠חָֽיִל׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-yĕhwòşǔ֔ʻa rĕʼéh֙ náţa֣ţi̇y bĕ⁠yáֽdĕ⁠ká֔ ʼeţ-yĕriyẖ֖wò wĕ⁠ʼeţ-malĕká֑̇⁠ḣ gi̇ḃwòré֖y he⁠ẖáֽyil׃"],[6,3,"וְ⁠סַבֹּתֶ֣ם אֶת־הָ⁠עִ֗יר כֹּ֚ל אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֔ה הַקֵּ֥יף אֶת־הָ⁠עִ֖יר פַּ֣עַם אֶחָ֑ת כֹּ֥ה תַעֲשֶׂ֖ה שֵׁ֥שֶׁת יָמִֽים׃","wĕ⁠sabò̇ţe֣m ʼeţ-há⁠ʻi֗yr kò֚̇l ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֔h haqé֥̇yp ʼeţ-há⁠ʻi֖yr pȧ֣ʻam ʼeẖá֑ţ kò֥̇h ţaʻàşê֖h şé֥̌şěţ yámiֽym׃"],[6,4,"וְ⁠שִׁבְעָ֣ה כֹהֲנִ֡ים יִשְׂאוּ֩ שִׁבְעָ֨ה שׁוֹפְר֤וֹת הַ⁠יּֽוֹבְלִים֙ לִ⁠פְנֵ֣י הָ⁠אָר֔וֹן וּ⁠בַ⁠יּוֹם֙ הַ⁠שְּׁבִיעִ֔י תָּסֹ֥בּוּ אֶת־הָ⁠עִ֖יר שֶׁ֣בַע פְּעָמִ֑ים וְ⁠הַ⁠כֹּ֣הֲנִ֔ים יִתְקְע֖וּ בַּ⁠שּׁוֹפָרֽוֹת׃","wĕ⁠şǐbĕʻá֣h kòhàni֡ym yişĕ̂ʼẇ֩ şǐbĕʻá֨h ş̌wòpĕr֤wòţ ha⁠ẏֽwòbĕliym֙ li⁠pĕné֣y há⁠ʼár֔wòn ẇ⁠ba⁠ẏwòm֙ ha⁠şĕ̇̌biyʻi֔y ţá̇sò֥ḃẇ ʼeţ-há⁠ʻi֖yr şě֣baʻ pĕ̇ʻámi֑ym wĕ⁠ha⁠kò֣̇hàni֔ym yiţĕqĕʻ֖ẇ bȧ⁠ş̇̌wòpárֽwòţ׃"],[6,5,"וְ⁠הָיָ֞ה בִּ⁠מְשֹׁ֣ךְ ׀ בְּ⁠קֶ֣רֶן הַ⁠יּוֹבֵ֗ל ב⁠שמע⁠כם אֶת־ק֣וֹל הַ⁠שּׁוֹפָ֔ר יָרִ֥יעוּ כָל־הָ⁠עָ֖ם תְּרוּעָ֣ה גְדוֹלָ֑ה וְ⁠נָ֨פְלָ֜ה חוֹמַ֤ת הָ⁠עִיר֙ תַּחְתֶּ֔י⁠הָ וְ⁠עָל֥וּ הָ⁠עָ֖ם אִ֥ישׁ נֶגְדּֽ⁠וֹ׃","wĕ⁠háyá֞h bi̇⁠mĕşò֣̌kĕ ׀ bĕ̇⁠qe֣ren ha⁠ẏwòbé֗l b⁠şmʻ⁠km ʼeţ-q֣wòl ha⁠ş̇̌wòpá֔r yári֥yʻẇ kál-há⁠ʻá֖m ţĕ̇rẇʻá֣h gĕdwòlá֑h wĕ⁠ná֨pĕlá֜h ẖwòma֤ţ há⁠ʻiyr֙ ţȧẖĕţė֔y⁠há wĕ⁠ʻál֥ẇ há⁠ʻá֖m ʼi֥yş̌ negĕḋֽ⁠wò׃"],[6,6,"וַ⁠יִּקְרָ֞א יְהוֹשֻׁ֤עַ בִּן־נוּן֙ אֶל־הַ⁠כֹּ֣הֲנִ֔ים וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם שְׂא֖וּ אֶת־אֲר֣וֹן הַ⁠בְּרִ֑ית וְ⁠שִׁבְעָ֣ה כֹֽהֲנִ֗ים יִשְׂאוּ֙ שִׁבְעָ֤ה שֽׁוֹפְרוֹת֙ יוֹבְלִ֔ים לִ⁠פְנֵ֖י אֲר֥וֹן יְהוָֽה׃","wa⁠yi̇qĕrá֞ʼ yĕhwòşǔ֤ʻa bi̇n-nẇn֙ ʼel-ha⁠kò֣̇hàni֔ym wa⁠yò֣̇ʼmer ʼàlé⁠he֔m şĕ̂ʼ֖ẇ ʼeţ-ʼàr֣wòn ha⁠bĕ̇ri֑yţ wĕ⁠şǐbĕʻá֣h kòֽhàni֗ym yişĕ̂ʼẇ֙ şǐbĕʻá֤h şֽ̌wòpĕrwòţ֙ ywòbĕli֔ym li⁠pĕné֖y ʼàr֥wòn yĕhwáֽh׃"],[6,7,"ו⁠יאמרו אֶל־הָ⁠עָ֔ם עִבְר֖וּ וְ⁠סֹ֣בּוּ אֶת־הָ⁠עִ֑יר וְ⁠הֶ֣⁠חָל֔וּץ יַעֲבֹ֕ר לִ⁠פְנֵ֖י אֲר֥וֹן יְהוָֽה׃","w⁠yʼmrw ʼel-há⁠ʻá֔m ʻibĕr֖ẇ wĕ⁠sò֣ḃẇ ʼeţ-há⁠ʻi֑yr wĕ⁠he֣⁠ẖál֔ẇẕ yaʻàbò֕r li⁠pĕné֖y ʼàr֥wòn yĕhwáֽh׃"],[6,8,"וַ⁠יְהִ֗י כֶּ⁠אֱמֹ֣ר יְהוֹשֻׁעַ֮ אֶל־הָ⁠עָם֒ וְ⁠שִׁבְעָ֣ה הַ⁠כֹּהֲנִ֡ים נֹשְׂאִים֩ שִׁבְעָ֨ה שׁוֹפְר֤וֹת הַ⁠יּֽוֹבְלִים֙ לִ⁠פְנֵ֣י יְהוָ֔ה עָבְר֕וּ וְ⁠תָקְע֖וּ בַּ⁠שּֽׁוֹפָר֑וֹת וַֽ⁠אֲרוֹן֙ בְּרִ֣ית יְהוָ֔ה הֹלֵ֖ךְ אַחֲרֵי⁠הֶֽם׃","wa⁠yĕhi֗y kė⁠ʼèmò֣r yĕhwòşǔʻa֮ ʼel-há⁠ʻám֒ wĕ⁠şǐbĕʻá֣h ha⁠kò̇hàni֡ym nòşĕ̂ʼiym֩ şǐbĕʻá֨h ş̌wòpĕr֤wòţ ha⁠ẏֽwòbĕliym֙ li⁠pĕné֣y yĕhwá֔h ʻábĕr֕ẇ wĕ⁠ţáqĕʻ֖ẇ bȧ⁠şֽ̇̌wòpár֑wòţ wֽa⁠ʼàrwòn֙ bĕ̇ri֣yţ yĕhwá֔h hòlé֖kĕ ʼaẖàréy⁠heֽm׃"],[6,9,"וְ⁠הֶ⁠חָל֣וּץ הֹלֵ֔ךְ לִ⁠פְנֵי֙ הַ⁠כֹּ֣הֲנִ֔ים תקעו הַ⁠שּֽׁוֹפָר֑וֹת וְ⁠הַֽ⁠מְאַסֵּ֗ף הֹלֵךְ֙ אַחֲרֵ֣י הָ⁠אָר֔וֹן הָל֖וֹךְ וְ⁠תָק֥וֹעַ בַּ⁠שּׁוֹפָרֽוֹת׃","wĕ⁠he⁠ẖál֣ẇẕ hòlé֔kĕ li⁠pĕnéy֙ ha⁠kò֣̇hàni֔ym ţqʻw ha⁠şֽ̇̌wòpár֑wòţ wĕ⁠haֽ⁠mĕʼasé̇֗p hòlékĕ֙ ʼaẖàré֣y há⁠ʼár֔wòn hál֖wòkĕ wĕ⁠ţáq֥wòʻa bȧ⁠ş̇̌wòpárֽwòţ׃"],[6,10,"וְ⁠אֶת־הָ⁠עָם֩ צִוָּ֨ה יְהוֹשֻׁ֜עַ לֵ⁠אמֹ֗ר לֹ֤א תָרִ֨יעוּ֙ וְ⁠לֹֽא־תַשְׁמִ֣יעוּ אֶת־קוֹלְ⁠כֶ֔ם וְ⁠לֹא־יֵצֵ֥א מִ⁠פִּי⁠כֶ֖ם דָּבָ֑ר עַ֠ד י֣וֹם אָמְרִ֧⁠י אֲלֵי⁠כֶ֛ם הָרִ֖יעוּ וַ⁠הֲרִיעֹתֶֽם׃","wĕ⁠ʼeţ-há⁠ʻám֩ ẕiwá̇֨h yĕhwòşǔ֜ʻa lé⁠ʼmò֗r lò֤ʼ ţári֨yʻẇ֙ wĕ⁠lòֽʼ-ţaşĕ̌mi֣yʻẇ ʼeţ-qwòlĕ⁠ke֔m wĕ⁠lòʼ-yéẕé֥ʼ mi⁠pi̇y⁠ke֖m dá̇bá֑r ʻa֠d y֣wòm ʼámĕri֧⁠y ʼàléy⁠ke֛m hári֖yʻẇ wa⁠hàriyʻòţeֽm׃"],[6,11,"וַ⁠יַּסֵּ֤ב אֲרוֹן־יְהוָה֙ אֶת־הָ⁠עִ֔יר הַקֵּ֖ף פַּ֣עַם אֶחָ֑ת וַ⁠יָּבֹ֨אוּ֙ הַֽ⁠מַּחֲנֶ֔ה וַ⁠יָּלִ֖ינוּ בַּֽ⁠מַּחֲנֶֽה׃פ","wa⁠yȧsé֤̇b ʼàrwòn-yĕhwáh֙ ʼeţ-há⁠ʻi֔yr haqé֖̇p pȧ֣ʻam ʼeẖá֑ţ wa⁠yá̇bò֨ʼẇ֙ haֽ⁠mȧẖàne֔h wa⁠yá̇li֖ynẇ bȧֽ⁠mȧẖàneֽh׃p"],[6,12,"וַ⁠יַּשְׁכֵּ֥ם יְהוֹשֻׁ֖עַ בַּ⁠בֹּ֑קֶר וַ⁠יִּשְׂא֥וּ הַ⁠כֹּהֲנִ֖ים אֶת־אֲר֥וֹן יְהוָֽה׃","wa⁠yȧşĕ̌ké֥̇m yĕhwòşǔ֖ʻa bȧ⁠bò֑̇qer wa⁠yi̇şĕ̂ʼ֥ẇ ha⁠kò̇hàni֖ym ʼeţ-ʼàr֥wòn yĕhwáֽh׃"],[6,13,"וְ⁠שִׁבְעָ֣ה הַ⁠כֹּהֲנִ֡ים נֹשְׂאִים֩ שִׁבְעָ֨ה שׁוֹפְר֜וֹת הַ⁠יֹּבְלִ֗ים לִ⁠פְנֵי֙ אֲר֣וֹן יְהוָ֔ה הֹלְכִ֣ים הָל֔וֹךְ וְ⁠תָקְע֖וּ בַּ⁠שּׁוֹפָר֑וֹת וְ⁠הֶ⁠חָלוּץ֙ הֹלֵ֣ךְ לִ⁠פְנֵי⁠הֶ֔ם וְ⁠הַֽ⁠מְאַסֵּ֗ף הֹלֵךְ֙ אַֽחֲרֵי֙ אֲר֣וֹן יְהוָ֔ה הולך וְ⁠תָק֥וֹעַ בַּ⁠שּׁוֹפָרֽוֹת׃","wĕ⁠şǐbĕʻá֣h ha⁠kò̇hàni֡ym nòşĕ̂ʼiym֩ şǐbĕʻá֨h ş̌wòpĕr֜wòţ ha⁠yò̇bĕli֗ym li⁠pĕnéy֙ ʼàr֣wòn yĕhwá֔h hòlĕki֣ym hál֔wòkĕ wĕ⁠ţáqĕʻ֖ẇ bȧ⁠ş̇̌wòpár֑wòţ wĕ⁠he⁠ẖálẇẕ֙ hòlé֣kĕ li⁠pĕnéy⁠he֔m wĕ⁠hֽa⁠mĕʼasé̇֗p hòlékĕ֙ ʼֽaẖàréy֙ ʼàr֣wòn yĕhwá֔h hwlk wĕ⁠ţáq֥wòʻa bȧ⁠ş̇̌wòpárֽwòţ׃"],[6,14,"וַ⁠יָּסֹ֨בּוּ אֶת־הָ⁠עִ֜יר בַּ⁠יּ֤וֹם הַ⁠שֵּׁנִי֙ פַּ֣עַם אַחַ֔ת וַ⁠יָּשֻׁ֖בוּ הַֽ⁠מַּחֲנֶ֑ה כֹּ֥ה עָשׂ֖וּ שֵׁ֥שֶׁת יָמִֽים׃","wa⁠yá̇sò֨ḃẇ ʼeţ-há⁠ʻi֜yr bȧ⁠ẏ֤wòm ha⁠şé̇̌niy֙ pȧ֣ʻam ʼaẖa֔ţ wa⁠yá̇şǔ֖bẇ haֽ⁠mȧẖàne֑h kò֥̇h ʻáş֖̂ẇ şé֥̌şěţ yámiֽym׃"],[6,15,"וַ⁠יְהִ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י וַ⁠יַּשְׁכִּ֨מוּ֙ כַּ⁠עֲל֣וֹת הַ⁠שַּׁ֔חַר וַ⁠יָּסֹ֧בּוּ אֶת־הָ⁠עִ֛יר כַּ⁠מִּשְׁפָּ֥ט הַ⁠זֶּ֖ה שֶׁ֣בַע פְּעָמִ֑ים רַ֚ק בַּ⁠יּ֣וֹם הַ⁠ה֔וּא סָבְב֥וּ אֶת־הָ⁠עִ֖יר שֶׁ֥בַע פְּעָמִֽים׃","wa⁠yĕhi֣y ׀ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y wa⁠yȧşĕ̌ki̇֨mẇ֙ kȧ⁠ʻàl֣wòţ ha⁠şȧ̌֔ẖar wa⁠yá̇sò֧ḃẇ ʼeţ-há⁠ʻi֛yr kȧ⁠mi̇şĕ̌pá֥̇t ha⁠zė֖h şě֣baʻ pĕ̇ʻámi֑ym ra֚q bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ sábĕb֥ẇ ʼeţ-há⁠ʻi֖yr şě֥baʻ pĕ̇ʻámiֽym׃"],[6,16,"וַ⁠יְהִי֙ בַּ⁠פַּ֣עַם הַ⁠שְּׁבִיעִ֔ית תָּקְע֥וּ הַ⁠כֹּהֲנִ֖ים בַּ⁠שּׁוֹפָר֑וֹת וַ⁠יֹּ֨אמֶר יְהוֹשֻׁ֤עַ אֶל־הָ⁠עָם֙ הָרִ֔יעוּ כִּֽי־נָתַ֧ן יְהוָ֛ה לָ⁠כֶ֖ם אֶת־הָ⁠עִֽיר׃","wa⁠yĕhiy֙ bȧ⁠pȧ֣ʻam ha⁠şĕ̇̌biyʻi֔yţ ţá̇qĕʻ֥ẇ ha⁠kò̇hàni֖ym bȧ⁠ş̇̌wòpár֑wòţ wa⁠yò̇֨ʼmer yĕhwòşǔ֤ʻa ʼel-há⁠ʻám֙ hári֔yʻẇ kiֽ̇y-náţa֧n yĕhwá֛h lá⁠ke֖m ʼeţ-há⁠ʻiֽyr׃"],[6,17,"וְ⁠הָיְתָ֨ה הָ⁠עִ֥יר חֵ֛רֶם הִ֥יא וְ⁠כָל־אֲשֶׁר־בָּ֖⁠הּ לַֽ⁠יהוָ֑ה רַק֩ רָחָ֨ב הַ⁠זּוֹנָ֜ה תִּֽחְיֶ֗ה הִ֚יא וְ⁠כָל־אֲשֶׁ֣ר אִתָּ֣⁠הּ בַּ⁠בַּ֔יִת כִּ֣י הֶחְבְּאַ֔תָה אֶת־הַ⁠מַּלְאָכִ֖ים אֲשֶׁ֥ר שָׁלָֽחְנוּ׃","wĕ⁠háyĕţá֨h há⁠ʻi֥yr ẖé֛rem hi֥yʼ wĕ⁠kál-ʼàşěr-bá֖̇⁠ḣ laֽ⁠yhwá֑h raq֩ ráẖá֨b ha⁠żwòná֜h ţiֽ̇ẖĕye֗h hi֚yʼ wĕ⁠kál-ʼàşě֣r ʼiţá֣̇⁠ḣ bȧ⁠bȧ֔yiţ ki֣̇y heẖĕbĕ̇ʼa֔ţáh ʼeţ-ha⁠mȧlĕʼáki֖ym ʼàşě֥r şá̌láֽẖĕnẇ׃"],[6,18,"וְ⁠רַק־אַתֶּם֙ שִׁמְר֣וּ מִן־הַ⁠חֵ֔רֶם פֶּֽן־תַּחֲרִ֖ימוּ וּ⁠לְקַחְתֶּ֣ם מִן־הַ⁠חֵ֑רֶם וְ⁠שַׂמְתֶּ֞ם אֶת־מַחֲנֵ֤ה יִשְׂרָאֵל֙ לְ⁠חֵ֔רֶם וַ⁠עֲכַרְתֶּ֖ם אוֹתֽ⁠וֹ׃","wĕ⁠raq-ʼaţėm֙ şǐmĕr֣ẇ min-ha⁠ẖé֔rem pėֽn-ţȧẖàri֖ymẇ ẇ⁠lĕqaẖĕţė֣m min-ha⁠ẖé֑rem wĕ⁠şâmĕţė֞m ʼeţ-maẖàné֤h yişĕ̂ráʼél֙ lĕ⁠ẖé֔rem wa⁠ʻàkarĕţė֖m ʼwòţֽ⁠wò׃"],[6,19,"וְ⁠כֹ֣ל ׀ כֶּ֣סֶף וְ⁠זָהָ֗ב וּ⁠כְלֵ֤י נְחֹ֨שֶׁת֙ וּ⁠בַרְזֶ֔ל קֹ֥דֶשׁ ה֖וּא לַֽ⁠יהוָ֑ה אוֹצַ֥ר יְהוָ֖ה יָבֽוֹא׃","wĕ⁠kò֣l ׀ kė֣sep wĕ⁠záhá֗b ẇ⁠kĕlé֤y nĕẖò֨şěţ֙ ẇ⁠barĕze֔l qò֥deş̌ h֖ẇʼ laֽ⁠yhwá֑h ʼwòẕa֥r yĕhwá֖h yábֽwòʼ׃"],[6,20,"וַ⁠יָּ֣רַע הָ⁠עָ֔ם וַֽ⁠יִּתְקְע֖וּ בַּ⁠שֹּֽׁפָר֑וֹת וַ⁠יְהִי֩ כִ⁠שְׁמֹ֨עַ הָ⁠עָ֜ם אֶת־ק֣וֹל הַ⁠שּׁוֹפָ֗ר וַ⁠יָּרִ֤יעוּ הָ⁠עָם֙ תְּרוּעָ֣ה גְדוֹלָ֔ה וַ⁠תִּפֹּ֨ל הַֽ⁠חוֹמָ֜ה תַּחְתֶּ֗י⁠הָ וַ⁠יַּ֨עַל הָ⁠עָ֤ם הָ⁠עִ֨ירָ⁠ה֙ אִ֣ישׁ נֶגְדּ֔⁠וֹ וַֽ⁠יִּלְכְּד֖וּ אֶת־הָ⁠עִֽיר׃","wa⁠yá֣̇raʻ há⁠ʻá֔m waֽ⁠yi̇ţĕqĕʻ֖ẇ bȧ⁠şòֽ̇̌pár֑wòţ wa⁠yĕhiy֩ ki⁠şĕ̌mò֨ʻa há⁠ʻá֜m ʼeţ-q֣wòl ha⁠ş̇̌wòpá֗r wa⁠yá̇ri֤yʻẇ há⁠ʻám֙ ţĕ̇rẇʻá֣h gĕdwòlá֔h wa⁠ţi̇pò̇֨l haֽ⁠ẖwòmá֜h ţȧẖĕţė֗y⁠há wa⁠yȧ֨ʻal há⁠ʻá֤m há⁠ʻi֨yrá⁠h֙ ʼi֣yş̌ negĕḋ֔⁠wò waֽ⁠yi̇lĕkĕ̇d֖ẇ ʼeţ-há⁠ʻiֽyr׃"],[6,21,"וַֽ⁠יַּחֲרִ֨ימוּ֙ אֶת־כָּל־אֲשֶׁ֣ר בָּ⁠עִ֔יר מֵ⁠אִישׁ֙ וְ⁠עַד־אִשָּׁ֔ה מִ⁠נַּ֖עַר וְ⁠עַד־זָקֵ֑ן וְ⁠עַ֨ד שׁ֥וֹר וָ⁠שֶׂ֛ה וַ⁠חֲמ֖וֹר לְ⁠פִי־חָֽרֶב׃","waֽ⁠yȧẖàri֨ymẇ֙ ʼeţ-ká̇l-ʼàşě֣r bá̇⁠ʻi֔yr mé⁠ʼiyş̌֙ wĕ⁠ʻad-ʼişá̇̌֔h mi⁠nȧ֖ʻar wĕ⁠ʻad-záqé֑n wĕ⁠ʻa֨d ş֥̌wòr wá⁠şê֛h wa⁠ẖàm֖wòr lĕ⁠piy-ẖáֽreb׃"],[6,22,"וְ⁠לִ⁠שְׁנַ֨יִם הָ⁠אֲנָשִׁ֜ים הַֽ⁠מְרַגְּלִ֤ים אֶת־הָ⁠אָ֨רֶץ֙ אָמַ֣ר יְהוֹשֻׁ֔עַ בֹּ֖אוּ בֵּית־הָ⁠אִשָּׁ֣ה הַ⁠זּוֹנָ֑ה וְ⁠הוֹצִ֨יאוּ מִ⁠שָּׁ֤ם אֶת־הָֽ⁠אִשָּׁה֙ וְ⁠אֶת־כָּל־אֲשֶׁר־לָ֔⁠הּ כַּ⁠אֲשֶׁ֥ר נִשְׁבַּעְתֶּ֖ם לָֽ⁠הּ׃","wĕ⁠li⁠şĕ̌na֨yim há⁠ʼànáşǐ֜ym haֽ⁠mĕragĕ̇li֤ym ʼeţ-há⁠ʼá֨reẕ֙ ʼáma֣r yĕhwòşǔ֔ʻa bò֖̇ʼẇ bé̇yţ-há⁠ʼişá֣̇̌h ha⁠żwòná֑h wĕ⁠hwòẕi֨yʼẇ mi⁠şá֤̇̌m ʼeţ-háֽ⁠ʼişá̇̌h֙ wĕ⁠ʼeţ-ká̇l-ʼàşěr-lá֔⁠ḣ kȧ⁠ʼàşě֥r nişĕ̌bȧʻĕţė֖m láֽ⁠ḣ׃"],[6,23,"וַ⁠יָּבֹ֜אוּ הַ⁠נְּעָרִ֣ים הַֽ⁠מְרַגְּלִ֗ים וַ⁠יֹּצִ֡יאוּ אֶת־רָ֠חָב וְ⁠אֶת־אָבִ֨י⁠הָ וְ⁠אֶת־אִמָּ֤⁠הּ וְ⁠אֶת־אַחֶ֨י⁠הָ֙ וְ⁠אֶת־כָּל־אֲשֶׁר־לָ֔⁠הּ וְ⁠אֵ֥ת כָּל־מִשְׁפְּחוֹתֶ֖י⁠הָ הוֹצִ֑יאוּ וַ⁠יַּ֨נִּיח֔וּ⁠ם מִ⁠ח֖וּץ לְ⁠מַחֲנֵ֥ה יִשְׂרָאֵֽל׃","wa⁠yá̇bò֜ʼẇ ha⁠nĕ̇ʻári֣ym haֽ⁠mĕragĕ̇li֗ym wa⁠yò̇ẕi֡yʼẇ ʼeţ-rá֠ẖáb wĕ⁠ʼeţ-ʼábi֨y⁠há wĕ⁠ʼeţ-ʼimá֤̇⁠ḣ wĕ⁠ʼeţ-ʼaẖe֨y⁠há֙ wĕ⁠ʼeţ-ká̇l-ʼàşěr-lá֔⁠ḣ wĕ⁠ʼé֥ţ ká̇l-mişĕ̌pĕ̇ẖwòţe֖y⁠há hwòẕi֑yʼẇ wa⁠yȧ֨ni̇yẖ֔ẇ⁠m mi⁠ẖ֖ẇẕ lĕ⁠maẖàné֥h yişĕ̂ráʼéֽl׃"],[6,24,"וְ⁠הָ⁠עִ֛יר שָׂרְפ֥וּ בָ⁠אֵ֖שׁ וְ⁠כָל־אֲשֶׁר־בָּ֑⁠הּ רַ֣ק ׀ הַ⁠כֶּ֣סֶף וְ⁠הַ⁠זָּהָ֗ב וּ⁠כְלֵ֤י הַ⁠נְּחֹ֨שֶׁת֙ וְ⁠הַ⁠בַּרְזֶ֔ל נָתְנ֖וּ אוֹצַ֥ר בֵּית־יְהוָֽה׃","wĕ⁠há⁠ʻi֛yr şá̂rĕp֥ẇ bá⁠ʼé֖ş̌ wĕ⁠kál-ʼàşěr-bá֑̇⁠ḣ ra֣q ׀ ha⁠kė֣sep wĕ⁠ha⁠zá̇há֗b ẇ⁠kĕlé֤y ha⁠nĕ̇ẖò֨şěţ֙ wĕ⁠ha⁠bȧrĕze֔l náţĕn֖ẇ ʼwòẕa֥r bé̇yţ-yĕhwáֽh׃"],[6,25,"וְֽ⁠אֶת־רָחָ֣ב הַ֠⁠זּוֹנָה וְ⁠אֶת־בֵּ֨ית אָבִ֤י⁠הָ וְ⁠אֶת־כָּל־אֲשֶׁר־לָ⁠הּ֙ הֶחֱיָ֣ה יְהוֹשֻׁ֔עַ וַ⁠תֵּ֨שֶׁב֙ בְּ⁠קֶ֣רֶב יִשְׂרָאֵ֔ל עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה כִּ֤י הֶחְבִּ֨יאָה֙ אֶת־הַ⁠מַּלְאָכִ֔ים אֲשֶׁר־שָׁלַ֥ח יְהוֹשֻׁ֖עַ לְ⁠רַגֵּ֥ל אֶת־יְרִיחֽוֹ׃פ","wĕֽ⁠ʼeţ-ráẖá֣b ha֠⁠żwònáh wĕ⁠ʼeţ-bé̇֨yţ ʼábi֤y⁠há wĕ⁠ʼeţ-ká̇l-ʼàşěr-lá⁠ḣ֙ heẖèyá֣h yĕhwòşǔ֔ʻa wa⁠ţé̇֨şěb֙ bĕ̇⁠qe֣reb yişĕ̂ráʼé֔l ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h ki֤̇y heẖĕbi̇֨yʼáh֙ ʼeţ-ha⁠mȧlĕʼáki֔ym ʼàşěr-şá̌la֥ẖ yĕhwòşǔ֖ʻa lĕ⁠ragé֥̇l ʼeţ-yĕriyẖֽwò׃p"],[6,26,"וַ⁠יַּשְׁבַּ֣ע יְהוֹשֻׁ֔עַ בָּ⁠עֵ֥ת הַ⁠הִ֖יא לֵ⁠אמֹ֑ר אָר֨וּר הָ⁠אִ֜ישׁ לִ⁠פְנֵ֣י יְהוָ֗ה אֲשֶׁ֤ר יָקוּם֙ וּ⁠בָנָ֞ה אֶת־הָ⁠עִ֤יר הַ⁠זֹּאת֙ אֶת־יְרִיח֔וֹ בִּ⁠בְכֹר֣⁠וֹ יְיַסְּדֶ֔⁠נָּה וּ⁠בִ⁠צְעִיר֖⁠וֹ יַצִּ֥יב דְּלָתֶֽי⁠הָ׃","wa⁠yȧşĕ̌bȧ֣ʻ yĕhwòşǔ֔ʻa bá̇⁠ʻé֥ţ ha⁠hi֖yʼ lé⁠ʼmò֑r ʼár֨ẇr há⁠ʼi֜yş̌ li⁠pĕné֣y yĕhwá֗h ʼàşě֤r yáqẇm֙ ẇ⁠báná֞h ʼeţ-há⁠ʻi֤yr ha⁠zò̇ʼţ֙ ʼeţ-yĕriyẖ֔wò bi̇⁠bĕkòr֣⁠wò yĕyasĕ̇de֔⁠ná̇h ẇ⁠bi⁠ẕĕʻiyr֖⁠wò yaẕi֥̇yb dĕ̇láţeֽy⁠há׃"],[6,27,"וַ⁠יְהִ֥י יְהוָ֖ה אֶת־יְהוֹשֻׁ֑עַ וַ⁠יְהִ֥י שָׁמְע֖⁠וֹ בְּ⁠כָל־הָ⁠אָֽרֶץ׃","wa⁠yĕhi֥y yĕhwá֖h ʼeţ-yĕhwòşǔ֑ʻa wa⁠yĕhi֥y şá̌mĕʻ֖⁠wò bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[7,1,"וַ⁠יִּמְעֲל֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל מַ֖עַל בַּ⁠חֵ֑רֶם וַ⁠יִּקַּ֡ח עָכָ֣ן בֶּן־כַּרְמִי֩ בֶן־זַבְדִּ֨י בֶן־זֶ֜רַח לְ⁠מַטֵּ֤ה יְהוּדָה֙ מִן־הַ⁠חֵ֔רֶם וַ⁠יִּֽחַר־אַ֥ף יְהוָ֖ה בִּ⁠בְנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yi̇mĕʻàl֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l ma֖ʻal bȧ⁠ẖé֑rem wa⁠yi̇qȧ֡ẖ ʻáká֣n bėn-kȧrĕmiy֩ ben-zabĕdi̇֨y ben-ze֜raẖ lĕ⁠maté֤̇h yĕhẇdáh֙ min-ha⁠ẖé֔rem wa⁠yiֽ̇ẖar-ʼa֥p yĕhwá֖h bi̇⁠bĕné֥y yişĕ̂ráʼéֽl׃"],[7,2,"וַ⁠יִּשְׁלַח֩ יְהוֹשֻׁ֨עַ אֲנָשִׁ֜ים מִֽ⁠ירִיח֗וֹ הָ⁠עַ֞י אֲשֶׁ֨ר עִם־בֵּ֥ית אָ֨וֶן֙ מִ⁠קֶּ֣דֶם לְ⁠בֵֽית־אֵ֔ל וַ⁠יֹּ֤אמֶר אֲלֵי⁠הֶם֙ לֵ⁠אמֹ֔ר עֲל֖וּ וְ⁠רַגְּל֣וּ אֶת־הָ⁠אָ֑רֶץ וַֽ⁠יַּעֲלוּ֙ הָ⁠אֲנָשִׁ֔ים וַֽ⁠יְרַגְּל֖וּ אֶת־הָ⁠עָֽי׃","wa⁠yi̇şĕ̌laẖ֩ yĕhwòşǔ֨ʻa ʼànáşǐ֜ym miֽ⁠yriyẖ֗wò há⁠ʻa֞y ʼàşě֨r ʻim-bé֥̇yţ ʼá֨wen֙ mi⁠qė֣dem lĕ⁠béֽyţ-ʼé֔l wa⁠yò֤̇ʼmer ʼàléy⁠hem֙ lé⁠ʼmò֔r ʻàl֖ẇ wĕ⁠ragĕ̇l֣ẇ ʼeţ-há⁠ʼá֑reẕ waֽ⁠yȧʻàlẇ֙ há⁠ʼànáşǐ֔ym waֽ⁠yĕragĕ̇l֖ẇ ʼeţ-há⁠ʻáֽy׃"],[7,3,"וַ⁠יָּשֻׁ֣בוּ אֶל־יְהוֹשֻׁ֗עַ וַ⁠יֹּאמְר֣וּ אֵלָי⁠ו֮ אַל־יַ֣עַל כָּל־הָ⁠עָם֒ כְּ⁠אַלְפַּ֣יִם אִ֗ישׁ א֚וֹ כִּ⁠שְׁלֹ֣שֶׁת אֲלָפִ֣ים אִ֔ישׁ יַעֲל֖וּ וְ⁠יַכּ֣וּ אֶת־הָ⁠עָ֑י אַל־תְּיַגַּע־שָׁ֨מָּ⁠ה֙ אֶת־כָּל־הָ⁠עָ֔ם כִּ֥י מְעַ֖ט הֵֽמָּה׃","wa⁠yá̇şǔ֣bẇ ʼel-yĕhwòşǔ֗ʻa wa⁠yò̇ʼmĕr֣ẇ ʼéláy⁠w֮ ʼal-ya֣ʻal ká̇l-há⁠ʻám֒ kĕ̇⁠ʼalĕpȧ֣yim ʼi֗yş̌ ʼ֚wò ki̇⁠şĕ̌lò֣şěţ ʼàlápi֣ym ʼi֔yş̌ yaʻàl֖ẇ wĕ⁠yak֣̇ẇ ʼeţ-há⁠ʻá֑y ʼal-ţĕ̇yagȧʻ-şá̌֨má̇⁠h֙ ʼeţ-ká̇l-há⁠ʻá֔m ki֥̇y mĕʻa֖t héֽmá̇h׃"],[7,4,"וַ⁠יַּעֲל֤וּ מִן־הָ⁠עָם֙ שָׁ֔מָּ⁠ה כִּ⁠שְׁלֹ֥שֶׁת אֲלָפִ֖ים אִ֑ישׁ וַ⁠יָּנֻ֕סוּ לִ⁠פְנֵ֖י אַנְשֵׁ֥י הָ⁠עָֽי׃","wa⁠yȧʻàl֤ẇ min-há⁠ʻám֙ şá̌֔má̇⁠h ki̇⁠şĕ̌lò֥şěţ ʼàlápi֖ym ʼi֑yş̌ wa⁠yá̇nu֕sẇ li⁠pĕné֖y ʼanĕşé֥̌y há⁠ʻáֽy׃"],[7,5,"וַ⁠יַּכּ֨וּ מֵ⁠הֶ֜ם אַנְשֵׁ֣י הָ⁠עַ֗י כִּ⁠שְׁלֹשִׁ֤ים וְ⁠שִׁשָּׁה֙ אִ֔ישׁ וַֽ⁠יִּרְדְּפ֞וּ⁠ם לִ⁠פְנֵ֤י הַ⁠שַּׁ֨עַר֙ עַד־הַ⁠שְּׁבָרִ֔ים וַ⁠יַּכּ֖וּ⁠ם בַּ⁠מּוֹרָ֑ד וַ⁠יִּמַּ֥ס לְבַב־הָ⁠עָ֖ם וַ⁠יְהִ֥י לְ⁠מָֽיִם׃","wa⁠yȧk̇֨ẇ mé⁠he֜m ʼanĕşé֣̌y há⁠ʻa֗y ki̇⁠şĕ̌lòşǐ֤ym wĕ⁠şǐşá̇̌h֙ ʼi֔yş̌ waֽ⁠yi̇rĕdĕ̇p֞ẇ⁠m li⁠pĕné֤y ha⁠şȧ̌֨ʻar֙ ʻad-ha⁠şĕ̇̌bári֔ym wa⁠yȧk֖̇ẇ⁠m bȧ⁠ṁwòrá֑d wa⁠yi̇mȧ֥s lĕbab-há⁠ʻá֖m wa⁠yĕhi֥y lĕ⁠máֽyim׃"],[7,6,"וַ⁠יִּקְרַ֨ע יְהוֹשֻׁ֜עַ שִׂמְלֹתָ֗י⁠ו וַ⁠יִּפֹּל֩ עַל־פָּנָ֨י⁠ו אַ֜רְצָ⁠ה לִ⁠פְנֵ֨י אֲר֤וֹן יְהוָה֙ עַד־הָ⁠עֶ֔רֶב ה֖וּא וְ⁠זִקְנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יַּעֲל֥וּ עָפָ֖ר עַל־רֹאשָֽׁ⁠ם׃","wa⁠yi̇qĕra֨ʻ yĕhwòşǔ֜ʻa şîmĕlòţá֗y⁠w wa⁠yi̇pò̇l֩ ʻal-pá̇ná֨y⁠w ʼa֜rĕẕá⁠h li⁠pĕné֨y ʼàr֤wòn yĕhwáh֙ ʻad-há⁠ʻe֔reb h֖ẇʼ wĕ⁠ziqĕné֣y yişĕ̂ráʼé֑l wa⁠yȧʻàl֥ẇ ʻápá֖r ʻal-ròʼşáֽ̌⁠m׃"],[7,7,"וַ⁠יֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֲהָ֣הּ ׀ אֲדֹנָ֣⁠י יְהוִ֗ה לָ֠⁠מָה הֵעֲבַ֨רְתָּ הַעֲבִ֜יר אֶת־הָ⁠עָ֤ם הַ⁠זֶּה֙ אֶת־הַ⁠יַּרְדֵּ֔ן לָ⁠תֵ֥ת אֹתָ֛⁠נוּ בְּ⁠יַ֥ד הָ⁠אֱמֹרִ֖י לְ⁠הַאֲבִידֵ֑⁠נוּ וְ⁠לוּ֙ הוֹאַ֣לְנוּ וַ⁠נֵּ֔שֶׁב בְּ⁠עֵ֖בֶר הַ⁠יַּרְדֵּֽן׃","wa⁠yò̇֨ʼmer yĕhwòşǔ֜ʻa ʼàhá֣ḣ ׀ ʼàdòná֣⁠y yĕhwi֗h lá֠⁠máh héʻàba֨rĕţá̇ haʻàbi֜yr ʼeţ-há⁠ʻá֤m ha⁠zėh֙ ʼeţ-ha⁠yȧrĕdé̇֔n lá⁠ţé֥ţ ʼòţá֛⁠nẇ bĕ̇⁠ya֥d há⁠ʼèmòri֖y lĕ⁠haʼàbiydé֑⁠nẇ wĕ⁠lẇ֙ hwòʼa֣lĕnẇ wa⁠né̇֔şěb bĕ̇⁠ʻé֖ber ha⁠yȧrĕdéֽ̇n׃"],[7,8,"בִּ֖י אֲדֹנָ֑⁠י מָ֣ה אֹמַ֔ר אַ֠חֲרֵי אֲשֶׁ֨ר הָפַ֧ךְ יִשְׂרָאֵ֛ל עֹ֖רֶף לִ⁠פְנֵ֥י אֹיְבָֽי⁠ו׃","bi֖̇y ʼàdòná֑⁠y má֣h ʼòma֔r ʼa֠ẖàréy ʼàşě֨r hápa֧kĕ yişĕ̂ráʼé֛l ʻò֖rep li⁠pĕné֥y ʼòyĕbáֽy⁠w׃"],[7,9,"וְ⁠יִשְׁמְע֣וּ הַֽ⁠כְּנַעֲנִ֗י וְ⁠כֹל֙ יֹשְׁבֵ֣י הָ⁠אָ֔רֶץ וְ⁠נָסַ֣בּוּ עָלֵ֔י⁠נוּ וְ⁠הִכְרִ֥יתוּ אֶת־שְׁמֵ֖⁠נוּ מִן־הָ⁠אָ֑רֶץ וּ⁠מַֽה־תַּעֲשֵׂ֖ה לְ⁠שִׁמְ⁠ךָ֥ הַ⁠גָּדֽוֹל׃ס","wĕ⁠yişĕ̌mĕʻ֣ẇ haֽ⁠kĕ̇naʻàni֗y wĕ⁠kòl֙ yòşĕ̌bé֣y há⁠ʼá֔reẕ wĕ⁠nása֣ḃẇ ʻálé֔y⁠nẇ wĕ⁠hikĕri֥yţẇ ʼeţ-şĕ̌mé֖⁠nẇ min-há⁠ʼá֑reẕ ẇ⁠maֽh-ţȧʻàşé֖̂h lĕ⁠şǐmĕ⁠ká֥ ha⁠gá̇dֽwòl׃s"],[7,10,"וַ⁠יֹּ֧אמֶר יְהוָ֛ה אֶל־יְהוֹשֻׁ֖עַ קֻ֣ם לָ֑⁠ךְ לָ֣⁠מָּה זֶּ֔ה אַתָּ֖ה נֹפֵ֥ל עַל־פָּנֶֽי⁠ךָ׃","wa⁠yò֧̇ʼmer yĕhwá֛h ʼel-yĕhwòşǔ֖ʻa qu֣m lá֑⁠kĕ lá֣⁠má̇h zė֔h ʼaţá֖̇h nòpé֥l ʻal-pá̇neֽy⁠ká׃"],[7,11,"חָטָא֙ יִשְׂרָאֵ֔ל וְ⁠גַם֙ עָבְר֣וּ אֶת־בְּרִיתִ֔⁠י אֲשֶׁ֥ר צִוִּ֖יתִי אוֹתָ֑⁠ם וְ⁠גַ֤ם לָֽקְחוּ֙ מִן־הַ⁠חֵ֔רֶם וְ⁠גַ֤ם גָּֽנְבוּ֙ וְ⁠גַ֣ם כִּֽחֲשׁ֔וּ וְ⁠גַ֖ם שָׂ֥מוּ בִ⁠כְלֵי⁠הֶֽם׃","ẖátáʼ֙ yişĕ̂ráʼé֔l wĕ⁠gam֙ ʻábĕr֣ẇ ʼeţ-bĕ̇riyţi֔⁠y ʼàşě֥r ẕiwi֖̇yţiy ʼwòţá֑⁠m wĕ⁠ga֤m láֽqĕẖẇ֙ min-ha⁠ẖé֔rem wĕ⁠ga֤m gáֽ̇nĕbẇ֙ wĕ⁠ga֣m kiֽ̇ẖàş̌֔ẇ wĕ⁠ga֖m şá֥̂mẇ bi⁠kĕléy⁠heֽm׃"],[7,12,"וְ⁠לֹ֨א יֻכְל֜וּ בְּנֵ֣י יִשְׂרָאֵ֗ל לָ⁠קוּם֙ לִ⁠פְנֵ֣י אֹיְבֵי⁠הֶ֔ם עֹ֗רֶף יִפְנוּ֙ לִ⁠פְנֵ֣י אֹֽיְבֵי⁠הֶ֔ם כִּ֥י הָי֖וּ לְ⁠חֵ֑רֶם לֹ֤א אוֹסִיף֙ לִֽ⁠הְי֣וֹת עִמָּ⁠כֶ֔ם אִם־לֹ֥א תַשְׁמִ֛ידוּ הַ⁠חֵ֖רֶם מִֽ⁠קִּרְבְּ⁠כֶֽם׃","wĕ⁠lò֨ʼ yukĕl֜ẇ bĕ̇né֣y yişĕ̂ráʼé֗l lá⁠qẇm֙ li⁠pĕné֣y ʼòyĕbéy⁠he֔m ʻò֗rep yipĕnẇ֙ li⁠pĕné֣y ʼòֽyĕbéy⁠he֔m ki֥̇y háy֖ẇ lĕ⁠ẖé֑rem lò֤ʼ ʼwòsiyp֙ liֽ⁠hĕy֣wòţ ʻimá̇⁠ke֔m ʼim-lò֥ʼ ţaşĕ̌mi֛ydẇ ha⁠ẖé֖rem miֽ⁠qi̇rĕbĕ̇⁠keֽm׃"],[7,13,"קֻ֚ם קַדֵּ֣שׁ אֶת־הָ⁠עָ֔ם וְ⁠אָמַרְתָּ֖ הִתְקַדְּשׁ֣וּ לְ⁠מָחָ֑ר כִּ֣י כֹה֩ אָמַ֨ר יְהוָ֜ה אֱלֹהֵ֣י יִשְׂרָאֵ֗ל חֵ֤רֶם בְּ⁠קִרְבְּ⁠ךָ֙ יִשְׂרָאֵ֔ל לֹ֣א תוּכַ֗ל לָ⁠קוּם֙ לִ⁠פְנֵ֣י אֹיְבֶ֔י⁠ךָ עַד־הֲסִירְ⁠כֶ֥ם הַ⁠חֵ֖רֶם מִֽ⁠קִּרְבְּ⁠כֶֽם׃","qu֚m qadé֣̇ş̌ ʼeţ-há⁠ʻá֔m wĕ⁠ʼámarĕţá֖̇ hiţĕqadĕ̇ş֣̌ẇ lĕ⁠máẖá֑r ki֣̇y kòh֩ ʼáma֨r yĕhwá֜h ʼèlòhé֣y yişĕ̂ráʼé֗l ẖé֤rem bĕ̇⁠qirĕbĕ̇⁠ká֙ yişĕ̂ráʼé֔l lò֣ʼ ţẇka֗l lá⁠qẇm֙ li⁠pĕné֣y ʼòyĕbe֔y⁠ká ʻad-hàsiyrĕ⁠ke֥m ha⁠ẖé֖rem miֽ⁠qi̇rĕbĕ̇⁠keֽm׃"],[7,14,"וְ⁠נִקְרַבְתֶּ֥ם בַּ⁠בֹּ֖קֶר לְ⁠שִׁבְטֵי⁠כֶ֑ם וְ⁠הָיָ֡ה הַ⁠שֵּׁבֶט֩ אֲשֶׁר־יִלְכְּדֶ֨⁠נּוּ יְהוָ֜ה יִקְרַ֣ב לַ⁠מִּשְׁפָּח֗וֹת וְ⁠הַ⁠מִּשְׁפָּחָ֞ה אֲשֶֽׁר־יִלְכְּדֶ֤⁠נָּה יְהוָה֙ תִּקְרַ֣ב לַ⁠בָּתִּ֔ים וְ⁠הַ⁠בַּ֨יִת֙ אֲשֶׁ֣ר יִלְכְּדֶ֣⁠נּוּ יְהוָ֔ה יִקְרַ֖ב לַ⁠גְּבָרִֽים׃","wĕ⁠niqĕrabĕţė֥m bȧ⁠bò֖̇qer lĕ⁠şǐbĕtéy⁠ke֑m wĕ⁠háyá֡h ha⁠şé̇̌bet֩ ʼàşěr-yilĕkĕ̇de֨⁠ṅẇ yĕhwá֜h yiqĕra֣b la⁠mi̇şĕ̌pá̇ẖ֗wòţ wĕ⁠ha⁠mi̇şĕ̌pá̇ẖá֞h ʼàşěֽr-yilĕkĕ̇de֤⁠ná̇h yĕhwáh֙ ţi̇qĕra֣b la⁠bá̇ţi̇֔ym wĕ⁠ha⁠bȧ֨yiţ֙ ʼàşě֣r yilĕkĕ̇de֣⁠ṅẇ yĕhwá֔h yiqĕra֖b la⁠gĕ̇báriֽym׃"],[7,15,"וְ⁠הָיָה֙ הַ⁠נִּלְכָּ֣ד בַּ⁠חֵ֔רֶם יִשָּׂרֵ֣ף בָּ⁠אֵ֔שׁ אֹת֖⁠וֹ וְ⁠אֶת־כָּל־אֲשֶׁר־ל֑⁠וֹ כִּ֤י עָבַר֙ אֶת־בְּרִ֣ית יְהוָ֔ה וְ⁠כִֽי־עָשָׂ֥ה נְבָלָ֖ה בְּ⁠יִשְׂרָאֵֽל׃","wĕ⁠háyáh֙ ha⁠ni̇lĕká֣̇d bȧ⁠ẖé֔rem yişá̇̂ré֣p bá̇⁠ʼé֔ş̌ ʼòţ֖⁠wò wĕ⁠ʼeţ-ká̇l-ʼàşěr-l֑⁠wò ki֤̇y ʻábar֙ ʼeţ-bĕ̇ri֣yţ yĕhwá֔h wĕ⁠kiֽy-ʻáşá֥̂h nĕbálá֖h bĕ̇⁠yişĕ̂ráʼéֽl׃"],[7,16,"וַ⁠יַּשְׁכֵּ֤ם יְהוֹשֻׁ֨עַ֙ בַּ⁠בֹּ֔קֶר וַ⁠יַּקְרֵ֥ב אֶת־יִשְׂרָאֵ֖ל לִ⁠שְׁבָטָ֑י⁠ו וַ⁠יִּלָּכֵ֖ד שֵׁ֥בֶט יְהוּדָֽה׃","wa⁠yȧşĕ̌ké֤̇m yĕhwòşǔ֨ʻa֙ bȧ⁠bò̇֔qer wa⁠yȧqĕré֥b ʼeţ-yişĕ̂ráʼé֖l li⁠şĕ̌bátá֑y⁠w wa⁠yi̇lá̇ké֖d şé֥̌bet yĕhẇdáֽh׃"],[7,17,"וַ⁠יַּקְרֵב֙ אֶת־מִשְׁפַּ֣חַת יְהוּדָ֔ה וַ⁠יִּלְכֹּ֕ד אֵ֖ת מִשְׁפַּ֣חַת הַ⁠זַּרְחִ֑י וַ⁠יַּקְרֵ֞ב אֶת־מִשְׁפַּ֤חַת הַ⁠זַּרְחִי֙ לַ⁠גְּבָרִ֔ים וַ⁠יִּלָּכֵ֖ד זַבְדִּֽי׃","wa⁠yȧqĕréb֙ ʼeţ-mişĕ̌pȧ֣ẖaţ yĕhẇdá֔h wa⁠yi̇lĕkò̇֕d ʼé֖ţ mişĕ̌pȧ֣ẖaţ ha⁠zȧrĕẖi֑y wa⁠yȧqĕré֞b ʼeţ-mişĕ̌pȧ֤ẖaţ ha⁠zȧrĕẖiy֙ la⁠gĕ̇bári֔ym wa⁠yi̇lá̇ké֖d zabĕdiֽ̇y׃"],[7,18,"וַ⁠יַּקְרֵ֥ב אֶת־בֵּית֖⁠וֹ לַ⁠גְּבָרִ֑ים וַ⁠יִּלָּכֵ֗ד עָכָ֞ן בֶּן־כַּרְמִ֧י בֶן־זַבְדִּ֛י בֶּן־זֶ֖רַח לְ⁠מַטֵּ֥ה יְהוּדָֽה׃","wa⁠yȧqĕré֥b ʼeţ-bé̇yţ֖⁠wò la⁠gĕ̇bári֑ym wa⁠yi̇lá̇ké֗d ʻáká֞n bėn-kȧrĕmi֧y ben-zabĕdi֛̇y bėn-ze֖raẖ lĕ⁠maté֥̇h yĕhẇdáֽh׃"],[7,19,"וַ⁠יֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֶל־עָכָ֗ן בְּנִ⁠י֙ שִֽׂים־נָ֣א כָב֗וֹד לַֽ⁠יהוָ֛ה אֱלֹהֵ֥י יִשְׂרָאֵ֖ל וְ⁠תֶן־ל֣⁠וֹ תוֹדָ֑ה וְ⁠הַגֶּד־נָ֥א לִ⁠י֙ מֶ֣ה עָשִׂ֔יתָ אַל־תְּכַחֵ֖ד מִמֶּֽ⁠נִּי׃","wa⁠yò̇֨ʼmer yĕhwòşǔ֜ʻa ʼel-ʻáká֗n bĕ̇ni⁠y֙ şîֽym-ná֣ʼ káb֗wòd laֽ⁠yhwá֛h ʼèlòhé֥y yişĕ̂ráʼé֖l wĕ⁠ţen-l֣⁠wò ţwòdá֑h wĕ⁠hagėd-ná֥ʼ li⁠y֙ me֣h ʻáşî֔yţá ʼal-ţĕ̇kaẖé֖d mimėֽ⁠ni̇y׃"],[7,20,"וַ⁠יַּ֧עַן עָכָ֛ן אֶת־יְהוֹשֻׁ֖עַ וַ⁠יֹּאמַ֑ר אָמְנָ֗ה אָנֹכִ֤י חָטָ֨אתִי֙ לַֽ⁠יהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל וְ⁠כָ⁠זֹ֥את וְ⁠כָ⁠זֹ֖את עָשִֽׂיתִי׃","wa⁠yȧ֧ʻan ʻáká֛n ʼeţ-yĕhwòşǔ֖ʻa wa⁠yò̇ʼma֑r ʼámĕná֗h ʼánòki֤y ẖátá֨ʼţiy֙ laֽ⁠yhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l wĕ⁠ká⁠zò֥ʼţ wĕ⁠ká⁠zò֖ʼţ ʻáşîֽyţiy׃"],[7,21,"ו⁠אראה בַ⁠שָּׁלָ֡ל אַדֶּ֣רֶת שִׁנְעָר֩ אַחַ֨ת טוֹבָ֜ה וּ⁠מָאתַ֧יִם שְׁקָלִ֣ים כֶּ֗סֶף וּ⁠לְשׁ֨וֹן זָהָ֤ב אֶחָד֙ חֲמִשִּׁ֤ים שְׁקָלִים֙ מִשְׁקָל֔⁠וֹ וָֽ⁠אֶחְמְדֵ֖⁠ם וָֽ⁠אֶקָּחֵ֑⁠ם וְ⁠הִנָּ֨⁠ם טְמוּנִ֥ים בָּ⁠אָ֛רֶץ בְּ⁠ת֥וֹךְ הָ⁠אָֽהֳלִ֖⁠י וְ⁠הַ⁠כֶּ֥סֶף תַּחְתֶּֽי⁠הָ׃","w⁠ʼrʼh ba⁠şá̇̌lá֡l ʼadė֣reţ şǐnĕʻár֩ ʼaẖa֨ţ twòbá֜h ẇ⁠máʼţa֧yim şĕ̌qáli֣ym kė֗sep ẇ⁠lĕş̌֨wòn záhá֤b ʼeẖád֙ ẖàmişi֤̇̌ym şĕ̌qáliym֙ mişĕ̌qál֔⁠wò wáֽ⁠ʼeẖĕmĕdé֖⁠m wáֽ⁠ʼeqá̇ẖé֑⁠m wĕ⁠hiná̇֨⁠m tĕmẇni֥ym bá̇⁠ʼá֛reẕ bĕ̇⁠ţ֥wòkĕ há⁠ʼֽáholi֖⁠y wĕ⁠ha⁠kė֥sep ţȧẖĕţėֽy⁠há׃"],[7,22,"וַ⁠יִּשְׁלַ֤ח יְהוֹשֻׁ֨עַ֙ מַלְאָכִ֔ים וַ⁠יָּרֻ֖צוּ הָ⁠אֹ֑הֱלָ⁠ה וְ⁠הִנֵּ֧ה טְמוּנָ֛ה בְּ⁠אָהֳל֖⁠וֹ וְ⁠הַ⁠כֶּ֥סֶף תַּחְתֶּֽי⁠הָ׃","wa⁠yi̇şĕ̌la֤ẖ yĕhwòşǔ֨ʻa֙ malĕʼáki֔ym wa⁠yá̇ru֖ẕẇ há⁠ʼò֑hèlá⁠h wĕ⁠hiné֧̇h tĕmẇná֛h bĕ̇⁠ʼáhol֖⁠wò wĕ⁠ha⁠kė֥sep ţȧẖĕţėֽy⁠há׃"],[7,23,"וַ⁠יִּקָּחוּ⁠ם֙ מִ⁠תּ֣וֹךְ הָ⁠אֹ֔הֶל וַ⁠יְבִאוּ⁠ם֙ אֶל־יְהוֹשֻׁ֔עַ וְ⁠אֶ֖ל כָּל־בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יַּצִּקֻ֖⁠ם לִ⁠פְנֵ֥י יְהוָֽה׃","wa⁠yi̇qá̇ẖẇ⁠m֙ mi⁠ţ֣̇wòkĕ há⁠ʼò֔hel wa⁠yĕbiʼẇ⁠m֙ ʼel-yĕhwòşǔ֔ʻa wĕ⁠ʼe֖l ká̇l-bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yȧẕi̇qu֖⁠m li⁠pĕné֥y yĕhwáֽh׃"],[7,24,"וַ⁠יִּקַּ֣ח יְהוֹשֻׁ֣עַ אֶת־עָכָ֣ן בֶּן־זֶ֡רַח וְ⁠אֶת־הַ⁠כֶּ֣סֶף וְ⁠אֶת־הָ⁠אַדֶּ֣רֶת וְֽ⁠אֶת־לְשׁ֣וֹן הַ⁠זָּהָ֡ב וְֽ⁠אֶת־בָּנָ֡י⁠ו וְֽ⁠אֶת־בְּנֹתָ֡י⁠ו וְ⁠אֶת־שׁוֹר⁠וֹ֩ וְ⁠אֶת־חֲמֹר֨⁠וֹ וְ⁠אֶת־צֹאנ֤⁠וֹ וְ⁠אֶֽת־אָהֳל⁠וֹ֙ וְ⁠אֶת־כָּל־אֲשֶׁר־ל֔⁠וֹ וְ⁠כָל־יִשְׂרָאֵ֖ל עִמּ֑⁠וֹ וַ⁠יַּעֲל֥וּ אֹתָ֖⁠ם עֵ֥מֶק עָכֽוֹר׃","wa⁠yi̇qȧ֣ẖ yĕhwòşǔ֣ʻa ʼeţ-ʻáká֣n bėn-ze֡raẖ wĕ⁠ʼeţ-ha⁠kė֣sep wĕ⁠ʼeţ-há⁠ʼadė֣reţ wĕֽ⁠ʼeţ-lĕş֣̌wòn ha⁠zá̇há֡b wĕֽ⁠ʼeţ-bá̇ná֡y⁠w wĕֽ⁠ʼeţ-bĕ̇nòţá֡y⁠w wĕ⁠ʼeţ-ş̌wòr⁠wò֩ wĕ⁠ʼeţ-ẖàmòr֨⁠wò wĕ⁠ʼeţ-ẕòʼn֤⁠wò wĕ⁠ʼeֽţ-ʼáhol⁠wò֙ wĕ⁠ʼeţ-ká̇l-ʼàşěr-l֔⁠wò wĕ⁠kál-yişĕ̂ráʼé֖l ʻiṁ֑⁠wò wa⁠yȧʻàl֥ẇ ʼòţá֖⁠m ʻé֥meq ʻákֽwòr׃"],[7,25,"וַ⁠יֹּ֤אמֶר יְהוֹשֻׁ֨עַ֙ מֶ֣ה עֲכַרְתָּ֔⁠נוּ יַעְכֳּרְ⁠ךָ֥ יְהוָ֖ה בַּ⁠יּ֣וֹם הַ⁠זֶּ֑ה וַ⁠יִּרְגְּמ֨וּ אֹת֤⁠וֹ כָל־יִשְׂרָאֵל֙ אֶ֔בֶן וַ⁠יִּשְׂרְפ֤וּ אֹתָ⁠ם֙ בָּ⁠אֵ֔שׁ וַ⁠יִּסְקְל֥וּ אֹתָ֖⁠ם בָּ⁠אֲבָנִֽים׃","wa⁠yò֤̇ʼmer yĕhwòşǔ֨ʻa֙ me֣h ʻàkarĕţá̇֔⁠nẇ yaʻĕkȯrĕ⁠ká֥ yĕhwá֖h bȧ⁠ẏ֣wòm ha⁠zė֑h wa⁠yi̇rĕgĕ̇m֨ẇ ʼòţ֤⁠wò kál-yişĕ̂ráʼél֙ ʼe֔ben wa⁠yi̇şĕ̂rĕp֤ẇ ʼòţá⁠m֙ bá̇⁠ʼé֔ş̌ wa⁠yi̇sĕqĕl֥ẇ ʼòţá֖⁠m bá̇⁠ʼàbániֽym׃"],[7,26,"וַ⁠יָּקִ֨ימוּ עָלָ֜י⁠ו גַּל־אֲבָנִ֣ים גָּד֗וֹל עַ֚ד הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה וַ⁠יָּ֥שָׁב יְהוָ֖ה מֵ⁠חֲר֣וֹן אַפּ֑⁠וֹ עַל־כֵּ֠ן קָרָ֞א שֵׁ֣ם הַ⁠מָּק֤וֹם הַ⁠הוּא֙ עֵ֣מֶק עָכ֔וֹר עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wa⁠yá̇qi֨ymẇ ʻálá֜y⁠w gȧl-ʼàbáni֣ym gá̇d֗wòl ʻa֚d ha⁠ẏ֣wòm ha⁠zė֔h wa⁠yá֥̇şá̌b yĕhwá֖h mé⁠ẖàr֣wòn ʼaṗ֑⁠wò ʻal-ké̇֠n qárá֞ʼ şé֣̌m ha⁠má̇q֤wòm ha⁠hẇʼ֙ ʻé֣meq ʻák֔wòr ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[8,1,"וַ⁠יֹּ֨אמֶר יְהוָ֤ה אֶל־יְהוֹשֻׁ֨עַ֙ אַל־תִּירָ֣א וְ⁠אַל־תֵּחָ֔ת קַ֣ח עִמְּ⁠ךָ֗ אֵ֚ת כָּל־עַ֣ם הַ⁠מִּלְחָמָ֔ה וְ⁠ק֖וּם עֲלֵ֣ה הָ⁠עָ֑י רְאֵ֣ה ׀ נָתַ֣תִּי בְ⁠יָדְ⁠ךָ֗ אֶת־מֶ֤לֶךְ הָ⁠עַי֙ וְ⁠אֶת־עַמּ֔⁠וֹ וְ⁠אֶת־עִיר֖⁠וֹ וְ⁠אֶת־אַרְצֽ⁠וֹ׃","wa⁠yò̇֨ʼmer yĕhwá֤h ʼel-yĕhwòşǔ֨ʻa֙ ʼal-ţi̇yrá֣ʼ wĕ⁠ʼal-ţé̇ẖá֔ţ qa֣ẖ ʻimĕ̇⁠ká֗ ʼé֚ţ ká̇l-ʻa֣m ha⁠mi̇lĕẖámá֔h wĕ⁠q֖ẇm ʻàlé֣h há⁠ʻá֑y rĕʼé֣h ׀ náţa֣ţi̇y bĕ⁠yádĕ⁠ká֗ ʼeţ-me֤lekĕ há⁠ʻay֙ wĕ⁠ʼeţ-ʻaṁ֔⁠wò wĕ⁠ʼeţ-ʻiyr֖⁠wò wĕ⁠ʼeţ-ʼarĕẕֽ⁠wò׃"],[8,2,"וְ⁠עָשִׂ֨יתָ לָ⁠עַ֜י וּ⁠לְ⁠מַלְכָּ֗⁠הּ כַּ⁠אֲשֶׁ֨ר עָשִׂ֤יתָ לִֽ⁠ירִיחוֹ֙ וּ⁠לְ⁠מַלְכָּ֔⁠הּ רַק־שְׁלָלָ֥⁠הּ וּ⁠בְהֶמְתָּ֖⁠הּ תָּבֹ֣זּוּ לָ⁠כֶ֑ם שִׂים־לְ⁠ךָ֥ אֹרֵ֛ב לָ⁠עִ֖יר מֵ⁠אַחֲרֶֽי⁠הָ׃","wĕ⁠ʻáşî֨yţá lá⁠ʻa֜y ẇ⁠lĕ⁠malĕká̇֗⁠ḣ kȧ⁠ʼàşě֨r ʻáşî֤yţá liֽ⁠yriyẖwò֙ ẇ⁠lĕ⁠malĕká̇֔⁠ḣ raq-şĕ̌lálá֥⁠ḣ ẇ⁠bĕhemĕţá֖̇⁠ḣ ţá̇bò֣żẇ lá⁠ke֑m şîym-lĕ⁠ká֥ ʼòré֛b lá⁠ʻi֖yr mé⁠ʼaẖàreֽy⁠há׃"],[8,3,"וַ⁠יָּ֧קָם יְהוֹשֻׁ֛עַ וְ⁠כָל־עַ֥ם הַ⁠מִּלְחָמָ֖ה לַ⁠עֲל֣וֹת הָ⁠עָ֑י וַ⁠יִּבְחַ֣ר יְ֠הוֹשֻׁעַ שְׁלֹשִׁ֨ים אֶ֤לֶף אִישׁ֙ גִּבּוֹרֵ֣י הַ⁠חַ֔יִל וַ⁠יִּשְׁלָחֵ֖⁠ם לָֽיְלָה׃","wa⁠yá֧̇qám yĕhwòşǔ֛ʻa wĕ⁠kál-ʻa֥m ha⁠mi̇lĕẖámá֖h la⁠ʻàl֣wòţ há⁠ʻá֑y wa⁠yi̇bĕẖa֣r yĕ֠hwòşǔʻa şĕ̌lòşǐ֨ym ʼe֤lep ʼiyş̌֙ gi̇ḃwòré֣y ha⁠ẖa֔yil wa⁠yi̇şĕ̌láẖé֖⁠m láֽyĕláh׃"],[8,4,"וַ⁠יְצַ֨ו אֹתָ֜⁠ם לֵ⁠אמֹ֗ר רְ֠אוּ אַתֶּ֞ם אֹרְבִ֤ים לָ⁠עִיר֙ מֵ⁠אַחֲרֵ֣י הָ⁠עִ֔יר אַל־תַּרְחִ֥יקוּ מִן־הָ⁠עִ֖יר מְאֹ֑ד וִ⁠הְיִיתֶ֥ם כֻּלְּ⁠כֶ֖ם נְכֹנִֽים׃","wa⁠yĕẕa֨w ʼòţá֜⁠m lé⁠ʼmò֗r rĕ֠ʼẇ ʼaţė֞m ʼòrĕbi֤ym lá⁠ʻiyr֙ mé⁠ʼaẖàré֣y há⁠ʻi֔yr ʼal-ţȧrĕẖi֥yqẇ min-há⁠ʻi֖yr mĕʼò֑d wi⁠hĕyiyţe֥m ku̇lĕ̇⁠ke֖m nĕkòniֽym׃"],[8,5,"וַ⁠אֲנִ֗י וְ⁠כָל־הָ⁠עָם֙ אֲשֶׁ֣ר אִתִּ֔⁠י נִקְרַ֖ב אֶל־הָ⁠עִ֑יר וְ⁠הָיָ֗ה כִּֽי־יֵצְא֤וּ לִ⁠קְרָאתֵ֨⁠נוּ֙ כַּ⁠אֲשֶׁ֣ר בָּ⁠רִֽאשֹׁנָ֔ה וְ⁠נַ֖סְנוּ לִ⁠פְנֵי⁠הֶֽם׃","wa⁠ʼàni֗y wĕ⁠kál-há⁠ʻám֙ ʼàşě֣r ʼiţi̇֔⁠y niqĕra֖b ʼel-há⁠ʻi֑yr wĕ⁠háyá֗h kiֽ̇y-yéẕĕʼ֤ẇ li⁠qĕráʼţé֨⁠nẇ֙ kȧ⁠ʼàşě֣r bá̇⁠riֽʼşò̌ná֔h wĕ⁠na֖sĕnẇ li⁠pĕnéy⁠heֽm׃"],[8,6,"וְ⁠יָצְא֣וּ אַחֲרֵ֗י⁠נוּ עַ֣ד הַתִּיקֵ֤⁠נוּ אוֹתָ⁠ם֙ מִן־הָ⁠עִ֔יר כִּ֣י יֹֽאמְר֔וּ נָסִ֣ים לְ⁠פָנֵ֔י⁠נוּ כַּ⁠אֲשֶׁ֖ר בָּ⁠רִֽאשֹׁנָ֑ה וְ⁠נַ֖סְנוּ לִ⁠פְנֵי⁠הֶֽם׃","wĕ⁠yáẕĕʼ֣ẇ ʼaẖàré֗y⁠nẇ ʻa֣d haţi̇yqé֤⁠nẇ ʼwòţá⁠m֙ min-há⁠ʻi֔yr ki֣̇y yòֽʼmĕr֔ẇ nási֣ym lĕ⁠páné֔y⁠nẇ kȧ⁠ʼàşě֖r bá̇⁠riֽʼşò̌ná֑h wĕ⁠na֖sĕnẇ li⁠pĕnéy⁠heֽm׃"],[8,7,"וְ⁠אַתֶּ֗ם תָּקֻ֨מוּ֙ מֵ⁠הָ֣⁠אוֹרֵ֔ב וְ⁠הוֹרַשְׁתֶּ֖ם אֶת־הָ⁠עִ֑יר וּ⁠נְתָנָ֛⁠הּ יְהוָ֥ה אֱלֹֽהֵי⁠כֶ֖ם בְּ⁠יֶדְ⁠כֶֽם׃","wĕ⁠ʼaţė֗m ţá̇qu֨mẇ֙ mé⁠há֣⁠ʼwòré֔b wĕ⁠hwòraşĕ̌ţė֖m ʼeţ-há⁠ʻi֑yr ẇ⁠nĕţáná֛⁠ḣ yĕhwá֥h ʼèlòֽhéy⁠ke֖m bĕ̇⁠yedĕ⁠keֽm׃"],[8,8,"וְ⁠הָיָ֞ה כְּ⁠תָפְשְׂ⁠כֶ֣ם אֶת־הָ⁠עִ֗יר תַּצִּ֤יתוּ אֶת־הָ⁠עִיר֙ בָּ⁠אֵ֔שׁ כִּ⁠דְבַ֥ר יְהוָ֖ה תַּעֲשׂ֑וּ רְא֖וּ צִוִּ֥יתִי אֶתְ⁠כֶֽם׃","wĕ⁠háyá֞h kĕ̇⁠ţápĕşĕ̂⁠ke֣m ʼeţ-há⁠ʻi֗yr ţȧẕi֤̇yţẇ ʼeţ-há⁠ʻiyr֙ bá̇⁠ʼé֔ş̌ ki̇⁠dĕba֥r yĕhwá֖h ţȧʻàş֑̂ẇ rĕʼ֖ẇ ẕiwi֥̇yţiy ʼeţĕ⁠keֽm׃"],[8,9,"וַ⁠יִּשְׁלָחֵ֣⁠ם יְהוֹשֻׁ֗עַ וַ⁠יֵּֽלְכוּ֙ אֶל־הַ⁠מַּאְרָ֔ב וַ⁠יֵּשְׁב֗וּ בֵּ֧ין בֵּֽית־אֵ֛ל וּ⁠בֵ֥ין הָ⁠עַ֖י מִ⁠יָּ֣ם לָ⁠עָ֑י וַ⁠יָּ֧לֶן יְהוֹשֻׁ֛עַ בַּ⁠לַּ֥יְלָה הַ⁠ה֖וּא בְּ⁠ת֥וֹךְ הָ⁠עָֽם׃","wa⁠yi̇şĕ̌láẖé֣⁠m yĕhwòşǔ֗ʻa wa⁠yéֽ̇lĕkẇ֙ ʼel-ha⁠mȧʼĕrá֔b wa⁠yé̇şĕ̌b֗ẇ bé֧̇yn béֽ̇yţ-ʼé֛l ẇ⁠bé֥yn há⁠ʻa֖y mi⁠yá֣̇m lá⁠ʻá֑y wa⁠yá֧̇len yĕhwòşǔ֛ʻa bȧ⁠lȧ֥yĕláh ha⁠h֖ẇʼ bĕ̇⁠ţ֥wòkĕ há⁠ʻáֽm׃"],[8,10,"וַ⁠יַּשְׁכֵּ֤ם יְהוֹשֻׁ֨עַ֙ בַּ⁠בֹּ֔קֶר וַ⁠יִּפְקֹ֖ד אֶת־הָ⁠עָ֑ם וַ⁠יַּ֨עַל ה֜וּא וְ⁠זִקְנֵ֧י יִשְׂרָאֵ֛ל לִ⁠פְנֵ֥י הָ⁠עָ֖ם הָ⁠עָֽי׃","wa⁠yȧşĕ̌ké֤̇m yĕhwòşǔ֨ʻa֙ bȧ⁠bò̇֔qer wa⁠yi̇pĕqò֖d ʼeţ-há⁠ʻá֑m wa⁠yȧ֨ʻal h֜ẇʼ wĕ⁠ziqĕné֧y yişĕ̂ráʼé֛l li⁠pĕné֥y há⁠ʻá֖m há⁠ʻáֽy׃"],[8,11,"וְ⁠כָל־הָ⁠עָ֨ם הַ⁠מִּלְחָמָ֜ה אֲשֶׁ֣ר אִתּ֗⁠וֹ עָלוּ֙ וַֽ⁠יִּגְּשׁ֔וּ וַ⁠יָּבֹ֖אוּ נֶ֣גֶד הָ⁠עִ֑יר וַֽ⁠יַּחֲנוּ֙ מִ⁠צְּפ֣וֹן לָ⁠עַ֔י וְ⁠הַ⁠גַּ֖י בינ⁠ו וּ⁠בֵין־הָ⁠עָֽי׃","wĕ⁠kál-há⁠ʻá֨m ha⁠mi̇lĕẖámá֜h ʼàşě֣r ʼiţ̇֗⁠wò ʻálẇ֙ waֽ⁠yi̇gĕ̇ş̌֔ẇ wa⁠yá̇bò֖ʼẇ ne֣ged há⁠ʻi֑yr waֽ⁠yȧẖànẇ֙ mi⁠ẕĕ̇p֣wòn lá⁠ʻa֔y wĕ⁠ha⁠gȧ֖y byn⁠w ẇ⁠béyn-há⁠ʻáֽy׃"],[8,12,"וַ⁠יִּקַּ֕ח כַּ⁠חֲמֵ֥שֶׁת אֲלָפִ֖ים אִ֑ישׁ וַ⁠יָּ֨שֶׂם אוֹתָ֜⁠ם אֹרֵ֗ב בֵּ֧ין בֵּֽית־אֵ֛ל וּ⁠בֵ֥ין הָ⁠עַ֖י מִ⁠יָּ֥ם לָ⁠עִֽיר׃","wa⁠yi̇qȧ֕ẖ kȧ⁠ẖàmé֥şěţ ʼàlápi֖ym ʼi֑yş̌ wa⁠yá̇֨şêm ʼwòţá֜⁠m ʼòré֗b bé֧̇yn béֽ̇yţ-ʼé֛l ẇ⁠bé֥yn há⁠ʻa֖y mi⁠yá֥̇m lá⁠ʻiֽyr׃"],[8,13,"וַ⁠יָּשִׂ֨ימוּ הָ⁠עָ֜ם אֶת־כָּל־הַֽ⁠מַּחֲנֶ֗ה אֲשֶׁר֙ מִ⁠צְּפ֣וֹן לָ⁠עִ֔יר וְ⁠אֶת־עֲקֵב֖⁠וֹ מִ⁠יָּ֣ם לָ⁠עִ֑יר וַ⁠יֵּ֧לֶךְ יְהוֹשֻׁ֛עַ בַּ⁠לַּ֥יְלָה הַ⁠ה֖וּא בְּ⁠ת֥וֹךְ הָ⁠עֵֽמֶק׃","wa⁠yá̇şî֨ymẇ há⁠ʻá֜m ʼeţ-ká̇l-haֽ⁠mȧẖàne֗h ʼàşěr֙ mi⁠ẕĕ̇p֣wòn lá⁠ʻi֔yr wĕ⁠ʼeţ-ʻàqéb֖⁠wò mi⁠yá֣̇m lá⁠ʻi֑yr wa⁠yé֧̇lekĕ yĕhwòşǔ֛ʻa bȧ⁠lȧ֥yĕláh ha⁠h֖ẇʼ bĕ̇⁠ţ֥wòkĕ há⁠ʻéֽmeq׃"],[8,14,"וַ⁠יְהִ֞י כִּ⁠רְא֣וֹת מֶֽלֶךְ־הָ⁠עַ֗י וַֽ⁠יְמַהֲר֡וּ וַ⁠יַּשְׁכִּ֡ימוּ וַ⁠יֵּצְא֣וּ אַנְשֵֽׁי־הָ⁠עִ֣יר לִ⁠קְרַֽאת־יִ֠שְׂרָאֵל לַֽ⁠מִּלְחָמָ֞ה ה֧וּא וְ⁠כָל־עַמּ֛⁠וֹ לַ⁠מּוֹעֵ֖ד לִ⁠פְנֵ֣י הָֽ⁠עֲרָבָ֑ה וְ⁠הוּא֙ לֹ֣א יָדַ֔ע כִּֽי־אֹרֵ֥ב ל֖⁠וֹ מֵ⁠אַחֲרֵ֥י הָ⁠עִֽיר׃","wa⁠yĕhi֞y ki̇⁠rĕʼ֣wòţ meֽlekĕ-há⁠ʻa֗y waֽ⁠yĕmahàr֡ẇ wa⁠yȧşĕ̌ki̇֡ymẇ wa⁠yé̇ẕĕʼ֣ẇ ʼanĕşéֽ̌y-há⁠ʻi֣yr li⁠qĕraֽʼţ-yi֠şĕ̂ráʼél laֽ⁠mi̇lĕẖámá֞h h֧ẇʼ wĕ⁠kál-ʻaṁ֛⁠wò la⁠ṁwòʻé֖d li⁠pĕné֣y háֽ⁠ʻàrábá֑h wĕ⁠hẇʼ֙ lò֣ʼ yáda֔ʻ kiֽ̇y-ʼòré֥b l֖⁠wò mé⁠ʼaẖàré֥y há⁠ʻiֽyr׃"],[8,15,"וַ⁠יִּנָּֽגְע֛וּ יְהוֹשֻׁ֥עַ וְ⁠כָל־יִשְׂרָאֵ֖ל לִ⁠פְנֵי⁠הֶ֑ם וַ⁠יָּנֻ֖סוּ דֶּ֥רֶךְ הַ⁠מִּדְבָּֽר׃","wa⁠yi̇náֽ̇gĕʻ֛ẇ yĕhwòşǔ֥ʻa wĕ⁠kál-yişĕ̂ráʼé֖l li⁠pĕnéy⁠he֑m wa⁠yá̇nu֖sẇ dė֥rekĕ ha⁠mi̇dĕbáֽ̇r׃"],[8,16,"וַ⁠יִּזָּעֲק֗וּ כָּל־הָ⁠עָם֙ אֲשֶׁ֣ר ב⁠עיר לִ⁠רְדֹּ֖ף אַחֲרֵי⁠הֶ֑ם וַֽ⁠יִּרְדְּפוּ֙ אַחֲרֵ֣י יְהוֹשֻׁ֔עַ וַ⁠יִּנָּתְק֖וּ מִן־הָ⁠עִֽיר׃","wa⁠yi̇zá̇ʻàq֗ẇ ká̇l-há⁠ʻám֙ ʼàşě֣r b⁠ʻyr li⁠rĕdò֖̇p ʼaẖàréy⁠he֑m waֽ⁠yi̇rĕdĕ̇pẇ֙ ʼaẖàré֣y yĕhwòşǔ֔ʻa wa⁠yi̇ná̇ţĕq֖ẇ min-há⁠ʻiֽyr׃"],[8,17,"וְ⁠לֹֽא־נִשְׁאַ֣ר אִ֗ישׁ בָּ⁠עַי֙ וּ⁠בֵ֣ית אֵ֔ל אֲשֶׁ֥ר לֹֽא־יָצְא֖וּ אַחֲרֵ֣י יִשְׂרָאֵ֑ל וַ⁠יַּעַזְב֤וּ אֶת־הָ⁠עִיר֙ פְּתוּחָ֔ה וַֽ⁠יִּרְדְּפ֖וּ אַחֲרֵ֥י יִשְׂרָאֵֽל׃פ","wĕ⁠lòֽʼ-nişĕ̌ʼa֣r ʼi֗yş̌ bá̇⁠ʻay֙ ẇ⁠bé֣yţ ʼé֔l ʼàşě֥r lòֽʼ-yáẕĕʼ֖ẇ ʼaẖàré֣y yişĕ̂ráʼé֑l wa⁠yȧʻazĕb֤ẇ ʼeţ-há⁠ʻiyr֙ pĕ̇ţẇẖá֔h waֽ⁠yi̇rĕdĕ̇p֖ẇ ʼaẖàré֥y yişĕ̂ráʼéֽl׃p"],[8,18,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־יְהוֹשֻׁ֗עַ נְ֠טֵה בַּ⁠כִּיד֤וֹן אֲשֶׁר־בְּ⁠יָֽדְ⁠ךָ֙ אֶל־הָ⁠עַ֔י כִּ֥י בְ⁠יָדְ⁠ךָ֖ אֶתְּנֶ֑⁠נָּה וַ⁠יֵּ֧ט יְהוֹשֻׁ֛עַ בַּ⁠כִּיד֥וֹן אֲשֶׁר־בְּ⁠יָד֖⁠וֹ אֶל־הָ⁠עִֽיר׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-yĕhwòşǔ֗ʻa nĕ֠téh bȧ⁠ki̇yd֤wòn ʼàşěr-bĕ̇⁠yáֽdĕ⁠ká֙ ʼel-há⁠ʻa֔y ki֥̇y bĕ⁠yádĕ⁠ká֖ ʼeţĕ̇ne֑⁠ná̇h wa⁠yé֧̇t yĕhwòşǔ֛ʻa bȧ⁠ki̇yd֥wòn ʼàşěr-bĕ̇⁠yád֖⁠wò ʼel-há⁠ʻiֽyr׃"],[8,19,"וְ⁠הָ⁠אוֹרֵ֡ב קָם֩ מְהֵרָ֨ה מִ⁠מְּקוֹמ֤⁠וֹ וַ⁠יָּר֨וּצוּ֙ כִּ⁠נְט֣וֹת יָד֔⁠וֹ וַ⁠יָּבֹ֥אוּ הָ⁠עִ֖יר וַֽ⁠יִּלְכְּד֑וּ⁠הָ וַֽ⁠יְמַהֲר֔וּ וַ⁠יַּצִּ֥יתוּ אֶת־הָ⁠עִ֖יר בָּ⁠אֵֽשׁ׃","wĕ⁠há⁠ʼwòré֡b qám֩ mĕhérá֨h mi⁠mĕ̇qwòm֤⁠wò wa⁠yá̇r֨ẇẕẇ֙ ki̇⁠nĕt֣wòţ yád֔⁠wò wa⁠yá̇bò֥ʼẇ há⁠ʻi֖yr waֽ⁠yi̇lĕkĕ̇d֑ẇ⁠há waֽ⁠yĕmahàr֔ẇ wa⁠yȧẕi֥̇yţẇ ʼeţ-há⁠ʻi֖yr bá̇⁠ʼéֽş̌׃"],[8,20,"וַ⁠יִּפְנ֣וּ אַנְשֵׁי֩ הָ⁠עַ֨י אַחֲרֵי⁠הֶ֜ם וַ⁠יִּרְא֗וּ וְ⁠הִנֵּ֨ה עָלָ֜ה עֲשַׁ֤ן הָ⁠עִיר֙ הַ⁠שָּׁמַ֔יְמָ⁠ה וְ⁠לֹא־הָיָ֨ה בָ⁠הֶ֥ם יָדַ֛יִם לָ⁠נ֖וּס הֵ֣נָּה וָ⁠הֵ֑נָּה וְ⁠הָ⁠עָם֙ הַ⁠נָּ֣ס הַ⁠מִּדְבָּ֔ר נֶהְפַּ֖ךְ אֶל־הָ⁠רוֹדֵֽף׃","wa⁠yi̇pĕn֣ẇ ʼanĕşé̌y֩ há⁠ʻa֨y ʼaẖàréy⁠he֜m wa⁠yi̇rĕʼ֗ẇ wĕ⁠hiné̇֨h ʻálá֜h ʻàşǎ֤n há⁠ʻiyr֙ ha⁠şá̇̌ma֔yĕmá⁠h wĕ⁠lòʼ-háyá֨h bá⁠he֥m yáda֛yim lá⁠n֖ẇs hé֣ná̇h wá⁠hé֑ná̇h wĕ⁠há⁠ʻám֙ ha⁠ná֣̇s ha⁠mi̇dĕbá̇֔r nehĕpȧ֖kĕ ʼel-há⁠rwòdéֽp׃"],[8,21,"וִ⁠יהוֹשֻׁ֨עַ וְ⁠כָֽל־יִשְׂרָאֵ֜ל רָא֗וּ כִּֽי־לָכַ֤ד הָֽ⁠אֹרֵב֙ אֶת־הָ⁠עִ֔יר וְ⁠כִ֥י עָלָ֖ה עֲשַׁ֣ן הָ⁠עִ֑יר וַ⁠יָּשֻׁ֕בוּ וַ⁠יַּכּ֖וּ אֶת־אַנְשֵׁ֥י הָ⁠עָֽי׃","wi⁠yhwòşǔ֨ʻa wĕ⁠káֽl-yişĕ̂ráʼé֜l ráʼ֗ẇ kiֽ̇y-láka֤d háֽ⁠ʼòréb֙ ʼeţ-há⁠ʻi֔yr wĕ⁠ki֥y ʻálá֖h ʻàşǎ֣n há⁠ʻi֑yr wa⁠yá̇şǔ֕bẇ wa⁠yȧk֖̇ẇ ʼeţ-ʼanĕşé֥̌y há⁠ʻáֽy׃"],[8,22,"וְ⁠אֵ֨לֶּה יָצְא֤וּ מִן־הָ⁠עִיר֙ לִ⁠קְרָאתָ֔⁠ם וַ⁠יִּֽהְי֤וּ לְ⁠יִשְׂרָאֵל֙ בַּ⁠תָּ֔וֶךְ אֵ֥לֶּה מִ⁠זֶּ֖ה וְ⁠אֵ֣לֶּה מִ⁠זֶּ֑ה וַ⁠יַּכּ֣וּ אוֹתָ֔⁠ם עַד־בִּלְתִּ֥י הִשְׁאִֽיר־ל֖⁠וֹ שָׂרִ֥יד וּ⁠פָלִֽיט׃","wĕ⁠ʼé֨lėh yáẕĕʼ֤ẇ min-há⁠ʻiyr֙ li⁠qĕráʼţá֔⁠m wa⁠yiֽ̇hĕy֤ẇ lĕ⁠yişĕ̂ráʼél֙ bȧ⁠ţá̇֔wekĕ ʼé֥lėh mi⁠zė֖h wĕ⁠ʼé֣lėh mi⁠zė֑h wa⁠yȧk֣̇ẇ ʼwòţá֔⁠m ʻad-bi̇lĕţi֥̇y hişĕ̌ʼiֽyr-l֖⁠wò şá̂ri֥yd ẇ⁠páliֽyt׃"],[8,23,"וְ⁠אֶת־מֶ֥לֶךְ הָ⁠עַ֖י תָּ֣פְשׂוּ חָ֑י וַ⁠יַּקְרִ֥בוּ אֹת֖⁠וֹ אֶל־יְהוֹשֻֽׁעַ׃","wĕ⁠ʼeţ-me֥lekĕ há⁠ʻa֖y ţá֣̇pĕş̂ẇ ẖá֑y wa⁠yȧqĕri֥bẇ ʼòţ֖⁠wò ʼel-yĕhwòşǔֽʻa׃"],[8,24,"וַ⁠יְהִ֣י כְּ⁠כַלּ֣וֹת יִשְׂרָאֵ֡ל לַ⁠הֲרֹג֩ אֶת־כָּל־יֹשְׁבֵ֨י הָ⁠עַ֜י בַּ⁠שָּׂדֶ֗ה בַּ⁠מִּדְבָּר֙ אֲשֶׁ֣ר רְדָפ֣וּ⁠ם בּ֔⁠וֹ וַֽ⁠יִּפְּל֥וּ כֻלָּ֛⁠ם לְ⁠פִי־חֶ֖רֶב עַד־תֻּמָּ֑⁠ם וַ⁠יָּשֻׁ֤בוּ כָל־יִשְׂרָאֵל֙ הָ⁠עַ֔י וַ⁠יַּכּ֥וּ אֹתָ֖⁠הּ לְ⁠פִי־חָֽרֶב׃","wa⁠yĕhi֣y kĕ̇⁠kal֣̇wòţ yişĕ̂ráʼé֡l la⁠hàròg֩ ʼeţ-ká̇l-yòşĕ̌bé֨y há⁠ʻa֜y bȧ⁠şá̇̂de֗h bȧ⁠mi̇dĕbá̇r֙ ʼàşě֣r rĕdáp֣ẇ⁠m ḃ֔⁠wò waֽ⁠yi̇pĕ̇l֥ẇ kulá֛̇⁠m lĕ⁠piy-ẖe֖reb ʻad-ţu̇má֑̇⁠m wa⁠yá̇şǔ֤bẇ kál-yişĕ̂ráʼél֙ há⁠ʻa֔y wa⁠yȧk֥̇ẇ ʼòţá֖⁠ḣ lĕ⁠piy-ẖáֽreb׃"],[8,25,"וַ⁠יְהִי֩ כָל־הַ⁠נֹּ֨פְלִ֜ים בַּ⁠יּ֤וֹם הַ⁠הוּא֙ מֵ⁠אִ֣ישׁ וְ⁠עַד־אִשָּׁ֔ה שְׁנֵ֥ים עָשָׂ֖ר אָ֑לֶף כֹּ֖ל אַנְשֵׁ֥י הָ⁠עָֽי׃","wa⁠yĕhiy֩ kál-ha⁠nò̇֨pĕli֜ym bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ mé⁠ʼi֣yş̌ wĕ⁠ʻad-ʼişá̇̌֔h şĕ̌né֥ym ʻáşá֖̂r ʼá֑lep kò֖̇l ʼanĕşé֥̌y há⁠ʻáֽy׃"],[8,26,"וִ⁠יהוֹשֻׁ֨עַ֙ לֹֽא־הֵשִׁ֣יב יָד֔⁠וֹ אֲשֶׁ֥ר נָטָ֖ה בַּ⁠כִּיד֑וֹן עַ֚ד אֲשֶׁ֣ר הֶחֱרִ֔ים אֵ֖ת כָּל־יֹשְׁבֵ֥י הָ⁠עָֽי׃","wi⁠yhwòşǔ֨ʻa֙ lòֽʼ-héşǐ֣yb yád֔⁠wò ʼàşě֥r nátá֖h bȧ⁠ki̇yd֑wòn ʻa֚d ʼàşě֣r heẖèri֔ym ʼé֖ţ ká̇l-yòşĕ̌bé֥y há⁠ʻáֽy׃"],[8,27,"רַ֣ק הַ⁠בְּהֵמָ֗ה וּ⁠שְׁלַל֙ הָ⁠עִ֣יר הַ⁠הִ֔יא בָּזְז֥וּ לָ⁠הֶ֖ם יִשְׂרָאֵ֑ל כִּ⁠דְבַ֣ר יְהוָ֔ה אֲשֶׁ֥ר צִוָּ֖ה אֶת־יְהוֹשֻֽׁעַ׃","ra֣q ha⁠bĕ̇hémá֗h ẇ⁠şĕ̌lal֙ há⁠ʻi֣yr ha⁠hi֔yʼ bá̇zĕz֥ẇ lá⁠he֖m yişĕ̂ráʼé֑l ki̇⁠dĕba֣r yĕhwá֔h ʼàşě֥r ẕiwá֖̇h ʼeţ-yĕhwòşǔֽʻa׃"],[8,28,"וַ⁠יִּשְׂרֹ֥ף יְהוֹשֻׁ֖עַ אֶת־הָ⁠עָ֑י וַ⁠יְשִׂימֶ֤⁠הָ תֵּל־עוֹלָם֙ שְׁמָמָ֔ה עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yi̇şĕ̂rò֥p yĕhwòşǔ֖ʻa ʼeţ-há⁠ʻá֑y wa⁠yĕşîyme֤⁠há ţé̇l-ʻwòlám֙ şĕ̌mámá֔h ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[8,29,"וְ⁠אֶת־מֶ֧לֶךְ הָ⁠עַ֛י תָּלָ֥ה עַל־הָ⁠עֵ֖ץ עַד־עֵ֣ת הָ⁠עָ֑רֶב וּ⁠כְ⁠ב֣וֹא הַ⁠שֶּׁמֶשׁ֩ צִוָּ֨ה יְהוֹשֻׁ֜עַ וַ⁠יֹּרִ֧ידוּ אֶת־נִבְלָת֣⁠וֹ מִן־הָ⁠עֵ֗ץ וַ⁠יַּשְׁלִ֤יכוּ אוֹתָ⁠הּ֙ אֶל־פֶּ֨תַח֙ שַׁ֣עַר הָ⁠עִ֔יר וַ⁠יָּקִ֤ימוּ עָלָי⁠ו֙ גַּל־אֲבָנִ֣ים גָּד֔וֹל עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wĕ⁠ʼeţ-me֧lekĕ há⁠ʻa֛y ţá̇lá֥h ʻal-há⁠ʻé֖ẕ ʻad-ʻé֣ţ há⁠ʻá֑reb ẇ⁠kĕ⁠b֣wòʼ ha⁠şė̌meş̌֩ ẕiwá̇֨h yĕhwòşǔ֜ʻa wa⁠yò̇ri֧ydẇ ʼeţ-nibĕláţ֣⁠wò min-há⁠ʻé֗ẕ wa⁠yȧşĕ̌li֤ykẇ ʼwòţá⁠ḣ֙ ʼel-pė֨ţaẖ֙ şǎ֣ʻar há⁠ʻi֔yr wa⁠yá̇qi֤ymẇ ʻáláy⁠w֙ gȧl-ʼàbáni֣ym gá̇d֔wòl ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[8,30,"אָ֣ז יִבְנֶ֤ה יְהוֹשֻׁ֨עַ֙ מִזְבֵּ֔חַ לַֽ⁠יהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל בְּ⁠הַ֖ר עֵיבָֽל׃","ʼá֣z yibĕne֤h yĕhwòşǔ֨ʻa֙ mizĕbé̇֔ẖa laֽ⁠yhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l bĕ̇⁠ha֖r ʻéybáֽl׃"],[8,31,"כַּ⁠אֲשֶׁ֣ר צִוָּה֩ מֹשֶׁ֨ה עֶֽבֶד־יְהוָ֜ה אֶת־בְּנֵ֣י יִשְׂרָאֵ֗ל כַּ⁠כָּתוּב֙ בְּ⁠סֵ֨פֶר֙ תּוֹרַ֣ת מֹשֶׁ֔ה מִזְבַּח֙ אֲבָנִ֣ים שְׁלֵמ֔וֹת אֲשֶׁ֛ר לֹֽא־הֵנִ֥יף עֲלֵי⁠הֶ֖ן בַּרְזֶ֑ל וַ⁠יַּעֲל֨וּ עָלָ֤י⁠ו עֹלוֹת֙ לַֽ⁠יהוָ֔ה וַֽ⁠יִּזְבְּח֖וּ שְׁלָמִֽים׃","kȧ⁠ʼàşě֣r ẕiwá̇h֩ mòşě֨h ʻeֽbed-yĕhwá֜h ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֗l kȧ⁠ká̇ţẇb֙ bĕ̇⁠sé֨per֙ ţ̇wòra֣ţ mòşě֔h mizĕbȧẖ֙ ʼàbáni֣ym şĕ̌lém֔wòţ ʼàşě֛r lòֽʼ-héni֥yp ʻàléy⁠he֖n bȧrĕze֑l wa⁠yȧʻàl֨ẇ ʻálá֤y⁠w ʻòlwòţ֙ laֽ⁠yhwá֔h waֽ⁠yi̇zĕbĕ̇ẖ֖ẇ şĕ̌lámiֽym׃"],[8,32,"וַ⁠יִּכְתָּב־שָׁ֖ם עַל־הָ⁠אֲבָנִ֑ים אֵ֗ת מִשְׁנֵה֙ תּוֹרַ֣ת מֹשֶׁ֔ה אֲשֶׁ֣ר כָּתַ֔ב לִ⁠פְנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yi̇kĕţá̇b-şá֖̌m ʻal-há⁠ʼàbáni֑ym ʼé֗ţ mişĕ̌néh֙ ţ̇wòra֣ţ mòşě֔h ʼàşě֣r ká̇ţa֔b li⁠pĕné֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[8,33,"וְ⁠כָל־יִשְׂרָאֵ֡ל וּ⁠זְקֵנָ֡י⁠ו וְ⁠שֹׁטְרִ֣ים ׀ וְ⁠שֹׁפְטָ֡י⁠ו עֹמְדִ֣ים מִ⁠זֶּ֣ה ׀ וּ⁠מִ⁠זֶּ֣ה ׀ לָ⁠אָר֡וֹן נֶגֶד֩ הַ⁠כֹּהֲנִ֨ים הַ⁠לְוִיִּ֜ם נֹשְׂאֵ֣י ׀ אֲר֣וֹן בְּרִית־יְהוָ֗ה כַּ⁠גֵּר֙ כָּֽ⁠אֶזְרָ֔ח חֶצְי⁠וֹ֙ אֶל־מ֣וּל הַר־גְּרִזִ֔ים וְ⁠הַֽ⁠חֶצְי֖⁠וֹ אֶל־מ֣וּל הַר־עֵיבָ֑ל כַּ⁠אֲשֶׁ֨ר צִוָּ֜ה מֹשֶׁ֣ה עֶֽבֶד־יְהוָ֗ה לְ⁠בָרֵ֛ךְ אֶת־הָ⁠עָ֥ם יִשְׂרָאֵ֖ל בָּ⁠רִאשֹׁנָֽה׃","wĕ⁠kál-yişĕ̂ráʼé֡l ẇ⁠zĕqéná֡y⁠w wĕ⁠şò̌tĕri֣ym ׀ wĕ⁠şò̌pĕtá֡y⁠w ʻòmĕdi֣ym mi⁠zė֣h ׀ ẇ⁠mi⁠zė֣h ׀ lá⁠ʼár֡wòn neged֩ ha⁠kò̇hàni֨ym ha⁠lĕwiyi̇֜m nòşĕ̂ʼé֣y ׀ ʼàr֣wòn bĕ̇riyţ-yĕhwá֗h kȧ⁠gé̇r֙ káֽ̇⁠ʼezĕrá֔ẖ ẖeẕĕy⁠wò֙ ʼel-m֣ẇl har-gĕ̇rizi֔ym wĕ⁠haֽ⁠ẖeẕĕy֖⁠wò ʼel-m֣ẇl har-ʻéybá֑l kȧ⁠ʼàşě֨r ẕiwá̇֜h mòşě֣h ʻeֽbed-yĕhwá֗h lĕ⁠báré֛kĕ ʼeţ-há⁠ʻá֥m yişĕ̂ráʼé֖l bá̇⁠riʼşò̌náֽh׃"],[8,34,"וְ⁠אַֽחֲרֵי־כֵ֗ן קָרָא֙ אֶת־כָּל־דִּבְרֵ֣י הַ⁠תּוֹרָ֔ה הַ⁠בְּרָכָ֖ה וְ⁠הַ⁠קְּלָלָ֑ה כְּ⁠כָל־הַ⁠כָּת֖וּב בְּ⁠סֵ֥פֶר הַ⁠תּוֹרָֽה׃","wĕ⁠ʼֽaẖàréy-ké֗n qáráʼ֙ ʼeţ-ká̇l-di̇bĕré֣y ha⁠ţ̇wòrá֔h ha⁠bĕ̇ráká֖h wĕ⁠ha⁠qĕ̇lálá֑h kĕ̇⁠kál-ha⁠ká̇ţ֖ẇb bĕ̇⁠sé֥per ha⁠ţ̇wòráֽh׃"],[8,35,"לֹֽא־הָיָ֣ה דָבָ֔ר מִ⁠כֹּ֖ל אֲשֶׁר־צִוָּ֣ה מֹשֶׁ֑ה אֲשֶׁ֨ר לֹֽא־קָרָ֜א יְהוֹשֻׁ֗עַ נֶ֣גֶד כָּל־קְהַ֤ל יִשְׂרָאֵל֙ וְ⁠הַ⁠נָּשִׁ֣ים וְ⁠הַ⁠טַּ֔ף וְ⁠הַ⁠גֵּ֖ר הַ⁠הֹלֵ֥ךְ בְּ⁠קִרְבָּֽ⁠ם׃פ","lòֽʼ-háyá֣h dábá֔r mi⁠kò֖̇l ʼàşěr-ẕiwá֣̇h mòşě֑h ʼàşě֨r lòֽʼ-qárá֜ʼ yĕhwòşǔ֗ʻa ne֣ged ká̇l-qĕha֤l yişĕ̂ráʼél֙ wĕ⁠ha⁠ná̇şǐ֣ym wĕ⁠ha⁠tȧ֔p wĕ⁠ha⁠gé֖̇r ha⁠hòlé֥kĕ bĕ̇⁠qirĕbáֽ̇⁠m׃p"],[9,1,"וַ⁠יְהִ֣י כִ⁠שְׁמֹ֣עַ כָּֽל־הַ⁠מְּלָכִ֡ים אֲשֶׁר֩ בְּ⁠עֵ֨בֶר הַ⁠יַּרְדֵּ֜ן בָּ⁠הָ֣ר וּ⁠בַ⁠שְּׁפֵלָ֗ה וּ⁠בְ⁠כֹל֙ ח֚וֹף הַ⁠יָּ֣ם הַ⁠גָּד֔וֹל אֶל־מ֖וּל הַ⁠לְּבָנ֑וֹן הַֽ⁠חִתִּי֙ וְ⁠הָ֣⁠אֱמֹרִ֔י הַֽ⁠כְּנַעֲנִי֙ הַ⁠פְּרִזִּ֔י הַ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִֽי׃","wa⁠yĕhi֣y ki⁠şĕ̌mò֣ʻa káֽ̇l-ha⁠mĕ̇láki֡ym ʼàşěr֩ bĕ̇⁠ʻé֨ber ha⁠yȧrĕdé̇֜n bá̇⁠há֣r ẇ⁠ba⁠şĕ̇̌pélá֗h ẇ⁠bĕ⁠kòl֙ ẖ֚wòp ha⁠yá֣̇m ha⁠gá̇d֔wòl ʼel-m֖ẇl ha⁠lĕ̇bán֑wòn haֽ⁠ẖiţi̇y֙ wĕ⁠há֣⁠ʼèmòri֔y haֽ⁠kĕ̇naʻàniy֙ ha⁠pĕ̇rizi̇֔y ha⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsiֽy׃"],[9,2,"וַ⁠יִּֽתְקַבְּצ֣וּ יַחְדָּ֔ו לְ⁠הִלָּחֵ֥ם עִם־יְהוֹשֻׁ֖עַ וְ⁠עִם־יִשְׂרָאֵ֑ל פֶּ֖ה אֶחָֽד׃פ","wa⁠yiֽ̇ţĕqabĕ̇ẕ֣ẇ yaẖĕdá̇֔w lĕ⁠hilá̇ẖé֥m ʻim-yĕhwòşǔ֖ʻa wĕ⁠ʻim-yişĕ̂ráʼé֑l pė֖h ʼeẖáֽd׃p"],[9,3,"וְ⁠יֹשְׁבֵ֨י גִבְע֜וֹן שָׁמְע֗וּ אֵת֩ אֲשֶׁ֨ר עָשָׂ֧ה יְהוֹשֻׁ֛עַ לִֽ⁠ירִיח֖וֹ וְ⁠לָ⁠עָֽי׃","wĕ⁠yòşĕ̌bé֨y gibĕʻ֜wòn şá̌mĕʻ֗ẇ ʼéţ֩ ʼàşě֨r ʻáşá֧̂h yĕhwòşǔ֛ʻa liֽ⁠yriyẖ֖wò wĕ⁠lá⁠ʻáֽy׃"],[9,4,"וַ⁠יַּעֲשׂ֤וּ גַם־הֵ֨מָּה֙ בְּ⁠עָרְמָ֔ה וַ⁠יֵּלְכ֖וּ וַ⁠יִּצְטַיָּ֑רוּ וַ⁠יִּקְח֞וּ שַׂקִּ֤ים בָּלִים֙ לַ⁠חֲמ֣וֹרֵי⁠הֶ֔ם וְ⁠נֹאד֥וֹת יַ֨יִן֙ בָּלִ֔ים וּ⁠מְבֻקָּעִ֖ים וּ⁠מְצֹרָרִֽים׃","wa⁠yȧʻàş֤̂ẇ gam-hé֨má̇h֙ bĕ̇⁠ʻárĕmá֔h wa⁠yé̇lĕk֖ẇ wa⁠yi̇ẕĕtayá֑̇rẇ wa⁠yi̇qĕẖ֞ẇ şâqi֤̇ym bá̇liym֙ la⁠ẖàm֣wòréy⁠he֔m wĕ⁠nòʼd֥wòţ ya֨yin֙ bá̇li֔ym ẇ⁠mĕbuqá̇ʻi֖ym ẇ⁠mĕẕòráriֽym׃"],[9,5,"וּ⁠נְעָל֨וֹת בָּל֤וֹת וּ⁠מְטֻלָּאוֹת֙ בְּ⁠רַגְלֵי⁠הֶ֔ם וּ⁠שְׂלָמ֥וֹת בָּל֖וֹת עֲלֵי⁠הֶ֑ם וְ⁠כֹל֙ לֶ֣חֶם צֵידָ֔⁠ם יָבֵ֖שׁ הָיָ֥ה נִקֻּדִֽים׃","ẇ⁠nĕʻál֨wòţ bá̇l֤wòţ ẇ⁠mĕtulá̇ʼwòţ֙ bĕ̇⁠ragĕléy⁠he֔m ẇ⁠şĕ̂lám֥wòţ bá̇l֖wòţ ʻàléy⁠he֑m wĕ⁠kòl֙ le֣ẖem ẕéydá֔⁠m yábé֖ş̌ háyá֥h niqu̇diֽym׃"],[9,6,"וַ⁠יֵּלְכ֧וּ אֶל־יְהוֹשֻׁ֛עַ אֶל־הַֽ⁠מַּחֲנֶ֖ה הַ⁠גִּלְגָּ֑ל וַ⁠יֹּאמְר֨וּ אֵלָ֜י⁠ו וְ⁠אֶל־אִ֣ישׁ יִשְׂרָאֵ֗ל מֵ⁠אֶ֤רֶץ רְחוֹקָה֙ בָּ֔אנוּ וְ⁠עַתָּ֖ה כִּרְתוּ־לָ֥⁠נוּ בְרִֽית׃","wa⁠yé̇lĕk֧ẇ ʼel-yĕhwòşǔ֛ʻa ʼel-haֽ⁠mȧẖàne֖h ha⁠gi̇lĕgá֑̇l wa⁠yò̇ʼmĕr֨ẇ ʼélá֜y⁠w wĕ⁠ʼel-ʼi֣yş̌ yişĕ̂ráʼé֗l mé⁠ʼe֤reẕ rĕẖwòqáh֙ bá̇֔ʼnẇ wĕ⁠ʻaţá֖̇h ki̇rĕţẇ-lá֥⁠nẇ bĕriֽyţ׃"],[9,7,"ו⁠יאמרו אִֽישׁ־יִשְׂרָאֵ֖ל אֶל־הַ⁠חִוִּ֑י אוּלַ֗י בְּ⁠קִרְבִּ⁠י֙ אַתָּ֣ה יוֹשֵׁ֔ב וְ⁠אֵ֖יךְ אכרות־לְ⁠ךָ֥ בְרִֽית׃","w⁠yʼmrw ʼiֽyş̌-yişĕ̂ráʼé֖l ʼel-ha⁠ẖiwi֑̇y ʼẇla֗y bĕ̇⁠qirĕbi̇⁠y֙ ʼaţá֣̇h ywòşé̌֔b wĕ⁠ʼé֖ykĕ ʼkrwţ-lĕ⁠ká֥ bĕriֽyţ׃"],[9,8,"וַ⁠יֹּאמְר֥וּ אֶל־יְהוֹשֻׁ֖עַ עֲבָדֶ֣י⁠ךָ אֲנָ֑חְנוּ וַ⁠יֹּ֨אמֶר אֲלֵ⁠הֶ֧ם יְהוֹשֻׁ֛עַ מִ֥י אַתֶּ֖ם וּ⁠מֵ⁠אַ֥יִן תָּבֹֽאוּ׃","wa⁠yò̇ʼmĕr֥ẇ ʼel-yĕhwòşǔ֖ʻa ʻàbáde֣y⁠ká ʼàná֑ẖĕnẇ wa⁠yò̇֨ʼmer ʼàlé⁠he֧m yĕhwòşǔ֛ʻa mi֥y ʼaţė֖m ẇ⁠mé⁠ʼa֥yin ţá̇bòֽʼẇ׃"],[9,9,"וַ⁠יֹּאמְר֣וּ אֵלָ֗י⁠ו מֵ⁠אֶ֨רֶץ רְחוֹקָ֤ה מְאֹד֙ בָּ֣אוּ עֲבָדֶ֔י⁠ךָ לְ⁠שֵׁ֖ם יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ כִּֽי־שָׁמַ֣עְנוּ שָׁמְע֔⁠וֹ וְ⁠אֵ֛ת כָּל־אֲשֶׁ֥ר עָשָׂ֖ה בְּ⁠מִצְרָֽיִם׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֗y⁠w mé⁠ʼe֨reẕ rĕẖwòqá֤h mĕʼòd֙ bá֣̇ʼẇ ʻàbáde֔y⁠ká lĕ⁠şé֖̌m yĕhwá֣h ʼèlòhe֑y⁠ká kiֽ̇y-şá̌ma֣ʻĕnẇ şá̌mĕʻ֔⁠wò wĕ⁠ʼé֛ţ ká̇l-ʼàşě֥r ʻáşá֖̂h bĕ̇⁠miẕĕráֽyim׃"],[9,10,"וְ⁠אֵ֣ת ׀ כָּל־אֲשֶׁ֣ר עָשָׂ֗ה לִ⁠שְׁנֵי֙ מַלְכֵ֣י הָ⁠אֱמֹרִ֔י אֲשֶׁ֖ר בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֑ן לְ⁠סִיחוֹן֙ מֶ֣לֶךְ חֶשְׁבּ֔וֹן וּ⁠לְ⁠ע֥וֹג מֶֽלֶךְ־הַ⁠בָּשָׁ֖ן אֲשֶׁ֥ר בְּ⁠עַשְׁתָּרֽוֹת׃","wĕ⁠ʼé֣ţ ׀ ká̇l-ʼàşě֣r ʻáşá̂֗h li⁠şĕ̌néy֙ malĕké֣y há⁠ʼèmòri֔y ʼàşě֖r bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé֑̇n lĕ⁠siyẖwòn֙ me֣lekĕ ẖeşĕ̌ḃ֔wòn ẇ⁠lĕ⁠ʻ֥wòg meֽlekĕ-ha⁠bá̇şá֖̌n ʼàşě֥r bĕ̇⁠ʻaşĕ̌ţá̇rֽwòţ׃"],[9,11,"וַ⁠יֹּאמְר֣וּ אֵלֵ֡י⁠נוּ זְֽקֵינֵי⁠נוּ֩ וְ⁠כָל־יֹשְׁבֵ֨י אַרְצֵ֜⁠נוּ לֵ⁠אמֹ֗ר קְח֨וּ בְ⁠יֶדְ⁠כֶ֤ם צֵידָה֙ לַ⁠דֶּ֔רֶךְ וּ⁠לְכ֖וּ לִ⁠קְרָאתָ֑⁠ם וַ⁠אֲמַרְתֶּ֤ם אֲלֵי⁠הֶם֙ עַבְדֵי⁠כֶ֣ם אֲנַ֔חְנוּ וְ⁠עַתָּ֖ה כִּרְתוּ־לָ֥⁠נוּ בְרִֽית׃","wa⁠yò̇ʼmĕr֣ẇ ʼélé֡y⁠nẇ zĕֽqéynéy⁠nẇ֩ wĕ⁠kál-yòşĕ̌bé֨y ʼarĕẕé֜⁠nẇ lé⁠ʼmò֗r qĕẖ֨ẇ bĕ⁠yedĕ⁠ke֤m ẕéydáh֙ la⁠dė֔rekĕ ẇ⁠lĕk֖ẇ li⁠qĕráʼţá֑⁠m wa⁠ʼàmarĕţė֤m ʼàléy⁠hem֙ ʻabĕdéy⁠ke֣m ʼàna֔ẖĕnẇ wĕ⁠ʻaţá֖̇h ki̇rĕţẇ-lá֥⁠nẇ bĕriֽyţ׃"],[9,12,"זֶ֣ה ׀ לַחְמֵ֗⁠נוּ חָ֞ם הִצְטַיַּ֤דְנוּ אֹת⁠וֹ֙ מִ⁠בָּ֣תֵּ֔י⁠נוּ בְּ⁠י֥וֹם צֵאתֵ֖⁠נוּ לָ⁠לֶ֣כֶת אֲלֵי⁠כֶ֑ם וְ⁠עַתָּה֙ הִנֵּ֣ה יָבֵ֔שׁ וְ⁠הָיָ֖ה נִקֻּדִֽים׃","ze֣h ׀ laẖĕmé֗⁠nẇ ẖá֞m hiẕĕtayȧ֤dĕnẇ ʼòţ⁠wò֙ mi⁠bá֣̇ţé̇֔y⁠nẇ bĕ̇⁠y֥wòm ẕéʼţé֖⁠nẇ lá⁠le֣keţ ʼàléy⁠ke֑m wĕ⁠ʻaţá̇h֙ hiné֣̇h yábé֔ş̌ wĕ⁠háyá֖h niqu̇diֽym׃"],[9,13,"וְ⁠אֵ֨לֶּה נֹאד֤וֹת הַ⁠יַּ֨יִן֙ אֲשֶׁ֣ר מִלֵּ֣אנוּ חֲדָשִׁ֔ים וְ⁠הִנֵּ֖ה הִתְבַּקָּ֑עוּ וְ⁠אֵ֤לֶּה שַׂלְמוֹתֵ֨י⁠נוּ֙ וּ⁠נְעָלֵ֔י⁠נוּ בָּל֕וּ מֵ⁠רֹ֥ב הַ⁠דֶּ֖רֶךְ מְאֹֽד׃","wĕ⁠ʼé֨lėh nòʼd֤wòţ ha⁠yȧ֨yin֙ ʼàşě֣r milé֣̇ʼnẇ ẖàdáşǐ֔ym wĕ⁠hiné֖̇h hiţĕbȧqá֑̇ʻẇ wĕ⁠ʼé֤lėh şâlĕmwòţé֨y⁠nẇ֙ ẇ⁠nĕʻálé֔y⁠nẇ bá̇l֕ẇ mé⁠rò֥b ha⁠dė֖rekĕ mĕʼòֽd׃"],[9,14,"וַ⁠יִּקְח֥וּ הָֽ⁠אֲנָשִׁ֖ים מִ⁠צֵּידָ֑⁠ם וְ⁠אֶת־פִּ֥י יְהוָ֖ה לֹ֥א שָׁאָֽלוּ׃","wa⁠yi̇qĕẖ֥ẇ háֽ⁠ʼànáşǐ֖ym mi⁠ẕé̇ydá֑⁠m wĕ⁠ʼeţ-pi֥̇y yĕhwá֖h lò֥ʼ şá̌ʼáֽlẇ׃"],[9,15,"וַ⁠יַּ֨עַשׂ לָ⁠הֶ֤ם יְהוֹשֻׁ֨עַ֙ שָׁל֔וֹם וַ⁠יִּכְרֹ֥ת לָ⁠הֶ֛ם בְּרִ֖ית לְ⁠חַיּוֹתָ֑⁠ם וַ⁠יִּשָּׁבְע֣וּ לָ⁠הֶ֔ם נְשִׂיאֵ֖י הָ⁠עֵדָֽה׃","wa⁠yȧ֨ʻaş̂ lá⁠he֤m yĕhwòşǔ֨ʻa֙ şá̌l֔wòm wa⁠yi̇kĕrò֥ţ lá⁠he֛m bĕ̇ri֖yţ lĕ⁠ẖaẏwòţá֑⁠m wa⁠yi̇şá̇̌bĕʻ֣ẇ lá⁠he֔m nĕşîyʼé֖y há⁠ʻédáֽh׃"],[9,16,"וַ⁠יְהִ֗י מִ⁠קְצֵה֙ שְׁלֹ֣שֶׁת יָמִ֔ים אַחֲרֵ֕י אֲשֶׁר־כָּרְת֥וּ לָ⁠הֶ֖ם בְּרִ֑ית וַֽ⁠יִּשְׁמְע֗וּ כִּי־קְרֹבִ֥ים הֵם֙ אֵלָ֔י⁠ו וּ⁠בְ⁠קִרְבּ֖⁠וֹ הֵ֥ם יֹשְׁבִֽים׃","wa⁠yĕhi֗y mi⁠qĕẕéh֙ şĕ̌lò֣şěţ yámi֔ym ʼaẖàré֕y ʼàşěr-ká̇rĕţ֥ẇ lá⁠he֖m bĕ̇ri֑yţ waֽ⁠yi̇şĕ̌mĕʻ֗ẇ ki̇y-qĕròbi֥ym hém֙ ʼélá֔y⁠w ẇ⁠bĕ⁠qirĕḃ֖⁠wò hé֥m yòşĕ̌biֽym׃"],[9,17,"וַ⁠יִּסְע֣וּ בְנֵֽי־יִשְׂרָאֵ֗ל וַ⁠יָּבֹ֛אוּ אֶל־עָרֵי⁠הֶ֖ם בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֑י וְ⁠עָרֵי⁠הֶם֙ גִּבְע֣וֹן וְ⁠הַ⁠כְּפִירָ֔ה וּ⁠בְאֵר֖וֹת וְ⁠קִרְיַ֥ת יְעָרִֽים׃","wa⁠yi̇sĕʻ֣ẇ bĕnéֽy-yişĕ̂ráʼé֗l wa⁠yá̇bò֛ʼẇ ʼel-ʻáréy⁠he֖m bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֑y wĕ⁠ʻáréy⁠hem֙ gi̇bĕʻ֣wòn wĕ⁠ha⁠kĕ̇piyrá֔h ẇ⁠bĕʼér֖wòţ wĕ⁠qirĕya֥ţ yĕʻáriֽym׃"],[9,18,"וְ⁠לֹ֤א הִכּוּ⁠ם֙ בְּנֵ֣י יִשְׂרָאֵ֔ל כִּֽי־נִשְׁבְּע֤וּ לָ⁠הֶם֙ נְשִׂיאֵ֣י הָֽ⁠עֵדָ֔ה בַּֽ⁠יהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּלֹּ֥נוּ כָל־הָ⁠עֵדָ֖ה עַל־הַ⁠נְּשִׂיאִֽים׃","wĕ⁠lò֤ʼ hik̇ẇ⁠m֙ bĕ̇né֣y yişĕ̂ráʼé֔l kiֽ̇y-nişĕ̌bĕ̇ʻ֤ẇ lá⁠hem֙ nĕşîyʼé֣y háֽ⁠ʻédá֔h bȧֽ⁠yhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l wa⁠yi̇lò֥̇nẇ kál-há⁠ʻédá֖h ʻal-ha⁠nĕ̇şîyʼiֽym׃"],[9,19,"וַ⁠יֹּאמְר֤וּ כָל־הַ⁠נְּשִׂיאִים֙ אֶל־כָּל־הָ֣⁠עֵדָ֔ה אֲנַ֨חְנוּ֙ נִשְׁבַּ֣עְנוּ לָ⁠הֶ֔ם בַּֽ⁠יהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וְ⁠עַתָּ֕ה לֹ֥א נוּכַ֖ל לִ⁠נְגֹּ֥עַ בָּ⁠הֶֽם׃","wa⁠yò̇ʼmĕr֤ẇ kál-ha⁠nĕ̇şîyʼiym֙ ʼel-ká̇l-há֣⁠ʻédá֔h ʼàna֨ẖĕnẇ֙ nişĕ̌bȧ֣ʻĕnẇ lá⁠he֔m bȧֽ⁠yhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l wĕ⁠ʻaţá̇֕h lò֥ʼ nẇka֖l li⁠nĕgò֥̇ʻa bá̇⁠heֽm׃"],[9,20,"זֹ֛את נַעֲשֶׂ֥ה לָ⁠הֶ֖ם וְ⁠הַחֲיֵ֣ה אוֹתָ֑⁠ם וְ⁠לֹֽא־יִֽהְיֶ֤ה עָלֵ֨י⁠נוּ֙ קֶ֔צֶף עַל־הַ⁠שְּׁבוּעָ֖ה אֲשֶׁר־נִשְׁבַּ֥עְנוּ לָ⁠הֶֽם׃","zò֛ʼţ naʻàşê֥h lá⁠he֖m wĕ⁠haẖàyé֣h ʼwòţá֑⁠m wĕ⁠lòֽʼ-yiֽhĕye֤h ʻálé֨y⁠nẇ֙ qe֔ẕep ʻal-ha⁠şĕ̇̌bẇʻá֖h ʼàşěr-nişĕ̌bȧ֥ʻĕnẇ lá⁠heֽm׃"],[9,21,"וַ⁠יֹּאמְר֧וּ אֲלֵי⁠הֶ֛ם הַ⁠נְּשִׂיאִ֖ים יִֽחְי֑וּ וַ֠⁠יִּֽהְיוּ חֹטְבֵ֨י עֵצִ֤ים וְ⁠שֹֽׁאֲבֵי־מַ֨יִם֙ לְ⁠כָל־הָ֣⁠עֵדָ֔ה כַּ⁠אֲשֶׁ֛ר דִּבְּר֥וּ לָ⁠הֶ֖ם הַ⁠נְּשִׂיאִֽים׃","wa⁠yò̇ʼmĕr֧ẇ ʼàléy⁠he֛m ha⁠nĕ̇şîyʼi֖ym yiֽẖĕy֑ẇ wa֠⁠yiֽ̇hĕyẇ ẖòtĕbé֨y ʻéẕi֤ym wĕ⁠şòֽ̌ʼàbéy-ma֨yim֙ lĕ⁠kál-há֣⁠ʻédá֔h kȧ⁠ʼàşě֛r di̇bĕ̇r֥ẇ lá⁠he֖m ha⁠nĕ̇şîyʼiֽym׃"],[9,22,"וַ⁠יִּקְרָ֤א לָ⁠הֶם֙ יְהוֹשֻׁ֔עַ וַ⁠יְדַבֵּ֥ר אֲלֵי⁠הֶ֖ם לֵ⁠אמֹ֑ר לָ⁠מָּה֩ רִמִּיתֶ֨ם אֹתָ֜⁠נוּ לֵ⁠אמֹ֗ר רְחוֹקִ֨ים אֲנַ֤חְנוּ מִ⁠כֶּם֙ מְאֹ֔ד וְ⁠אַתֶּ֖ם בְּ⁠קִרְבֵּ֥⁠נוּ יֹשְׁבִֽים׃","wa⁠yi̇qĕrá֤ʼ lá⁠hem֙ yĕhwòşǔ֔ʻa wa⁠yĕdabé֥̇r ʼàléy⁠he֖m lé⁠ʼmò֑r lá⁠má̇h֩ rimi̇yţe֨m ʼòţá֜⁠nẇ lé⁠ʼmò֗r rĕẖwòqi֨ym ʼàna֤ẖĕnẇ mi⁠kėm֙ mĕʼò֔d wĕ⁠ʼaţė֖m bĕ̇⁠qirĕbé֥̇⁠nẇ yòşĕ̌biֽym׃"],[9,23,"וְ⁠עַתָּ֖ה אֲרוּרִ֣ים אַתֶּ֑ם וְ⁠לֹֽא־יִכָּרֵ֨ת מִ⁠כֶּ֜ם עֶ֗בֶד וְ⁠חֹטְבֵ֥י עֵצִ֛ים וְ⁠שֹֽׁאֲבֵי־מַ֖יִם לְ⁠בֵ֥ית אֱלֹהָֽ⁠י׃","wĕ⁠ʻaţá֖̇h ʼàrẇri֣ym ʼaţė֑m wĕ⁠lòֽʼ-yiká̇ré֨ţ mi⁠kė֜m ʻe֗bed wĕ⁠ẖòtĕbé֥y ʻéẕi֛ym wĕ⁠şòֽ̌ʼàbéy-ma֖yim lĕ⁠bé֥yţ ʼèlòháֽ⁠y׃"],[9,24,"וַ⁠יַּעֲנ֨וּ אֶת־יְהוֹשֻׁ֜עַ וַ⁠יֹּאמְר֗וּ כִּי֩ הֻגֵּ֨ד הֻגַּ֤ד לַ⁠עֲבָדֶ֨י⁠ךָ֙ אֵת֩ אֲשֶׁ֨ר צִוָּ֜ה יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ אֶת־מֹשֶׁ֣ה עַבְדּ֔⁠וֹ לָ⁠תֵ֤ת לָ⁠כֶם֙ אֶת־כָּל־הָ⁠אָ֔רֶץ וּ⁠לְ⁠הַשְׁמִ֛יד אֶת־כָּל־יֹשְׁבֵ֥י הָ⁠אָ֖רֶץ מִ⁠פְּנֵי⁠כֶ֑ם וַ⁠נִּירָ֨א מְאֹ֤ד לְ⁠נַפְשֹׁתֵ֨י⁠נוּ֙ מִ⁠פְּנֵי⁠כֶ֔ם וַֽ⁠נַּעֲשֵׂ֖ה אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","wa⁠yȧʻàn֨ẇ ʼeţ-yĕhwòşǔ֜ʻa wa⁠yò̇ʼmĕr֗ẇ ki̇y֩ hugé̇֨d hugȧ֤d la⁠ʻàbáde֨y⁠ká֙ ʼéţ֩ ʼàşě֨r ẕiwá̇֜h yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʼeţ-mòşě֣h ʻabĕḋ֔⁠wò lá⁠ţé֤ţ lá⁠kem֙ ʼeţ-ká̇l-há⁠ʼá֔reẕ ẇ⁠lĕ⁠haşĕ̌mi֛yd ʼeţ-ká̇l-yòşĕ̌bé֥y há⁠ʼá֖reẕ mi⁠pĕ̇néy⁠ke֑m wa⁠ni̇yrá֨ʼ mĕʼò֤d lĕ⁠napĕşò̌ţé֨y⁠nẇ֙ mi⁠pĕ̇néy⁠ke֔m waֽ⁠nȧʻàşé֖̂h ʼeţ-ha⁠dá̇bá֥r ha⁠zėֽh׃"],[9,25,"וְ⁠עַתָּ֖ה הִנְ⁠נ֣וּ בְ⁠יָדֶ֑⁠ךָ כַּ⁠טּ֨וֹב וְ⁠כַ⁠יָּשָׁ֧ר בְּ⁠עֵינֶ֛י⁠ךָ לַ⁠עֲשׂ֥וֹת לָ֖⁠נוּ עֲשֵֽׂה׃","wĕ⁠ʻaţá֖̇h hinĕ⁠n֣ẇ bĕ⁠yáde֑⁠ká kȧ⁠ṫ֨wòb wĕ⁠ka⁠yá̇şá֧̌r bĕ̇⁠ʻéyne֛y⁠ká la⁠ʻàş֥̂wòţ lá֖⁠nẇ ʻàşéֽ̂h׃"],[9,26,"וַ⁠יַּ֥עַשׂ לָ⁠הֶ֖ם כֵּ֑ן וַ⁠יַּצֵּ֥ל אוֹתָ֛⁠ם מִ⁠יַּ֥ד בְּנֵֽי־יִשְׂרָאֵ֖ל וְ⁠לֹ֥א הֲרָגֽוּ⁠ם׃","wa⁠yȧ֥ʻaş̂ lá⁠he֖m ké֑̇n wa⁠yȧẕé֥̇l ʼwòţá֛⁠m mi⁠yȧ֥d bĕ̇néֽy-yişĕ̂ráʼé֖l wĕ⁠lò֥ʼ hàrágֽẇ⁠m׃"],[9,27,"וַ⁠יִּתְּנֵ֨⁠ם יְהוֹשֻׁ֜עַ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא חֹטְבֵ֥י עֵצִ֛ים וְ⁠שֹׁ֥אֲבֵי מַ֖יִם לָֽ⁠עֵדָ֑ה וּ⁠לְ⁠מִזְבַּ֤ח יְהוָה֙ עַד־הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה אֶל־הַ⁠מָּק֖וֹם אֲשֶׁ֥ר יִבְחָֽר׃פ","wa⁠yi̇ţĕ̇né֨⁠m yĕhwòşǔ֜ʻa bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ ẖòtĕbé֥y ʻéẕi֛ym wĕ⁠şò֥̌ʼàbéy ma֖yim láֽ⁠ʻédá֑h ẇ⁠lĕ⁠mizĕbȧ֤ẖ yĕhwáh֙ ʻad-ha⁠ẏ֣wòm ha⁠zė֔h ʼel-ha⁠má̇q֖wòm ʼàşě֥r yibĕẖáֽr׃p"],[10,1,"וַ⁠יְהִי֩ כִ⁠שְׁמֹ֨עַ אֲדֹֽנִי־צֶ֜דֶק מֶ֣לֶךְ יְרוּשָׁלִַ֗ם כִּֽי־לָכַ֨ד יְהוֹשֻׁ֣עַ אֶת־הָ⁠עַי֮ וַ⁠יַּחֲרִימָ⁠הּ֒ כַּ⁠אֲשֶׁ֨ר עָשָׂ֤ה לִֽ⁠ירִיחוֹ֙ וּ⁠לְ⁠מַלְכָּ֔⁠הּ כֵּן־עָשָׂ֥ה לָ⁠עַ֖י וּ⁠לְ⁠מַלְכָּ֑⁠הּ וְ⁠כִ֨י הִשְׁלִ֜ימוּ יֹשְׁבֵ֤י גִבְעוֹן֙ אֶת־יִשְׂרָאֵ֔ל וַ⁠יִּֽהְי֖וּ בְּ⁠קִרְבָּֽ⁠ם׃","wa⁠yĕhiy֩ ki⁠şĕ̌mò֨ʻa ʼàdòֽniy-ẕe֜deq me֣lekĕ yĕrẇşá̌lia֗m kiֽ̇y-láka֨d yĕhwòşǔ֣ʻa ʼeţ-há⁠ʻay֮ wa⁠yȧẖàriymá⁠ḣ֒ kȧ⁠ʼàşě֨r ʻáşá֤̂h liֽ⁠yriyẖwò֙ ẇ⁠lĕ⁠malĕká̇֔⁠ḣ ké̇n-ʻáşá֥̂h lá⁠ʻa֖y ẇ⁠lĕ⁠malĕká֑̇⁠ḣ wĕ⁠ki֨y hişĕ̌li֜ymẇ yòşĕ̌bé֤y gibĕʻwòn֙ ʼeţ-yişĕ̂ráʼé֔l wa⁠yiֽ̇hĕy֖ẇ bĕ̇⁠qirĕbáֽ̇⁠m׃"],[10,2,"וַ⁠יִּֽירְא֣וּ מְאֹ֔ד כִּ֣י עִ֤יר גְּדוֹלָה֙ גִּבְע֔וֹן כְּ⁠אַחַ֖ת עָרֵ֣י הַ⁠מַּמְלָכָ֑ה וְ⁠כִ֨י הִ֤יא גְדוֹלָה֙ מִן־הָ⁠עַ֔י וְ⁠כָל־אֲנָשֶׁ֖י⁠הָ גִּבֹּרִֽים׃","wa⁠yiֽ̇yrĕʼ֣ẇ mĕʼò֔d ki֣̇y ʻi֤yr gĕ̇dwòláh֙ gi̇bĕʻ֔wòn kĕ̇⁠ʼaẖa֖ţ ʻáré֣y ha⁠mȧmĕláká֑h wĕ⁠ki֨y hi֤yʼ gĕdwòláh֙ min-há⁠ʻa֔y wĕ⁠kál-ʼànáşě֖y⁠há gi̇bò̇riֽym׃"],[10,3,"וַ⁠יִּשְׁלַ֨ח אֲדֹנִי־צֶ֜דֶק מֶ֣לֶךְ יְרוּשָׁלִַ֗ם אֶל־הוֹהָ֣ם מֶֽלֶךְ־חֶ֠בְרוֹן וְ⁠אֶל־פִּרְאָ֨ם מֶֽלֶךְ־יַרְמ֜וּת וְ⁠אֶל־יָפִ֧יעַ מֶֽלֶךְ־לָכִ֛ישׁ וְ⁠אֶל־דְּבִ֥יר מֶֽלֶךְ־עֶגְל֖וֹן לֵ⁠אמֹֽר׃","wa⁠yi̇şĕ̌la֨ẖ ʼàdòniy-ẕe֜deq me֣lekĕ yĕrẇşá̌lia֗m ʼel-hwòhá֣m meֽlekĕ-ẖe֠bĕrwòn wĕ⁠ʼel-pi̇rĕʼá֨m meֽlekĕ-yarĕm֜ẇţ wĕ⁠ʼel-yápi֧yʻa meֽlekĕ-láki֛yş̌ wĕ⁠ʼel-dĕ̇bi֥yr meֽlekĕ-ʻegĕl֖wòn lé⁠ʼmòֽr׃"],[10,4,"עֲלֽוּ־אֵלַ֣⁠י וְ⁠עִזְרֻ֔⁠נִי וְ⁠נַכֶּ֖ה אֶת־גִּבְע֑וֹן כִּֽי־הִשְׁלִ֥ימָה אֶת־יְהוֹשֻׁ֖עַ וְ⁠אֶת־בְּנֵ֥י יִשְׂרָאֵֽל׃","ʻàlֽẇ-ʼéla֣⁠y wĕ⁠ʻizĕru֔⁠niy wĕ⁠nakė֖h ʼeţ-gi̇bĕʻ֑wòn kiֽ̇y-hişĕ̌li֥ymáh ʼeţ-yĕhwòşǔ֖ʻa wĕ⁠ʼeţ-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[10,5,"וַ⁠יֵּאָסְפ֨וּ וַֽ⁠יַּעֲל֜וּ חֲמֵ֣שֶׁת ׀ מַלְכֵ֣י הָ⁠אֱמֹרִ֗י מֶ֣לֶךְ יְרוּשָׁלִַ֜ם מֶֽלֶךְ־חֶבְר֤וֹן מֶֽלֶךְ־יַרְמוּת֙ מֶֽלֶךְ־לָכִ֣ישׁ מֶֽלֶךְ־עֶגְל֔וֹן הֵ֖ם וְ⁠כָל־מַֽחֲנֵי⁠הֶ֑ם וַֽ⁠יַּחֲנוּ֙ עַל־גִּבְע֔וֹן וַ⁠יִּֽלָּחֲמ֖וּ עָלֶֽי⁠הָ׃","wa⁠yé̇ʼásĕp֨ẇ waֽ⁠yȧʻàl֜ẇ ẖàmé֣şěţ ׀ malĕké֣y há⁠ʼèmòri֗y me֣lekĕ yĕrẇşá̌lia֜m meֽlekĕ-ẖebĕr֤wòn meֽlekĕ-yarĕmẇţ֙ meֽlekĕ-láki֣yş̌ meֽlekĕ-ʻegĕl֔wòn hé֖m wĕ⁠kál-maֽẖànéy⁠he֑m waֽ⁠yȧẖànẇ֙ ʻal-gi̇bĕʻ֔wòn wa⁠yiֽ̇lá̇ẖàm֖ẇ ʻáleֽy⁠há׃"],[10,6,"וַ⁠יִּשְׁלְח֣וּ אַנְשֵׁי֩ גִבְע֨וֹן אֶל־יְהוֹשֻׁ֤עַ אֶל־הַֽ⁠מַּחֲנֶה֙ הַ⁠גִּלְגָּ֣לָ⁠ה לֵ⁠אמֹ֔ר אַל־תֶּ֥רֶף יָדֶ֖י⁠ךָ מֵֽ⁠עֲבָדֶ֑י⁠ךָ עֲלֵ֧ה אֵלֵ֣י⁠נוּ מְהֵרָ֗ה וְ⁠הוֹשִׁ֤יעָ⁠ה לָּ֨⁠נוּ֙ וְ⁠עָזְרֵ֔⁠נוּ כִּ֚י נִקְבְּצ֣וּ אֵלֵ֔י⁠נוּ כָּל־מַלְכֵ֥י הָ⁠אֱמֹרִ֖י יֹשְׁבֵ֥י הָ⁠הָֽר׃","wa⁠yi̇şĕ̌lĕẖ֣ẇ ʼanĕşé̌y֩ gibĕʻ֨wòn ʼel-yĕhwòşǔ֤ʻa ʼel-haֽ⁠mȧẖàneh֙ ha⁠gi̇lĕgá֣̇lá⁠h lé⁠ʼmò֔r ʼal-ţė֥rep yáde֖y⁠ká méֽ⁠ʻàbáde֑y⁠ká ʻàlé֧h ʼélé֣y⁠nẇ mĕhérá֗h wĕ⁠hwòşǐ֤yʻá⁠h lá̇֨⁠nẇ֙ wĕ⁠ʻázĕré֔⁠nẇ ki֚̇y niqĕbĕ̇ẕ֣ẇ ʼélé֔y⁠nẇ ká̇l-malĕké֥y há⁠ʼèmòri֖y yòşĕ̌bé֥y há⁠háֽr׃"],[10,7,"וַ⁠יַּ֨עַל יְהוֹשֻׁ֜עַ מִן־הַ⁠גִּלְגָּ֗ל ה֚וּא וְ⁠כָל־עַ֤ם הַ⁠מִּלְחָמָה֙ עִמּ֔⁠וֹ וְ⁠כֹ֖ל גִּבּוֹרֵ֥י הֶ⁠חָֽיִל׃פ","wa⁠yȧ֨ʻal yĕhwòşǔ֜ʻa min-ha⁠gi̇lĕgá̇֗l h֚ẇʼ wĕ⁠kál-ʻa֤m ha⁠mi̇lĕẖámáh֙ ʻiṁ֔⁠wò wĕ⁠kò֖l gi̇ḃwòré֥y he⁠ẖáֽyil׃p"],[10,8,"וַ⁠יֹּ֨אמֶר יְהוָ֤ה אֶל־יְהוֹשֻׁ֨עַ֙ אַל־תִּירָ֣א מֵ⁠הֶ֔ם כִּ֥י בְ⁠יָדְ⁠ךָ֖ נְתַתִּ֑י⁠ם לֹֽא־יַעֲמֹ֥ד אִ֛ישׁ מֵ⁠הֶ֖ם בְּ⁠פָנֶֽי⁠ךָ׃","wa⁠yò̇֨ʼmer yĕhwá֤h ʼel-yĕhwòşǔ֨ʻa֙ ʼal-ţi̇yrá֣ʼ mé⁠he֔m ki֥̇y bĕ⁠yádĕ⁠ká֖ nĕţaţi֑̇y⁠m lòֽʼ-yaʻàmò֥d ʼi֛yş̌ mé⁠he֖m bĕ̇⁠páneֽy⁠ká׃"],[10,9,"וַ⁠יָּבֹ֧א אֲלֵי⁠הֶ֛ם יְהוֹשֻׁ֖עַ פִּתְאֹ֑ם כָּל־הַ⁠לַּ֕יְלָה עָלָ֖ה מִן־הַ⁠גִּלְגָּֽל׃","wa⁠yá̇bò֧ʼ ʼàléy⁠he֛m yĕhwòşǔ֖ʻa pi̇ţĕʼò֑m ká̇l-ha⁠lȧ֕yĕláh ʻálá֖h min-ha⁠gi̇lĕgáֽ̇l׃"],[10,10,"וַ⁠יְהֻמֵּ֤⁠ם יְהוָה֙ לִ⁠פְנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יַּכֵּ֥⁠ם מַכָּֽה־גְדוֹלָ֖ה בְּ⁠גִבְע֑וֹן וַֽ⁠יִּרְדְּפֵ֗⁠ם דֶּ֚רֶךְ מַעֲלֵ֣ה בֵית־חוֹרֹ֔ן וַ⁠יַּכֵּ֥⁠ם עַד־עֲזֵקָ֖ה וְ⁠עַד־מַקֵּדָֽה׃","wa⁠yĕhumé֤̇⁠m yĕhwáh֙ li⁠pĕné֣y yişĕ̂ráʼé֔l wa⁠yȧké֥̇⁠m makáֽ̇h-gĕdwòlá֖h bĕ̇⁠gibĕʻ֑wòn waֽ⁠yi̇rĕdĕ̇pé֗⁠m dė֚rekĕ maʻàlé֣h béyţ-ẖwòrò֔n wa⁠yȧké֥̇⁠m ʻad-ʻàzéqá֖h wĕ⁠ʻad-maqé̇dáֽh׃"],[10,11,"וַ⁠יְהִ֞י בְּ⁠נֻסָ֣⁠ם ׀ מִ⁠פְּנֵ֣י יִשְׂרָאֵ֗ל הֵ֞ם בְּ⁠מוֹרַ֤ד בֵּית־חוֹרֹן֙ וַֽ⁠יהוָ֡ה הִשְׁלִ֣יךְ עֲלֵי⁠הֶם֩ אֲבָנִ֨ים גְּדֹל֧וֹת מִן־הַ⁠שָּׁמַ֛יִם עַד־עֲזֵקָ֖ה וַ⁠יָּמֻ֑תוּ רַבִּ֗ים אֲשֶׁר־מֵ֨תוּ֙ בְּ⁠אַבְנֵ֣י הַ⁠בָּרָ֔ד מֵ⁠אֲשֶׁ֥ר הָרְג֛וּ בְּנֵ֥י יִשְׂרָאֵ֖ל בֶּ⁠חָֽרֶב׃ס","wa⁠yĕhi֞y bĕ̇⁠nusá֣⁠m ׀ mi⁠pĕ̇né֣y yişĕ̂ráʼé֗l hé֞m bĕ̇⁠mwòra֤d bé̇yţ-ẖwòròn֙ waֽ⁠yhwá֡h hişĕ̌li֣ykĕ ʻàléy⁠hem֩ ʼàbáni֨ym gĕ̇dòl֧wòţ min-ha⁠şá̇̌ma֛yim ʻad-ʻàzéqá֖h wa⁠yá̇mu֑ţẇ rabi̇֗ym ʼàşěr-mé֨ţẇ֙ bĕ̇⁠ʼabĕné֣y ha⁠bá̇rá֔d mé⁠ʼàşě֥r hárĕg֛ẇ bĕ̇né֥y yişĕ̂ráʼé֖l bė⁠ẖáֽreb׃s"],[10,12,"אָ֣ז יְדַבֵּ֤ר יְהוֹשֻׁעַ֙ לַֽ⁠יהוָ֔ה בְּ⁠י֗וֹם תֵּ֤ת יְהוָה֙ אֶת־הָ֣⁠אֱמֹרִ֔י לִ⁠פְנֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יֹּ֣אמֶר ׀ לְ⁠עֵינֵ֣י יִשְׂרָאֵ֗ל שֶׁ֚מֶשׁ בְּ⁠גִבְע֣וֹן דּ֔וֹם וְ⁠יָרֵ֖חַ בְּ⁠עֵ֥מֶק אַיָּלֽוֹן׃","ʼá֣z yĕdabé֤̇r yĕhwòşǔʻa֙ laֽ⁠yhwá֔h bĕ̇⁠y֗wòm ţé֤̇ţ yĕhwáh֙ ʼeţ-há֣⁠ʼèmòri֔y li⁠pĕné֖y bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yò֣̇ʼmer ׀ lĕ⁠ʻéyné֣y yişĕ̂ráʼé֗l şě֚meş̌ bĕ̇⁠gibĕʻ֣wòn ḋ֔wòm wĕ⁠yáré֖ẖa bĕ̇⁠ʻé֥meq ʼayá̇lֽwòn׃"],[10,13,"וַ⁠יִּדֹּ֨ם הַ⁠שֶּׁ֜מֶשׁ וְ⁠יָרֵ֣חַ עָמָ֗ד עַד־יִקֹּ֥ם גּוֹי֙ אֹֽיְבָ֔י⁠ו הֲ⁠לֹא־הִ֥יא כְתוּבָ֖ה עַל־סֵ֣פֶר הַ⁠יָּשָׁ֑ר וַ⁠יַּעֲמֹ֤ד הַ⁠שֶּׁ֨מֶשׁ֙ בַּ⁠חֲצִ֣י הַ⁠שָּׁמַ֔יִם וְ⁠לֹא־אָ֥ץ לָ⁠ב֖וֹא כְּ⁠י֥וֹם תָּמִֽים׃","wa⁠yi̇dò̇֨m ha⁠şė̌֜meş̌ wĕ⁠yáré֣ẖa ʻámá֗d ʻad-yiqò֥̇m ġwòy֙ ʼòֽyĕbá֔y⁠w hà⁠lòʼ-hi֥yʼ kĕţẇbá֖h ʻal-sé֣per ha⁠yá̇şá֑̌r wa⁠yȧʻàmò֤d ha⁠şė̌֨meş̌֙ bȧ⁠ẖàẕi֣y ha⁠şá̇̌ma֔yim wĕ⁠lòʼ-ʼá֥ẕ lá⁠b֖wòʼ kĕ̇⁠y֥wòm ţá̇miֽym׃"],[10,14,"וְ⁠לֹ֨א הָיָ֜ה כַּ⁠יּ֤וֹם הַ⁠הוּא֙ לְ⁠פָנָ֣י⁠ו וְ⁠אַחֲרָ֔י⁠ו לִ⁠שְׁמֹ֥עַ יְהוָ֖ה בְּ⁠ק֣וֹל אִ֑ישׁ כִּ֣י יְהוָ֔ה נִלְחָ֖ם לְ⁠יִשְׂרָאֵֽל׃פ","wĕ⁠lò֨ʼ háyá֜h kȧ⁠ẏ֤wòm ha⁠hẇʼ֙ lĕ⁠páná֣y⁠w wĕ⁠ʼaẖàrá֔y⁠w li⁠şĕ̌mò֥ʻa yĕhwá֖h bĕ̇⁠q֣wòl ʼi֑yş̌ ki֣̇y yĕhwá֔h nilĕẖá֖m lĕ⁠yişĕ̂ráʼéֽl׃p"],[10,15,"וַ⁠יָּ֤שָׁב יְהוֹשֻׁ֨עַ֙ וְ⁠כָל־יִשְׂרָאֵ֣ל עִמּ֔⁠וֹ אֶל־הַֽ⁠מַּחֲנֶ֖ה הַ⁠גִּלְגָּֽלָ⁠ה׃","wa⁠yá֤̇şá̌b yĕhwòşǔ֨ʻa֙ wĕ⁠kál-yişĕ̂ráʼé֣l ʻiṁ֔⁠wò ʼel-haֽ⁠mȧẖàne֖h ha⁠gi̇lĕgáֽ̇lá⁠h׃"],[10,16,"וַ⁠יָּנֻ֕סוּ חֲמֵ֖שֶׁת הַ⁠מְּלָכִ֣ים הָ⁠אֵ֑לֶּה וַ⁠יֵּחָבְא֥וּ בַ⁠מְּעָרָ֖ה בְּ⁠מַקֵּדָֽה׃","wa⁠yá̇nu֕sẇ ẖàmé֖şěţ ha⁠mĕ̇láki֣ym há⁠ʼé֑lėh wa⁠yé̇ẖábĕʼ֥ẇ ba⁠mĕ̇ʻárá֖h bĕ̇⁠maqé̇dáֽh׃"],[10,17,"וַ⁠יֻּגַּ֖ד לִ⁠יהוֹשֻׁ֣עַ לֵ⁠אמֹ֑ר נִמְצְאוּ֙ חֲמֵ֣שֶׁת הַ⁠מְּלָכִ֔ים נֶחְבְּאִ֥ים בַּ⁠מְּעָרָ֖ה בְּ⁠מַקֵּדָֽה׃","wa⁠yu̇gȧ֖d li⁠yhwòşǔ֣ʻa lé⁠ʼmò֑r nimĕẕĕʼẇ֙ ẖàmé֣şěţ ha⁠mĕ̇láki֔ym neẖĕbĕ̇ʼi֥ym bȧ⁠mĕ̇ʻárá֖h bĕ̇⁠maqé̇dáֽh׃"],[10,18,"וַ⁠יֹּ֣אמֶר יְהוֹשֻׁ֔עַ גֹּ֛לּוּ אֲבָנִ֥ים גְּדֹל֖וֹת אֶל־פִּ֣י הַ⁠מְּעָרָ֑ה וְ⁠הַפְקִ֧ידוּ עָלֶ֛י⁠הָ אֲנָשִׁ֖ים לְ⁠שָׁמְרָֽ⁠ם׃","wa⁠yò֣̇ʼmer yĕhwòşǔ֔ʻa gò֛̇l̇ẇ ʼàbáni֥ym gĕ̇dòl֖wòţ ʼel-pi֣̇y ha⁠mĕ̇ʻárá֑h wĕ⁠hapĕqi֧ydẇ ʻále֛y⁠há ʼànáşǐ֖ym lĕ⁠şá̌mĕráֽ⁠m׃"],[10,19,"וְ⁠אַתֶּם֙ אַֽל־תַּעֲמֹ֔דוּ רִדְפוּ֙ אַחֲרֵ֣י אֹֽיְבֵי⁠כֶ֔ם וְ⁠זִנַּבְתֶּ֖ם אוֹתָ֑⁠ם אַֽל־תִּתְּנ֗וּ⁠ם לָ⁠בוֹא֙ אֶל־עָ֣רֵי⁠הֶ֔ם כִּ֧י נְתָנָ֛⁠ם יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם בְּ⁠יֶדְ⁠כֶֽם׃","wĕ⁠ʼaţėm֙ ʼaֽl-ţȧʻàmò֔dẇ ridĕpẇ֙ ʼaẖàré֣y ʼòֽyĕbéy⁠ke֔m wĕ⁠zinȧbĕţė֖m ʼwòţá֑⁠m ʼaֽl-ţi̇ţĕ̇n֗ẇ⁠m lá⁠bwòʼ֙ ʼel-ʻá֣réy⁠he֔m ki֧̇y nĕţáná֛⁠m yĕhwá֥h ʼèlòhéy⁠ke֖m bĕ̇⁠yedĕ⁠keֽm׃"],[10,20,"וַ⁠יְהִי֩ כְּ⁠כַלּ֨וֹת יְהוֹשֻׁ֜עַ וּ⁠בְנֵ֣י יִשְׂרָאֵ֗ל לְ⁠הַכּוֹתָ֛⁠ם מַכָּ֥ה גְדוֹלָֽה־מְאֹ֖ד עַד־תֻּמָּ֑⁠ם וְ⁠הַ⁠שְּׂרִידִים֙ שָׂרְד֣וּ מֵ⁠הֶ֔ם וַ⁠יָּבֹ֖אוּ אֶל־עָרֵ֥י הַ⁠מִּבְצָֽר׃","wa⁠yĕhiy֩ kĕ̇⁠kal̇֨wòţ yĕhwòşǔ֜ʻa ẇ⁠bĕné֣y yişĕ̂ráʼé֗l lĕ⁠hak̇wòţá֛⁠m maká֥̇h gĕdwòláֽh-mĕʼò֖d ʻad-ţu̇má֑̇⁠m wĕ⁠ha⁠şĕ̇̂riydiym֙ şá̂rĕd֣ẇ mé⁠he֔m wa⁠yá̇bò֖ʼẇ ʼel-ʻáré֥y ha⁠mi̇bĕẕáֽr׃"],[10,21,"וַ⁠יָּשֻׁבוּ֩ כָל־הָ⁠עָ֨ם אֶל־הַ⁠מַּחֲנֶ֧ה אֶל־יְהוֹשֻׁ֛עַ מַקֵּדָ֖ה בְּ⁠שָׁל֑וֹם לֹֽא־חָרַ֞ץ לִ⁠בְנֵ֧י יִשְׂרָאֵ֛ל לְ⁠אִ֖ישׁ אֶת־לְשֹׁנֽ⁠וֹ׃","wa⁠yá̇şǔbẇ֩ kál-há⁠ʻá֨m ʼel-ha⁠mȧẖàne֧h ʼel-yĕhwòşǔ֛ʻa maqé̇dá֖h bĕ̇⁠şá̌l֑wòm lòֽʼ-ẖára֞ẕ li⁠bĕné֧y yişĕ̂ráʼé֛l lĕ⁠ʼi֖yş̌ ʼeţ-lĕşò̌nֽ⁠wò׃"],[10,22,"וַ⁠יֹּ֣אמֶר יְהוֹשֻׁ֔עַ פִּתְח֖וּ אֶת־פִּ֣י הַ⁠מְּעָרָ֑ה וְ⁠הוֹצִ֣יאוּ אֵלַ֗⁠י אֶת־חֲמֵ֛שֶׁת הַ⁠מְּלָכִ֥ים הָ⁠אֵ֖לֶּה מִן־הַ⁠מְּעָרָֽה׃","wa⁠yò֣̇ʼmer yĕhwòşǔ֔ʻa pi̇ţĕẖ֖ẇ ʼeţ-pi֣̇y ha⁠mĕ̇ʻárá֑h wĕ⁠hwòẕi֣yʼẇ ʼéla֗⁠y ʼeţ-ẖàmé֛şěţ ha⁠mĕ̇láki֥ym há⁠ʼé֖lėh min-ha⁠mĕ̇ʻáráֽh׃"],[10,23,"וַ⁠יַּ֣עֲשׂוּ כֵ֔ן וַ⁠יֹּצִ֣יאוּ אֵלָ֗י⁠ו אֶת־חֲמֵ֛שֶׁת הַ⁠מְּלָכִ֥ים הָ⁠אֵ֖לֶּה מִן־הַ⁠מְּעָרָ֑ה אֵ֣ת ׀ מֶ֣לֶךְ יְרוּשָׁלִַ֗ם אֶת־מֶ֤לֶךְ חֶבְרוֹן֙ אֶת־מֶ֣לֶךְ יַרְמ֔וּת אֶת־מֶ֥לֶךְ לָכִ֖ישׁ אֶת־מֶ֥לֶךְ עֶגְלֽוֹן׃","wa⁠yȧ֣ʻàş̂ẇ ké֔n wa⁠yò̇ẕi֣yʼẇ ʼélá֗y⁠w ʼeţ-ẖàmé֛şěţ ha⁠mĕ̇láki֥ym há⁠ʼé֖lėh min-ha⁠mĕ̇ʻárá֑h ʼé֣ţ ׀ me֣lekĕ yĕrẇşá̌lia֗m ʼeţ-me֤lekĕ ẖebĕrwòn֙ ʼeţ-me֣lekĕ yarĕm֔ẇţ ʼeţ-me֥lekĕ láki֖yş̌ ʼeţ-me֥lekĕ ʻegĕlֽwòn׃"],[10,24,"וַ֠⁠יְהִי כְּֽ⁠הוֹצִיאָ֞⁠ם אֶת־הַ⁠מְּלָכִ֣ים הָ⁠אֵלֶּה֮ אֶל־יְהוֹשֻׁעַ֒ וַ⁠יִּקְרָ֨א יְהוֹשֻׁ֜עַ אֶל־כָּל־אִ֣ישׁ יִשְׂרָאֵ֗ל וַ֠⁠יֹּאמֶר אֶל־קְצִינֵ֞י אַנְשֵׁ֤י הַ⁠מִּלְחָמָה֙ הֶ⁠הָלְכ֣וּא אִתּ֔⁠וֹ קִרְב֗וּ שִׂ֚ימוּ אֶת־רַגְלֵי⁠כֶ֔ם עַֽל־צַוְּארֵ֖י הַ⁠מְּלָכִ֣ים הָ⁠אֵ֑לֶּה וַֽ⁠יִּקְרְב֔וּ וַ⁠יָּשִׂ֥ימוּ אֶת־רַגְלֵי⁠הֶ֖ם עַל־צַוְּארֵי⁠הֶֽם׃","wa֠⁠yĕhiy kĕֽ̇⁠hwòẕiyʼá֞⁠m ʼeţ-ha⁠mĕ̇láki֣ym há⁠ʼélėh֮ ʼel-yĕhwòşǔʻa֒ wa⁠yi̇qĕrá֨ʼ yĕhwòşǔ֜ʻa ʼel-ká̇l-ʼi֣yş̌ yişĕ̂ráʼé֗l wa֠⁠yò̇ʼmer ʼel-qĕẕiyné֞y ʼanĕşé֤̌y ha⁠mi̇lĕẖámáh֙ he⁠hálĕk֣ẇʼ ʼiţ̇֔⁠wò qirĕb֗ẇ şî֚ymẇ ʼeţ-ragĕléy⁠ke֔m ʻaֽl-ẕawĕ̇ʼré֖y ha⁠mĕ̇láki֣ym há⁠ʼé֑lėh waֽ⁠yi̇qĕrĕb֔ẇ wa⁠yá̇şî֥ymẇ ʼeţ-ragĕléy⁠he֖m ʻal-ẕawĕ̇ʼréy⁠heֽm׃"],[10,25,"וַ⁠יֹּ֤אמֶר אֲלֵי⁠הֶם֙ יְהוֹשֻׁ֔עַ אַל־תִּֽירְא֖וּ וְ⁠אַל־תֵּחָ֑תּוּ חִזְק֣וּ וְ⁠אִמְצ֔וּ כִּ֣י כָ֗כָה יַעֲשֶׂ֤ה יְהוָה֙ לְ⁠כָל־אֹ֣יְבֵי⁠כֶ֔ם אֲשֶׁ֥ר אַתֶּ֖ם נִלְחָמִ֥ים אוֹתָֽ⁠ם׃","wa⁠yò֤̇ʼmer ʼàléy⁠hem֙ yĕhwòşǔ֔ʻa ʼal-ţiֽ̇yrĕʼ֖ẇ wĕ⁠ʼal-ţé̇ẖá֑ţ̇ẇ ẖizĕq֣ẇ wĕ⁠ʼimĕẕ֔ẇ ki֣̇y ká֗káh yaʻàşê֤h yĕhwáh֙ lĕ⁠kál-ʼò֣yĕbéy⁠ke֔m ʼàşě֥r ʼaţė֖m nilĕẖámi֥ym ʼwòţáֽ⁠m׃"],[10,26,"וַ⁠יַּכֵּ֨⁠ם יְהוֹשֻׁ֤עַ אַֽחֲרֵי־כֵן֙ וַ⁠יְמִיתֵ֔⁠ם וַ⁠יִּתְלֵ֕⁠ם עַ֖ל חֲמִשָּׁ֣ה עֵצִ֑ים וַ⁠יִּֽהְי֛וּ תְּלוּיִ֥ם עַל־הָ⁠עֵצִ֖ים עַד־הָ⁠עָֽרֶב׃","wa⁠yȧké̇֨⁠m yĕhwòşǔ֤ʻa ʼaֽẖàréy-kén֙ wa⁠yĕmiyţé֔⁠m wa⁠yi̇ţĕlé֕⁠m ʻa֖l ẖàmişá֣̇̌h ʻéẕi֑ym wa⁠yiֽ̇hĕy֛ẇ ţĕ̇lẇyi֥m ʻal-há⁠ʻéẕi֖ym ʻad-há⁠ʻáֽreb׃"],[10,27,"וַ⁠יְהִ֞י לְ⁠עֵ֣ת ׀ בּ֣וֹא הַ⁠שֶּׁ֗מֶשׁ צִוָּ֤ה יְהוֹשֻׁ֨עַ֙ וַ⁠יֹּֽרִידוּ⁠ם֙ מֵ⁠עַ֣ל הָ⁠עֵצִ֔ים וַ⁠יַּ֨שְׁלִכֻ֔⁠ם אֶל־הַ⁠מְּעָרָ֖ה אֲשֶׁ֣ר נֶחְבְּאוּ־שָׁ֑ם וַ⁠יָּשִׂ֜מוּ אֲבָנִ֤ים גְּדֹלוֹת֙ עַל־פִּ֣י הַ⁠מְּעָרָ֔ה עַד־עֶ֖צֶם הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wa⁠yĕhi֞y lĕ⁠ʻé֣ţ ׀ ḃ֣wòʼ ha⁠şė̌֗meş̌ ẕiwá֤̇h yĕhwòşǔ֨ʻa֙ wa⁠yòֽ̇riydẇ⁠m֙ mé⁠ʻa֣l há⁠ʻéẕi֔ym wa⁠yȧ֨şĕ̌liku֔⁠m ʼel-ha⁠mĕ̇ʻárá֖h ʼàşě֣r neẖĕbĕ̇ʼẇ-şá֑̌m wa⁠yá̇şî֜mẇ ʼàbáni֤ym gĕ̇dòlwòţ֙ ʻal-pi֣̇y ha⁠mĕ̇ʻárá֔h ʻad-ʻe֖ẕem ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[10,28,"וְ⁠אֶת־מַקֵּדָה֩ לָכַ֨ד יְהוֹשֻׁ֜עַ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא וַ⁠יַּכֶּ֣⁠הָ לְ⁠פִי־חֶרֶב֮ וְ⁠אֶת־מַלְכָּ⁠הּ֒ הֶחֱרִ֣ם אוֹתָ֗⁠ם וְ⁠אֶת־כָּל־הַ⁠נֶּ֨פֶשׁ֙ אֲשֶׁר־בָּ֔⁠הּ לֹ֥א הִשְׁאִ֖יר שָׂרִ֑יד וַ⁠יַּ֨עַשׂ֙ לְ⁠מֶ֣לֶךְ מַקֵּדָ֔ה כַּ⁠אֲשֶׁ֥ר עָשָׂ֖ה לְ⁠מֶ֥לֶךְ יְרִיחֽוֹ׃","wĕ⁠ʼeţ-maqé̇dáh֩ láka֨d yĕhwòşǔ֜ʻa bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ wa⁠yȧkė֣⁠há lĕ⁠piy-ẖereb֮ wĕ⁠ʼeţ-malĕká̇⁠ḣ֒ heẖèri֣m ʼwòţá֗⁠m wĕ⁠ʼeţ-ká̇l-ha⁠nė֨peş̌֙ ʼàşěr-bá̇֔⁠ḣ lò֥ʼ hişĕ̌ʼi֖yr şá̂ri֑yd wa⁠yȧ֨ʻaş̂֙ lĕ⁠me֣lekĕ maqé̇dá֔h kȧ⁠ʼàşě֥r ʻáşá֖̂h lĕ⁠me֥lekĕ yĕriyẖֽwò׃"],[10,29,"וַ⁠יַּעֲבֹ֣ר יְ֠הוֹשֻׁעַ וְ⁠כָֽל־יִשְׂרָאֵ֥ל עִמּ֛⁠וֹ מִ⁠מַּקֵּדָ֖ה לִבְנָ֑ה וַ⁠יִּלָּ֖חֶם עִם־לִבְנָֽה׃","wa⁠yȧʻàbò֣r yĕ֠hwòşǔʻa wĕ⁠káֽl-yişĕ̂ráʼé֥l ʻiṁ֛⁠wò mi⁠mȧqé̇dá֖h libĕná֑h wa⁠yi̇lá֖̇ẖem ʻim-libĕnáֽh׃"],[10,30,"וַ⁠יִּתֵּן֩ יְהוָ֨ה גַּם־אוֹתָ֜⁠הּ בְּ⁠יַ֣ד יִשְׂרָאֵ֘ל וְ⁠אֶת־מַלְכָּ⁠הּ֒ וַ⁠יַּכֶּ֣⁠הָ לְ⁠פִי־חֶ֗רֶב וְ⁠אֶת־כָּל־הַ⁠נֶּ֨פֶשׁ֙ אֲשֶׁר־בָּ֔⁠הּ לֹֽא־הִשְׁאִ֥יר בָּ֖⁠הּ שָׂרִ֑יד וַ⁠יַּ֣עַשׂ לְ⁠מַלְכָּ֔⁠הּ כַּ⁠אֲשֶׁ֥ר עָשָׂ֖ה לְ⁠מֶ֥לֶךְ יְרִיחֽוֹ׃ס","wa⁠yi̇ţé̇n֩ yĕhwá֨h gȧm-ʼwòţá֜⁠ḣ bĕ̇⁠ya֣d yişĕ̂ráʼé֘l wĕ⁠ʼeţ-malĕká̇⁠ḣ֒ wa⁠yȧkė֣⁠há lĕ⁠piy-ẖe֗reb wĕ⁠ʼeţ-ká̇l-ha⁠nė֨peş̌֙ ʼàşěr-bá̇֔⁠ḣ lòֽʼ-hişĕ̌ʼi֥yr bá֖̇⁠ḣ şá̂ri֑yd wa⁠yȧ֣ʻaş̂ lĕ⁠malĕká̇֔⁠ḣ kȧ⁠ʼàşě֥r ʻáşá֖̂h lĕ⁠me֥lekĕ yĕriyẖֽwò׃s"],[10,31,"וַ⁠יַּעֲבֹ֣ר יְ֠הוֹשֻׁעַ וְ⁠כָל־יִשְׂרָאֵ֥ל עִמּ֛⁠וֹ מִ⁠לִּבְנָ֖ה לָכִ֑ישָׁ⁠ה וַ⁠יִּ֣חַן עָלֶ֔י⁠הָ וַ⁠יִּלָּ֖חֶם בָּֽ⁠הּ׃","wa⁠yȧʻàbò֣r yĕ֠hwòşǔʻa wĕ⁠kál-yişĕ̂ráʼé֥l ʻiṁ֛⁠wò mi⁠li̇bĕná֖h láki֑yşá̌⁠h wa⁠yi֣̇ẖan ʻále֔y⁠há wa⁠yi̇lá֖̇ẖem báֽ̇⁠ḣ׃"],[10,32,"וַ⁠יִּתֵּן֩ יְהוָ֨ה אֶת־לָכִ֜ישׁ בְּ⁠יַ֣ד יִשְׂרָאֵ֗ל וַֽ⁠יִּלְכְּדָ⁠הּ֙ בַּ⁠יּ֣וֹם הַ⁠שֵּׁנִ֔י וַ⁠יַּכֶּ֣⁠הָ לְ⁠פִי־חֶ֔רֶב וְ⁠אֶת־כָּל־הַ⁠נֶּ֖פֶשׁ אֲשֶׁר־בָּ֑⁠הּ כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה לְ⁠לִבְנָֽה׃פ","wa⁠yi̇ţé̇n֩ yĕhwá֨h ʼeţ-láki֜yş̌ bĕ̇⁠ya֣d yişĕ̂ráʼé֗l waֽ⁠yi̇lĕkĕ̇dá⁠ḣ֙ bȧ⁠ẏ֣wòm ha⁠şé̇̌ni֔y wa⁠yȧkė֣⁠há lĕ⁠piy-ẖe֔reb wĕ⁠ʼeţ-ká̇l-ha⁠nė֖peş̌ ʼàşěr-bá֑̇⁠ḣ kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h lĕ⁠libĕnáֽh׃p"],[10,33,"אָ֣ז עָלָ֗ה הֹרָם֙ מֶ֣לֶךְ גֶּ֔זֶר לַ⁠עְזֹ֖ר אֶת־לָכִ֑ישׁ וַ⁠יַּכֵּ֤⁠הוּ יְהוֹשֻׁ֨עַ֙ וְ⁠אֶת־עַמּ֔⁠וֹ עַד־בִּלְתִּ֥י הִשְׁאִֽיר־ל֖⁠וֹ שָׂרִֽיד׃","ʼá֣z ʻálá֗h hòrám֙ me֣lekĕ gė֔zer la⁠ʻĕzò֖r ʼeţ-láki֑yş̌ wa⁠yȧké֤̇⁠hẇ yĕhwòşǔ֨ʻa֙ wĕ⁠ʼeţ-ʻaṁ֔⁠wò ʻad-bi̇lĕţi֥̇y hişĕ̌ʼiֽyr-l֖⁠wò şá̂riֽyd׃"],[10,34,"וַ⁠יַּעֲבֹ֣ר יְ֠הוֹשֻׁעַ וְ⁠כָל־יִשְׂרָאֵ֥ל עִמּ֛⁠וֹ מִ⁠לָּכִ֖ישׁ עֶגְלֹ֑נָ⁠ה וַ⁠יַּחֲנ֣וּ עָלֶ֔י⁠הָ וַ⁠יִּֽלָּחֲמ֖וּ עָלֶֽי⁠הָ׃","wa⁠yȧʻàbò֣r yĕ֠hwòşǔʻa wĕ⁠kál-yişĕ̂ráʼé֥l ʻiṁ֛⁠wò mi⁠lá̇ki֖yş̌ ʻegĕlò֑ná⁠h wa⁠yȧẖàn֣ẇ ʻále֔y⁠há wa⁠yiֽ̇lá̇ẖàm֖ẇ ʻáleֽy⁠há׃"],[10,35,"וַֽ⁠יִּלְכְּד֜וּ⁠הָ בַּ⁠יּ֤וֹם הַ⁠הוּא֙ וַ⁠יַּכּ֣וּ⁠הָ לְ⁠פִי־חֶ֔רֶב וְ⁠אֵת֙ כָּל־הַ⁠נֶּ֣פֶשׁ אֲשֶׁר־בָּ֔⁠הּ בַּ⁠יּ֥וֹם הַ⁠ה֖וּא הֶחֱרִ֑ים כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה לְ⁠לָכִֽישׁ׃פ","waֽ⁠yi̇lĕkĕ̇d֜ẇ⁠há bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ wa⁠yȧk֣̇ẇ⁠há lĕ⁠piy-ẖe֔reb wĕ⁠ʼéţ֙ ká̇l-ha⁠nė֣peş̌ ʼàşěr-bá̇֔⁠ḣ bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ heẖèri֑ym kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h lĕ⁠lákiֽyş̌׃p"],[10,36,"וַ⁠יַּ֣עַל יְ֠הוֹשֻׁעַ וְ⁠כָֽל־יִשְׂרָאֵ֥ל עִמּ֛⁠וֹ מֵ⁠עֶגְל֖וֹנָ⁠ה חֶבְר֑וֹנָ⁠ה וַ⁠יִּֽלָּחֲמ֖וּ עָלֶֽי⁠הָ׃","wa⁠yȧ֣ʻal yĕ֠hwòşǔʻa wĕ⁠káֽl-yişĕ̂ráʼé֥l ʻiṁ֛⁠wò mé⁠ʻegĕl֖wòná⁠h ẖebĕr֑wòná⁠h wa⁠yiֽ̇lá̇ẖàm֖ẇ ʻáleֽy⁠há׃"],[10,37,"וַ⁠יִּלְכְּד֣וּ⁠הָ וַ⁠יַּכּֽוּ⁠הָ־לְ⁠פִי־חֶ֠רֶב וְ⁠אֶת־מַלְכָּ֨⁠הּ וְ⁠אֶת־כָּל־עָרֶ֜י⁠הָ וְ⁠אֶת־כָּל־הַ⁠נֶּ֤פֶשׁ אֲשֶׁר־בָּ⁠הּ֙ לֹֽא־הִשְׁאִ֣יר שָׂרִ֔יד כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה לְ⁠עֶגְל֑וֹן וַ⁠יַּחֲרֵ֣ם אוֹתָ֔⁠הּ וְ⁠אֶת־כָּל־הַ⁠נֶּ֖פֶשׁ אֲשֶׁר־בָּֽ⁠הּ׃ס","wa⁠yi̇lĕkĕ̇d֣ẇ⁠há wa⁠yȧkֽ̇ẇ⁠há-lĕ⁠piy-ẖe֠reb wĕ⁠ʼeţ-malĕká̇֨⁠ḣ wĕ⁠ʼeţ-ká̇l-ʻáre֜y⁠há wĕ⁠ʼeţ-ká̇l-ha⁠nė֤peş̌ ʼàşěr-bá̇⁠ḣ֙ lòֽʼ-hişĕ̌ʼi֣yr şá̂ri֔yd kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h lĕ⁠ʻegĕl֑wòn wa⁠yȧẖàré֣m ʼwòţá֔⁠ḣ wĕ⁠ʼeţ-ká̇l-ha⁠nė֖peş̌ ʼàşěr-báֽ̇⁠ḣ׃s"],[10,38,"וַ⁠יָּ֧שָׁב יְהוֹשֻׁ֛עַ וְ⁠כָל־יִשְׂרָאֵ֥ל עִמּ֖⁠וֹ דְּבִ֑רָ⁠ה וַ⁠יִּלָּ֖חֶם עָלֶֽי⁠הָ׃","wa⁠yá֧̇şá̌b yĕhwòşǔ֛ʻa wĕ⁠kál-yişĕ̂ráʼé֥l ʻiṁ֖⁠wò dĕ̇bi֑rá⁠h wa⁠yi̇lá֖̇ẖem ʻáleֽy⁠há׃"],[10,39,"וַֽ⁠יִּלְכְּדָ֞⁠הּ וְ⁠אֶת־מַלְכָּ֤⁠הּ וְ⁠אֶת־כָּל־עָרֶ֨י⁠הָ֙ וַ⁠יַּכּ֣וּ⁠ם לְ⁠פִי־חֶ֔רֶב וַֽ⁠יַּחֲרִ֨ימוּ֙ אֶת־כָּל־נֶ֣פֶשׁ אֲשֶׁר־בָּ֔⁠הּ לֹ֥א הִשְׁאִ֖יר שָׂרִ֑יד כַּ⁠אֲשֶׁ֨ר עָשָׂ֜ה לְ⁠חֶבְר֗וֹן כֵּן־עָשָׂ֤ה לִ⁠דְבִ֨רָ⁠ה֙ וּ⁠לְ⁠מַלְכָּ֔⁠הּ וְ⁠כַ⁠אֲשֶׁ֥ר עָשָׂ֛ה לְ⁠לִבְנָ֖ה וּ⁠לְ⁠מַלְכָּֽ⁠הּ׃","waֽ⁠yi̇lĕkĕ̇dá֞⁠ḣ wĕ⁠ʼeţ-malĕká֤̇⁠ḣ wĕ⁠ʼeţ-ká̇l-ʻáre֨y⁠há֙ wa⁠yȧk֣̇ẇ⁠m lĕ⁠piy-ẖe֔reb waֽ⁠yȧẖàri֨ymẇ֙ ʼeţ-ká̇l-ne֣peş̌ ʼàşěr-bá̇֔⁠ḣ lò֥ʼ hişĕ̌ʼi֖yr şá̂ri֑yd kȧ⁠ʼàşě֨r ʻáşá̂֜h lĕ⁠ẖebĕr֗wòn ké̇n-ʻáşá֤̂h li⁠dĕbi֨rá⁠h֙ ẇ⁠lĕ⁠malĕká̇֔⁠ḣ wĕ⁠ka⁠ʼàşě֥r ʻáşá֛̂h lĕ⁠libĕná֖h ẇ⁠lĕ⁠malĕkáֽ̇⁠ḣ׃"],[10,40,"וַ⁠יַּכֶּ֣ה יְהוֹשֻׁ֣עַ אֶת־כָּל־הָ⁠אָ֡רֶץ הָ⁠הָר֩ וְ⁠הַ⁠נֶּ֨גֶב וְ⁠הַ⁠שְּׁפֵלָ֜ה וְ⁠הָ⁠אֲשֵׁד֗וֹת וְ⁠אֵת֙ כָּל־מַלְכֵי⁠הֶ֔ם לֹ֥א הִשְׁאִ֖יר שָׂרִ֑יד וְ⁠אֵ֤ת כָּל־הַ⁠נְּשָׁמָה֙ הֶחֱרִ֔ים כַּ⁠אֲשֶׁ֣ר צִוָּ֔ה יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wa⁠yȧkė֣h yĕhwòşǔ֣ʻa ʼeţ-ká̇l-há⁠ʼá֡reẕ há⁠hár֩ wĕ⁠ha⁠nė֨geb wĕ⁠ha⁠şĕ̇̌pélá֜h wĕ⁠há⁠ʼàşé̌d֗wòţ wĕ⁠ʼéţ֙ ká̇l-malĕkéy⁠he֔m lò֥ʼ hişĕ̌ʼi֖yr şá̂ri֑yd wĕ⁠ʼé֤ţ ká̇l-ha⁠nĕ̇şá̌máh֙ heẖèri֔ym kȧ⁠ʼàşě֣r ẕiwá̇֔h yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[10,41,"וַ⁠יַּכֵּ֧⁠ם יְהוֹשֻׁ֛עַ מִ⁠קָּדֵ֥שׁ בַּרְנֵ֖עַ וְ⁠עַד־עַזָּ֑ה וְ⁠אֵ֛ת כָּל־אֶ֥רֶץ גֹּ֖שֶׁן וְ⁠עַד־גִּבְעֽוֹן׃","wa⁠yȧké֧̇⁠m yĕhwòşǔ֛ʻa mi⁠qá̇dé֥ş̌ bȧrĕné֖ʻa wĕ⁠ʻad-ʻazá֑̇h wĕ⁠ʼé֛ţ ká̇l-ʼe֥reẕ gò֖̇şěn wĕ⁠ʻad-gi̇bĕʻֽwòn׃"],[10,42,"וְ⁠אֵ֨ת כָּל־הַ⁠מְּלָכִ֤ים הָ⁠אֵ֨לֶּה֙ וְ⁠אֶת־אַרְצָ֔⁠ם לָכַ֥ד יְהוֹשֻׁ֖עַ פַּ֣עַם אֶחָ֑ת כִּ֗י יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל נִלְחָ֖ם לְ⁠יִשְׂרָאֵֽל׃","wĕ⁠ʼé֨ţ ká̇l-ha⁠mĕ̇láki֤ym há⁠ʼé֨lėh֙ wĕ⁠ʼeţ-ʼarĕẕá֔⁠m láka֥d yĕhwòşǔ֖ʻa pȧ֣ʻam ʼeẖá֑ţ ki̇֗y yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l nilĕẖá֖m lĕ⁠yişĕ̂ráʼéֽl׃"],[10,43,"וַ⁠יָּ֤שָׁב יְהוֹשֻׁ֨עַ֙ וְ⁠כָל־יִשְׂרָאֵ֣ל עִמּ֔⁠וֹ אֶל־הַֽ⁠מַּחֲנֶ֖ה הַ⁠גִּלְגָּֽלָ⁠ה׃פ","wa⁠yá֤̇şá̌b yĕhwòşǔ֨ʻa֙ wĕ⁠kál-yişĕ̂ráʼé֣l ʻiṁ֔⁠wò ʼel-haֽ⁠mȧẖàne֖h ha⁠gi̇lĕgáֽ̇lá⁠h׃p"],[11,1,"וַ⁠יְהִ֕י כִּ⁠שְׁמֹ֖עַ יָבִ֣ין מֶֽלֶךְ־חָצ֑וֹר וַ⁠יִּשְׁלַ֗ח אֶל־יוֹבָב֙ מֶ֣לֶךְ מָד֔וֹן וְ⁠אֶל־מֶ֥לֶךְ שִׁמְר֖וֹן וְ⁠אֶל־מֶ֥לֶךְ אַכְשָֽׁף׃","wa⁠yĕhi֕y ki̇⁠şĕ̌mò֖ʻa yábi֣yn meֽlekĕ-ẖáẕ֑wòr wa⁠yi̇şĕ̌la֗ẖ ʼel-ywòbáb֙ me֣lekĕ mád֔wòn wĕ⁠ʼel-me֥lekĕ şǐmĕr֖wòn wĕ⁠ʼel-me֥lekĕ ʼakĕşáֽ̌p׃"],[11,2,"וְֽ⁠אֶל־הַ⁠מְּלָכִ֞ים אֲשֶׁ֣ר מִ⁠צְּפ֗וֹן בָּ⁠הָ֧ר וּ⁠בָ⁠עֲרָבָ֛ה נֶ֥גֶב כִּֽנֲר֖וֹת וּ⁠בַ⁠שְּׁפֵלָ֑ה וּ⁠בְ⁠נָפ֥וֹת דּ֖וֹר מִ⁠יָּֽם׃","wĕֽ⁠ʼel-ha⁠mĕ̇láki֞ym ʼàşě֣r mi⁠ẕĕ̇p֗wòn bá̇⁠há֧r ẇ⁠bá⁠ʻàrábá֛h ne֥geb kiֽ̇nàr֖wòţ ẇ⁠ba⁠şĕ̇̌pélá֑h ẇ⁠bĕ⁠náp֥wòţ ḋ֖wòr mi⁠yáֽ̇m׃"],[11,3,"הַֽ⁠כְּנַעֲנִי֙ מִ⁠מִּזְרָ֣ח וּ⁠מִ⁠יָּ֔ם וְ⁠הָ⁠אֱמֹרִ֧י וְ⁠הַ⁠חִתִּ֛י וְ⁠הַ⁠פְּרִזִּ֥י וְ⁠הַ⁠יְבוּסִ֖י בָּ⁠הָ֑ר וְ⁠הַֽ⁠חִוִּי֙ תַּ֣חַת חֶרְמ֔וֹן בְּ⁠אֶ֖רֶץ הַ⁠מִּצְפָּֽה׃","haֽ⁠kĕ̇naʻàniy֙ mi⁠mi̇zĕrá֣ẖ ẇ⁠mi⁠yá̇֔m wĕ⁠há⁠ʼèmòri֧y wĕ⁠ha⁠ẖiţi֛̇y wĕ⁠ha⁠pĕ̇rizi֥̇y wĕ⁠ha⁠yĕbẇsi֖y bá̇⁠há֑r wĕ⁠haֽ⁠ẖiwi̇y֙ ţȧ֣ẖaţ ẖerĕm֔wòn bĕ̇⁠ʼe֖reẕ ha⁠mi̇ẕĕpáֽ̇h׃"],[11,4,"וַ⁠יֵּצְא֣וּ הֵ֗ם וְ⁠כָל־מַֽחֲנֵי⁠הֶם֙ עִמָּ֔⁠ם עַם־רָ֕ב כַּ⁠ח֛וֹל אֲשֶׁ֥ר עַל־שְׂפַת־הַ⁠יָּ֖ם לָ⁠רֹ֑ב וְ⁠ס֥וּס וָ⁠רֶ֖כֶב רַב־מְאֹֽד׃","wa⁠yé̇ẕĕʼ֣ẇ hé֗m wĕ⁠kál-maֽẖànéy⁠hem֙ ʻimá̇֔⁠m ʻam-rá֕b kȧ⁠ẖ֛wòl ʼàşě֥r ʻal-şĕ̂paţ-ha⁠yá֖̇m lá⁠rò֑b wĕ⁠s֥ẇs wá⁠re֖keb rab-mĕʼòֽd׃"],[11,5,"וַ⁠יִּוָּ֣עֲד֔וּ כֹּ֖ל הַ⁠מְּלָכִ֣ים הָ⁠אֵ֑לֶּה וַ⁠יָּבֹ֜אוּ וַ⁠יַּחֲנ֤וּ יַחְדָּו֙ אֶל־מֵ֣י מֵר֔וֹם לְ⁠הִלָּחֵ֖ם עִם־יִשְׂרָאֵֽל׃פ","wa⁠yi̇wá֣̇ʻàd֔ẇ kò֖̇l ha⁠mĕ̇láki֣ym há⁠ʼé֑lėh wa⁠yá̇bò֜ʼẇ wa⁠yȧẖàn֤ẇ yaẖĕdá̇w֙ ʼel-mé֣y mér֔wòm lĕ⁠hilá̇ẖé֖m ʻim-yişĕ̂ráʼéֽl׃p"],[11,6,"וַ⁠יֹּ֨אמֶר יְהוָ֣ה אֶל־יְהוֹשֻׁעַ֮ אַל־תִּירָ֣א מִ⁠פְּנֵי⁠הֶם֒ כִּֽי־מָחָ֞ר כָּ⁠עֵ֣ת הַ⁠זֹּ֗את אָנֹכִ֞י נֹתֵ֧ן אֶת־כֻּלָּ֛⁠ם חֲלָלִ֖ים לִ⁠פְנֵ֣י יִשְׂרָאֵ֑ל אֶת־סוּסֵי⁠הֶ֣ם תְּעַקֵּ֔ר וְ⁠אֶת־מַרְכְּבֹתֵי⁠הֶ֖ם תִּשְׂרֹ֥ף בָּ⁠אֵֽשׁ׃","wa⁠yò̇֨ʼmer yĕhwá֣h ʼel-yĕhwòşǔʻa֮ ʼal-ţi̇yrá֣ʼ mi⁠pĕ̇néy⁠hem֒ kiֽ̇y-máẖá֞r ká̇⁠ʻé֣ţ ha⁠zò̇֗ʼţ ʼánòki֞y nòţé֧n ʼeţ-ku̇lá֛̇⁠m ẖàláli֖ym li⁠pĕné֣y yişĕ̂ráʼé֑l ʼeţ-sẇséy⁠he֣m ţĕ̇ʻaqé̇֔r wĕ⁠ʼeţ-marĕkĕ̇bòţéy⁠he֖m ţi̇şĕ̂rò֥p bá̇⁠ʼéֽş̌׃"],[11,7,"וַ⁠יָּבֹ֣א יְהוֹשֻׁ֡עַ וְ⁠כָל־עַם֩ הַ⁠מִּלְחָמָ֨ה עִמּ֧⁠וֹ עֲלֵי⁠הֶ֛ם עַל־מֵ֥י מֵר֖וֹם פִּתְאֹ֑ם וַֽ⁠יִּפְּל֖וּ בָּ⁠הֶֽם׃","wa⁠yá̇bò֣ʼ yĕhwòşǔ֡ʻa wĕ⁠kál-ʻam֩ ha⁠mi̇lĕẖámá֨h ʻiṁ֧⁠wò ʻàléy⁠he֛m ʻal-mé֥y mér֖wòm pi̇ţĕʼò֑m waֽ⁠yi̇pĕ̇l֖ẇ bá̇⁠heֽm׃"],[11,8,"וַ⁠יִּתְּנֵ֨⁠ם יְהוָ֥ה בְּ⁠יַֽד־יִשְׂרָאֵל֮ וַ⁠יַּכּוּ⁠ם֒ וַֽ⁠יִּרְדְּפ֞וּ⁠ם עַד־צִיד֣וֹן רַבָּ֗ה וְ⁠עַד֙ מִשְׂרְפ֣וֹת מַ֔יִם וְ⁠עַד־בִּקְעַ֥ת מִצְפֶּ֖ה מִזְרָ֑חָ⁠ה וַ⁠יַּכֻּ֕⁠ם עַד־בִּלְתִּ֥י הִשְׁאִֽיר־לָ⁠הֶ֖ם שָׂרִֽיד׃","wa⁠yi̇ţĕ̇né֨⁠m yĕhwá֥h bĕ̇⁠yaֽd-yişĕ̂ráʼél֮ wa⁠yȧk̇ẇ⁠m֒ waֽ⁠yi̇rĕdĕ̇p֞ẇ⁠m ʻad-ẕiyd֣wòn rabá̇֗h wĕ⁠ʻad֙ mişĕ̂rĕp֣wòţ ma֔yim wĕ⁠ʻad-bi̇qĕʻa֥ţ miẕĕpė֖h mizĕrá֑ẖá⁠h wa⁠yȧku̇֕⁠m ʻad-bi̇lĕţi֥̇y hişĕ̌ʼiֽyr-lá⁠he֖m şá̂riֽyd׃"],[11,9,"וַ⁠יַּ֤עַשׂ לָ⁠הֶם֙ יְהוֹשֻׁ֔עַ כַּ⁠אֲשֶׁ֥ר אָֽמַר־ל֖⁠וֹ יְהוָ֑ה אֶת־סוּסֵי⁠הֶ֣ם עִקֵּ֔ר וְ⁠אֶת־מַרְכְּבֹתֵי⁠הֶ֖ם שָׂרַ֥ף בָּ⁠אֵֽשׁ׃ס","wa⁠yȧ֤ʻaş̂ lá⁠hem֙ yĕhwòşǔ֔ʻa kȧ⁠ʼàşě֥r ʼáֽmar-l֖⁠wò yĕhwá֑h ʼeţ-sẇséy⁠he֣m ʻiqé̇֔r wĕ⁠ʼeţ-marĕkĕ̇bòţéy⁠he֖m şá̂ra֥p bá̇⁠ʼéֽş̌׃s"],[11,10,"וַ⁠יָּ֨שָׁב יְהוֹשֻׁ֜עַ בָּ⁠עֵ֤ת הַ⁠הִיא֙ וַ⁠יִּלְכֹּ֣ד אֶת־חָצ֔וֹר וְ⁠אֶת־מַלְכָּ֖⁠הּ הִכָּ֣ה בֶ⁠חָ֑רֶב כִּֽי־חָצ֣וֹר לְ⁠פָנִ֔ים הִ֕יא רֹ֖אשׁ כָּל־הַ⁠מַּמְלָכ֥וֹת הָ⁠אֵֽלֶּה׃","wa⁠yá̇֨şá̌b yĕhwòşǔ֜ʻa bá̇⁠ʻé֤ţ ha⁠hiyʼ֙ wa⁠yi̇lĕkò֣̇d ʼeţ-ẖáẕ֔wòr wĕ⁠ʼeţ-malĕká֖̇⁠ḣ hiká֣̇h be⁠ẖá֑reb kiֽ̇y-ẖáẕ֣wòr lĕ⁠páni֔ym hi֕yʼ rò֖ʼş̌ ká̇l-ha⁠mȧmĕlák֥wòţ há⁠ʼéֽlėh׃"],[11,11,"וַ֠⁠יַּכּוּ אֶת־כָּל־הַ⁠נֶּ֨פֶשׁ אֲשֶׁר־בָּ֤⁠הּ לְ⁠פִי־חֶ֨רֶב֙ הַֽחֲרֵ֔ם לֹ֥א נוֹתַ֖ר כָּל־נְשָׁמָ֑ה וְ⁠אֶת־חָצ֖וֹר שָׂרַ֥ף בָּ⁠אֵֽשׁ׃","wa֠⁠yȧk̇ẇ ʼeţ-ká̇l-ha⁠nė֨peş̌ ʼàşěr-bá֤̇⁠ḣ lĕ⁠piy-ẖe֨reb֙ haֽẖàré֔m lò֥ʼ nwòţa֖r ká̇l-nĕşá̌má֑h wĕ⁠ʼeţ-ẖáẕ֖wòr şá̂ra֥p bá̇⁠ʼéֽş̌׃"],[11,12,"וְֽ⁠אֶת־כָּל־עָרֵ֣י הַ⁠מְּלָכִֽים־הָ֠⁠אֵלֶּה וְֽ⁠אֶת־כָּל־מַלְכֵי⁠הֶ֞ם לָכַ֧ד יְהוֹשֻׁ֛עַ וַ⁠יַּכֵּ֥⁠ם לְ⁠פִי־חֶ֖רֶב הֶחֱרִ֣ים אוֹתָ֑⁠ם כַּ⁠אֲשֶׁ֣ר צִוָּ֔ה מֹשֶׁ֖ה עֶ֥בֶד יְהוָֽה׃","wĕֽ⁠ʼeţ-ká̇l-ʻáré֣y ha⁠mĕ̇lákֽiym-há֠⁠ʼélėh wĕֽ⁠ʼeţ-ká̇l-malĕkéy⁠he֞m láka֧d yĕhwòşǔ֛ʻa wa⁠yȧké֥̇⁠m lĕ⁠piy-ẖe֖reb heẖèri֣ym ʼwòţá֑⁠m kȧ⁠ʼàşě֣r ẕiwá̇֔h mòşě֖h ʻe֥bed yĕhwáֽh׃"],[11,13,"רַ֣ק כָּל־הֶ⁠עָרִ֗ים הָ⁠עֹֽמְדוֹת֙ עַל־תִּלָּ֔⁠ם לֹ֥א שְׂרָפָ֖⁠ם יִשְׂרָאֵ֑ל זוּלָתִ֛י אֶת־חָצ֥וֹר לְ⁠בַדָּ֖⁠הּ שָׂרַ֥ף יְהוֹשֻֽׁעַ׃","ra֣q ká̇l-he⁠ʻári֗ym há⁠ʻòֽmĕdwòţ֙ ʻal-ţi̇lá̇֔⁠m lò֥ʼ şĕ̂rápá֖⁠m yişĕ̂ráʼé֑l zẇláţi֛y ʼeţ-ẖáẕ֥wòr lĕ⁠badá֖̇⁠ḣ şá̂ra֥p yĕhwòşǔֽʻa׃"],[11,14,"וְ֠⁠כֹל שְׁלַ֞ל הֶ⁠עָרִ֤ים הָ⁠אֵ֨לֶּה֙ וְ⁠הַ⁠בְּהֵמָ֔ה בָּזְז֥וּ לָ⁠הֶ֖ם בְּנֵ֣י יִשְׂרָאֵ֑ל רַ֣ק אֶֽת־כָּל־הָ⁠אָדָ֞ם הִכּ֣וּ לְ⁠פִי־חֶ֗רֶב עַד־הִשְׁמִדָ⁠ם֙ אוֹתָ֔⁠ם לֹ֥א הִשְׁאִ֖ירוּ כָּל־נְשָׁמָֽה׃","wĕ֠⁠kòl şĕ̌la֞l he⁠ʻári֤ym há⁠ʼé֨lėh֙ wĕ⁠ha⁠bĕ̇hémá֔h bá̇zĕz֥ẇ lá⁠he֖m bĕ̇né֣y yişĕ̂ráʼé֑l ra֣q ʼeֽţ-ká̇l-há⁠ʼádá֞m hik֣̇ẇ lĕ⁠piy-ẖe֗reb ʻad-hişĕ̌midá⁠m֙ ʼwòţá֔⁠m lò֥ʼ hişĕ̌ʼi֖yrẇ ká̇l-nĕşá̌máֽh׃"],[11,15,"כַּ⁠אֲשֶׁ֨ר צִוָּ֤ה יְהוָה֙ אֶת־מֹשֶׁ֣ה עַבְדּ֔⁠וֹ כֵּן־צִוָּ֥ה מֹשֶׁ֖ה אֶת־יְהוֹשֻׁ֑עַ וְ⁠כֵן֙ עָשָׂ֣ה יְהוֹשֻׁ֔עַ לֹֽא־הֵסִ֣יר דָּבָ֔ר מִ⁠כֹּ֛ל אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","kȧ⁠ʼàşě֨r ẕiwá֤̇h yĕhwáh֙ ʼeţ-mòşě֣h ʻabĕḋ֔⁠wò ké̇n-ẕiwá֥̇h mòşě֖h ʼeţ-yĕhwòşǔ֑ʻa wĕ⁠kén֙ ʻáşá֣̂h yĕhwòşǔ֔ʻa lòֽʼ-hési֣yr dá̇bá֔r mi⁠kò֛̇l ʼàşěr-ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[11,16,"וַ⁠יִּקַּ֨ח יְהוֹשֻׁ֜עַ אֶת־כָּל־הָ⁠אָ֣רֶץ הַ⁠זֹּ֗את הָ⁠הָ֤ר וְ⁠אֶת־כָּל־הַ⁠נֶּ֨גֶב֙ וְ⁠אֵת֙ כָּל־אֶ֣רֶץ הַ⁠גֹּ֔שֶׁן וְ⁠אֶת־הַ⁠שְּׁפֵלָ֖ה וְ⁠אֶת־הָ⁠עֲרָבָ֑ה וְ⁠אֶת־הַ֥ר יִשְׂרָאֵ֖ל וּ⁠שְׁפֵלָתֹֽ⁠ה׃","wa⁠yi̇qȧ֨ẖ yĕhwòşǔ֜ʻa ʼeţ-ká̇l-há⁠ʼá֣reẕ ha⁠zò̇֗ʼţ há⁠há֤r wĕ⁠ʼeţ-ká̇l-ha⁠nė֨geb֙ wĕ⁠ʼéţ֙ ká̇l-ʼe֣reẕ ha⁠gò̇֔şěn wĕ⁠ʼeţ-ha⁠şĕ̇̌pélá֖h wĕ⁠ʼeţ-há⁠ʻàrábá֑h wĕ⁠ʼeţ-ha֥r yişĕ̂ráʼé֖l ẇ⁠şĕ̌péláţòֽ⁠h׃"],[11,17,"מִן־הָ⁠הָ֤ר הֶֽ⁠חָלָק֙ הָ⁠עוֹלֶ֣ה שֵׂעִ֔יר וְ⁠עַד־בַּ֤עַל גָּד֙ בְּ⁠בִקְעַ֣ת הַ⁠לְּבָנ֔וֹן תַּ֖חַת הַר־חֶרְמ֑וֹן וְ⁠אֵ֤ת כָּל־מַלְכֵי⁠הֶם֙ לָכַ֔ד וַ⁠יַּכֵּ֖⁠ם וַ⁠יְמִיתֵֽ⁠ם׃","min-há⁠há֤r heֽ⁠ẖáláq֙ há⁠ʻwòle֣h şé̂ʻi֔yr wĕ⁠ʻad-bȧ֤ʻal gá̇d֙ bĕ̇⁠biqĕʻa֣ţ ha⁠lĕ̇bán֔wòn ţȧ֖ẖaţ har-ẖerĕm֑wòn wĕ⁠ʼé֤ţ ká̇l-malĕkéy⁠hem֙ láka֔d wa⁠yȧké֖̇⁠m wa⁠yĕmiyţéֽ⁠m׃"],[11,18,"יָמִ֣ים רַבִּ֗ים עָשָׂ֧ה יְהוֹשֻׁ֛עַ אֶת־כָּל־הַ⁠מְּלָכִ֥ים הָ⁠אֵ֖לֶּה מִלְחָמָֽה׃","yámi֣ym rabi̇֗ym ʻáşá֧̂h yĕhwòşǔ֛ʻa ʼeţ-ká̇l-ha⁠mĕ̇láki֥ym há⁠ʼé֖lėh milĕẖámáֽh׃"],[11,19,"לֹֽא־הָיְתָ֣ה עִ֗יר אֲשֶׁ֤ר הִשְׁלִ֨ימָה֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל בִּלְתִּ֥י הַ⁠חִוִּ֖י יֹשְׁבֵ֣י גִבְע֑וֹן אֶת־הַ⁠כֹּ֖ל לָקְח֥וּ בַ⁠מִּלְחָמָֽה׃","lòֽʼ-háyĕţá֣h ʻi֗yr ʼàşě֤r hişĕ̌li֨ymáh֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l bi̇lĕţi֥̇y ha⁠ẖiwi֖̇y yòşĕ̌bé֣y gibĕʻ֑wòn ʼeţ-ha⁠kò֖̇l láqĕẖ֥ẇ ba⁠mi̇lĕẖámáֽh׃"],[11,20,"כִּ֣י מֵ⁠אֵ֣ת יְהוָ֣ה ׀ הָיְתָ֡ה לְ⁠חַזֵּ֣ק אֶת־לִבָּ⁠ם֩ לִ⁠קְרַ֨את הַ⁠מִּלְחָמָ֤ה אֶת־יִשְׂרָאֵל֙ לְמַ֣עַן הַֽחֲרִימָ֔⁠ם לְ⁠בִלְתִּ֥י הֱיוֹת־לָ⁠הֶ֖ם תְּחִנָּ֑ה כִּ֚י לְמַ֣עַן הַשְׁמִידָ֔⁠ם כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","ki֣̇y mé⁠ʼé֣ţ yĕhwá֣h ׀ háyĕţá֡h lĕ⁠ẖazé֣̇q ʼeţ-libá̇⁠m֩ li⁠qĕra֨ʼţ ha⁠mi̇lĕẖámá֤h ʼeţ-yişĕ̂ráʼél֙ lĕma֣ʻan haֽẖàriymá֔⁠m lĕ⁠bilĕţi֥̇y hèywòţ-lá⁠he֖m ţĕ̇ẖiná֑̇h ki֚̇y lĕma֣ʻan haşĕ̌miydá֔⁠m kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[11,21,"וַ⁠יָּבֹ֨א יְהוֹשֻׁ֜עַ בָּ⁠עֵ֣ת הַ⁠הִ֗יא וַ⁠יַּכְרֵ֤ת אֶת־הָֽ⁠עֲנָקִים֙ מִן־הָ⁠הָ֤ר מִן־חֶבְרוֹן֙ מִן־דְּבִ֣ר מִן־עֲנָ֔ב וּ⁠מִ⁠כֹּל֙ הַ֣ר יְהוּדָ֔ה וּ⁠מִ⁠כֹּ֖ל הַ֣ר יִשְׂרָאֵ֑ל עִם־עָרֵי⁠הֶ֖ם הֶחֱרִימָ֥⁠ם יְהוֹשֻֽׁעַ׃","wa⁠yá̇bò֨ʼ yĕhwòşǔ֜ʻa bá̇⁠ʻé֣ţ ha⁠hi֗yʼ wa⁠yȧkĕré֤ţ ʼeţ-háֽ⁠ʻànáqiym֙ min-há⁠há֤r min-ẖebĕrwòn֙ min-dĕ̇bi֣r min-ʻàná֔b ẇ⁠mi⁠kò̇l֙ ha֣r yĕhẇdá֔h ẇ⁠mi⁠kò֖̇l ha֣r yişĕ̂ráʼé֑l ʻim-ʻáréy⁠he֖m heẖèriymá֥⁠m yĕhwòşǔֽʻa׃"],[11,22,"לֹֽא־נוֹתַ֣ר עֲנָקִ֔ים בְּ⁠אֶ֖רֶץ בְּנֵ֣י יִשְׂרָאֵ֑ל רַ֗ק בְּ⁠עַזָּ֛ה בְּ⁠גַ֥ת וּ⁠בְ⁠אַשְׁדּ֖וֹד נִשְׁאָֽרוּ׃","lòֽʼ-nwòţa֣r ʻànáqi֔ym bĕ̇⁠ʼe֖reẕ bĕ̇né֣y yişĕ̂ráʼé֑l ra֗q bĕ̇⁠ʻazá֛̇h bĕ̇⁠ga֥ţ ẇ⁠bĕ⁠ʼaşĕ̌ḋ֖wòd nişĕ̌ʼáֽrẇ׃"],[11,23,"וַ⁠יִּקַּ֨ח יְהוֹשֻׁ֜עַ אֶת־כָּל־הָ⁠אָ֗רֶץ כְּ֠⁠כֹל אֲשֶׁ֨ר דִּבֶּ֣ר יְהוָה֮ אֶל־מֹשֶׁה֒ וַ⁠יִּתְּנָ⁠הּ֩ יְהוֹשֻׁ֨עַ לְ⁠נַחֲלָ֧ה לְ⁠יִשְׂרָאֵ֛ל כְּ⁠מַחְלְקֹתָ֖⁠ם לְ⁠שִׁבְטֵי⁠הֶ֑ם וְ⁠הָ⁠אָ֥רֶץ שָׁקְטָ֖ה מִ⁠מִּלְחָמָֽה׃פ","wa⁠yi̇qȧ֨ẖ yĕhwòşǔ֜ʻa ʼeţ-ká̇l-há⁠ʼá֗reẕ kĕ̇֠⁠kòl ʼàşě֨r di̇bė֣r yĕhwáh֮ ʼel-mòşěh֒ wa⁠yi̇ţĕ̇ná⁠ḣ֩ yĕhwòşǔ֨ʻa lĕ⁠naẖàlá֧h lĕ⁠yişĕ̂ráʼé֛l kĕ̇⁠maẖĕlĕqòţá֖⁠m lĕ⁠şǐbĕtéy⁠he֑m wĕ⁠há⁠ʼá֥reẕ şá̌qĕtá֖h mi⁠mi̇lĕẖámáֽh׃p"],[12,1,"וְ⁠אֵ֣לֶּה ׀ מַלְכֵ֣י הָ⁠אָ֗רֶץ אֲשֶׁ֨ר הִכּ֤וּ בְנֵֽי־יִשְׂרָאֵל֙ וַ⁠יִּֽרְשׁ֣וּ אֶת־אַרְצָ֔⁠ם בְּ⁠עֵ֥בֶר הַ⁠יַּרְדֵּ֖ן מִזְרְחָ֣⁠ה הַ⁠שָּׁ֑מֶשׁ מִ⁠נַּ֤חַל אַרְנוֹן֙ עַד־הַ֣ר חֶרְמ֔וֹן וְ⁠כָל־הָ⁠עֲרָבָ֖ה מִזְרָֽחָ⁠ה׃","wĕ⁠ʼé֣lėh ׀ malĕké֣y há⁠ʼá֗reẕ ʼàşě֨r hik֤̇ẇ bĕnéֽy-yişĕ̂ráʼél֙ wa⁠yiֽ̇rĕş֣̌ẇ ʼeţ-ʼarĕẕá֔⁠m bĕ̇⁠ʻé֥ber ha⁠yȧrĕdé֖̇n mizĕrĕẖá֣⁠h ha⁠şá֑̇̌meş̌ mi⁠nȧ֤ẖal ʼarĕnwòn֙ ʻad-ha֣r ẖerĕm֔wòn wĕ⁠kál-há⁠ʻàrábá֖h mizĕráֽẖá⁠h׃"],[12,2,"סִיחוֹן֙ מֶ֣לֶךְ הָ⁠אֱמֹרִ֔י הַ⁠יּוֹשֵׁ֖ב בְּ⁠חֶשְׁבּ֑וֹן מֹשֵׁ֡ל מֵ⁠עֲרוֹעֵ֡ר אֲשֶׁר֩ עַל־שְׂפַת־נַ֨חַל אַרְנ֜וֹן וְ⁠ת֤וֹךְ הַ⁠נַּ֨חַל֙ וַ⁠חֲצִ֣י הַ⁠גִּלְעָ֔ד וְ⁠עַד֙ יַבֹּ֣ק הַ⁠נַּ֔חַל גְּב֖וּל בְּנֵ֥י עַמּֽוֹן׃","siyẖwòn֙ me֣lekĕ há⁠ʼèmòri֔y ha⁠ẏwòşé֖̌b bĕ̇⁠ẖeşĕ̌ḃ֑wòn mòşé̌֡l mé⁠ʻàrwòʻé֡r ʼàşěr֩ ʻal-şĕ̂paţ-na֨ẖal ʼarĕn֜wòn wĕ⁠ţ֤wòkĕ ha⁠nȧ֨ẖal֙ wa⁠ẖàẕi֣y ha⁠gi̇lĕʻá֔d wĕ⁠ʻad֙ yabò֣̇q ha⁠nȧ֔ẖal gĕ̇b֖ẇl bĕ̇né֥y ʻaṁֽwòn׃"],[12,3,"וְ⁠הָ⁠עֲרָבָה֩ עַד־יָ֨ם כִּנְר֜וֹת מִזְרָ֗חָ⁠ה וְ֠⁠עַד יָ֣ם הָ⁠עֲרָבָ֤ה יָם־הַ⁠מֶּ֨לַח֙ מִזְרָ֔חָ⁠ה דֶּ֖רֶךְ בֵּ֣ית הַיְשִׁמ֑וֹת וּ⁠מִ֨⁠תֵּימָ֔ן תַּ֖חַת אַשְׁדּ֥וֹת הַ⁠פִּסְגָּֽה׃","wĕ⁠há⁠ʻàrábáh֩ ʻad-yá֨m ki̇nĕr֜wòţ mizĕrá֗ẖá⁠h wĕ֠⁠ʻad yá֣m há⁠ʻàrábá֤h yám-ha⁠mė֨laẖ֙ mizĕrá֔ẖá⁠h dė֖rekĕ bé֣̇yţ hayĕşǐm֑wòţ ẇ⁠mi֨⁠ţé̇ymá֔n ţȧ֖ẖaţ ʼaşĕ̌ḋ֥wòţ ha⁠pi̇sĕgáֽ̇h׃"],[12,4,"וּ⁠גְב֗וּל ע֚וֹג מֶ֣לֶךְ הַ⁠בָּשָׁ֔ן מִ⁠יֶּ֖תֶר הָ⁠רְפָאִ֑ים הַ⁠יּוֹשֵׁ֥ב בְּ⁠עַשְׁתָּר֖וֹת וּ⁠בְ⁠אֶדְרֶֽעִי׃","ẇ⁠gĕb֗ẇl ʻ֚wòg me֣lekĕ ha⁠bá̇şá̌֔n mi⁠yė֖ţer há⁠rĕpáʼi֑ym ha⁠ẏwòşé֥̌b bĕ̇⁠ʻaşĕ̌ţá̇r֖wòţ ẇ⁠bĕ⁠ʼedĕreֽʻiy׃"],[12,5,"וּ֠⁠מֹשֵׁל בְּ⁠הַ֨ר חֶרְמ֤וֹן וּ⁠בְ⁠סַלְכָה֙ וּ⁠בְ⁠כָל־הַ⁠בָּשָׁ֔ן עַד־גְּב֥וּל הַ⁠גְּשׁוּרִ֖י וְ⁠הַ⁠מַּעֲכָתִ֑י וַ⁠חֲצִי֙ הַ⁠גִּלְעָ֔ד גְּב֖וּל סִיח֥וֹן מֶֽלֶךְ־חֶשְׁבּֽוֹן׃","ẇ֠⁠mòşé̌l bĕ̇⁠ha֨r ẖerĕm֤wòn ẇ⁠bĕ⁠salĕkáh֙ ẇ⁠bĕ⁠kál-ha⁠bá̇şá̌֔n ʻad-gĕ̇b֥ẇl ha⁠gĕ̇ş̌ẇri֖y wĕ⁠ha⁠mȧʻàkáţi֑y wa⁠ẖàẕiy֙ ha⁠gi̇lĕʻá֔d gĕ̇b֖ẇl siyẖ֥wòn meֽlekĕ-ẖeşĕ̌ḃֽwòn׃"],[12,6,"מֹשֶׁ֧ה עֶֽבֶד־יְהוָ֛ה וּ⁠בְנֵ֥י יִשְׂרָאֵ֖ל הִכּ֑וּ⁠ם וַֽ֠⁠יִּתְּנָ⁠הּ מֹשֶׁ֨ה עֶֽבֶד־יְהוָ֜ה יְרֻשָּׁ֗ה לָ⁠רֻֽאוּבֵנִי֙ וְ⁠לַ⁠גָּדִ֔י וְ⁠לַ⁠חֲצִ֖י שֵׁ֥בֶט הַֽ⁠מְנַשֶּֽׁה׃ס","mòşě֧h ʻeֽbed-yĕhwá֛h ẇ⁠bĕné֥y yişĕ̂ráʼé֖l hik֑̇ẇ⁠m waֽ֠⁠yi̇ţĕ̇ná⁠ḣ mòşě֨h ʻeֽbed-yĕhwá֜h yĕruşá̇̌֗h lá⁠ruֽʼẇbéniy֙ wĕ⁠la⁠gá̇di֔y wĕ⁠la⁠ẖàẕi֖y şé֥̌bet haֽ⁠mĕnaşėֽ̌h׃s"],[12,7,"וְ⁠אֵ֣לֶּה מַלְכֵ֣י הָ⁠אָ֡רֶץ אֲשֶׁר֩ הִכָּ֨ה יְהוֹשֻׁ֜עַ וּ⁠בְנֵ֣י יִשְׂרָאֵ֗ל בְּ⁠עֵ֤בֶר הַ⁠יַּרְדֵּן֙ יָ֔מָּ⁠ה מִ⁠בַּ֤עַל גָּד֙ בְּ⁠בִקְעַ֣ת הַ⁠לְּבָנ֔וֹן וְ⁠עַד־הָ⁠הָ֥ר הֶ⁠חָלָ֖ק הָ⁠עֹלֶ֣ה שֵׂעִ֑ירָ⁠ה וַ⁠יִּתְּנָ֨⁠הּ יְהוֹשֻׁ֜עַ לְ⁠שִׁבְטֵ֧י יִשְׂרָאֵ֛ל יְרֻשָּׁ֖ה כְּ⁠מַחְלְקֹתָֽ⁠ם׃","wĕ⁠ʼé֣lėh malĕké֣y há⁠ʼá֡reẕ ʼàşěr֩ hiká̇֨h yĕhwòşǔ֜ʻa ẇ⁠bĕné֣y yişĕ̂ráʼé֗l bĕ̇⁠ʻé֤ber ha⁠yȧrĕdé̇n֙ yá֔má̇⁠h mi⁠bȧ֤ʻal gá̇d֙ bĕ̇⁠biqĕʻa֣ţ ha⁠lĕ̇bán֔wòn wĕ⁠ʻad-há⁠há֥r he⁠ẖálá֖q há⁠ʻòle֣h şé̂ʻi֑yrá⁠h wa⁠yi̇ţĕ̇ná֨⁠ḣ yĕhwòşǔ֜ʻa lĕ⁠şǐbĕté֧y yişĕ̂ráʼé֛l yĕruşá֖̇̌h kĕ̇⁠maẖĕlĕqòţáֽ⁠m׃"],[12,8,"בָּ⁠הָ֣ר וּ⁠בַ⁠שְּׁפֵלָ֗ה וּ⁠בָֽ⁠עֲרָבָה֙ וּ⁠בָ֣⁠אֲשֵׁד֔וֹת וּ⁠בַ⁠מִּדְבָּ֖ר וּ⁠בַ⁠נֶּ֑גֶב הַֽ⁠חִתִּי֙ הָֽ⁠אֱמֹרִ֔י וְ⁠הַֽ⁠כְּנַעֲנִי֙ הַ⁠פְּרִזִּ֔י הַ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִֽי׃פ","bá̇⁠há֣r ẇ⁠ba⁠şĕ̇̌pélá֗h ẇ⁠báֽ⁠ʻàrábáh֙ ẇ⁠bá֣⁠ʼàşé̌d֔wòţ ẇ⁠ba⁠mi̇dĕbá֖̇r ẇ⁠ba⁠nė֑geb haֽ⁠ẖiţi̇y֙ háֽ⁠ʼèmòri֔y wĕ⁠haֽ⁠kĕ̇naʻàniy֙ ha⁠pĕ̇rizi̇֔y ha⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsiֽy׃p"],[12,9,"מֶ֥לֶךְ יְרִיח֖וֹ אֶחָ֑ד מֶ֧לֶךְ הָ⁠עַ֛י אֲשֶׁר־מִ⁠צַּ֥ד בֵּֽית־אֵ֖ל אֶחָֽד׃","me֥lekĕ yĕriyẖ֖wò ʼeẖá֑d me֧lekĕ há⁠ʻa֛y ʼàşěr-mi⁠ẕȧ֥d béֽ̇yţ-ʼé֖l ʼeẖáֽd׃"],[12,10,"מֶ֤לֶךְ יְרוּשָׁלִַ֨ם֙ אֶחָ֔ד מֶ֥לֶךְ חֶבְר֖וֹן אֶחָֽד׃","me֤lekĕ yĕrẇşá̌lia֨m֙ ʼeẖá֔d me֥lekĕ ẖebĕr֖wòn ʼeẖáֽd׃"],[12,11,"מֶ֤לֶךְ יַרְמוּת֙ אֶחָ֔ד מֶ֥לֶךְ לָכִ֖ישׁ אֶחָֽד׃","me֤lekĕ yarĕmẇţ֙ ʼeẖá֔d me֥lekĕ láki֖yş̌ ʼeẖáֽd׃"],[12,12,"מֶ֤לֶךְ עֶגְלוֹן֙ אֶחָ֔ד מֶ֥לֶךְ גֶּ֖זֶר אֶחָֽד׃","me֤lekĕ ʻegĕlwòn֙ ʼeẖá֔d me֥lekĕ gė֖zer ʼeẖáֽd׃"],[12,13,"מֶ֤לֶךְ דְּבִר֙ אֶחָ֔ד מֶ֥לֶךְ גֶּ֖דֶר אֶחָֽד׃","me֤lekĕ dĕ̇bir֙ ʼeẖá֔d me֥lekĕ gė֖der ʼeẖáֽd׃"],[12,14,"מֶ֤לֶךְ חָרְמָה֙ אֶחָ֔ד מֶ֥לֶךְ עֲרָ֖ד אֶחָֽד׃","me֤lekĕ ẖárĕmáh֙ ʼeẖá֔d me֥lekĕ ʻàrá֖d ʼeẖáֽd׃"],[12,15,"מֶ֤לֶךְ לִבְנָה֙ אֶחָ֔ד מֶ֥לֶךְ עֲדֻלָּ֖ם אֶחָֽד׃","me֤lekĕ libĕnáh֙ ʼeẖá֔d me֥lekĕ ʻàdulá֖̇m ʼeẖáֽd׃"],[12,16,"מֶ֤לֶךְ מַקֵּדָה֙ אֶחָ֔ד מֶ֥לֶךְ בֵּֽית־אֵ֖ל אֶחָֽד׃","me֤lekĕ maqé̇dáh֙ ʼeẖá֔d me֥lekĕ béֽ̇yţ-ʼé֖l ʼeẖáֽd׃"],[12,17,"מֶ֤לֶךְ תַּפּ֨וּחַ֙ אֶחָ֔ד מֶ֥לֶךְ חֵ֖פֶר אֶחָֽד׃","me֤lekĕ ţȧṗ֨ẇẖa֙ ʼeẖá֔d me֥lekĕ ẖé֖per ʼeẖáֽd׃"],[12,18,"מֶ֤לֶךְ אֲפֵק֙ אֶחָ֔ד מֶ֥לֶךְ לַ⁠שָּׁר֖וֹן אֶחָֽד׃","me֤lekĕ ʼàpéq֙ ʼeẖá֔d me֥lekĕ la⁠şá̇̌r֖wòn ʼeẖáֽd׃"],[12,19,"מֶ֤לֶךְ מָדוֹן֙ אֶחָ֔ד מֶ֥לֶךְ חָצ֖וֹר אֶחָֽד׃","me֤lekĕ mádwòn֙ ʼeẖá֔d me֥lekĕ ẖáẕ֖wòr ʼeẖáֽd׃"],[12,20,"מֶ֣לֶךְ שִׁמְר֤וֹן מְראוֹן֙ אֶחָ֔ד מֶ֥לֶךְ אַכְשָׁ֖ף אֶחָֽד׃","me֣lekĕ şǐmĕr֤wòn mĕrʼwòn֙ ʼeẖá֔d me֥lekĕ ʼakĕşá֖̌p ʼeẖáֽd׃"],[12,21,"מֶ֤לֶךְ תַּעְנַךְ֙ אֶחָ֔ד מֶ֥לֶךְ מְגִדּ֖וֹ אֶחָֽד׃","me֤lekĕ ţȧʻĕnakĕ֙ ʼeẖá֔d me֥lekĕ mĕgiḋ֖wò ʼeẖáֽd׃"],[12,22,"מֶ֤לֶךְ קֶ֨דֶשׁ֙ אֶחָ֔ד מֶֽלֶךְ־יָקְנֳעָ֥ם לַ⁠כַּרְמֶ֖ל אֶחָֽד׃","me֤lekĕ qe֨deş̌֙ ʼeẖá֔d meֽlekĕ-yáqĕnoʻá֥m la⁠kȧrĕme֖l ʼeẖáֽd׃"],[12,23,"מֶ֥לֶךְ דּ֛וֹר לְ⁠נָפַ֥ת דּ֖וֹר אֶחָ֑ד מֶֽלֶךְ־גּוֹיִ֥ם לְ⁠גִלְגָּ֖ל אֶחָֽד׃","me֥lekĕ ḋ֛wòr lĕ⁠nápa֥ţ ḋ֖wòr ʼeẖá֑d meֽlekĕ-ġwòyi֥m lĕ⁠gilĕgá֖̇l ʼeẖáֽd׃"],[12,24,"מֶ֥לֶךְ תִּרְצָ֖ה אֶחָ֑ד כָּל־מְלָכִ֖ים שְׁלֹשִׁ֥ים וְ⁠אֶחָֽד׃פ","me֥lekĕ ţi̇rĕẕá֖h ʼeẖá֑d ká̇l-mĕláki֖ym şĕ̌lòşǐ֥ym wĕ⁠ʼeẖáֽd׃p"],[13,1,"וִ⁠יהוֹשֻׁ֣עַ זָקֵ֔ן בָּ֖א בַּ⁠יָּמִ֑ים וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלָ֗י⁠ו אַתָּ֤ה זָקַ֨נְתָּה֙ בָּ֣אתָ בַ⁠יָּמִ֔ים וְ⁠הָ⁠אָ֛רֶץ נִשְׁאֲרָ֥ה הַרְבֵּֽה־מְאֹ֖ד לְ⁠רִשְׁתָּֽ⁠הּ׃","wi⁠yhwòşǔ֣ʻa záqé֔n bá֖̇ʼ bȧ⁠yá̇mi֑ym wa⁠yò̇֨ʼmer yĕhwá֜h ʼélá֗y⁠w ʼaţá֤̇h záqa֨nĕţá̇h֙ bá֣̇ʼţá ba⁠yá̇mi֔ym wĕ⁠há⁠ʼá֛reẕ nişĕ̌ʼàrá֥h harĕbéֽ̇h-mĕʼò֖d lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[13,2,"זֹ֥את הָ⁠אָ֖רֶץ הַ⁠נִּשְׁאָ֑רֶת כָּל־גְּלִיל֥וֹת הַ⁠פְּלִשְׁתִּ֖ים וְ⁠כָל־הַ⁠גְּשׁוּרִֽי׃","zò֥ʼţ há⁠ʼá֖reẕ ha⁠ni̇şĕ̌ʼá֑reţ ká̇l-gĕ̇liyl֥wòţ ha⁠pĕ̇lişĕ̌ţi֖̇ym wĕ⁠kál-ha⁠gĕ̇ş̌ẇriֽy׃"],[13,3,"מִֽן־הַ⁠שִּׁיח֞וֹר אֲשֶׁ֣ר ׀ עַל־פְּנֵ֣י מִצְרַ֗יִם וְ⁠עַ֨ד גְּב֤וּל עֶקְרוֹן֙ צָפ֔וֹנָ⁠ה לַֽ⁠כְּנַעֲנִ֖י תֵּחָשֵׁ֑ב חֲמֵ֣שֶׁת ׀ סַרְנֵ֣י פְלִשְׁתִּ֗ים הָ⁠עַזָּתִ֤י וְ⁠הָ⁠אַשְׁדּוֹדִי֙ הָ⁠אֶשְׁקְלוֹנִ֣י הַ⁠גִּתִּ֔י וְ⁠הָ⁠עֶקְרוֹנִ֖י וְ⁠הָ⁠עַוִּֽים׃","miֽn-ha⁠şi̇̌yẖ֞wòr ʼàşě֣r ׀ ʻal-pĕ̇né֣y miẕĕra֗yim wĕ⁠ʻa֨d gĕ̇b֤ẇl ʻeqĕrwòn֙ ẕáp֔wòná⁠h laֽ⁠kĕ̇naʻàni֖y ţé̇ẖáşé֑̌b ẖàmé֣şěţ ׀ sarĕné֣y pĕlişĕ̌ţi̇֗ym há⁠ʻazá̇ţi֤y wĕ⁠há⁠ʼaşĕ̌ḋwòdiy֙ há⁠ʼeşĕ̌qĕlwòni֣y ha⁠gi̇ţi̇֔y wĕ⁠há⁠ʻeqĕrwòni֖y wĕ⁠há⁠ʻawiֽ̇ym׃"],[13,4,"מִ⁠תֵּימָ֞ן כָּל־אֶ֣רֶץ הַֽ⁠כְּנַעֲנִ֗י וּ⁠מְעָרָ֛ה אֲשֶׁ֥ר לַ⁠צִּידֹנִ֖ים עַד־אֲפֵ֑קָ⁠ה עַ֖ד גְּב֥וּל הָ⁠אֱמֹרִֽי׃","mi⁠ţé̇ymá֞n ká̇l-ʼe֣reẕ haֽ⁠kĕ̇naʻàni֗y ẇ⁠mĕʻárá֛h ʼàşě֥r la⁠ẕi̇ydòni֖ym ʻad-ʼàpé֑qá⁠h ʻa֖d gĕ̇b֥ẇl há⁠ʼèmòriֽy׃"],[13,5,"וְ⁠הָ⁠אָ֣רֶץ הַ⁠גִּבְלִ֗י וְ⁠כָל־הַ⁠לְּבָנוֹן֙ מִזְרַ֣ח הַ⁠שֶּׁ֔מֶשׁ מִ⁠בַּ֣עַל גָּ֔ד תַּ֖חַת הַר־חֶרְמ֑וֹן עַ֖ד לְב֥וֹא חֲמָֽת׃","wĕ⁠há⁠ʼá֣reẕ ha⁠gi̇bĕli֗y wĕ⁠kál-ha⁠lĕ̇bánwòn֙ mizĕra֣ẖ ha⁠şė̌֔meş̌ mi⁠bȧ֣ʻal gá̇֔d ţȧ֖ẖaţ har-ẖerĕm֑wòn ʻa֖d lĕb֥wòʼ ẖàmáֽţ׃"],[13,6,"כָּל־יֹשְׁבֵ֣י הָ֠⁠הָר מִֽן־הַ⁠לְּבָנ֞וֹן עַד־מִשְׂרְפֹ֥ת מַ֨יִם֙ כָּל־צִ֣ידֹנִ֔ים אָֽנֹכִי֙ אוֹרִישֵׁ֔⁠ם מִ⁠פְּנֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל רַ֠ק הַפִּלֶ֤⁠הָ לְ⁠יִשְׂרָאֵל֙ בְּֽ⁠נַחֲלָ֔ה כַּ⁠אֲשֶׁ֖ר צִוִּיתִֽי⁠ךָ׃","ká̇l-yòşĕ̌bé֣y há֠⁠hár miֽn-ha⁠lĕ̇bán֞wòn ʻad-mişĕ̂rĕpò֥ţ ma֨yim֙ ká̇l-ẕi֣ydòni֔ym ʼáֽnòkiy֙ ʼwòriyşé̌֔⁠m mi⁠pĕ̇né֖y bĕ̇né֣y yişĕ̂ráʼé֑l ra֠q hapi̇le֤⁠há lĕ⁠yişĕ̂ráʼél֙ bĕֽ̇⁠naẖàlá֔h kȧ⁠ʼàşě֖r ẕiwi̇yţiֽy⁠ká׃"],[13,7,"וְ⁠עַתָּ֗ה חַלֵּ֞ק אֶת־הָ⁠אָ֧רֶץ הַ⁠זֹּ֛את בְּ⁠נַחֲלָ֖ה לְ⁠תִשְׁעַ֣ת הַ⁠שְּׁבָטִ֑ים וַ⁠חֲצִ֖י הַ⁠שֵּׁ֥בֶט הַֽ⁠מְנַשֶּֽׁה׃","wĕ⁠ʻaţá̇֗h ẖalé̇֞q ʼeţ-há⁠ʼá֧reẕ ha⁠zò֛̇ʼţ bĕ̇⁠naẖàlá֖h lĕ⁠ţişĕ̌ʻa֣ţ ha⁠şĕ̇̌báti֑ym wa⁠ẖàẕi֖y ha⁠şé֥̇̌bet haֽ⁠mĕnaşėֽ̌h׃"],[13,8,"עִמּ֗⁠וֹ הָ⁠רֽאוּבֵנִי֙ וְ⁠הַ⁠גָּדִ֔י לָקְח֖וּ נַחֲלָתָ֑⁠ם אֲשֶׁר֩ נָתַ֨ן לָ⁠הֶ֜ם מֹשֶׁ֗ה בְּ⁠עֵ֤בֶר הַ⁠יַּרְדֵּן֙ מִזְרָ֔חָ⁠ה כַּ⁠אֲשֶׁר֙ נָתַ֣ן לָ⁠הֶ֔ם מֹשֶׁ֖ה עֶ֥בֶד יְהוָֽה׃","ʻiṁ֗⁠wò há⁠rֽʼẇbéniy֙ wĕ⁠ha⁠gá̇di֔y láqĕẖ֖ẇ naẖàláţá֑⁠m ʼàşěr֩ náţa֨n lá⁠he֜m mòşě֗h bĕ̇⁠ʻé֤ber ha⁠yȧrĕdé̇n֙ mizĕrá֔ẖá⁠h kȧ⁠ʼàşěr֙ náţa֣n lá⁠he֔m mòşě֖h ʻe֥bed yĕhwáֽh׃"],[13,9,"מֵ⁠עֲרוֹעֵ֡ר אֲשֶׁר֩ עַל־שְׂפַת־נַ֨חַל אַרְנ֜וֹן וְ⁠הָ⁠עִ֨יר אֲשֶׁ֧ר בְּ⁠תוֹךְ־הַ⁠נַּ֛חַל וְ⁠כָל־הַ⁠מִּישֹׁ֥ר מֵידְבָ֖א עַד־דִּיבֽוֹן׃","mé⁠ʻàrwòʻé֡r ʼàşěr֩ ʻal-şĕ̂paţ-na֨ẖal ʼarĕn֜wòn wĕ⁠há⁠ʻi֨yr ʼàşě֧r bĕ̇⁠ţwòkĕ-ha⁠nȧ֛ẖal wĕ⁠kál-ha⁠mi̇yşò֥̌r méydĕbá֖ʼ ʻad-di̇ybֽwòn׃"],[13,10,"וְ⁠כֹ֗ל עָרֵי֙ סִיחוֹן֙ מֶ֣לֶךְ הָ⁠אֱמֹרִ֔י אֲשֶׁ֥ר מָלַ֖ךְ בְּ⁠חֶשְׁבּ֑וֹן עַד־גְּב֖וּל בְּנֵ֥י עַמּֽוֹן׃","wĕ⁠kò֗l ʻáréy֙ siyẖwòn֙ me֣lekĕ há⁠ʼèmòri֔y ʼàşě֥r mála֖kĕ bĕ̇⁠ẖeşĕ̌ḃ֑wòn ʻad-gĕ̇b֖ẇl bĕ̇né֥y ʻaṁֽwòn׃"],[13,11,"וְ⁠הַ⁠גִּלְעָ֞ד וּ⁠גְב֧וּל הַ⁠גְּשׁוּרִ֣י וְ⁠הַ⁠מַּעֲכָתִ֗י וְ⁠כֹ֨ל הַ֥ר חֶרְמ֛וֹן וְ⁠כָל־הַ⁠בָּשָׁ֖ן עַד־סַלְכָֽה׃","wĕ⁠ha⁠gi̇lĕʻá֞d ẇ⁠gĕb֧ẇl ha⁠gĕ̇ş̌ẇri֣y wĕ⁠ha⁠mȧʻàkáţi֗y wĕ⁠kò֨l ha֥r ẖerĕm֛wòn wĕ⁠kál-ha⁠bá̇şá֖̌n ʻad-salĕkáֽh׃"],[13,12,"כָּל־מַמְלְכ֥וּת עוֹג֙ בַּ⁠בָּשָׁ֔ן אֲשֶׁר־מָלַ֥ךְ בְּ⁠עַשְׁתָּר֖וֹת וּ⁠בְ⁠אֶדְרֶ֑עִי ה֤וּא נִשְׁאַר֙ מִ⁠יֶּ֣תֶר הָ⁠רְפָאִ֔ים וַ⁠יַּכֵּ֥⁠ם מֹשֶׁ֖ה וַ⁠יֹּרִשֵֽׁ⁠ם׃","ká̇l-mamĕlĕk֥ẇţ ʻwòg֙ bȧ⁠bá̇şá̌֔n ʼàşěr-mála֥kĕ bĕ̇⁠ʻaşĕ̌ţá̇r֖wòţ ẇ⁠bĕ⁠ʼedĕre֑ʻiy h֤ẇʼ nişĕ̌ʼar֙ mi⁠yė֣ţer há⁠rĕpáʼi֔ym wa⁠yȧké֥̇⁠m mòşě֖h wa⁠yò̇rişéֽ̌⁠m׃"],[13,13,"וְ⁠לֹ֤א הוֹרִ֨ישׁוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֶת־הַ⁠גְּשׁוּרִ֖י וְ⁠אֶת־הַ⁠מַּעֲכָתִ֑י וַ⁠יֵּ֨שֶׁב גְּשׁ֤וּר וּ⁠מַֽעֲכָת֙ בְּ⁠קֶ֣רֶב יִשְׂרָאֵ֔ל עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wĕ⁠lò֤ʼ hwòri֨yş̌ẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼeţ-ha⁠gĕ̇ş̌ẇri֖y wĕ⁠ʼeţ-ha⁠mȧʻàkáţi֑y wa⁠yé̇֨şěb gĕ̇ş֤̌ẇr ẇ⁠maֽʻàkáţ֙ bĕ̇⁠qe֣reb yişĕ̂ráʼé֔l ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[13,14,"רַ֚ק לְ⁠שֵׁ֣בֶט הַ⁠לֵּוִ֔י לֹ֥א נָתַ֖ן נַחֲלָ֑ה אִשֵּׁ֨י יְהוָ֜ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ ה֣וּא נַחֲלָת֔⁠וֹ כַּ⁠אֲשֶׁ֖ר דִּבֶּר־לֽ⁠וֹ׃ס","ra֚q lĕ⁠şé֣̌bet ha⁠lé̇wi֔y lò֥ʼ náţa֖n naẖàlá֑h ʼişé̇̌֨y yĕhwá֜h ʼèlòhé֤y yişĕ̂ráʼél֙ h֣ẇʼ naẖàláţ֔⁠wò kȧ⁠ʼàşě֖r di̇bėr-lֽ⁠wò׃s"],[13,15,"וַ⁠יִּתֵּ֣ן מֹשֶׁ֔ה לְ⁠מַטֵּ֥ה בְנֵֽי־רְאוּבֵ֖ן לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","wa⁠yi̇ţé֣̇n mòşě֔h lĕ⁠maté֥̇h bĕnéֽy-rĕʼẇbé֖n lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[13,16,"וַ⁠יְהִ֨י לָ⁠הֶ֜ם הַ⁠גְּב֗וּל מֵ⁠עֲרוֹעֵ֡ר אֲשֶׁר֩ עַל־שְׂפַת־נַ֨חַל אַרְנ֜וֹן וְ⁠הָ⁠עִ֨יר אֲשֶׁ֧ר בְּ⁠תוֹךְ־הַ⁠נַּ֛חַל וְ⁠כָל־הַ⁠מִּישֹׁ֖ר עַל־מֵידְבָֽא׃","wa⁠yĕhi֨y lá⁠he֜m ha⁠gĕ̇b֗ẇl mé⁠ʻàrwòʻé֡r ʼàşěr֩ ʻal-şĕ̂paţ-na֨ẖal ʼarĕn֜wòn wĕ⁠há⁠ʻi֨yr ʼàşě֧r bĕ̇⁠ţwòkĕ-ha⁠nȧ֛ẖal wĕ⁠kál-ha⁠mi̇yşò֖̌r ʻal-méydĕbáֽʼ׃"],[13,17,"חֶשְׁבּ֥וֹן וְ⁠כָל־עָרֶ֖י⁠הָ אֲשֶׁ֣ר בַּ⁠מִּישֹׁ֑ר דִּיבוֹן֙ וּ⁠בָמ֣וֹת בַּ֔עַל וּ⁠בֵ֖ית בַּ֥עַל מְעֽוֹן׃","ẖeşĕ̌ḃ֥wòn wĕ⁠kál-ʻáre֖y⁠há ʼàşě֣r bȧ⁠mi̇yşò֑̌r di̇ybwòn֙ ẇ⁠bám֣wòţ bȧ֔ʻal ẇ⁠bé֖yţ bȧ֥ʻal mĕʻֽwòn׃"],[13,18,"וְ⁠יַ֥הְצָ⁠ה וּ⁠קְדֵמֹ֖ת וּ⁠מֵפָֽעַת׃","wĕ⁠ya֥hĕẕá⁠h ẇ⁠qĕdémò֖ţ ẇ⁠mépáֽʻaţ׃"],[13,19,"וְ⁠קִרְיָתַ֣יִם וְ⁠שִׂבְמָ֔ה וְ⁠צֶ֥רֶת הַשַּׁ֖חַר בְּ⁠הַ֥ר הָ⁠עֵֽמֶק׃","wĕ⁠qirĕyáţa֣yim wĕ⁠şîbĕmá֔h wĕ⁠ẕe֥reţ haşȧ֖̌ẖar bĕ̇⁠ha֥r há⁠ʻéֽmeq׃"],[13,20,"וּ⁠בֵ֥ית פְּע֛וֹר וְ⁠אַשְׁדּ֥וֹת הַ⁠פִּסְגָּ֖ה וּ⁠בֵ֥ית הַיְשִׁמֽוֹת׃","ẇ⁠bé֥yţ pĕ̇ʻ֛wòr wĕ⁠ʼaşĕ̌ḋ֥wòţ ha⁠pi̇sĕgá֖̇h ẇ⁠bé֥yţ hayĕşǐmֽwòţ׃"],[13,21,"וְ⁠כֹל֙ עָרֵ֣י הַ⁠מִּישֹׁ֔ר וְ⁠כָֽל־מַמְלְכ֗וּת סִיחוֹן֙ מֶ֣לֶךְ הָ⁠אֱמֹרִ֔י אֲשֶׁ֥ר מָלַ֖ךְ בְּ⁠חֶשְׁבּ֑וֹן אֲשֶׁר֩ הִכָּ֨ה מֹשֶׁ֜ה אֹת֣⁠וֹ ׀ וְ⁠אֶת־נְשִׂיאֵ֣י מִדְיָ֗ן אֶת־אֱוִ֤י וְ⁠אֶת־רֶ֨קֶם֙ וְ⁠אֶת־צ֤וּר וְ⁠אֶת־חוּר֙ וְ⁠אֶת־רֶ֔בַע נְסִיכֵ֣י סִיח֔וֹן יֹשְׁבֵ֖י הָ⁠אָֽרֶץ׃","wĕ⁠kòl֙ ʻáré֣y ha⁠mi̇yşò̌֔r wĕ⁠káֽl-mamĕlĕk֗ẇţ siyẖwòn֙ me֣lekĕ há⁠ʼèmòri֔y ʼàşě֥r mála֖kĕ bĕ̇⁠ẖeşĕ̌ḃ֑wòn ʼàşěr֩ hiká̇֨h mòşě֜h ʼòţ֣⁠wò ׀ wĕ⁠ʼeţ-nĕşîyʼé֣y midĕyá֗n ʼeţ-ʼèwi֤y wĕ⁠ʼeţ-re֨qem֙ wĕ⁠ʼeţ-ẕ֤ẇr wĕ⁠ʼeţ-ẖẇr֙ wĕ⁠ʼeţ-re֔baʻ nĕsiyké֣y siyẖ֔wòn yòşĕ̌bé֖y há⁠ʼáֽreẕ׃"],[13,22,"וְ⁠אֶת־בִּלְעָ֥ם בֶּן־בְּע֖וֹר הַ⁠קּוֹסֵ֑ם הָרְג֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל בַּ⁠חֶ֖רֶב אֶל־חַלְלֵי⁠הֶֽם׃","wĕ⁠ʼeţ-bi̇lĕʻá֥m bėn-bĕ̇ʻ֖wòr ha⁠q̇wòsé֑m hárĕg֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l bȧ⁠ẖe֖reb ʼel-ẖalĕléy⁠heֽm׃"],[13,23,"וַ⁠יְהִ֗י גְּבוּל֙ בְּנֵ֣י רְאוּבֵ֔ן הַ⁠יַּרְדֵּ֖ן וּ⁠גְב֑וּל זֹ֣את נַחֲלַ֤ת בְּנֵֽי־רְאוּבֵן֙ לְ⁠מִשְׁפְּחֹתָ֔⁠ם הֶ⁠עָרִ֖ים וְ⁠חַצְרֵי⁠הֶֽן׃פ","wa⁠yĕhi֗y gĕ̇bẇl֙ bĕ̇né֣y rĕʼẇbé֔n ha⁠yȧrĕdé֖̇n ẇ⁠gĕb֑ẇl zò֣ʼţ naẖàla֤ţ bĕ̇néֽy-rĕʼẇbén֙ lĕ⁠mişĕ̌pĕ̇ẖòţá֔⁠m he⁠ʻári֖ym wĕ⁠ẖaẕĕréy⁠heֽn׃p"],[13,24,"וַ⁠יִּתֵּ֤ן מֹשֶׁה֙ לְ⁠מַטֵּה־גָ֔ד לִ⁠בְנֵי־גָ֖ד לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","wa⁠yi̇ţé֤̇n mòşěh֙ lĕ⁠maté̇h-gá֔d li⁠bĕnéy-gá֖d lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[13,25,"וַ⁠יְהִ֤י לָ⁠הֶם֙ הַ⁠גְּב֔וּל יַעְזֵר֙ וְ⁠כָל־עָרֵ֣י הַ⁠גִּלְעָ֔ד וַ⁠חֲצִ֕י אֶ֖רֶץ בְּנֵ֣י עַמּ֑וֹן עַד־עֲרוֹעֵ֕ר אֲשֶׁ֖ר עַל־פְּנֵ֥י רַבָּֽה׃","wa⁠yĕhi֤y lá⁠hem֙ ha⁠gĕ̇b֔ẇl yaʻĕzér֙ wĕ⁠kál-ʻáré֣y ha⁠gi̇lĕʻá֔d wa⁠ẖàẕi֕y ʼe֖reẕ bĕ̇né֣y ʻaṁ֑wòn ʻad-ʻàrwòʻé֕r ʼàşě֖r ʻal-pĕ̇né֥y rabáֽ̇h׃"],[13,26,"וּ⁠מֵ⁠חֶשְׁבּ֛וֹן עַד־רָמַ֥ת הַ⁠מִּצְפֶּ֖ה וּ⁠בְטֹנִ֑ים וּ⁠מִֽ⁠מַּחֲנַ֖יִם עַד־גְּב֥וּל לִדְבִֽר׃","ẇ⁠mé⁠ẖeşĕ̌ḃ֛wòn ʻad-ráma֥ţ ha⁠mi̇ẕĕpė֖h ẇ⁠bĕtòni֑ym ẇ⁠miֽ⁠mȧẖàna֖yim ʻad-gĕ̇b֥ẇl lidĕbiֽr׃"],[13,27,"וּ⁠בָ⁠עֵ֡מֶק בֵּ֣ית הָרָם֩ וּ⁠בֵ֨ית נִמְרָ֜ה וְ⁠סֻכּ֣וֹת וְ⁠צָפ֗וֹן יֶ֚תֶר מַמְלְכ֗וּת סִיחוֹן֙ מֶ֣לֶךְ חֶשְׁבּ֔וֹן הַ⁠יַּרְדֵּ֖ן וּ⁠גְבֻ֑ל עַד־קְצֵה֙ יָם־כִּנֶּ֔רֶת עֵ֥בֶר הַ⁠יַּרְדֵּ֖ן מִזְרָֽחָ⁠ה׃","ẇ⁠bá⁠ʻé֡meq bé֣̇yţ hárám֩ ẇ⁠bé֨yţ nimĕrá֜h wĕ⁠suk֣̇wòţ wĕ⁠ẕáp֗wòn ye֚ţer mamĕlĕk֗ẇţ siyẖwòn֙ me֣lekĕ ẖeşĕ̌ḃ֔wòn ha⁠yȧrĕdé֖̇n ẇ⁠gĕbu֑l ʻad-qĕẕéh֙ yám-ki̇nė֔reţ ʻé֥ber ha⁠yȧrĕdé֖̇n mizĕráֽẖá⁠h׃"],[13,28,"זֹ֛את נַחֲלַ֥ת בְּנֵי־גָ֖ד לְ⁠מִשְׁפְּחֹתָ֑⁠ם הֶ⁠עָרִ֖ים וְ⁠חַצְרֵי⁠הֶֽם׃","zò֛ʼţ naẖàla֥ţ bĕ̇néy-gá֖d lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m he⁠ʻári֖ym wĕ⁠ẖaẕĕréy⁠heֽm׃"],[13,29,"וַ⁠יִּתֵּ֣ן מֹשֶׁ֔ה לַ⁠חֲצִ֖י שֵׁ֣בֶט מְנַשֶּׁ֑ה וַ⁠יְהִ֗י לַ⁠חֲצִ֛י מַטֵּ֥ה בְנֵֽי־מְנַשֶּׁ֖ה לְ⁠מִשְׁפְּחוֹתָֽ⁠ם׃","wa⁠yi̇ţé֣̇n mòşě֔h la⁠ẖàẕi֖y şé֣̌bet mĕnaşė֑̌h wa⁠yĕhi֗y la⁠ẖàẕi֛y maté֥̇h bĕnéֽy-mĕnaşė֖̌h lĕ⁠mişĕ̌pĕ̇ẖwòţáֽ⁠m׃"],[13,30,"וַ⁠יְהִ֣י גְבוּלָ֗⁠ם מִ⁠מַּחֲנַ֨יִם כָּֽל־הַ⁠בָּשָׁ֜ן כָּֽל־מַמְלְכ֣וּת ׀ ע֣וֹג מֶֽלֶךְ־הַ⁠בָּשָׁ֗ן וְ⁠כָל־חַוֺּ֥ת יָאִ֛יר אֲשֶׁ֥ר בַּ⁠בָּשָׁ֖ן שִׁשִּׁ֥ים עִֽיר׃","wa⁠yĕhi֣y gĕbẇlá֗⁠m mi⁠mȧẖàna֨yim káֽ̇l-ha⁠bá̇şá̌֜n káֽ̇l-mamĕlĕk֣ẇţ ׀ ʻ֣wòg meֽlekĕ-ha⁠bá̇şá̌֗n wĕ⁠kál-ẖaẇֺ֥ţ yáʼi֛yr ʼàşě֥r bȧ⁠bá̇şá֖̌n şǐşi֥̇̌ym ʻiֽyr׃"],[13,31,"וַ⁠חֲצִ֤י הַ⁠גִּלְעָד֙ וְ⁠עַשְׁתָּר֣וֹת וְ⁠אֶדְרֶ֔עִי עָרֵ֛י מַמְלְכ֥וּת ע֖וֹג בַּ⁠בָּשָׁ֑ן לִ⁠בְנֵ֤י מָכִיר֙ בֶּן־מְנַשֶּׁ֔ה לַ⁠חֲצִ֥י בְנֵֽי־מָכִ֖יר לְ⁠מִשְׁפְּחוֹתָֽ⁠ם׃","wa⁠ẖàẕi֤y ha⁠gi̇lĕʻád֙ wĕ⁠ʻaşĕ̌ţá̇r֣wòţ wĕ⁠ʼedĕre֔ʻiy ʻáré֛y mamĕlĕk֥ẇţ ʻ֖wòg bȧ⁠bá̇şá֑̌n li⁠bĕné֤y mákiyr֙ bėn-mĕnaşė̌֔h la⁠ẖàẕi֥y bĕnéֽy-máki֖yr lĕ⁠mişĕ̌pĕ̇ẖwòţáֽ⁠m׃"],[13,32,"אֵ֕לֶּה אֲשֶׁר־נִחַ֥ל מֹשֶׁ֖ה בְּ⁠עַֽרְב֣וֹת מוֹאָ֑ב מֵ⁠עֵ֛בֶר לְ⁠יַרְדֵּ֥ן יְרִיח֖וֹ מִזְרָֽחָ⁠ה׃ס","ʼé֕lėh ʼàşěr-niẖa֥l mòşě֖h bĕ̇⁠ʻaֽrĕb֣wòţ mwòʼá֑b mé⁠ʻé֛ber lĕ⁠yarĕdé֥̇n yĕriyẖ֖wò mizĕráֽẖá⁠h׃s"],[13,33,"וּ⁠לְ⁠שֵׁ֨בֶט֙ הַ⁠לֵּוִ֔י לֹֽא־נָתַ֥ן מֹשֶׁ֖ה נַחֲלָ֑ה יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ ה֣וּא נַחֲלָתָ֔⁠ם כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר לָ⁠הֶֽם׃","ẇ⁠lĕ⁠şé̌֨bet֙ ha⁠lé̇wi֔y lòֽʼ-náţa֥n mòşě֖h naẖàlá֑h yĕhwá֞h ʼèlòhé֤y yişĕ̂ráʼél֙ h֣ẇʼ naẖàláţá֔⁠m kȧ⁠ʼàşě֖r di̇bė֥r lá⁠heֽm׃"],[14,1,"וְ⁠אֵ֛לֶּה אֲשֶׁר־נָחֲל֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל בְּ⁠אֶ֣רֶץ כְּנָ֑עַן אֲשֶׁ֨ר נִֽחֲל֜וּ אוֹתָ֗⁠ם אֶלְעָזָ֤ר הַ⁠כֹּהֵן֙ וִ⁠יהוֹשֻׁ֣עַ בִּן־נ֔וּן וְ⁠רָאשֵׁ֛י אֲב֥וֹת הַ⁠מַּטּ֖וֹת לִ⁠בְנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ʼé֛lėh ʼàşěr-náẖàl֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l bĕ̇⁠ʼe֣reẕ kĕ̇ná֑ʻan ʼàşě֨r niֽẖàl֜ẇ ʼwòţá֗⁠m ʼelĕʻázá֤r ha⁠kò̇hén֙ wi⁠yhwòşǔ֣ʻa bi̇n-n֔ẇn wĕ⁠ráʼşé֛̌y ʼàb֥wòţ ha⁠mȧṫ֖wòţ li⁠bĕné֥y yişĕ̂ráʼéֽl׃"],[14,2,"בְּ⁠גוֹרַ֖ל נַחֲלָתָ֑⁠ם כַּ⁠אֲשֶׁ֨ר צִוָּ֤ה יְהוָה֙ בְּ⁠יַד־מֹשֶׁ֔ה לְ⁠תִשְׁעַ֥ת הַ⁠מַּטּ֖וֹת וַ⁠חֲצִ֥י הַ⁠מַּטֶּֽה׃","bĕ̇⁠gwòra֖l naẖàláţá֑⁠m kȧ⁠ʼàşě֨r ẕiwá֤̇h yĕhwáh֙ bĕ̇⁠yad-mòşě֔h lĕ⁠ţişĕ̌ʻa֥ţ ha⁠mȧṫ֖wòţ wa⁠ẖàẕi֥y ha⁠mȧtėֽh׃"],[14,3,"כִּֽי־נָתַ֨ן מֹשֶׁ֜ה נַחֲלַ֨ת שְׁנֵ֤י הַ⁠מַּטּוֹת֙ וַ⁠חֲצִ֣י הַ⁠מַּטֶּ֔ה מֵ⁠עֵ֖בֶר לַ⁠יַּרְדֵּ֑ן וְ⁠לַ֨⁠לְוִיִּ֔ם לֹֽא־נָתַ֥ן נַחֲלָ֖ה בְּ⁠תוֹכָֽ⁠ם׃","kiֽ̇y-náţa֨n mòşě֜h naẖàla֨ţ şĕ̌né֤y ha⁠mȧṫwòţ֙ wa⁠ẖàẕi֣y ha⁠mȧtė֔h mé⁠ʻé֖ber la⁠yȧrĕdé֑̇n wĕ⁠la֨⁠lĕwiyi̇֔m lòֽʼ-náţa֥n naẖàlá֖h bĕ̇⁠ţwòkáֽ⁠m׃"],[14,4,"כִּֽי־הָי֧וּ בְנֵֽי־יוֹסֵ֛ף שְׁנֵ֥י מַטּ֖וֹת מְנַשֶּׁ֣ה וְ⁠אֶפְרָ֑יִם וְ⁠לֹֽא־נָתְנוּ֩ חֵ֨לֶק לַ⁠לְוִיִּ֜ם בָּ⁠אָ֗רֶץ כִּ֤י אִם־עָרִים֙ לָ⁠שֶׁ֔בֶת וּ⁠מִ֨גְרְשֵׁי⁠הֶ֔ם לְ⁠מִקְנֵי⁠הֶ֖ם וּ⁠לְ⁠קִנְיָנָֽ⁠ם׃","kiֽ̇y-háy֧ẇ bĕnéֽy-ywòsé֛p şĕ̌né֥y maṫ֖wòţ mĕnaşė֣̌h wĕ⁠ʼepĕrá֑yim wĕ⁠lòֽʼ-náţĕnẇ֩ ẖé֨leq la⁠lĕwiyi̇֜m bá̇⁠ʼá֗reẕ ki֤̇y ʼim-ʻáriym֙ lá⁠şě֔beţ ẇ⁠mi֨gĕrĕşé̌y⁠he֔m lĕ⁠miqĕnéy⁠he֖m ẇ⁠lĕ⁠qinĕyánáֽ⁠m׃"],[14,5,"כַּ⁠אֲשֶׁ֨ר צִוָּ֤ה יְהוָה֙ אֶת־מֹשֶׁ֔ה כֵּ֥ן עָשׂ֖וּ בְּנֵ֣י יִשְׂרָאֵ֑ל וַֽ⁠יַּחְלְק֖וּ אֶת־הָ⁠אָֽרֶץ׃פ","kȧ⁠ʼàşě֨r ẕiwá֤̇h yĕhwáh֙ ʼeţ-mòşě֔h ké֥̇n ʻáş֖̂ẇ bĕ̇né֣y yişĕ̂ráʼé֑l waֽ⁠yȧẖĕlĕq֖ẇ ʼeţ-há⁠ʼáֽreẕ׃p"],[14,6,"וַ⁠יִּגְּשׁ֨וּ בְנֵֽי־יְהוּדָ֤ה אֶל־יְהוֹשֻׁ֨עַ֙ בַּ⁠גִּלְגָּ֔ל וַ⁠יֹּ֣אמֶר אֵלָ֔י⁠ו כָּלֵ֥ב בֶּן־יְפֻנֶּ֖ה הַ⁠קְּנִזִּ֑י אַתָּ֣ה יָדַ֡עְתָּ אֶֽת־הַ⁠דָּבָר֩ אֲשֶׁר־דִּבֶּ֨ר יְהוָ֜ה אֶל־מֹשֶׁ֣ה אִישׁ־הָ⁠אֱלֹהִ֗ים עַ֧ל אֹדוֹתַ֛⁠י וְ⁠עַ֥ל אֹדוֹתֶ֖י⁠ךָ בְּ⁠קָדֵ֥שׁ בַּרְנֵֽעַ׃","wa⁠yi̇gĕ̇ş̌֨ẇ bĕnéֽy-yĕhẇdá֤h ʼel-yĕhwòşǔ֨ʻa֙ bȧ⁠gi̇lĕgá̇֔l wa⁠yò֣̇ʼmer ʼélá֔y⁠w ká̇lé֥b bėn-yĕpunė֖h ha⁠qĕ̇nizi֑̇y ʼaţá֣̇h yáda֡ʻĕţá̇ ʼeֽţ-ha⁠dá̇bár֩ ʼàşěr-di̇bė֨r yĕhwá֜h ʼel-mòşě֣h ʼiyş̌-há⁠ʼèlòhi֗ym ʻa֧l ʼòdwòţa֛⁠y wĕ⁠ʻa֥l ʼòdwòţe֖y⁠ká bĕ̇⁠qádé֥ş̌ bȧrĕnéֽʻa׃"],[14,7,"בֶּן־אַרְבָּעִ֨ים שָׁנָ֜ה אָנֹכִ֗י בִּ֠⁠שְׁלֹחַ מֹשֶׁ֨ה עֶֽבֶד־יְהוָ֥ה אֹתִ֛⁠י מִ⁠קָּדֵ֥שׁ בַּרְנֵ֖עַ לְ⁠רַגֵּ֣ל אֶת־הָ⁠אָ֑רֶץ וָ⁠אָשֵׁ֤ב אֹת⁠וֹ֙ דָּבָ֔ר כַּ⁠אֲשֶׁ֖ר עִם־לְבָבִֽ⁠י׃","bėn-ʼarĕbá̇ʻi֨ym şá̌ná֜h ʼánòki֗y bi̇֠⁠şĕ̌lòẖa mòşě֨h ʻeֽbed-yĕhwá֥h ʼòţi֛⁠y mi⁠qá̇dé֥ş̌ bȧrĕné֖ʻa lĕ⁠ragé֣̇l ʼeţ-há⁠ʼá֑reẕ wá⁠ʼáşé֤̌b ʼòţ⁠wò֙ dá̇bá֔r kȧ⁠ʼàşě֖r ʻim-lĕbábiֽ⁠y׃"],[14,8,"וְ⁠אַחַ⁠י֙ אֲשֶׁ֣ר עָל֣וּ עִמִּ֔⁠י הִמְסִ֖יו אֶת־לֵ֣ב הָ⁠עָ֑ם וְ⁠אָנֹכִ֣י מִלֵּ֔אתִי אַחֲרֵ֖י יְהוָ֥ה אֱלֹהָֽ⁠י׃","wĕ⁠ʼaẖa⁠y֙ ʼàşě֣r ʻál֣ẇ ʻimi̇֔⁠y himĕsi֖yw ʼeţ-lé֣b há⁠ʻá֑m wĕ⁠ʼánòki֣y milé̇֔ʼţiy ʼaẖàré֖y yĕhwá֥h ʼèlòháֽ⁠y׃"],[14,9,"וַ⁠יִּשָּׁבַ֣ע מֹשֶׁ֗ה בַּ⁠יּ֣וֹם הַ⁠הוּא֮ לֵ⁠אמֹר֒ אִם־לֹ֗א הָ⁠אָ֨רֶץ֙ אֲשֶׁ֨ר דָּרְכָ֤ה רַגְלְ⁠ךָ֙ בָּ֔⁠הּ לְ⁠ךָ֨ תִֽהְיֶ֧ה לְ⁠נַחֲלָ֛ה וּ⁠לְ⁠בָנֶ֖י⁠ךָ עַד־עוֹלָ֑ם כִּ֣י מִלֵּ֔אתָ אַחֲרֵ֖י יְהוָ֥ה אֱלֹהָֽ⁠י׃","wa⁠yi̇şá̇̌ba֣ʻ mòşě֗h bȧ⁠ẏ֣wòm ha⁠hẇʼ֮ lé⁠ʼmòr֒ ʼim-lò֗ʼ há⁠ʼá֨reẕ֙ ʼàşě֨r dá̇rĕká֤h ragĕlĕ⁠ká֙ bá̇֔⁠ḣ lĕ⁠ká֨ ţiֽhĕye֧h lĕ⁠naẖàlá֛h ẇ⁠lĕ⁠báne֖y⁠ká ʻad-ʻwòlá֑m ki֣̇y milé̇֔ʼţá ʼaẖàré֖y yĕhwá֥h ʼèlòháֽ⁠y׃"],[14,10,"וְ⁠עַתָּ֗ה הִנֵּה֩ הֶחֱיָ֨ה יְהוָ֣ה ׀ אוֹתִ⁠י֮ כַּ⁠אֲשֶׁ֣ר דִּבֵּר֒ זֶה֩ אַרְבָּעִ֨ים וְ⁠חָמֵ֜שׁ שָׁנָ֗ה מֵ֠⁠אָז דִּבֶּ֨ר יְהוָ֜ה אֶת־הַ⁠דָּבָ֤ר הַ⁠זֶּה֙ אֶל־מֹשֶׁ֔ה אֲשֶׁר־הָלַ֥ךְ יִשְׂרָאֵ֖ל בַּ⁠מִּדְבָּ֑ר וְ⁠עַתָּה֙ הִנֵּ֣ה אָנֹכִ֣י הַ⁠יּ֔וֹם בֶּן־חָמֵ֥שׁ וּ⁠שְׁמוֹנִ֖ים שָׁנָֽה׃","wĕ⁠ʻaţá̇֗h hiné̇h֩ heẖèyá֨h yĕhwá֣h ׀ ʼwòţi⁠y֮ kȧ⁠ʼàşě֣r di̇bé̇r֒ zeh֩ ʼarĕbá̇ʻi֨ym wĕ⁠ẖámé֜ş̌ şá̌ná֗h mé֠⁠ʼáz di̇bė֨r yĕhwá֜h ʼeţ-ha⁠dá̇bá֤r ha⁠zėh֙ ʼel-mòşě֔h ʼàşěr-hála֥kĕ yişĕ̂ráʼé֖l bȧ⁠mi̇dĕbá֑̇r wĕ⁠ʻaţá̇h֙ hiné֣̇h ʼánòki֣y ha⁠ẏ֔wòm bėn-ẖámé֥ş̌ ẇ⁠şĕ̌mwòni֖ym şá̌náֽh׃"],[14,11,"עוֹדֶ֨⁠נִּי הַ⁠יּ֜וֹם חָזָ֗ק כַּֽ⁠אֲשֶׁר֙ בְּ⁠י֨וֹם שְׁלֹ֤חַ אוֹתִ⁠י֙ מֹשֶׁ֔ה כְּ⁠כֹ֥חִ⁠י אָ֖ז וּ⁠כְ⁠כֹ֣חִ⁠י עָ֑תָּה לַ⁠מִּלְחָמָ֖ה וְ⁠לָ⁠צֵ֥את וְ⁠לָ⁠בֽוֹא׃","ʻwòde֨⁠ni̇y ha⁠ẏ֜wòm ẖázá֗q kֽ̇a⁠ʼàşěr֙ bĕ̇⁠y֨wòm şĕ̌lò֤ẖa ʼwòţi⁠y֙ mòşě֔h kĕ̇⁠kò֥ẖi⁠y ʼá֖z ẇ⁠kĕ⁠kò֣ẖi⁠y ʻá֑ţá̇h la⁠mi̇lĕẖámá֖h wĕ⁠lá⁠ẕé֥ʼţ wĕ⁠lá⁠bֽwòʼ׃"],[14,12,"וְ⁠עַתָּ֗ה תְּנָ⁠ה־לִּ⁠י֙ אֶת־הָ⁠הָ֣ר הַ⁠זֶּ֔ה אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא כִּ֣י אַתָּֽה־שָׁמַעְתָּ֩ בַ⁠יּ֨וֹם הַ⁠ה֜וּא כִּֽי־עֲנָקִ֣ים שָׁ֗ם וְ⁠עָרִים֙ גְּדֹל֣וֹת בְּצֻר֔וֹת אוּלַ֨י יְהוָ֤ה אוֹתִ⁠י֙ וְ⁠ה֣וֹרַשְׁתִּ֔י⁠ם כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה׃","wĕ⁠ʻaţá̇֗h ţĕ̇ná⁠h-li̇⁠y֙ ʼeţ-há⁠há֣r ha⁠zė֔h ʼàşěr-di̇bė֥r yĕhwá֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ ki֣̇y ʼaţáֽ̇h-şá̌maʻĕţá̇֩ ba⁠ẏ֨wòm ha⁠h֜ẇʼ kiֽ̇y-ʻànáqi֣ym şá̌֗m wĕ⁠ʻáriym֙ gĕ̇dòl֣wòţ bĕ̇ẕur֔wòţ ʼẇla֨y yĕhwá֤h ʼwòţi⁠y֙ wĕ⁠h֣wòraşĕ̌ţi̇֔y⁠m kȧ⁠ʼàşě֖r di̇bė֥r yĕhwáֽh׃"],[14,13,"וַֽ⁠יְבָרְכֵ֖⁠הוּ יְהוֹשֻׁ֑עַ וַ⁠יִּתֵּ֧ן אֶת־חֶבְר֛וֹן לְ⁠כָלֵ֥ב בֶּן־יְפֻנֶּ֖ה לְ⁠נַחֲלָֽה׃","waֽ⁠yĕbárĕké֖⁠hẇ yĕhwòşǔ֑ʻa wa⁠yi̇ţé֧̇n ʼeţ-ẖebĕr֛wòn lĕ⁠kálé֥b bėn-yĕpunė֖h lĕ⁠naẖàláֽh׃"],[14,14,"עַל־כֵּ֣ן הָיְתָֽה־חֶ֠בְרוֹן לְ⁠כָלֵ֨ב בֶּן־יְפֻנֶּ֤ה הַ⁠קְּנִזִּי֙ לְֽ⁠נַחֲלָ֔ה עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה יַ֚עַן אֲשֶׁ֣ר מִלֵּ֔א אַחֲרֵ֕י יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","ʻal-ké֣̇n háyĕţáֽh-ẖe֠bĕrwòn lĕ⁠kálé֨b bėn-yĕpunė֤h ha⁠qĕ̇nizi̇y֙ lĕֽ⁠naẖàlá֔h ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h ya֚ʻan ʼàşě֣r milé̇֔ʼ ʼaẖàré֕y yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[14,15,"וְ⁠שֵׁ֨ם חֶבְר֤וֹן לְ⁠פָנִים֙ קִרְיַ֣ת אַרְבַּ֔ע הָ⁠אָדָ֧ם הַ⁠גָּד֛וֹל בָּ⁠עֲנָקִ֖ים ה֑וּא וְ⁠הָ⁠אָ֥רֶץ שָׁקְטָ֖ה מִ⁠מִּלְחָמָֽה׃פ","wĕ⁠şé̌֨m ẖebĕr֤wòn lĕ⁠pániym֙ qirĕya֣ţ ʼarĕbȧ֔ʻ há⁠ʼádá֧m ha⁠gá̇d֛wòl bá̇⁠ʻànáqi֖ym h֑ẇʼ wĕ⁠há⁠ʼá֥reẕ şá̌qĕtá֖h mi⁠mi̇lĕẖámáֽh׃p"],[15,1,"וַ⁠יְהִ֣י הַ⁠גּוֹרָ֗ל לְ⁠מַטֵּ֛ה בְּנֵ֥י יְהוּדָ֖ה לְ⁠מִשְׁפְּחֹתָ֑⁠ם אֶל־גְּב֨וּל אֱד֧וֹם מִדְבַּר־צִ֛ן נֶ֖גְבָּ⁠ה מִ⁠קְצֵ֥ה תֵימָֽן׃","wa⁠yĕhi֣y ha⁠ġwòrá֗l lĕ⁠maté֛̇h bĕ̇né֥y yĕhẇdá֖h lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m ʼel-gĕ̇b֨ẇl ʼèd֧wòm midĕbȧr-ẕi֛n ne֖gĕbá̇⁠h mi⁠qĕẕé֥h ţéymáֽn׃"],[15,2,"וַ⁠יְהִ֤י לָ⁠הֶם֙ גְּב֣וּל נֶ֔גֶב מִ⁠קְצֵ֖ה יָ֣ם הַ⁠מֶּ֑לַח מִן־הַ⁠לָּשֹׁ֖ן הַ⁠פֹּנֶ֥ה נֶֽגְבָּ⁠ה׃","wa⁠yĕhi֤y lá⁠hem֙ gĕ̇b֣ẇl ne֔geb mi⁠qĕẕé֖h yá֣m ha⁠mė֑laẖ min-ha⁠lá̇şò֖̌n ha⁠pò̇ne֥h neֽgĕbá̇⁠h׃"],[15,3,"וְ֠⁠יָצָא אֶל־מִ⁠נֶּ֜גֶב לְ⁠מַעֲלֵ֤ה עַקְרַבִּים֙ וְ⁠עָ֣בַר צִ֔נָ⁠ה וְ⁠עָלָ֥ה מִ⁠נֶּ֖גֶב לְ⁠קָדֵ֣שׁ בַּרְנֵ֑עַ וְ⁠עָבַ֤ר חֶצְרוֹן֙ וְ⁠עָלָ֣ה אַדָּ֔רָ⁠ה וְ⁠נָסַ֖ב הַ⁠קַּרְקָֽעָ⁠ה׃","wĕ֠⁠yáẕáʼ ʼel-mi⁠nė֜geb lĕ⁠maʻàlé֤h ʻaqĕrabi̇ym֙ wĕ⁠ʻá֣bar ẕi֔ná⁠h wĕ⁠ʻálá֥h mi⁠nė֖geb lĕ⁠qádé֣ş̌ bȧrĕné֑ʻa wĕ⁠ʻába֤r ẖeẕĕrwòn֙ wĕ⁠ʻálá֣h ʼadá̇֔rá⁠h wĕ⁠nása֖b ha⁠qȧrĕqáֽʻá⁠h׃"],[15,4,"וְ⁠עָבַ֣ר עַצְמ֗וֹנָ⁠ה וְ⁠יָצָא֙ נַ֣חַל מִצְרַ֔יִם ו⁠היה תֹּצְא֥וֹת הַ⁠גְּב֖וּל יָ֑מָּ⁠ה זֶה־יִהְיֶ֥ה לָ⁠כֶ֖ם גְּב֥וּל נֶֽגֶב׃","wĕ⁠ʻába֣r ʻaẕĕm֗wòná⁠h wĕ⁠yáẕáʼ֙ na֣ẖal miẕĕra֔yim w⁠hyh ţò̇ẕĕʼ֥wòţ ha⁠gĕ̇b֖ẇl yá֑má̇⁠h zeh-yihĕye֥h lá⁠ke֖m gĕ̇b֥ẇl neֽgeb׃"],[15,5,"וּ⁠גְב֥וּל קֵ֨דְמָ⁠ה֙ יָ֣ם הַ⁠מֶּ֔לַח עַד־קְצֵ֖ה הַ⁠יַּרְדֵּ֑ן וּ⁠גְב֞וּל לִ⁠פְאַ֤ת צָפ֨וֹנָ⁠ה֙ מִ⁠לְּשׁ֣וֹן הַ⁠יָּ֔ם מִ⁠קְצֵ֖ה הַ⁠יַּרְדֵּֽן׃","ẇ⁠gĕb֥ẇl qé֨dĕmá⁠h֙ yá֣m ha⁠mė֔laẖ ʻad-qĕẕé֖h ha⁠yȧrĕdé֑̇n ẇ⁠gĕb֞ẇl li⁠pĕʼa֤ţ ẕáp֨wòná⁠h֙ mi⁠lĕ̇ş֣̌wòn ha⁠yá̇֔m mi⁠qĕẕé֖h ha⁠yȧrĕdéֽ̇n׃"],[15,6,"וְ⁠עָלָ֤ה הַ⁠גְּבוּל֙ בֵּ֣ית חָגְלָ֔ה וְ⁠עָבַ֕ר מִ⁠צְּפ֖וֹן לְ⁠בֵ֣ית הָעֲרָבָ֑ה וְ⁠עָלָ֣ה הַ⁠גְּב֔וּל אֶ֥בֶן בֹּ֖הַן בֶּן־רְאוּבֵֽן׃","wĕ⁠ʻálá֤h ha⁠gĕ̇bẇl֙ bé֣̇yţ ẖágĕlá֔h wĕ⁠ʻába֕r mi⁠ẕĕ̇p֖wòn lĕ⁠bé֣yţ háʻàrábá֑h wĕ⁠ʻálá֣h ha⁠gĕ̇b֔ẇl ʼe֥ben bò֖̇han bėn-rĕʼẇbéֽn׃"],[15,7,"וְ⁠עָלָ֨ה הַ⁠גְּב֥וּל ׀ דְּבִרָ⁠ה֮ מֵ⁠עֵ֣מֶק עָכוֹר֒ וְ⁠צָפ֜וֹנָ⁠ה פֹּנֶ֣ה אֶל־הַ⁠גִּלְגָּ֗ל אֲשֶׁר־נֹ֨כַח֙ לְ⁠מַעֲלֵ֣ה אֲדֻמִּ֔ים אֲשֶׁ֥ר מִ⁠נֶּ֖גֶב לַ⁠נָּ֑חַל וְ⁠עָבַ֤ר הַ⁠גְּבוּל֙ אֶל־מֵי־עֵ֣ין שֶׁ֔מֶשׁ וְ⁠הָי֥וּ תֹצְאֹתָ֖י⁠ו אֶל־עֵ֥ין רֹגֵֽל׃","wĕ⁠ʻálá֨h ha⁠gĕ̇b֥ẇl ׀ dĕ̇birá⁠h֮ mé⁠ʻé֣meq ʻákwòr֒ wĕ⁠ẕáp֜wòná⁠h pò̇ne֣h ʼel-ha⁠gi̇lĕgá̇֗l ʼàşěr-nò֨kaẖ֙ lĕ⁠maʻàlé֣h ʼàdumi̇֔ym ʼàşě֥r mi⁠nė֖geb la⁠ná֑̇ẖal wĕ⁠ʻába֤r ha⁠gĕ̇bẇl֙ ʼel-méy-ʻé֣yn şě֔meş̌ wĕ⁠háy֥ẇ ţòẕĕʼòţá֖y⁠w ʼel-ʻé֥yn rògéֽl׃"],[15,8,"וְ⁠עָלָ֨ה הַ⁠גְּב֜וּל גֵּ֣י בֶן־הִנֹּ֗ם אֶל־כֶּ֤תֶף הַ⁠יְבוּסִי֙ מִ⁠נֶּ֔גֶב הִ֖יא יְרֽוּשָׁלִָ֑ם וְ⁠עָלָ֨ה הַ⁠גְּב֜וּל אֶל־רֹ֣אשׁ הָ⁠הָ֗ר אֲ֠שֶׁר עַל־פְּנֵ֤י גֵֽי־הִנֹּם֙ יָ֔מָּ⁠ה אֲשֶׁ֛ר בִּ⁠קְצֵ֥ה עֵֽמֶק־רְפָאִ֖ים צָפֹֽנָ⁠ה׃","wĕ⁠ʻálá֨h ha⁠gĕ̇b֜ẇl gé֣̇y ben-hinò̇֗m ʼel-kė֤ţep ha⁠yĕbẇsiy֙ mi⁠nė֔geb hi֖yʼ yĕrֽẇşá̌liá֑m wĕ⁠ʻálá֨h ha⁠gĕ̇b֜ẇl ʼel-rò֣ʼş̌ há⁠há֗r ʼà֠şěr ʻal-pĕ̇né֤y géֽy-hinò̇m֙ yá֔má̇⁠h ʼàşě֛r bi̇⁠qĕẕé֥h ʻéֽmeq-rĕpáʼi֖ym ẕápòֽná⁠h׃"],[15,9,"וְ⁠תָאַ֨ר הַ⁠גְּב֜וּל מֵ⁠רֹ֣אשׁ הָ⁠הָ֗ר אֶל־מַעְיַן֙ מֵ֣י נֶפְתּ֔וֹחַ וְ⁠יָצָ֖א אֶל־עָרֵ֣י הַר־עֶפְר֑וֹן וְ⁠תָאַ֤ר הַ⁠גְּבוּל֙ בַּעֲלָ֔ה הִ֖יא קִרְיַ֥ת יְעָרִֽים׃","wĕ⁠ţáʼa֨r ha⁠gĕ̇b֜ẇl mé⁠rò֣ʼş̌ há⁠há֗r ʼel-maʻĕyan֙ mé֣y nepĕţ̇֔wòẖa wĕ⁠yáẕá֖ʼ ʼel-ʻáré֣y har-ʻepĕr֑wòn wĕ⁠ţáʼa֤r ha⁠gĕ̇bẇl֙ bȧʻàlá֔h hi֖yʼ qirĕya֥ţ yĕʻáriֽym׃"],[15,10,"וְ⁠נָסַב֩ הַ⁠גְּב֨וּל מִ⁠בַּעֲלָ֥ה יָ֨מָּ⁠ה֙ אֶל־הַ֣ר שֵׂעִ֔יר וְ⁠עָבַ֕ר אֶל־כֶּ֧תֶף הַר־יְעָרִ֛ים מִ⁠צָּפ֖וֹנָ⁠ה הִ֣יא כְסָל֑וֹן וְ⁠יָרַ֥ד בֵּֽית־שֶׁ֖מֶשׁ וְ⁠עָבַ֥ר תִּמְנָֽה׃","wĕ⁠násab֩ ha⁠gĕ̇b֨ẇl mi⁠bȧʻàlá֥h yá֨má̇⁠h֙ ʼel-ha֣r şé̂ʻi֔yr wĕ⁠ʻába֕r ʼel-kė֧ţep har-yĕʻári֛ym mi⁠ẕá̇p֖wòná⁠h hi֣yʼ kĕsál֑wòn wĕ⁠yára֥d béֽ̇yţ-şě֖meş̌ wĕ⁠ʻába֥r ţi̇mĕnáֽh׃"],[15,11,"וְ⁠יָצָ֨א הַ⁠גְּב֜וּל אֶל־כֶּ֣תֶף עֶקְרוֹן֮ צָפוֹנָ⁠ה֒ וְ⁠תָאַ֤ר הַ⁠גְּבוּל֙ שִׁכְּר֔וֹנָ⁠ה וְ⁠עָבַ֥ר הַר־הַֽ⁠בַּעֲלָ֖ה וְ⁠יָצָ֣א יַבְנְאֵ֑ל וְ⁠הָי֛וּ תֹּצְא֥וֹת הַ⁠גְּב֖וּל יָֽמָּ⁠ה׃","wĕ⁠yáẕá֨ʼ ha⁠gĕ̇b֜ẇl ʼel-kė֣ţep ʻeqĕrwòn֮ ẕápwòná⁠h֒ wĕ⁠ţáʼa֤r ha⁠gĕ̇bẇl֙ şǐkĕ̇r֔wòná⁠h wĕ⁠ʻába֥r har-haֽ⁠bȧʻàlá֖h wĕ⁠yáẕá֣ʼ yabĕnĕʼé֑l wĕ⁠háy֛ẇ ţò̇ẕĕʼ֥wòţ ha⁠gĕ̇b֖ẇl yáֽmá̇⁠h׃"],[15,12,"וּ⁠גְב֣וּל יָ֔ם הַ⁠יָּ֥מָּ⁠ה הַ⁠גָּד֖וֹל וּ⁠גְב֑וּל זֶ֠ה גְּב֧וּל בְּנֵֽי־יְהוּדָ֛ה סָבִ֖יב לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","ẇ⁠gĕb֣ẇl yá֔m ha⁠yá֥̇má̇⁠h ha⁠gá̇d֖wòl ẇ⁠gĕb֑ẇl ze֠h gĕ̇b֧ẇl bĕ̇néֽy-yĕhẇdá֛h sábi֖yb lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[15,13,"וּ⁠לְ⁠כָלֵ֣ב בֶּן־יְפֻנֶּ֗ה נָ֤תַן חֵ֨לֶק֙ בְּ⁠ת֣וֹךְ בְּנֵֽי־יְהוּדָ֔ה אֶל־פִּ֥י יְהוָ֖ה לִֽ⁠יהוֹשֻׁ֑עַ אֶת־קִרְיַ֥ת אַרְבַּ֛ע אֲבִ֥י הָ⁠עֲנָ֖ק הִ֥יא חֶבְרֽוֹן׃","ẇ⁠lĕ⁠kálé֣b bėn-yĕpunė֗h ná֤ţan ẖé֨leq֙ bĕ̇⁠ţ֣wòkĕ bĕ̇néֽy-yĕhẇdá֔h ʼel-pi֥̇y yĕhwá֖h liֽ⁠yhwòşǔ֑ʻa ʼeţ-qirĕya֥ţ ʼarĕbȧ֛ʻ ʼàbi֥y há⁠ʻàná֖q hi֥yʼ ẖebĕrֽwòn׃"],[15,14,"וַ⁠יֹּ֤רֶשׁ מִ⁠שָּׁם֙ כָּלֵ֔ב אֶת־שְׁלוֹשָׁ֖ה בְּנֵ֣י הָ⁠עֲנָ֑ק אֶת־שֵׁשַׁ֤י וְ⁠אֶת־אֲחִימַן֙ וְ⁠אֶת־תַּלְמַ֔י יְלִידֵ֖י הָ⁠עֲנָֽק׃","wa⁠yò֤̇reş̌ mi⁠şá̇̌m֙ ká̇lé֔b ʼeţ-şĕ̌lwòşá֖̌h bĕ̇né֣y há⁠ʻàná֑q ʼeţ-şé̌şǎ֤y wĕ⁠ʼeţ-ʼàẖiyman֙ wĕ⁠ʼeţ-ţȧlĕma֔y yĕliydé֖y há⁠ʻànáֽq׃"],[15,15,"וַ⁠יַּ֣עַל מִ⁠שָּׁ֔ם אֶל־יֹשְׁבֵ֖י דְּבִ֑ר וְ⁠שֵׁם־דְּבִ֥ר לְ⁠פָנִ֖ים קִרְיַת־סֵֽפֶר׃","wa⁠yȧ֣ʻal mi⁠şá̇̌֔m ʼel-yòşĕ̌bé֖y dĕ̇bi֑r wĕ⁠şé̌m-dĕ̇bi֥r lĕ⁠páni֖ym qirĕyaţ-séֽper׃"],[15,16,"וַ⁠יֹּ֣אמֶר כָּלֵ֔ב אֲשֶׁר־יַכֶּ֥ה אֶת־קִרְיַת־סֵ֖פֶר וּ⁠לְכָדָ֑⁠הּ וְ⁠נָתַ֥תִּי ל֛⁠וֹ אֶת־עַכְסָ֥ה בִתִּ֖⁠י לְ⁠אִשָּֽׁה׃","wa⁠yò֣̇ʼmer ká̇lé֔b ʼàşěr-yakė֥h ʼeţ-qirĕyaţ-sé֖per ẇ⁠lĕkádá֑⁠ḣ wĕ⁠náţa֥ţi̇y l֛⁠wò ʼeţ-ʻakĕsá֥h biţi֖̇⁠y lĕ⁠ʼişáֽ̇̌h׃"],[15,17,"וַֽ⁠יִּלְכְּדָ֛⁠הּ עָתְנִיאֵ֥ל בֶּן־קְנַ֖ז אֲחִ֣י כָלֵ֑ב וַ⁠יִּתֶּן־ל֛⁠וֹ אֶת־עַכְסָ֥ה בִתּ֖⁠וֹ לְ⁠אִשָּֽׁה׃","waֽ⁠yi̇lĕkĕ̇dá֛⁠ḣ ʻáţĕniyʼé֥l bėn-qĕna֖z ʼàẖi֣y kálé֑b wa⁠yi̇ţėn-l֛⁠wò ʼeţ-ʻakĕsá֥h biţ֖̇⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[15,18,"וַ⁠יְהִ֣י בְּ⁠בוֹאָ֗⁠הּ וַ⁠תְּסִיתֵ֨⁠הוּ֙ לִ⁠שְׁא֤וֹל מֵֽ⁠אֵת־אָבִ֨י⁠הָ֙ שָׂדֶ֔ה וַ⁠תִּצְנַ֖ח מֵ⁠עַ֣ל הַ⁠חֲמ֑וֹר וַ⁠יֹּֽאמֶר־לָ֥⁠הּ כָּלֵ֖ב מַה־לָּֽ⁠ךְ׃","wa⁠yĕhi֣y bĕ̇⁠bwòʼá֗⁠ḣ wa⁠ţĕ̇siyţé֨⁠hẇ֙ li⁠şĕ̌ʼ֤wòl méֽ⁠ʼéţ-ʼábi֨y⁠há֙ şá̂de֔h wa⁠ţi̇ẕĕna֖ẖ mé⁠ʻa֣l ha⁠ẖàm֑wòr wa⁠yòֽ̇ʼmer-lá֥⁠ḣ ká̇lé֖b mah-láֽ̇⁠kĕ׃"],[15,19,"וַ⁠תֹּ֜אמֶר תְּנָ⁠ה־לִּ֣⁠י בְרָכָ֗ה כִּ֣י אֶ֤רֶץ הַ⁠נֶּ֨גֶב֙ נְתַתָּ֔⁠נִי וְ⁠נָתַתָּ֥ה לִ֖⁠י גֻּלֹּ֣ת מָ֑יִם וַ⁠יִּתֶּן־לָ֗⁠הּ אֵ֚ת גֻּלֹּ֣ת עִלִּיּ֔וֹת וְ⁠אֵ֖ת גֻּלֹּ֥ת תַּחְתִּיּֽוֹת׃פ","wa⁠ţò̇֜ʼmer ţĕ̇ná⁠h-li֣̇⁠y bĕráká֗h ki֣̇y ʼe֤reẕ ha⁠nė֨geb֙ nĕţaţá̇֔⁠niy wĕ⁠náţaţá֥̇h li֖⁠y gu̇lò֣̇ţ má֑yim wa⁠yi̇ţėn-lá֗⁠ḣ ʼé֚ţ gu̇lò֣̇ţ ʻili̇ẏ֔wòţ wĕ⁠ʼé֖ţ gu̇lò֥̇ţ ţȧẖĕţi̇ẏֽwòţ׃p"],[15,20,"זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵי־יְהוּדָ֖ה לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","zò֗ʼţ naẖàla֛ţ maté֥̇h bĕnéy-yĕhẇdá֖h lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[15,21,"וַ⁠יִּֽהְי֣וּ הֶ⁠עָרִ֗ים מִ⁠קְצֵה֙ לְ⁠מַטֵּ֣ה בְנֵֽי־יְהוּדָ֔ה אֶל־גְּב֥וּל אֱד֖וֹם בַּ⁠נֶּ֑גְבָּ⁠ה קַבְצְאֵ֥ל וְ⁠עֵ֖דֶר וְ⁠יָגֽוּר׃","wa⁠yiֽ̇hĕy֣ẇ he⁠ʻári֗ym mi⁠qĕẕéh֙ lĕ⁠maté֣̇h bĕnéֽy-yĕhẇdá֔h ʼel-gĕ̇b֥ẇl ʼèd֖wòm bȧ⁠nė֑gĕbá̇⁠h qabĕẕĕʼé֥l wĕ⁠ʻé֖der wĕ⁠yágֽẇr׃"],[15,22,"וְ⁠קִינָ֥ה וְ⁠דִֽימוֹנָ֖ה וְ⁠עַדְעָדָֽה׃","wĕ⁠qiyná֥h wĕ⁠diֽymwòná֖h wĕ⁠ʻadĕʻádáֽh׃"],[15,23,"וְ⁠קֶ֥דֶשׁ וְ⁠חָצ֖וֹר וְ⁠יִתְנָֽן׃","wĕ⁠qe֥deş̌ wĕ⁠ẖáẕ֖wòr wĕ⁠yiţĕnáֽn׃"],[15,24,"זִ֥יף וָ⁠טֶ֖לֶם וּ⁠בְעָלֽוֹת׃","zi֥yp wá⁠te֖lem ẇ⁠bĕʻálֽwòţ׃"],[15,25,"וְ⁠חָצ֤וֹר ׀ חֲדַתָּה֙ וּ⁠קְרִיּ֔וֹת חֶצְר֖וֹן הִ֥יא חָצֽוֹר׃","wĕ⁠ẖáẕ֤wòr ׀ ẖàdaţá̇h֙ ẇ⁠qĕriẏ֔wòţ ẖeẕĕr֖wòn hi֥yʼ ẖáẕֽwòr׃"],[15,26,"אֲמָ֥ם וּ⁠שְׁמַ֖ע וּ⁠מוֹלָדָֽה׃","ʼàmá֥m ẇ⁠şĕ̌ma֖ʻ ẇ⁠mwòládáֽh׃"],[15,27,"וַ⁠חֲצַ֥ר גַּדָּ֛ה וְ⁠חֶשְׁמ֖וֹן וּ⁠בֵ֥ית פָּֽלֶט׃","wa⁠ẖàẕa֥r gȧdá֛̇h wĕ⁠ẖeşĕ̌m֖wòn ẇ⁠bé֥yţ páֽ̇let׃"],[15,28,"וַ⁠חֲצַ֥ר שׁוּעָ֛ל וּ⁠בְאֵ֥ר שֶׁ֖בַע וּ⁠בִזְיוֹתְיָֽה׃","wa⁠ẖàẕa֥r ş̌ẇʻá֛l ẇ⁠bĕʼé֥r şě֖baʻ ẇ⁠bizĕywòţĕyáֽh׃"],[15,29,"בַּעֲלָ֥ה וְ⁠עִיִּ֖ים וָ⁠עָֽצֶם׃","bȧʻàlá֥h wĕ⁠ʻiyi֖̇ym wá⁠ʻáֽẕem׃"],[15,30,"וְ⁠אֶלְתּוֹלַ֥ד וּ⁠כְסִ֖יל וְ⁠חָרְמָֽה׃","wĕ⁠ʼelĕţ̇wòla֥d ẇ⁠kĕsi֖yl wĕ⁠ẖárĕmáֽh׃"],[15,31,"וְ⁠צִֽקְלַ֥ג וּ⁠מַדְמַנָּ֖ה וְ⁠סַנְסַנָּֽה׃","wĕ⁠ẕiֽqĕla֥g ẇ⁠madĕmaná֖̇h wĕ⁠sanĕsanáֽ̇h׃"],[15,32,"וּ⁠לְבָא֥וֹת וְ⁠שִׁלְחִ֖ים וְ⁠עַ֣יִן וְ⁠רִמּ֑וֹן כָּל־עָרִ֛ים עֶשְׂרִ֥ים וָ⁠תֵ֖שַׁע וְ⁠חַצְרֵי⁠הֶֽן׃ס","ẇ⁠lĕbáʼ֥wòţ wĕ⁠şǐlĕẖi֖ym wĕ⁠ʻa֣yin wĕ⁠riṁ֑wòn ká̇l-ʻári֛ym ʻeşĕ̂ri֥ym wá⁠ţé֖şǎʻ wĕ⁠ẖaẕĕréy⁠heֽn׃s"],[15,33,"בַּ⁠שְּׁפֵלָ֑ה אֶשְׁתָּא֥וֹל וְ⁠צָרְעָ֖ה וְ⁠אַשְׁנָֽה׃","bȧ⁠şĕ̇̌pélá֑h ʼeşĕ̌ţá̇ʼ֥wòl wĕ⁠ẕárĕʻá֖h wĕ⁠ʼaşĕ̌náֽh׃"],[15,34,"וְ⁠זָנ֨וֹחַ֙ וְ⁠עֵ֣ין גַּנִּ֔ים תַּפּ֖וּחַ וְ⁠הָ⁠עֵינָֽם׃","wĕ⁠zán֨wòẖa֙ wĕ⁠ʻé֣yn gȧni̇֔ym ţȧṗ֖ẇẖa wĕ⁠há⁠ʻéynáֽm׃"],[15,35,"יַרְמוּת֙ וַ⁠עֲדֻלָּ֔ם שׂוֹכֹ֖ה וַ⁠עֲזֵקָֽה׃","yarĕmẇţ֙ wa⁠ʻàdulá̇֔m ş̂wòkò֖h wa⁠ʻàzéqáֽh׃"],[15,36,"וְ⁠שַׁעֲרַ֨יִם֙ וַ⁠עֲדִיתַ֔יִם וְ⁠הַ⁠גְּדֵרָ֖ה וּ⁠גְדֵרֹתָ֑יִם עָרִ֥ים אַרְבַּֽע־עֶשְׂרֵ֖ה וְ⁠חַצְרֵי⁠הֶֽן׃","wĕ⁠şǎʻàra֨yim֙ wa⁠ʻàdiyţa֔yim wĕ⁠ha⁠gĕ̇dérá֖h ẇ⁠gĕdéròţá֑yim ʻári֥ym ʼarĕbȧֽʻ-ʻeşĕ̂ré֖h wĕ⁠ẖaẕĕréy⁠heֽn׃"],[15,37,"צְנָ֥ן וַ⁠חֲדָשָׁ֖ה וּ⁠מִגְדַּל־גָּֽד׃","ẕĕná֥n wa⁠ẖàdáşá֖̌h ẇ⁠migĕdȧl-gáֽ̇d׃"],[15,38,"וְ⁠דִלְעָ֥ן וְ⁠הַ⁠מִּצְפֶּ֖ה וְ⁠יָקְתְאֵֽל׃","wĕ⁠dilĕʻá֥n wĕ⁠ha⁠mi̇ẕĕpė֖h wĕ⁠yáqĕţĕʼéֽl׃"],[15,39,"לָכִ֥ישׁ וּ⁠בָצְקַ֖ת וְ⁠עֶגְלֽוֹן׃","láki֥yş̌ ẇ⁠báẕĕqa֖ţ wĕ⁠ʻegĕlֽwòn׃"],[15,40,"וְ⁠כַבּ֥וֹן וְ⁠לַחְמָ֖ס וְ⁠כִתְלִֽישׁ׃","wĕ⁠kaḃ֥wòn wĕ⁠laẖĕmá֖s wĕ⁠kiţĕliֽyş̌׃"],[15,41,"וּ⁠גְדֵר֕וֹת בֵּית־דָּג֥וֹן וְ⁠נַעֲמָ֖ה וּ⁠מַקֵּדָ֑ה עָרִ֥ים שֵׁשׁ־עֶשְׂרֵ֖ה וְ⁠חַצְרֵי⁠הֶֽן׃ס","ẇ⁠gĕdér֕wòţ bé̇yţ-dá̇g֥wòn wĕ⁠naʻàmá֖h ẇ⁠maqé̇dá֑h ʻári֥ym şé̌ş̌-ʻeşĕ̂ré֖h wĕ⁠ẖaẕĕréy⁠heֽn׃s"],[15,42,"לִבְנָ֥ה וָ⁠עֶ֖תֶר וְ⁠עָשָֽׁן׃","libĕná֥h wá⁠ʻe֖ţer wĕ⁠ʻáşáֽ̌n׃"],[15,43,"וְ⁠יִפְתָּ֥ח וְ⁠אַשְׁנָ֖ה וּ⁠נְצִֽיב׃","wĕ⁠yipĕţá֥̇ẖ wĕ⁠ʼaşĕ̌ná֖h ẇ⁠nĕẕiֽyb׃"],[15,44,"וּ⁠קְעִילָ֥ה וְ⁠אַכְזִ֖יב וּ⁠מָֽרֵאשָׁ֑ה עָרִ֥ים תֵּ֖שַׁע וְ⁠חַצְרֵי⁠הֶֽן׃","ẇ⁠qĕʻiylá֥h wĕ⁠ʼakĕzi֖yb ẇ⁠máֽréʼşá֑̌h ʻári֥ym ţé֖̇şǎʻ wĕ⁠ẖaẕĕréy⁠heֽn׃"],[15,45,"עֶקְר֥וֹן וּ⁠בְנֹתֶ֖י⁠הָ וַ⁠חֲצֵרֶֽי⁠הָ׃","ʻeqĕr֥wòn ẇ⁠bĕnòţe֖y⁠há wa⁠ẖàẕéreֽy⁠há׃"],[15,46,"מֵ⁠עֶקְר֖וֹן וָ⁠יָ֑מָּ⁠ה כֹּ֛ל אֲשֶׁר־עַל־יַ֥ד אַשְׁדּ֖וֹד וְ⁠חַצְרֵי⁠הֶֽן׃","mé⁠ʻeqĕr֖wòn wá⁠yá֑má̇⁠h kò֛̇l ʼàşěr-ʻal-ya֥d ʼaşĕ̌ḋ֖wòd wĕ⁠ẖaẕĕréy⁠heֽn׃"],[15,47,"אַשְׁדּ֞וֹד בְּנוֹתֶ֣י⁠הָ וַ⁠חֲצֵרֶ֗י⁠הָ עַזָּ֥ה בְּנוֹתֶ֥י⁠הָ וַ⁠חֲצֵרֶ֖י⁠הָ עַד־נַ֣חַל מִצְרָ֑יִם וְ⁠הַ⁠יָּ֥ם ה⁠גבול וּ⁠גְבֽוּל׃ס","ʼaşĕ̌ḋ֞wòd bĕ̇nwòţe֣y⁠há wa⁠ẖàẕére֗y⁠há ʻazá֥̇h bĕ̇nwòţe֥y⁠há wa⁠ẖàẕére֖y⁠há ʻad-na֣ẖal miẕĕrá֑yim wĕ⁠ha⁠yá֥̇m h⁠gbwl ẇ⁠gĕbֽẇl׃s"],[15,48,"וּ⁠בָ⁠הָ֑ר שָׁמִ֥יר וְ⁠יַתִּ֖יר וְ⁠שׂוֹכֹֽה׃","ẇ⁠bá⁠há֑r şá̌mi֥yr wĕ⁠yaţi֖̇yr wĕ⁠ş̂wòkòֽh׃"],[15,49,"וְ⁠דַנָּ֥ה וְ⁠קִרְיַת־סַנָּ֖ה הִ֥יא דְבִֽר׃","wĕ⁠daná֥̇h wĕ⁠qirĕyaţ-saná֖̇h hi֥yʼ dĕbiֽr׃"],[15,50,"וַ⁠עֲנָ֥ב וְ⁠אֶשְׁתְּמֹ֖ה וְ⁠עָנִֽים׃","wa⁠ʻàná֥b wĕ⁠ʼeşĕ̌ţĕ̇mò֖h wĕ⁠ʻániֽym׃"],[15,51,"וְ⁠גֹ֥שֶׁן וְ⁠חֹלֹ֖ן וְ⁠גִלֹ֑ה עָרִ֥ים אַֽחַת־עֶשְׂרֵ֖ה וְ⁠חַצְרֵי⁠הֶֽן׃","wĕ⁠gò֥şěn wĕ⁠ẖòlò֖n wĕ⁠gilò֑h ʻári֥ym ʼaֽẖaţ-ʻeşĕ̂ré֖h wĕ⁠ẖaẕĕréy⁠heֽn׃"],[15,52,"אֲרַ֥ב וְ⁠רוּמָ֖ה וְ⁠אֶשְׁעָֽן׃","ʼàra֥b wĕ⁠rẇmá֖h wĕ⁠ʼeşĕ̌ʻáֽn׃"],[15,53,"ו⁠ינים וּ⁠בֵית־תַּפּ֖וּחַ וַ⁠אֲפֵֽקָה׃","w⁠ynym ẇ⁠béyţ-ţȧṗ֖ẇẖa wa⁠ʼàpéֽqáh׃"],[15,54,"וְ⁠חֻמְטָ֗ה וְ⁠קִרְיַ֥ת אַרְבַּ֛ע הִ֥יא חֶבְר֖וֹן וְ⁠צִיעֹ֑ר עָרִ֥ים תֵּ֖שַׁע וְ⁠חַצְרֵי⁠הֶֽן׃ס","wĕ⁠ẖumĕtá֗h wĕ⁠qirĕya֥ţ ʼarĕbȧ֛ʻ hi֥yʼ ẖebĕr֖wòn wĕ⁠ẕiyʻò֑r ʻári֥ym ţé֖̇şǎʻ wĕ⁠ẖaẕĕréy⁠heֽn׃s"],[15,55,"מָע֥וֹן ׀ כַּרְמֶ֖ל וָ⁠זִ֥יף וְ⁠יוּטָּֽה׃","máʻ֥wòn ׀ kȧrĕme֖l wá⁠zi֥yp wĕ⁠yẇtáֽ̇h׃"],[15,56,"וְ⁠יִזְרְעֶ֥אל וְ⁠יָקְדְעָ֖ם וְ⁠זָנֽוֹחַ׃","wĕ⁠yizĕrĕʻe֥ʼl wĕ⁠yáqĕdĕʻá֖m wĕ⁠zánֽwòẖa׃"],[15,57,"הַ⁠קַּ֖יִן גִּבְעָ֣ה וְ⁠תִמְנָ֑ה עָרִ֥ים עֶ֖שֶׂר וְ⁠חַצְרֵי⁠הֶֽן׃","ha⁠qȧ֖yin gi̇bĕʻá֣h wĕ⁠ţimĕná֑h ʻári֥ym ʻe֖şêr wĕ⁠ẖaẕĕréy⁠heֽn׃"],[15,58,"חַלְח֥וּל בֵּֽית־צ֖וּר וּ⁠גְדֽוֹר׃","ẖalĕẖ֥ẇl béֽ̇yţ-ẕ֖ẇr ẇ⁠gĕdֽwòr׃"],[15,59,"וּ⁠מַעֲרָ֥ת וּ⁠בֵית־עֲנ֖וֹת וְ⁠אֶלְתְּקֹ֑ן עָרִ֥ים שֵׁ֖שׁ וְ⁠חַצְרֵי⁠הֶֽן׃","ẇ⁠maʻàrá֥ţ ẇ⁠béyţ-ʻàn֖wòţ wĕ⁠ʼelĕţĕ̇qò֑n ʻári֥ym şé֖̌ş̌ wĕ⁠ẖaẕĕréy⁠heֽn׃"],[15,60,"קִרְיַת־בַּ֗עַל הִ֛יא קִרְיַ֥ת יְעָרִ֖ים וְ⁠הָֽ⁠רַבָּ֑ה עָרִ֥ים שְׁתַּ֖יִם וְ⁠חַצְרֵי⁠הֶֽן׃ס","qirĕyaţ-bȧ֗ʻal hi֛yʼ qirĕya֥ţ yĕʻári֖ym wĕ⁠háֽ⁠rabá֑̇h ʻári֥ym şĕ̌ţȧ֖yim wĕ⁠ẖaẕĕréy⁠heֽn׃s"],[15,61,"בַּ⁠מִּדְבָּ֑ר בֵּ֚ית הָעֲרָבָ֔ה מִדִּ֖ין וּ⁠סְכָכָֽה׃","bȧ⁠mi̇dĕbá֑̇r bé֚̇yţ háʻàrábá֔h midi֖̇yn ẇ⁠sĕkákáֽh׃"],[15,62,"וְ⁠הַ⁠נִּבְשָׁ֥ן וְ⁠עִיר־הַ⁠מֶּ֖לַח וְ⁠עֵ֣ין גֶּ֑דִי עָרִ֥ים שֵׁ֖שׁ וְ⁠חַצְרֵי⁠הֶֽן׃","wĕ⁠ha⁠ni̇bĕşá֥̌n wĕ⁠ʻiyr-ha⁠mė֖laẖ wĕ⁠ʻé֣yn gė֑diy ʻári֥ym şé֖̌ş̌ wĕ⁠ẖaẕĕréy⁠heֽn׃"],[15,63,"וְ⁠אֶת־הַ⁠יְבוּסִי֙ יוֹשְׁבֵ֣י יְרֽוּשָׁלִַ֔ם לֹֽא־יוכלו בְנֵֽי־יְהוּדָ֖ה לְ⁠הֽוֹרִישָׁ֑⁠ם וַ⁠יֵּ֨שֶׁב הַ⁠יְבוּסִ֜י אֶת־בְּנֵ֤י יְהוּדָה֙ בִּ⁠יר֣וּשָׁלִַ֔ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wĕ⁠ʼeţ-ha⁠yĕbẇsiy֙ ywòşĕ̌bé֣y yĕrֽẇşá̌lia֔m lòֽʼ-ywklw bĕnéֽy-yĕhẇdá֖h lĕ⁠hֽwòriyşá֑̌⁠m wa⁠yé̇֨şěb ha⁠yĕbẇsi֜y ʼeţ-bĕ̇né֤y yĕhẇdáh֙ bi̇⁠yr֣ẇşá̌lia֔m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[16,1,"וַ⁠יֵּצֵ֨א הַ⁠גּוֹרָ֜ל לִ⁠בְנֵ֤י יוֹסֵף֙ מִ⁠יַּרְדֵּ֣ן יְרִיח֔וֹ לְ⁠מֵ֥י יְרִיח֖וֹ מִזְרָ֑חָ⁠ה הַ⁠מִּדְבָּ֗ר עֹלֶ֧ה מִ⁠ירִיח֛וֹ בָּ⁠הָ֖ר בֵּֽית־אֵֽל׃","wa⁠yé̇ẕé֨ʼ ha⁠ġwòrá֜l li⁠bĕné֤y ywòsép֙ mi⁠yȧrĕdé֣̇n yĕriyẖ֔wò lĕ⁠mé֥y yĕriyẖ֖wò mizĕrá֑ẖá⁠h ha⁠mi̇dĕbá̇֗r ʻòle֧h mi⁠yriyẖ֛wò bá̇⁠há֖r béֽ̇yţ-ʼéֽl׃"],[16,2,"וְ⁠יָצָ֥א מִ⁠בֵּֽית־אֵ֖ל ל֑וּזָ⁠ה וְ⁠עָבַ֛ר אֶל־גְּב֥וּל הָ⁠אַרְכִּ֖י עֲטָרֽוֹת׃","wĕ⁠yáẕá֥ʼ mi⁠béֽ̇yţ-ʼé֖l l֑ẇzá⁠h wĕ⁠ʻába֛r ʼel-gĕ̇b֥ẇl há⁠ʼarĕki֖̇y ʻàtárֽwòţ׃"],[16,3,"וְ⁠יָֽרַד־יָ֜מָּ⁠ה אֶל־גְּב֣וּל הַ⁠יַּפְלֵטִ֗י עַ֣ד גְּב֧וּל בֵּית־חוֹרֹ֛ן תַּחְתּ֖וֹן וְ⁠עַד־גָּ֑זֶר וְ⁠הָי֥וּ תצאת⁠ו יָֽמָּ⁠ה׃","wĕ⁠yáֽrad-yá֜má̇⁠h ʼel-gĕ̇b֣ẇl ha⁠yȧpĕléti֗y ʻa֣d gĕ̇b֧ẇl bé̇yţ-ẖwòrò֛n ţȧẖĕţ֖̇wòn wĕ⁠ʻad-gá֑̇zer wĕ⁠háy֥ẇ ţẕʼţ⁠w yáֽmá̇⁠h׃"],[16,4,"וַ⁠יִּנְחֲל֥וּ בְנֵי־יוֹסֵ֖ף מְנַשֶּׁ֥ה וְ⁠אֶפְרָֽיִם׃","wa⁠yi̇nĕẖàl֥ẇ bĕnéy-ywòsé֖p mĕnaşė֥̌h wĕ⁠ʼepĕráֽyim׃"],[16,5,"וַ⁠יְהִ֛י גְּב֥וּל בְּנֵֽי־אֶפְרַ֖יִם לְ⁠מִשְׁפְּחֹתָ֑⁠ם וַ⁠יְהִ֞י גְּב֤וּל נַחֲלָתָ⁠ם֙ מִזְרָ֔חָ⁠ה עַטְר֣וֹת אַדָּ֔ר עַד־בֵּ֥ית חוֹרֹ֖ן עֶלְיֽוֹן׃","wa⁠yĕhi֛y gĕ̇b֥ẇl bĕ̇néֽy-ʼepĕra֖yim lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m wa⁠yĕhi֞y gĕ̇b֤ẇl naẖàláţá⁠m֙ mizĕrá֔ẖá⁠h ʻatĕr֣wòţ ʼadá̇֔r ʻad-bé֥̇yţ ẖwòrò֖n ʻelĕyֽwòn׃"],[16,6,"וְ⁠יָצָ֨א הַ⁠גְּב֜וּל הַ⁠יָּ֗מָּ⁠ה הַֽ⁠מִּכְמְתָת֙ מִ⁠צָּפ֔וֹן וְ⁠נָסַ֧ב הַ⁠גְּב֛וּל מִזְרָ֖חָ⁠ה תַּאֲנַ֣ת שִׁלֹ֑ה וְ⁠עָבַ֣ר אוֹת֔⁠וֹ מִ⁠מִּזְרַ֖ח יָנֽוֹחָ⁠ה׃","wĕ⁠yáẕá֨ʼ ha⁠gĕ̇b֜ẇl ha⁠yá̇֗má̇⁠h haֽ⁠mi̇kĕmĕţáţ֙ mi⁠ẕá̇p֔wòn wĕ⁠nása֧b ha⁠gĕ̇b֛ẇl mizĕrá֖ẖá⁠h ţȧʼàna֣ţ şǐlò֑h wĕ⁠ʻába֣r ʼwòţ֔⁠wò mi⁠mi̇zĕra֖ẖ yánֽwòẖá⁠h׃"],[16,7,"וְ⁠יָרַ֥ד מִ⁠יָּנ֖וֹחָ⁠ה עֲטָר֣וֹת וְ⁠נַעֲרָ֑תָ⁠ה וּ⁠פָגַע֙ בִּֽ⁠ירִיח֔וֹ וְ⁠יָצָ֖א הַ⁠יַּרְדֵּֽן׃","wĕ⁠yára֥d mi⁠yá̇n֖wòẖá⁠h ʻàtár֣wòţ wĕ⁠naʻàrá֑ţá⁠h ẇ⁠págaʻ֙ biֽ̇⁠yriyẖ֔wò wĕ⁠yáẕá֖ʼ ha⁠yȧrĕdéֽ̇n׃"],[16,8,"מִ⁠תַּפּ֜וּחַ יֵלֵ֨ךְ הַ⁠גְּב֥וּל יָ֨מָּ⁠ה֙ נַ֣חַל קָנָ֔ה וְ⁠הָי֥וּ תֹצְאֹתָ֖י⁠ו הַ⁠יָּ֑מָּ⁠ה זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵי־אֶפְרַ֖יִם לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","mi⁠ţȧṗ֜ẇẖa yélé֨kĕ ha⁠gĕ̇b֥ẇl yá֨má̇⁠h֙ na֣ẖal qáná֔h wĕ⁠háy֥ẇ ţòẕĕʼòţá֖y⁠w ha⁠yá֑̇má̇⁠h zò֗ʼţ naẖàla֛ţ maté֥̇h bĕnéy-ʼepĕra֖yim lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[16,9,"וְ⁠הֶ⁠עָרִ֗ים הַ⁠מִּבְדָּלוֹת֙ לִ⁠בְנֵ֣י אֶפְרַ֔יִם בְּ⁠ת֖וֹךְ נַחֲלַ֣ת בְּנֵֽי־מְנַשֶּׁ֑ה כָּֽל־הֶ⁠עָרִ֖ים וְ⁠חַצְרֵי⁠הֶֽן׃","wĕ⁠he⁠ʻári֗ym ha⁠mi̇bĕdá̇lwòţ֙ li⁠bĕné֣y ʼepĕra֔yim bĕ̇⁠ţ֖wòkĕ naẖàla֣ţ bĕ̇néֽy-mĕnaşė֑̌h káֽ̇l-he⁠ʻári֖ym wĕ⁠ẖaẕĕréy⁠heֽn׃"],[16,10,"וְ⁠לֹ֣א הוֹרִ֔ישׁוּ אֶת־הַֽ⁠כְּנַעֲנִ֖י הַ⁠יּוֹשֵׁ֣ב בְּ⁠גָ֑זֶר וַ⁠יֵּ֨שֶׁב הַֽ⁠כְּנַעֲנִ֜י בְּ⁠קֶ֤רֶב אֶפְרַ֨יִם֙ עַד־הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה וַ⁠יְהִ֖י לְ⁠מַס־עֹבֵֽד׃פ","wĕ⁠lò֣ʼ hwòri֔yş̌ẇ ʼeţ-haֽ⁠kĕ̇naʻàni֖y ha⁠ẏwòşé֣̌b bĕ̇⁠gá֑zer wa⁠yé̇֨şěb haֽ⁠kĕ̇naʻàni֜y bĕ̇⁠qe֤reb ʼepĕra֨yim֙ ʻad-ha⁠ẏ֣wòm ha⁠zė֔h wa⁠yĕhi֖y lĕ⁠mas-ʻòbéֽd׃p"],[17,1,"וַ⁠יְהִ֤י הַ⁠גּוֹרָל֙ לְ⁠מַטֵּ֣ה מְנַשֶּׁ֔ה כִּי־ה֖וּא בְּכ֣וֹר יוֹסֵ֑ף לְ⁠מָכִיר֩ בְּכ֨וֹר מְנַשֶּׁ֜ה אֲבִ֣י הַ⁠גִּלְעָ֗ד כִּ֣י ה֤וּא הָיָה֙ אִ֣ישׁ מִלְחָמָ֔ה וַֽ⁠יְהִי־ל֖⁠וֹ הַ⁠גִּלְעָ֥ד וְ⁠הַ⁠בָּשָֽׁן׃","wa⁠yĕhi֤y ha⁠ġwòrál֙ lĕ⁠maté֣̇h mĕnaşė̌֔h ki̇y-h֖ẇʼ bĕ̇k֣wòr ywòsé֑p lĕ⁠mákiyr֩ bĕ̇k֨wòr mĕnaşė̌֜h ʼàbi֣y ha⁠gi̇lĕʻá֗d ki֣̇y h֤ẇʼ háyáh֙ ʼi֣yş̌ milĕẖámá֔h wֽa⁠yĕhiy-l֖⁠wò ha⁠gi̇lĕʻá֥d wĕ⁠ha⁠bá̇şáֽ̌n׃"],[17,2,"וַ֠⁠יְהִי לִ⁠בְנֵ֨י מְנַשֶּׁ֥ה הַ⁠נּוֹתָרִים֮ לְ⁠מִשְׁפְּחֹתָ⁠ם֒ לִ⁠בְנֵ֨י אֲבִיעֶ֜זֶר וְ⁠לִ⁠בְנֵי־חֵ֗לֶק וְ⁠לִ⁠בְנֵ֤י אַשְׂרִיאֵל֙ וְ⁠לִ⁠בְנֵי־שֶׁ֔כֶם וְ⁠לִ⁠בְנֵי־חֵ֖פֶר וְ⁠לִ⁠בְנֵ֣י שְׁמִידָ֑ע אֵ֠לֶּה בְּנֵ֨י מְנַשֶּׁ֧ה בֶּן־יוֹסֵ֛ף הַ⁠זְּכָרִ֖ים לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","wa֠⁠yĕhiy li⁠bĕné֨y mĕnaşė֥̌h ha⁠ṅwòţáriym֮ lĕ⁠mişĕ̌pĕ̇ẖòţá⁠m֒ li⁠bĕné֨y ʼàbiyʻe֜zer wĕ⁠li⁠bĕnéy-ẖé֗leq wĕ⁠li⁠bĕné֤y ʼaşĕ̂riyʼél֙ wĕ⁠li⁠bĕnéy-şě֔kem wĕ⁠li⁠bĕnéy-ẖé֖per wĕ⁠li⁠bĕné֣y şĕ̌miydá֑ʻ ʼé֠lėh bĕ̇né֨y mĕnaşė֧̌h bėn-ywòsé֛p ha⁠zĕ̇kári֖ym lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[17,3,"וְ⁠לִ⁠צְלָפְחָד֩ בֶּן־חֵ֨פֶר בֶּן־גִּלְעָ֜ד בֶּן־מָכִ֣יר בֶּן־מְנַשֶּׁ֗ה לֹא־הָ֥יוּ ל֛⁠וֹ בָּנִ֖ים כִּ֣י אִם־בָּנ֑וֹת וְ⁠אֵ֨לֶּה֙ שְׁמ֣וֹת בְּנֹתָ֔י⁠ו מַחְלָ֣ה וְ⁠נֹעָ֔ה חָגְלָ֥ה מִלְכָּ֖ה וְ⁠תִרְצָֽה׃","wĕ⁠li⁠ẕĕlápĕẖád֩ bėn-ẖé֨per bėn-gi̇lĕʻá֜d bėn-máki֣yr bėn-mĕnaşė̌֗h lòʼ-há֥yẇ l֛⁠wò bá̇ni֖ym ki֣̇y ʼim-bá̇n֑wòţ wĕ⁠ʼé֨lėh֙ şĕ̌m֣wòţ bĕ̇nòţá֔y⁠w maẖĕlá֣h wĕ⁠nòʻá֔h ẖágĕlá֥h milĕká֖̇h wĕ⁠ţirĕẕáֽh׃"],[17,4,"וַ⁠תִּקְרַ֡בְנָה לִ⁠פְנֵי֩ אֶלְעָזָ֨ר הַ⁠כֹּהֵ֜ן וְ⁠לִ⁠פְנֵ֣י ׀ יְהוֹשֻׁ֣עַ בִּן־נ֗וּן וְ⁠לִ⁠פְנֵ֤י הַ⁠נְּשִׂיאִים֙ לֵ⁠אמֹ֔ר יְהוָה֙ צִוָּ֣ה אֶת־מֹשֶׁ֔ה לָֽ⁠תֶת־לָ֥⁠נוּ נַחֲלָ֖ה בְּ⁠ת֣וֹךְ אַחֵ֑י⁠נוּ וַ⁠יִּתֵּ֨ן לָ⁠הֶ֜ם אֶל־פִּ֤י יְהוָה֙ נַֽחֲלָ֔ה בְּ⁠ת֖וֹךְ אֲחֵ֥י אֲבִי⁠הֶֽן׃","wa⁠ţi̇qĕra֡bĕnáh li⁠pĕnéy֩ ʼelĕʻázá֨r ha⁠kò̇hé֜n wĕ⁠li⁠pĕné֣y ׀ yĕhwòşǔ֣ʻa bi̇n-n֗ẇn wĕ⁠li⁠pĕné֤y ha⁠nĕ̇şîyʼiym֙ lé⁠ʼmò֔r yĕhwáh֙ ẕiwá֣̇h ʼeţ-mòşě֔h láֽ⁠ţeţ-lá֥⁠nẇ naẖàlá֖h bĕ̇⁠ţ֣wòkĕ ʼaẖé֑y⁠nẇ wa⁠yi̇ţé̇֨n lá⁠he֜m ʼel-pi֤̇y yĕhwáh֙ nֽaẖàlá֔h bĕ̇⁠ţ֖wòkĕ ʼàẖé֥y ʼàbiy⁠heֽn׃"],[17,5,"וַ⁠יִּפְּל֥וּ חַבְלֵֽי־מְנַשֶּׁ֖ה עֲשָׂרָ֑ה לְ⁠בַ֞ד מֵ⁠אֶ֤רֶץ הַ⁠גִּלְעָד֙ וְ⁠הַ⁠בָּשָׁ֔ן אֲשֶׁ֖ר מֵ⁠עֵ֥בֶר לַ⁠יַּרְדֵּֽן׃","wa⁠yi̇pĕ̇l֥ẇ ẖabĕléֽy-mĕnaşė֖̌h ʻàşá̂rá֑h lĕ⁠ba֞d mé⁠ʼe֤reẕ ha⁠gi̇lĕʻád֙ wĕ⁠ha⁠bá̇şá̌֔n ʼàşě֖r mé⁠ʻé֥ber la⁠yȧrĕdéֽ̇n׃"],[17,6,"כִּ֚י בְּנ֣וֹת מְנַשֶּׁ֔ה נָחֲל֥וּ נַחֲלָ֖ה בְּ⁠ת֣וֹךְ בָּנָ֑י⁠ו וְ⁠אֶ֨רֶץ֙ הַ⁠גִּלְעָ֔ד הָיְתָ֥ה לִ⁠בְנֵֽי־מְנַשֶּׁ֖ה הַ⁠נּֽוֹתָרִֽים׃","ki֚̇y bĕ̇n֣wòţ mĕnaşė̌֔h náẖàl֥ẇ naẖàlá֖h bĕ̇⁠ţ֣wòkĕ bá̇ná֑y⁠w wĕ⁠ʼe֨reẕ֙ ha⁠gi̇lĕʻá֔d háyĕţá֥h li⁠bĕnéֽy-mĕnaşė֖̌h ha⁠ṅֽwòţáriֽym׃"],[17,7,"וַ⁠יְהִ֤י גְבוּל־מְנַשֶּׁה֙ מֵֽ⁠אָשֵׁ֔ר הַֽ⁠מִּכְמְתָ֔ת אֲשֶׁ֖ר עַל־פְּנֵ֣י שְׁכֶ֑ם וְ⁠הָלַ֤ךְ הַ⁠גְּבוּל֙ אֶל־הַ⁠יָּמִ֔ין אֶל־יֹשְׁבֵ֖י עֵ֥ין תַּפּֽוּחַ׃","wa⁠yĕhi֤y gĕbẇl-mĕnaşė̌h֙ méֽ⁠ʼáşé̌֔r haֽ⁠mi̇kĕmĕţá֔ţ ʼàşě֖r ʻal-pĕ̇né֣y şĕ̌ke֑m wĕ⁠hála֤kĕ ha⁠gĕ̇bẇl֙ ʼel-ha⁠yá̇mi֔yn ʼel-yòşĕ̌bé֖y ʻé֥yn ţȧṗֽẇẖa׃"],[17,8,"לִ⁠מְנַשֶּׁ֕ה הָיְתָ֖ה אֶ֣רֶץ תַּפּ֑וּחַ וְ⁠תַפּ֛וּחַ אֶל־גְּב֥וּל מְנַשֶּׁ֖ה לִ⁠בְנֵ֥י אֶפְרָֽיִם׃","li⁠mĕnaşė̌֕h háyĕţá֖h ʼe֣reẕ ţȧṗ֑ẇẖa wĕ⁠ţaṗ֛ẇẖa ʼel-gĕ̇b֥ẇl mĕnaşė֖̌h li⁠bĕné֥y ʼepĕráֽyim׃"],[17,9,"וְ⁠יָרַ֣ד הַ⁠גְּבוּל֩ נַ֨חַל קָנָ֜ה נֶ֣גְבָּ⁠ה לַ⁠נַּ֗חַל עָרִ֤ים הָ⁠אֵ֨לֶּה֙ לְ⁠אֶפְרַ֔יִם בְּ⁠ת֖וֹךְ עָרֵ֣י מְנַשֶּׁ֑ה וּ⁠גְב֤וּל מְנַשֶּׁה֙ מִ⁠צְּפ֣וֹן לַ⁠נַּ֔חַל וַ⁠יְהִ֥י תֹצְאֹתָ֖י⁠ו הַ⁠יָּֽמָּ⁠ה׃","wĕ⁠yára֣d ha⁠gĕ̇bẇl֩ na֨ẖal qáná֜h ne֣gĕbá̇⁠h la⁠nȧ֗ẖal ʻári֤ym há⁠ʼé֨lėh֙ lĕ⁠ʼepĕra֔yim bĕ̇⁠ţ֖wòkĕ ʻáré֣y mĕnaşė֑̌h ẇ⁠gĕb֤ẇl mĕnaşė̌h֙ mi⁠ẕĕ̇p֣wòn la⁠nȧ֔ẖal wa⁠yĕhi֥y ţòẕĕʼòţá֖y⁠w ha⁠yáֽ̇má̇⁠h׃"],[17,10,"נֶ֣גְבָּ⁠ה לְ⁠אֶפְרַ֗יִם וְ⁠צָפ֨וֹנָ⁠ה֙ לִ⁠מְנַשֶּׁ֔ה וַ⁠יְהִ֥י הַ⁠יָּ֖ם גְּבוּל֑⁠וֹ וּ⁠בְ⁠אָשֵׁר֙ יִפְגְּע֣וּ⁠ן מִ⁠צָּפ֔וֹן וּ⁠בְ⁠יִשָּׂשכָ֖ר מִ⁠מִּזְרָֽח׃","ne֣gĕbá̇⁠h lĕ⁠ʼepĕra֗yim wĕ⁠ẕáp֨wòná⁠h֙ li⁠mĕnaşė̌֔h wa⁠yĕhi֥y ha⁠yá֖̇m gĕ̇bẇl֑⁠wò ẇ⁠bĕ⁠ʼáşé̌r֙ yipĕgĕ̇ʻ֣ẇ⁠n mi⁠ẕá̇p֔wòn ẇ⁠bĕ⁠yişá̇̂şká֖r mi⁠mi̇zĕráֽẖ׃"],[17,11,"וַ⁠יְהִ֨י לִ⁠מְנַשֶּׁ֜ה בְּ⁠יִשָּׂשכָ֣ר וּ⁠בְ⁠אָשֵׁ֗ר בֵּית־שְׁאָ֣ן וּ֠⁠בְנוֹתֶי⁠הָ וְ⁠יִבְלְעָ֨ם וּ⁠בְנוֹתֶ֜י⁠הָ וְֽ⁠אֶת־יֹשְׁבֵ֧י דֹ֣אר וּ⁠בְנוֹתֶ֗י⁠הָ וְ⁠יֹשְׁבֵ֤י עֵֽין־דֹּר֙ וּ⁠בְנֹתֶ֔י⁠הָ וְ⁠יֹשְׁבֵ֤י תַעְנַךְ֙ וּ⁠בְנֹתֶ֔י⁠הָ וְ⁠יֹשְׁבֵ֥י מְגִדּ֖וֹ וּ⁠בְנוֹתֶ֑י⁠הָ שְׁלֹ֖שֶׁת הַ⁠נָּֽפֶת׃","wa⁠yĕhi֨y li⁠mĕnaşė̌֜h bĕ̇⁠yişá̇̂şká֣r ẇ⁠bĕ⁠ʼáşé̌֗r bé̇yţ-şĕ̌ʼá֣n ẇ֠⁠bĕnwòţey⁠há wĕ⁠yibĕlĕʻá֨m ẇ⁠bĕnwòţe֜y⁠há wĕֽ⁠ʼeţ-yòşĕ̌bé֧y dò֣ʼr ẇ⁠bĕnwòţe֗y⁠há wĕ⁠yòşĕ̌bé֤y ʻéֽyn-dò̇r֙ ẇ⁠bĕnòţe֔y⁠há wĕ⁠yòşĕ̌bé֤y ţaʻĕnakĕ֙ ẇ⁠bĕnòţe֔y⁠há wĕ⁠yòşĕ̌bé֥y mĕgiḋ֖wò ẇ⁠bĕnwòţe֑y⁠há şĕ̌lò֖şěţ ha⁠náֽ̇peţ׃"],[17,12,"וְ⁠לֹ֤א יָכְלוּ֙ בְּנֵ֣י מְנַשֶּׁ֔ה לְ⁠הוֹרִ֖ישׁ אֶת־הֶֽ⁠עָרִ֣ים הָ⁠אֵ֑לֶּה וַ⁠יּ֨וֹאֶל֙ הַֽ⁠כְּנַעֲנִ֔י לָ⁠שֶׁ֖בֶת בָּ⁠אָ֥רֶץ הַ⁠זֹּֽאת׃","wĕ⁠lò֤ʼ yákĕlẇ֙ bĕ̇né֣y mĕnaşė̌֔h lĕ⁠hwòri֖yş̌ ʼeţ-heֽ⁠ʻári֣ym há⁠ʼé֑lėh wa⁠ẏ֨wòʼel֙ haֽ⁠kĕ̇naʻàni֔y lá⁠şě֖beţ bá̇⁠ʼá֥reẕ ha⁠zòֽ̇ʼţ׃"],[17,13,"וַֽ⁠יְהִ֗י כִּ֤י חָֽזְקוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יִּתְּנ֥וּ אֶת־הַֽ⁠כְּנַעֲנִ֖י לָ⁠מַ֑ס וְ⁠הוֹרֵ֖שׁ לֹ֥א הוֹרִישֽׁ⁠וֹ׃ס","wֽa⁠yĕhi֗y ki֤̇y ẖֽázĕqẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l wa⁠yi̇ţĕ̇n֥ẇ ʼeţ-haֽ⁠kĕ̇naʻàni֖y lá⁠ma֑s wĕ⁠hwòré֖ş̌ lò֥ʼ hwòriyşֽ̌⁠wò׃s"],[17,14,"וַֽ⁠יְדַבְּרוּ֙ בְּנֵ֣י יוֹסֵ֔ף אֶת־יְהוֹשֻׁ֖עַ לֵ⁠אמֹ֑ר מַדּוּעַ֩ נָתַ֨תָּה לִּ֜⁠י נַחֲלָ֗ה גּוֹרָ֤ל אֶחָד֙ וְ⁠חֶ֣בֶל אֶחָ֔ד וַֽ⁠אֲנִ֣י עַם־רָ֔ב עַ֥ד אֲשֶׁר־עַד־כֹּ֖ה בֵּֽרְכַ֥⁠נִי יְהוָֽה׃","waֽ⁠yĕdabĕ̇rẇ֙ bĕ̇né֣y ywòsé֔p ʼeţ-yĕhwòşǔ֖ʻa lé⁠ʼmò֑r maḋẇʻa֩ náţa֨ţá̇h li̇֜⁠y naẖàlá֗h ġwòrá֤l ʼeẖád֙ wĕ⁠ẖe֣bel ʼeẖá֔d wֽa⁠ʼàni֣y ʻam-rá֔b ʻa֥d ʼàşěr-ʻad-kò֖̇h béֽ̇rĕka֥⁠niy yĕhwáֽh׃"],[17,15,"וַ⁠יֹּ֨אמֶר אֲלֵי⁠הֶ֜ם יְהוֹשֻׁ֗עַ אִם־עַם־רַ֤ב אַתָּה֙ עֲלֵ֣ה לְ⁠ךָ֣ הַ⁠יַּ֔עְרָ⁠ה וּ⁠בֵרֵאתָ֤ לְ⁠ךָ֙ שָׁ֔ם בְּ⁠אֶ֥רֶץ הַ⁠פְּרִזִּ֖י וְ⁠הָֽ⁠רְפָאִ֑ים כִּֽי־אָ֥ץ לְ⁠ךָ֖ הַר־אֶפְרָֽיִם׃","wa⁠yò̇֨ʼmer ʼàléy⁠he֜m yĕhwòşǔ֗ʻa ʼim-ʻam-ra֤b ʼaţá̇h֙ ʻàlé֣h lĕ⁠ká֣ ha⁠yȧ֔ʻĕrá⁠h ẇ⁠béréʼţá֤ lĕ⁠ká֙ şá̌֔m bĕ̇⁠ʼe֥reẕ ha⁠pĕ̇rizi֖̇y wĕ⁠háֽ⁠rĕpáʼi֑ym kiֽ̇y-ʼá֥ẕ lĕ⁠ká֖ har-ʼepĕráֽyim׃"],[17,16,"וַ⁠יֹּֽאמְרוּ֙ בְּנֵ֣י יוֹסֵ֔ף לֹֽא־יִמָּ֥צֵא לָ֖⁠נוּ הָ⁠הָ֑ר וְ⁠רֶ֣כֶב בַּרְזֶ֗ל בְּ⁠כָל־הַֽ⁠כְּנַעֲנִי֙ הַ⁠יֹּשֵׁ֣ב בְּ⁠אֶֽרֶץ־הָ⁠עֵ֔מֶק לַֽ⁠אֲשֶׁ֤ר בְּ⁠בֵית־שְׁאָן֙ וּ⁠בְנוֹתֶ֔י⁠הָ וְ⁠לַֽ⁠אֲשֶׁ֖ר בְּ⁠עֵ֥מֶק יִזְרְעֶֽאל׃","wa⁠yòֽ̇ʼmĕrẇ֙ bĕ̇né֣y ywòsé֔p lòֽʼ-yimá֥̇ẕéʼ lá֖⁠nẇ há⁠há֑r wĕ⁠re֣keb bȧrĕze֗l bĕ̇⁠kál-haֽ⁠kĕ̇naʻàniy֙ ha⁠yò̇şé֣̌b bĕ̇⁠ʼeֽreẕ-há⁠ʻé֔meq lֽa⁠ʼàşě֤r bĕ̇⁠béyţ-şĕ̌ʼán֙ ẇ⁠bĕnwòţe֔y⁠há wĕ⁠laֽ⁠ʼàşě֖r bĕ̇⁠ʻé֥meq yizĕrĕʻeֽʼl׃"],[17,17,"וַ⁠יֹּ֤אמֶר יְהוֹשֻׁ֨עַ֙ אֶל־בֵּ֣ית יוֹסֵ֔ף לְ⁠אֶפְרַ֥יִם וְ⁠לִ⁠מְנַשֶּׁ֖ה לֵ⁠אמֹ֑ר עַם־רַ֣ב אַתָּ֗ה וְ⁠כֹ֤חַ גָּדוֹל֙ לָ֔⁠ךְ לֹֽא־יִהְיֶ֥ה לְ⁠ךָ֖ גּוֹרָ֥ל אֶחָֽד׃","wa⁠yò֤̇ʼmer yĕhwòşǔ֨ʻa֙ ʼel-bé֣̇yţ ywòsé֔p lĕ⁠ʼepĕra֥yim wĕ⁠li⁠mĕnaşė֖̌h lé⁠ʼmò֑r ʻam-ra֣b ʼaţá̇֗h wĕ⁠kò֤ẖa gá̇dwòl֙ lá֔⁠kĕ lòֽʼ-yihĕye֥h lĕ⁠ká֖ ġwòrá֥l ʼeẖáֽd׃"],[17,18,"כִּ֣י הַ֤ר יִֽהְיֶה־לָּ⁠ךְ֙ כִּֽי־יַ֣עַר ה֔וּא וּ⁠בֵ֣רֵאת֔⁠וֹ וְ⁠הָיָ֥ה לְ⁠ךָ֖ תֹּֽצְאֹתָ֑י⁠ו כִּֽי־תוֹרִ֣ישׁ אֶת־הַֽ⁠כְּנַעֲנִ֗י כִּ֣י רֶ֤כֶב בַּרְזֶל֙ ל֔⁠וֹ כִּ֥י חָזָ֖ק הֽוּא׃פ","ki֣̇y ha֤r yiֽhĕyeh-lá̇⁠kĕ֙ kiֽ̇y-ya֣ʻar h֔ẇʼ ẇ⁠bé֣réʼţ֔⁠wò wĕ⁠háyá֥h lĕ⁠ká֖ ţòֽ̇ẕĕʼòţá֑y⁠w kiֽ̇y-ţwòri֣yş̌ ʼeţ-haֽ⁠kĕ̇naʻàni֗y ki֣̇y re֤keb bȧrĕzel֙ l֔⁠wò ki֥̇y ẖázá֖q hֽẇʼ׃p"],[18,1,"וַ⁠יִּקָּ֨הֲל֜וּ כָּל־עֲדַ֤ת בְּנֵֽי־יִשְׂרָאֵל֙ שִׁלֹ֔ה וַ⁠יַּשְׁכִּ֥ינוּ שָׁ֖ם אֶת־אֹ֣הֶל מוֹעֵ֑ד וְ⁠הָ⁠אָ֥רֶץ נִכְבְּשָׁ֖ה לִ⁠פְנֵי⁠הֶֽם׃","wa⁠yi̇qá̇֨hàl֜ẇ ká̇l-ʻàda֤ţ bĕ̇néֽy-yişĕ̂ráʼél֙ şǐlò֔h wa⁠yȧşĕ̌ki֥̇ynẇ şá֖̌m ʼeţ-ʼò֣hel mwòʻé֑d wĕ⁠há⁠ʼá֥reẕ nikĕbĕ̇şá֖̌h li⁠pĕnéy⁠heֽm׃"],[18,2,"וַ⁠יִּוָּֽתְרוּ֙ בִּ⁠בְנֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֥ר לֹֽא־חָלְק֖וּ אֶת־נַֽחֲלָתָ֑⁠ם שִׁבְעָ֖ה שְׁבָטִֽים׃","wa⁠yi̇wáֽ̇ţĕrẇ֙ bi̇⁠bĕné֣y yişĕ̂ráʼé֔l ʼàşě֥r lòֽʼ-ẖálĕq֖ẇ ʼeţ-nֽaẖàláţá֑⁠m şǐbĕʻá֖h şĕ̌bátiֽym׃"],[18,3,"וַ⁠יֹּ֥אמֶר יְהוֹשֻׁ֖עַ אֶל־בְּנֵ֣י יִשְׂרָאֵ֑ל עַד־אָ֨נָה֙ אַתֶּ֣ם מִתְרַפִּ֔ים לָ⁠בוֹא֙ לָ⁠רֶ֣שֶׁת אֶת־הָ⁠אָ֔רֶץ אֲשֶׁר֙ נָתַ֣ן לָ⁠כֶ֔ם יְהוָ֖ה אֱלֹהֵ֥י אֲבֽוֹתֵי⁠כֶֽם׃","wa⁠yò֥̇ʼmer yĕhwòşǔ֖ʻa ʼel-bĕ̇né֣y yişĕ̂ráʼé֑l ʻad-ʼá֨náh֙ ʼaţė֣m miţĕrapi̇֔ym lá⁠bwòʼ֙ lá⁠re֣şěţ ʼeţ-há⁠ʼá֔reẕ ʼàşěr֙ náţa֣n lá⁠ke֔m yĕhwá֖h ʼèlòhé֥y ʼàbֽwòţéy⁠keֽm׃"],[18,4,"הָב֥וּ לָ⁠כֶ֛ם שְׁלֹשָׁ֥ה אֲנָשִׁ֖ים לַ⁠שָּׁ֑בֶט וְ⁠אֶשְׁלָחֵ֗⁠ם וְ⁠יָקֻ֜מוּ וְ⁠יִֽתְהַלְּכ֥וּ בָ⁠אָ֛רֶץ וְ⁠יִכְתְּב֥וּ אוֹתָ֛⁠הּ לְ⁠פִ֥י נַֽחֲלָתָ֖⁠ם וְ⁠יָבֹ֥אוּ אֵלָֽ⁠י׃","háb֥ẇ lá⁠ke֛m şĕ̌lòşá֥̌h ʼànáşǐ֖ym la⁠şá֑̇̌bet wĕ⁠ʼeşĕ̌láẖé֗⁠m wĕ⁠yáqu֜mẇ wĕ⁠yiֽţĕhalĕ̇k֥ẇ bá⁠ʼá֛reẕ wĕ⁠yikĕţĕ̇b֥ẇ ʼwòţá֛⁠ḣ lĕ⁠pi֥y naֽẖàláţá֖⁠m wĕ⁠yábò֥ʼẇ ʼéláֽ⁠y׃"],[18,5,"וְ⁠הִֽתְחַלְּק֥וּ אֹתָ֖⁠הּ לְ⁠שִׁבְעָ֣ה חֲלָקִ֑ים יְהוּדָ֞ה יַעֲמֹ֤ד עַל־גְּבוּל⁠וֹ֙ מִ⁠נֶּ֔גֶב וּ⁠בֵ֥ית יוֹסֵ֛ף יַעַמְד֥וּ עַל־גְּבוּלָ֖⁠ם מִ⁠צָּפֽוֹן׃","wĕ⁠hiֽţĕẖalĕ̇q֥ẇ ʼòţá֖⁠ḣ lĕ⁠şǐbĕʻá֣h ẖàláqi֑ym yĕhẇdá֞h yaʻàmò֤d ʻal-gĕ̇bẇl⁠wò֙ mi⁠nė֔geb ẇ⁠bé֥yţ ywòsé֛p yaʻamĕd֥ẇ ʻal-gĕ̇bẇlá֖⁠m mi⁠ẕá̇pֽwòn׃"],[18,6,"וְ⁠אַתֶּ֞ם תִּכְתְּב֤וּ אֶת־הָ⁠אָ֨רֶץ֙ שִׁבְעָ֣ה חֲלָקִ֔ים וַֽ⁠הֲבֵאתֶ֥ם אֵלַ֖⁠י הֵ֑נָּה וְ⁠יָרִ֨יתִי לָ⁠כֶ֤ם גּוֹרָל֙ פֹּ֔ה לִ⁠פְנֵ֖י יְהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","wĕ⁠ʼaţė֞m ţi̇kĕţĕ̇b֤ẇ ʼeţ-há⁠ʼá֨reẕ֙ şǐbĕʻá֣h ẖàláqi֔ym wֽa⁠hàbéʼţe֥m ʼéla֖⁠y hé֑ná̇h wĕ⁠yári֨yţiy lá⁠ke֤m ġwòrál֙ pò̇֔h li⁠pĕné֖y yĕhwá֥h ʼèlòhéֽy⁠nẇ׃"],[18,7,"כִּ֠י אֵֽין־חֵ֤לֶק לַ⁠לְוִיִּם֙ בְּ⁠קִרְבְּ⁠כֶ֔ם כִּֽי־כְהֻנַּ֥ת יְהוָ֖ה נַחֲלָת֑⁠וֹ וְ⁠גָ֡ד וּ⁠רְאוּבֵ֡ן וַ⁠חֲצִי֩ שֵׁ֨בֶט הַֽ⁠מְנַשֶּׁ֜ה לָקְח֣וּ נַחֲלָתָ֗⁠ם מֵ⁠עֵ֤בֶר לַ⁠יַּרְדֵּן֙ מִזְרָ֔חָ⁠ה אֲשֶׁר֙ נָתַ֣ן לָ⁠הֶ֔ם מֹשֶׁ֖ה עֶ֥בֶד יְהוָֽה׃","ki̇֠y ʼéֽyn-ẖé֤leq la⁠lĕwiyi̇m֙ bĕ̇⁠qirĕbĕ̇⁠ke֔m kiֽ̇y-kĕhunȧ֥ţ yĕhwá֖h naẖàláţ֑⁠wò wĕ⁠gá֡d ẇ⁠rĕʼẇbé֡n wa⁠ẖàẕiy֩ şé̌֨bet haֽ⁠mĕnaşė̌֜h láqĕẖ֣ẇ naẖàláţá֗⁠m mé⁠ʻé֤ber la⁠yȧrĕdé̇n֙ mizĕrá֔ẖá⁠h ʼàşěr֙ náţa֣n lá⁠he֔m mòşě֖h ʻe֥bed yĕhwáֽh׃"],[18,8,"וַ⁠יָּקֻ֥מוּ הָ⁠אֲנָשִׁ֖ים וַ⁠יֵּלֵ֑כוּ וַ⁠יְצַ֣ו יְהוֹשֻׁ֡עַ אֶת־הַ⁠הֹלְכִים֩ לִ⁠כְתֹּ֨ב אֶת־הָ⁠אָ֜רֶץ לֵ⁠אמֹ֗ר לְ֠כוּ וְ⁠הִתְהַלְּכ֨וּ בָ⁠אָ֜רֶץ וְ⁠כִתְב֤וּ אוֹתָ⁠הּ֙ וְ⁠שׁ֣וּבוּ אֵלַ֔⁠י וּ֠⁠פֹה אַשְׁלִ֨יךְ לָ⁠כֶ֥ם גּוֹרָ֛ל לִ⁠פְנֵ֥י יְהוָ֖ה בְּ⁠שִׁלֹֽה׃","wa⁠yá̇qu֥mẇ há⁠ʼànáşǐ֖ym wa⁠yé̇lé֑kẇ wa⁠yĕẕa֣w yĕhwòşǔ֡ʻa ʼeţ-ha⁠hòlĕkiym֩ li⁠kĕţò̇֨b ʼeţ-há⁠ʼá֜reẕ lé⁠ʼmò֗r lĕ֠kẇ wĕ⁠hiţĕhalĕ̇k֨ẇ bá⁠ʼá֜reẕ wĕ⁠kiţĕb֤ẇ ʼwòţá⁠ḣ֙ wĕ⁠ş֣̌ẇbẇ ʼéla֔⁠y ẇ֠⁠pòh ʼaşĕ̌li֨ykĕ lá⁠ke֥m ġwòrá֛l li⁠pĕné֥y yĕhwá֖h bĕ̇⁠şǐlòֽh׃"],[18,9,"וַ⁠יֵּלְכ֤וּ הָֽ⁠אֲנָשִׁים֙ וַ⁠יַּעַבְר֣וּ בָ⁠אָ֔רֶץ וַ⁠יִּכְתְּב֧וּ⁠הָ לֶֽ⁠עָרִ֛ים לְ⁠שִׁבְעָ֥ה חֲלָקִ֖ים עַל־סֵ֑פֶר וַ⁠יָּבֹ֧אוּ אֶל־יְהוֹשֻׁ֛עַ אֶל־הַֽ⁠מַּחֲנֶ֖ה שִׁלֹֽה׃","wa⁠yé̇lĕk֤ẇ hֽá⁠ʼànáşǐym֙ wa⁠yȧʻabĕr֣ẇ bá⁠ʼá֔reẕ wa⁠yi̇kĕţĕ̇b֧ẇ⁠há leֽ⁠ʻári֛ym lĕ⁠şǐbĕʻá֥h ẖàláqi֖ym ʻal-sé֑per wa⁠yá̇bò֧ʼẇ ʼel-yĕhwòşǔ֛ʻa ʼel-haֽ⁠mȧẖàne֖h şǐlòֽh׃"],[18,10,"וַ⁠יַּשְׁלֵךְ֩ לָ⁠הֶ֨ם יְהוֹשֻׁ֧עַ גּוֹרָ֛ל בְּ⁠שִׁלֹ֖ה לִ⁠פְנֵ֣י יְהוָ֑ה וַ⁠יְחַלֶּק־שָׁ֨ם יְהוֹשֻׁ֧עַ אֶת־הָ⁠אָ֛רֶץ לִ⁠בְנֵ֥י יִשְׂרָאֵ֖ל כְּ⁠מַחְלְקֹתָֽ⁠ם׃פ","wa⁠yȧşĕ̌lékĕ֩ lá⁠he֨m yĕhwòşǔ֧ʻa ġwòrá֛l bĕ̇⁠şǐlò֖h li⁠pĕné֣y yĕhwá֑h wa⁠yĕẖalėq-şá̌֨m yĕhwòşǔ֧ʻa ʼeţ-há⁠ʼá֛reẕ li⁠bĕné֥y yişĕ̂ráʼé֖l kĕ̇⁠maẖĕlĕqòţáֽ⁠m׃p"],[18,11,"וַ⁠יַּ֗עַל גּוֹרַ֛ל מַטֵּ֥ה בְנֵֽי־בִנְיָמִ֖ן לְ⁠מִשְׁפְּחֹתָ֑⁠ם וַ⁠יֵּצֵא֙ גְּב֣וּל גּֽוֹרָלָ֔⁠ם בֵּ֚ין בְּנֵ֣י יְהוּדָ֔ה וּ⁠בֵ֖ין בְּנֵ֥י יוֹסֵֽף׃","wa⁠yȧ֗ʻal ġwòra֛l maté֥̇h bĕnéֽy-binĕyámi֖n lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m wa⁠yé̇ẕéʼ֙ gĕ̇b֣ẇl ġֽwòrálá֔⁠m bé֚̇yn bĕ̇né֣y yĕhẇdá֔h ẇ⁠bé֖yn bĕ̇né֥y ywòséֽp׃"],[18,12,"וַ⁠יְהִ֨י לָ⁠הֶ֧ם הַ⁠גְּב֛וּל לִ⁠פְאַ֥ת צָפ֖וֹנָ⁠ה מִן־הַ⁠יַּרְדֵּ֑ן וְ⁠עָלָ֣ה הַ⁠גְּבוּל֩ אֶל־כֶּ֨תֶף יְרִיח֜וֹ מִ⁠צָּפ֗וֹן וְ⁠עָלָ֤ה בָ⁠הָר֙ יָ֔מָּ⁠ה ו⁠היה תֹּֽצְאֹתָ֔י⁠ו מִדְבַּ֖רָ⁠ה בֵּ֥ית אָֽוֶן׃","wa⁠yĕhi֨y lá⁠he֧m ha⁠gĕ̇b֛ẇl li⁠pĕʼa֥ţ ẕáp֖wòná⁠h min-ha⁠yȧrĕdé֑̇n wĕ⁠ʻálá֣h ha⁠gĕ̇bẇl֩ ʼel-kė֨ţep yĕriyẖ֜wò mi⁠ẕá̇p֗wòn wĕ⁠ʻálá֤h bá⁠hár֙ yá֔má̇⁠h w⁠hyh ţòֽ̇ẕĕʼòţá֔y⁠w midĕbȧ֖rá⁠h bé֥̇yţ ʼáֽwen׃"],[18,13,"וְ⁠עָבַר֩ מִ⁠שָּׁ֨ם הַ⁠גְּב֜וּל ל֗וּזָ⁠ה אֶל־כֶּ֤תֶף ל֨וּזָ⁠ה֙ נֶ֔גְבָּ⁠ה הִ֖יא בֵּֽית־אֵ֑ל וְ⁠יָרַ֤ד הַ⁠גְּבוּל֙ עַטְר֣וֹת אַדָּ֔ר עַל־הָ⁠הָ֕ר אֲשֶׁ֛ר מִ⁠נֶּ֥גֶב לְ⁠בֵית־חֹר֖וֹן תַּחְתּֽוֹן׃","wĕ⁠ʻábar֩ mi⁠şá̇̌֨m ha⁠gĕ̇b֜ẇl l֗ẇzá⁠h ʼel-kė֤ţep l֨ẇzá⁠h֙ ne֔gĕbá̇⁠h hi֖yʼ béֽ̇yţ-ʼé֑l wĕ⁠yára֤d ha⁠gĕ̇bẇl֙ ʻatĕr֣wòţ ʼadá̇֔r ʻal-há⁠há֕r ʼàşě֛r mi⁠nė֥geb lĕ⁠béyţ-ẖòr֖wòn ţȧẖĕţֽ̇wòn׃"],[18,14,"וְ⁠תָאַ֣ר הַ⁠גְּבוּל֩ וְ⁠נָסַ֨ב לִ⁠פְאַת־יָ֜ם נֶ֗גְבָּ⁠ה מִן־הָ⁠הָר֙ אֲשֶׁ֨ר עַל־פְּנֵ֥י בֵית־חֹרוֹן֮ נֶגְבָּ⁠ה֒ ו⁠היה תֹֽצְאֹתָ֗י⁠ו אֶל־קִרְיַת־בַּ֨עַל֙ הִ֚יא קִרְיַ֣ת יְעָרִ֔ים עִ֖יר בְּנֵ֣י יְהוּדָ֑ה זֹ֖את פְּאַת־יָֽם׃","wĕ⁠ţáʼa֣r ha⁠gĕ̇bẇl֩ wĕ⁠nása֨b li⁠pĕʼaţ-yá֜m ne֗gĕbá̇⁠h min-há⁠hár֙ ʼàşě֨r ʻal-pĕ̇né֥y béyţ-ẖòrwòn֮ negĕbá̇⁠h֒ w⁠hyh ţòֽẕĕʼòţá֗y⁠w ʼel-qirĕyaţ-bȧ֨ʻal֙ hi֚yʼ qirĕya֣ţ yĕʻári֔ym ʻi֖yr bĕ̇né֣y yĕhẇdá֑h zò֖ʼţ pĕ̇ʼaţ-yáֽm׃"],[18,15,"וּ⁠פְאַת־נֶ֕גְבָּ⁠ה מִ⁠קְצֵ֖ה קִרְיַ֣ת יְעָרִ֑ים וְ⁠יָצָ֤א הַ⁠גְּבוּל֙ יָ֔מָּ⁠ה וְ⁠יָצָ֕א אֶל־מַעְיַ֖ן מֵ֥י נֶפְתּֽוֹחַ׃","ẇ⁠pĕʼaţ-ne֕gĕbá̇⁠h mi⁠qĕẕé֖h qirĕya֣ţ yĕʻári֑ym wĕ⁠yáẕá֤ʼ ha⁠gĕ̇bẇl֙ yá֔má̇⁠h wĕ⁠yáẕá֕ʼ ʼel-maʻĕya֖n mé֥y nepĕţֽ̇wòẖa׃"],[18,16,"וְ⁠יָרַ֨ד הַ⁠גְּב֜וּל אֶל־קְצֵ֣ה הָ⁠הָ֗ר אֲשֶׁר֙ עַל־פְּנֵי֙ גֵּ֣י בֶן־הִנֹּ֔ם אֲשֶׁ֛ר בְּ⁠עֵ֥מֶק רְפָאִ֖ים צָפ֑וֹנָ⁠ה וְ⁠יָרַד֩ גֵּ֨י הִנֹּ֜ם אֶל־כֶּ֤תֶף הַ⁠יְבוּסִי֙ נֶ֔גְבָּ⁠ה וְ⁠יָרַ֖ד עֵ֥ין רֹגֵֽל׃","wĕ⁠yára֨d ha⁠gĕ̇b֜ẇl ʼel-qĕẕé֣h há⁠há֗r ʼàşěr֙ ʻal-pĕ̇néy֙ gé֣̇y ben-hinò̇֔m ʼàşě֛r bĕ̇⁠ʻé֥meq rĕpáʼi֖ym ẕáp֑wòná⁠h wĕ⁠yárad֩ gé̇֨y hinò̇֜m ʼel-kė֤ţep ha⁠yĕbẇsiy֙ ne֔gĕbá̇⁠h wĕ⁠yára֖d ʻé֥yn rògéֽl׃"],[18,17,"וְ⁠תָאַ֣ר מִ⁠צָּפ֗וֹן וְ⁠יָצָא֙ עֵ֣ין שֶׁ֔מֶשׁ וְ⁠יָצָא֙ אֶל־גְּלִיל֔וֹת אֲשֶׁר־נֹ֖כַח מַעֲלֵ֣ה אֲדֻמִּ֑ים וְ⁠יָרַ֕ד אֶ֥בֶן בֹּ֖הַן בֶּן־רְאוּבֵֽן׃","wĕ⁠ţáʼa֣r mi⁠ẕá̇p֗wòn wĕ⁠yáẕáʼ֙ ʻé֣yn şě֔meş̌ wĕ⁠yáẕáʼ֙ ʼel-gĕ̇liyl֔wòţ ʼàşěr-nò֖kaẖ maʻàlé֣h ʼàdumi֑̇ym wĕ⁠yára֕d ʼe֥ben bò֖̇han bėn-rĕʼẇbéֽn׃"],[18,18,"וְ⁠עָבַ֛ר אֶל־כֶּ֥תֶף מוּל־הָֽ⁠עֲרָבָ֖ה צָפ֑וֹנָ⁠ה וְ⁠יָרַ֖ד הָ⁠עֲרָבָֽתָ⁠ה׃","wĕ⁠ʻába֛r ʼel-kė֥ţep mẇl-hֽá⁠ʻàrábá֖h ẕáp֑wòná⁠h wĕ⁠yára֖d há⁠ʻàrábáֽţá⁠h׃"],[18,19,"וְ⁠עָבַ֨ר הַ⁠גְּב֜וּל אֶל־כֶּ֣תֶף בֵּית־חָגְלָה֮ צָפוֹנָ⁠ה֒ ו⁠היה ׀ תצאותי⁠ו הַ⁠גְּב֗וּל אֶל־לְשׁ֤וֹן יָם־הַ⁠מֶּ֨לַח֙ צָפ֔וֹנָ⁠ה אֶל־קְצֵ֥ה הַ⁠יַּרְדֵּ֖ן נֶ֑גְבָּ⁠ה זֶ֖ה גְּב֥וּל נֶֽגֶב׃","wĕ⁠ʻába֨r ha⁠gĕ̇b֜ẇl ʼel-kė֣ţep bé̇yţ-ẖágĕláh֮ ẕápwòná⁠h֒ w⁠hyh ׀ ţẕʼwţy⁠w ha⁠gĕ̇b֗ẇl ʼel-lĕş֤̌wòn yám-ha⁠mė֨laẖ֙ ẕáp֔wòná⁠h ʼel-qĕẕé֥h ha⁠yȧrĕdé֖̇n ne֑gĕbá̇⁠h ze֖h gĕ̇b֥ẇl neֽgeb׃"],[18,20,"וְ⁠הַ⁠יַּרְדֵּ֥ן יִגְבֹּל־אֹת֖⁠וֹ לִ⁠פְאַת־קֵ֑דְמָ⁠ה זֹ֡את נַחֲלַת֩ בְּנֵ֨י בִנְיָמִ֧ן לִ⁠גְבֽוּלֹתֶ֛י⁠הָ סָבִ֖יב לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","wĕ⁠ha⁠yȧrĕdé֥̇n yigĕbò̇l-ʼòţ֖⁠wò li⁠pĕʼaţ-qé֑dĕmá⁠h zò֡ʼţ naẖàlaţ֩ bĕ̇né֨y binĕyámi֧n li⁠gĕbֽẇlòţe֛y⁠há sábi֖yb lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[18,21,"וְ⁠הָי֣וּ הֶֽ⁠עָרִ֗ים לְ⁠מַטֵּ֛ה בְּנֵ֥י בִנְיָמִ֖ן לְ⁠מִשְׁפְּחֽוֹתֵי⁠הֶ֑ם יְרִיח֥וֹ וּ⁠בֵית־חָגְלָ֖ה וְ⁠עֵ֥מֶק קְצִֽיץ׃","wĕ⁠háy֣ẇ hֽe⁠ʻári֗ym lĕ⁠maté֛̇h bĕ̇né֥y binĕyámi֖n lĕ⁠mişĕ̌pĕ̇ẖֽwòţéy⁠he֑m yĕriyẖ֥wò ẇ⁠béyţ-ẖágĕlá֖h wĕ⁠ʻé֥meq qĕẕiֽyẕ׃"],[18,22,"וּ⁠בֵ֧ית הָֽעֲרָבָ֛ה וּ⁠צְמָרַ֖יִם וּ⁠בֵֽית־אֵֽל׃","ẇ⁠bé֧yţ hֽáʻàrábá֛h ẇ⁠ẕĕmára֖yim ẇ⁠béֽyţ-ʼéֽl׃"],[18,23,"וְ⁠הָ⁠עַוִּ֥ים וְ⁠הַ⁠פָּרָ֖ה וְ⁠עָפְרָֽה׃","wĕ⁠há⁠ʻawi֥̇ym wĕ⁠ha⁠pá̇rá֖h wĕ⁠ʻápĕráֽh׃"],[18,24,"וּ⁠כְפַ֧ר העמני וְ⁠הָֽ⁠עָפְנִ֖י וָ⁠גָ֑בַע עָרִ֥ים שְׁתֵּים־עֶשְׂרֵ֖ה וְ⁠חַצְרֵי⁠הֶֽן׃","ẇ⁠kĕpa֧r hʻmny wĕ⁠háֽ⁠ʻápĕni֖y wá⁠gá֑baʻ ʻári֥ym şĕ̌ţé̇ym-ʻeşĕ̂ré֖h wĕ⁠ẖaẕĕréy⁠heֽn׃"],[18,25,"גִּבְע֥וֹן וְ⁠הָֽ⁠רָמָ֖ה וּ⁠בְאֵרֽוֹת׃","gi̇bĕʻ֥wòn wĕ⁠háֽ⁠rámá֖h ẇ⁠bĕʼérֽwòţ׃"],[18,26,"וְ⁠הַ⁠מִּצְפֶּ֥ה וְ⁠הַ⁠כְּפִירָ֖ה וְ⁠הַ⁠מֹּצָֽה׃","wĕ⁠ha⁠mi̇ẕĕpė֥h wĕ⁠ha⁠kĕ̇piyrá֖h wĕ⁠ha⁠mò̇ẕáֽh׃"],[18,27,"וְ⁠רֶ֥קֶם וְ⁠יִרְפְּאֵ֖ל וְ⁠תַרְאֲלָֽה׃","wĕ⁠re֥qem wĕ⁠yirĕpĕ̇ʼé֖l wĕ⁠ţarĕʼàláֽh׃"],[18,28,"וְ⁠צֵלַ֡ע הָאֶ֜לֶף וְ⁠הַ⁠יְבוּסִ֨י הִ֤יא יְרֽוּשָׁלִַ֨ם֙ גִּבְעַ֣ת קִרְיַ֔ת עָרִ֥ים אַרְבַּֽע־עֶשְׂרֵ֖ה וְ⁠חַצְרֵי⁠הֶ֑ן זֹ֛את נַֽחֲלַ֥ת בְּנֵֽי־בִנְיָמִ֖ן לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃פ","wĕ⁠ẕéla֡ʻ háʼe֜lep wĕ⁠ha⁠yĕbẇsi֨y hi֤yʼ yĕrֽẇşá̌lia֨m֙ gi̇bĕʻa֣ţ qirĕya֔ţ ʻári֥ym ʼarĕbȧֽʻ-ʻeşĕ̂ré֖h wĕ⁠ẖaẕĕréy⁠he֑n zò֛ʼţ naֽẖàla֥ţ bĕ̇néֽy-binĕyámi֖n lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃p"],[19,1,"וַ⁠יֵּצֵ֞א הַ⁠גּוֹרָ֤ל הַ⁠שֵּׁנִי֙ לְ⁠שִׁמְע֔וֹן לְ⁠מַטֵּ֥ה בְנֵֽי־שִׁמְע֖וֹן לְ⁠מִשְׁפְּחוֹתָ֑⁠ם וַֽ⁠יְהִי֙ נַֽחֲלָתָ֔⁠ם בְּ⁠ת֖וֹךְ נַחֲלַ֥ת בְּנֵֽי־יְהוּדָֽה׃","wa⁠yé̇ẕé֞ʼ ha⁠ġwòrá֤l ha⁠şé̇̌niy֙ lĕ⁠şǐmĕʻ֔wòn lĕ⁠maté֥̇h bĕnéֽy-şǐmĕʻ֖wòn lĕ⁠mişĕ̌pĕ̇ẖwòţá֑⁠m waֽ⁠yĕhiy֙ naֽẖàláţá֔⁠m bĕ̇⁠ţ֖wòkĕ naẖàla֥ţ bĕ̇néֽy-yĕhẇdáֽh׃"],[19,2,"וַ⁠יְהִ֥י לָ⁠הֶ֖ם בְּ⁠נַֽחֲלָתָ֑⁠ם בְּאֵֽר־שֶׁ֥בַע וְ⁠שֶׁ֖בַע וּ⁠מוֹלָדָֽה׃","wa⁠yĕhi֥y lá⁠he֖m bĕ̇⁠naֽẖàláţá֑⁠m bĕ̇ʼéֽr-şě֥baʻ wĕ⁠şě֖baʻ ẇ⁠mwòládáֽh׃"],[19,3,"וַ⁠חֲצַ֥ר שׁוּעָ֛ל וּ⁠בָלָ֖ה וָ⁠עָֽצֶם׃","wa⁠ẖàẕa֥r ş̌ẇʻá֛l ẇ⁠bálá֖h wá⁠ʻáֽẕem׃"],[19,4,"וְ⁠אֶלְתּוֹלַ֥ד וּ⁠בְת֖וּל וְ⁠חָרְמָֽה׃","wĕ⁠ʼelĕţ̇wòla֥d ẇ⁠bĕţ֖ẇl wĕ⁠ẖárĕmáֽh׃"],[19,5,"וְ⁠צִֽקְלַ֥ג וּ⁠בֵית־הַמַּרְכָּב֖וֹת וַ⁠חֲצַ֥ר סוּסָֽה׃","wĕ⁠ẕiֽqĕla֥g ẇ⁠béyţ-hamȧrĕká̇b֖wòţ wa⁠ẖàẕa֥r sẇsáֽh׃"],[19,6,"וּ⁠בֵ֥ית לְבָא֖וֹת וְ⁠שָֽׁרוּחֶ֑ן עָרִ֥ים שְׁלֹשׁ־עֶשְׂרֵ֖ה וְ⁠חַצְרֵי⁠הֶֽן׃","ẇ⁠bé֥yţ lĕbáʼ֖wòţ wĕ⁠şáֽ̌rẇẖe֑n ʻári֥ym şĕ̌lòş̌-ʻeşĕ̂ré֖h wĕ⁠ẖaẕĕréy⁠heֽn׃"],[19,7,"עַ֥יִן ׀ רִמּ֖וֹן וָ⁠עֶ֣תֶר וְ⁠עָשָׁ֑ן עָרִ֥ים אַרְבַּ֖ע וְ⁠חַצְרֵי⁠הֶֽן׃","ʻa֥yin ׀ riṁ֖wòn wá⁠ʻe֣ţer wĕ⁠ʻáşá֑̌n ʻári֥ym ʼarĕbȧ֖ʻ wĕ⁠ẖaẕĕréy⁠heֽn׃"],[19,8,"וְ⁠כָל־הַֽ⁠חֲצֵרִ֗ים אֲשֶׁ֤ר סְבִיבוֹת֙ הֶֽ⁠עָרִ֣ים הָ⁠אֵ֔לֶּה עַד־בַּֽעֲלַ֥ת בְּאֵ֖ר רָ֣אמַת נֶ֑גֶב זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵֽי־שִׁמְע֖וֹן לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","wĕ⁠kál-hֽa⁠ẖàẕéri֗ym ʼàşě֤r sĕbiybwòţ֙ heֽ⁠ʻári֣ym há⁠ʼé֔lėh ʻad-bȧֽʻàla֥ţ bĕ̇ʼé֖r rá֣ʼmaţ ne֑geb zò֗ʼţ naẖàla֛ţ maté֥̇h bĕnéֽy-şǐmĕʻ֖wòn lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[19,9,"מֵ⁠חֶ֨בֶל֙ בְּנֵ֣י יְהוּדָ֔ה נַחֲלַ֖ת בְּנֵ֣י שִׁמְע֑וֹן כִּֽי־הָיָ֞ה חֵ֤לֶק בְּנֵֽי־יְהוּדָה֙ רַ֣ב מֵ⁠הֶ֔ם וַ⁠יִּנְחֲל֥וּ בְנֵֽי־שִׁמְע֖וֹן בְּ⁠ת֥וֹךְ נַחֲלָתָֽ⁠ם׃פ","mé⁠ẖe֨bel֙ bĕ̇né֣y yĕhẇdá֔h naẖàla֖ţ bĕ̇né֣y şǐmĕʻ֑wòn kiֽ̇y-háyá֞h ẖé֤leq bĕ̇néֽy-yĕhẇdáh֙ ra֣b mé⁠he֔m wa⁠yi̇nĕẖàl֥ẇ bĕnéֽy-şǐmĕʻ֖wòn bĕ̇⁠ţ֥wòkĕ naẖàláţáֽ⁠m׃p"],[19,10,"וַ⁠יַּ֨עַל֙ הַ⁠גּוֹרָ֣ל הַ⁠שְּׁלִישִׁ֔י לִ⁠בְנֵ֥י זְבוּלֻ֖ן לְ⁠מִשְׁפְּחֹתָ֑⁠ם וַ⁠יְהִ֛י גְּב֥וּל נַחֲלָתָ֖⁠ם עַד־שָׂרִֽיד׃","wa⁠yȧ֨ʻal֙ ha⁠ġwòrá֣l ha⁠şĕ̇̌liyşǐ֔y li⁠bĕné֥y zĕbẇlu֖n lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m wa⁠yĕhi֛y gĕ̇b֥ẇl naẖàláţá֖⁠m ʻad-şá̂riֽyd׃"],[19,11,"וְ⁠עָלָ֨ה גְבוּלָ֧⁠ם ׀ לַ⁠יָּ֛מָּ⁠ה וּ⁠מַרְעֲלָ֖ה וּ⁠פָגַ֣ע בְּ⁠דַבָּ֑שֶׁת וּ⁠פָגַע֙ אֶל־הַ⁠נַּ֔חַל אֲשֶׁ֖ר עַל־פְּנֵ֥י יָקְנְעָֽם׃","wĕ⁠ʻálá֨h gĕbẇlá֧⁠m ׀ la⁠yá֛̇má̇⁠h ẇ⁠marĕʻàlá֖h ẇ⁠pága֣ʻ bĕ̇⁠dabá֑̇şěţ ẇ⁠págaʻ֙ ʼel-ha⁠nȧ֔ẖal ʼàşě֖r ʻal-pĕ̇né֥y yáqĕnĕʻáֽm׃"],[19,12,"וְ⁠שָׁ֣ב מִ⁠שָּׂרִ֗יד קֵ֚דְמָ⁠ה מִזְרַ֣ח הַ⁠שֶּׁ֔מֶשׁ עַל־גְּב֥וּל כִּסְלֹ֖ת תָּבֹ֑ר וְ⁠יָצָ֥א אֶל־הַ⁠דָּֽבְרַ֖ת וְ⁠עָלָ֥ה יָפִֽיעַ׃","wĕ⁠şá֣̌b mi⁠şá̇̂ri֗yd qé֚dĕmá⁠h mizĕra֣ẖ ha⁠şė̌֔meş̌ ʻal-gĕ̇b֥ẇl ki̇sĕlò֖ţ ţá̇bò֑r wĕ⁠yáẕá֥ʼ ʼel-ha⁠dáֽ̇bĕra֖ţ wĕ⁠ʻálá֥h yápiֽyʻa׃"],[19,13,"וּ⁠מִ⁠שָּׁ֤ם עָבַר֙ קֵ֣דְמָ⁠ה מִזְרָ֔חָ⁠ה גִּתָּ֥⁠ה חֵ֖פֶר עִתָּ֣ה קָצִ֑ין וְ⁠יָצָ֛א רִמּ֥וֹן הַ⁠מְּתֹאָ֖ר הַ⁠נֵּעָֽה׃","ẇ⁠mi⁠şá֤̇̌m ʻábar֙ qé֣dĕmá⁠h mizĕrá֔ẖá⁠h gi̇ţá֥̇⁠h ẖé֖per ʻiţá֣̇h qáẕi֑yn wĕ⁠yáẕá֛ʼ riṁ֥wòn ha⁠mĕ̇ţòʼá֖r ha⁠né̇ʻáֽh׃"],[19,14,"וְ⁠נָסַ֤ב אֹת⁠וֹ֙ הַ⁠גְּב֔וּל מִ⁠צְּפ֖וֹן חַנָּתֹ֑ן וְ⁠הָיוּ֙ תֹּֽצְאֹתָ֔י⁠ו גֵּ֖י יִפְתַּח־אֵֽל׃","wĕ⁠nása֤b ʼòţ⁠wò֙ ha⁠gĕ̇b֔ẇl mi⁠ẕĕ̇p֖wòn ẖaná̇ţò֑n wĕ⁠háyẇ֙ ţòֽ̇ẕĕʼòţá֔y⁠w gé֖̇y yipĕţȧẖ-ʼéֽl׃"],[19,15,"וְ⁠קַטָּ֤ת וְ⁠נַֽהֲלָל֙ וְ⁠שִׁמְר֔וֹן וְ⁠יִדְאֲלָ֖ה וּ⁠בֵ֣ית לָ֑חֶם עָרִ֥ים שְׁתֵּים־עֶשְׂרֵ֖ה וְ⁠חַצְרֵי⁠הֶֽן׃","wĕ⁠qatá֤̇ţ wĕ⁠nֽahàlál֙ wĕ⁠şǐmĕr֔wòn wĕ⁠yidĕʼàlá֖h ẇ⁠bé֣yţ lá֑ẖem ʻári֥ym şĕ̌ţé̇ym-ʻeşĕ̂ré֖h wĕ⁠ẖaẕĕréy⁠heֽn׃"],[19,16,"זֹ֛את נַחֲלַ֥ת בְּנֵֽי־זְבוּלֻ֖ן לְ⁠מִשְׁפְּחוֹתָ֑⁠ם הֶֽ⁠עָרִ֥ים הָ⁠אֵ֖לֶּה וְ⁠חַצְרֵי⁠הֶֽן׃פ","zò֛ʼţ naẖàla֥ţ bĕ̇néֽy-zĕbẇlu֖n lĕ⁠mişĕ̌pĕ̇ẖwòţá֑⁠m heֽ⁠ʻári֥ym há⁠ʼé֖lėh wĕ⁠ẖaẕĕréy⁠heֽn׃p"],[19,17,"לְ⁠יִ֨שָּׂשכָ֔ר יָצָ֖א הַ⁠גּוֹרָ֣ל הָֽ⁠רְבִיעִ֑י לִ⁠בְנֵ֥י יִשָּׂשכָ֖ר לְ⁠מִשְׁפְּחוֹתָֽ⁠ם׃","lĕ⁠yi֨şá̇̂şká֔r yáẕá֖ʼ ha⁠ġwòrá֣l háֽ⁠rĕbiyʻi֑y li⁠bĕné֥y yişá̇̂şká֖r lĕ⁠mişĕ̌pĕ̇ẖwòţáֽ⁠m׃"],[19,18,"וַ⁠יְהִ֖י גְּבוּלָ֑⁠ם יִזְרְעֶ֥אלָ⁠ה וְ⁠הַ⁠כְּסוּלֹ֖ת וְ⁠שׁוּנֵֽם׃","wa⁠yĕhi֖y gĕ̇bẇlá֑⁠m yizĕrĕʻe֥ʼlá⁠h wĕ⁠ha⁠kĕ̇sẇlò֖ţ wĕ⁠ş̌ẇnéֽm׃"],[19,19,"וַ⁠חֲפָרַ֥יִם וְ⁠שִׁיאֹ֖ן וַ⁠אֲנָחֲרַֽת׃","wa⁠ẖàpára֥yim wĕ⁠şǐyʼò֖n wa⁠ʼànáẖàraֽţ׃"],[19,20,"וְ⁠הָֽ⁠רַבִּ֥ית וְ⁠קִשְׁי֖וֹן וָ⁠אָֽבֶץ׃","wĕ⁠háֽ⁠rabi֥̇yţ wĕ⁠qişĕ̌y֖wòn wá⁠ʼáֽbeẕ׃"],[19,21,"וְ⁠רֶ֧מֶת וְ⁠עֵין־גַּנִּ֛ים וְ⁠עֵ֥ין חַדָּ֖ה וּ⁠בֵ֥ית פַּצֵּֽץ׃","wĕ⁠re֧meţ wĕ⁠ʻéyn-gȧni֛̇ym wĕ⁠ʻé֥yn ẖadá֖̇h ẇ⁠bé֥yţ pȧẕéֽ̇ẕ׃"],[19,22,"וּ⁠פָגַע֩ הַ⁠גְּב֨וּל בְּ⁠תָב֤וֹר ו⁠שחצומ⁠ה וּ⁠בֵ֣ית שֶׁ֔מֶשׁ וְ⁠הָי֛וּ תֹּצְא֥וֹת גְּבוּלָ֖⁠ם הַ⁠יַּרְדֵּ֑ן עָרִ֥ים שֵׁשׁ־עֶשְׂרֵ֖ה וְ⁠חַצְרֵי⁠הֶֽן׃","ẇ⁠págaʻ֩ ha⁠gĕ̇b֨ẇl bĕ̇⁠ţáb֤wòr w⁠şẖẕwm⁠h ẇ⁠bé֣yţ şě֔meş̌ wĕ⁠háy֛ẇ ţò̇ẕĕʼ֥wòţ gĕ̇bẇlá֖⁠m ha⁠yȧrĕdé֑̇n ʻári֥ym şé̌ş̌-ʻeşĕ̂ré֖h wĕ⁠ẖaẕĕréy⁠heֽn׃"],[19,23,"זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵֽי־יִשָּׂשכָ֖ר לְ⁠מִשְׁפְּחֹתָ֑⁠ם הֶ⁠עָרִ֖ים וְ⁠חַצְרֵי⁠הֶֽן׃פ","zò֗ʼţ naẖàla֛ţ maté֥̇h bĕnéֽy-yişá̇̂şká֖r lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m he⁠ʻári֖ym wĕ⁠ẖaẕĕréy⁠heֽn׃p"],[19,24,"וַ⁠יֵּצֵא֙ הַ⁠גּוֹרָ֣ל הַֽ⁠חֲמִישִׁ֔י לְ⁠מַטֵּ֥ה בְנֵֽי־אָשֵׁ֖ר לְ⁠מִשְׁפְּחוֹתָֽ⁠ם׃","wa⁠yé̇ẕéʼ֙ ha⁠ġwòrá֣l haֽ⁠ẖàmiyşǐ֔y lĕ⁠maté֥̇h bĕnéֽy-ʼáşé֖̌r lĕ⁠mişĕ̌pĕ̇ẖwòţáֽ⁠m׃"],[19,25,"וַ⁠יְהִ֖י גְּבוּלָ֑⁠ם חֶלְקַ֥ת וַ⁠חֲלִ֖י וָ⁠בֶ֥טֶן וְ⁠אַכְשָֽׁף׃","wa⁠yĕhi֖y gĕ̇bẇlá֑⁠m ẖelĕqa֥ţ wa⁠ẖàli֖y wá⁠be֥ten wĕ⁠ʼakĕşáֽ̌p׃"],[19,26,"וְ⁠אַֽלַמֶּ֥לֶךְ וְ⁠עַמְעָ֖ד וּ⁠מִשְׁאָ֑ל וּ⁠פָגַ֤ע בְּ⁠כַרְמֶל֙ הַ⁠יָּ֔מָּ⁠ה וּ⁠בְ⁠שִׁיח֖וֹר לִבְנָֽת׃","wĕ⁠ʼaֽlamė֥lekĕ wĕ⁠ʻamĕʻá֖d ẇ⁠mişĕ̌ʼá֑l ẇ⁠pága֤ʻ bĕ̇⁠karĕmel֙ ha⁠yá̇֔má̇⁠h ẇ⁠bĕ⁠şǐyẖ֖wòr libĕnáֽţ׃"],[19,27,"וְ⁠שָׁ֨ב מִזְרַ֣ח הַ⁠שֶּׁמֶשׁ֮ בֵּ֣ית דָּגֹן֒ וּ⁠פָגַ֣ע בִּ֠⁠זְבֻלוּן וּ⁠בְ⁠גֵ֨י יִפְתַּח־אֵ֥ל צָפ֛וֹנָ⁠ה בֵּ֥ית הָעֵ֖מֶק וּ⁠נְעִיאֵ֑ל וְ⁠יָצָ֥א אֶל־כָּב֖וּל מִ⁠שְּׂמֹֽאל׃","wĕ⁠şá̌֨b mizĕra֣ẖ ha⁠şė̌meş֮̌ bé֣̇yţ dá̇gòn֒ ẇ⁠pága֣ʻ bi̇֠⁠zĕbulẇn ẇ⁠bĕ⁠gé֨y yipĕţȧẖ-ʼé֥l ẕáp֛wòná⁠h bé֥̇yţ háʻé֖meq ẇ⁠nĕʻiyʼé֑l wĕ⁠yáẕá֥ʼ ʼel-ká̇b֖ẇl mi⁠şĕ̇̂mòֽʼl׃"],[19,28,"וְ⁠עֶבְרֹ֥ן וּ⁠רְחֹ֖ב וְ⁠חַמּ֣וֹן וְ⁠קָנָ֑ה עַ֖ד צִיד֥וֹן רַבָּֽה׃","wĕ⁠ʻebĕrò֥n ẇ⁠rĕẖò֖b wĕ⁠ẖaṁ֣wòn wĕ⁠qáná֑h ʻa֖d ẕiyd֥wòn rabáֽ̇h׃"],[19,29,"וְ⁠שָׁ֤ב הַ⁠גְּבוּל֙ הָֽ⁠רָמָ֔ה וְ⁠עַד־עִ֖יר מִבְצַר־צֹ֑ר וְ⁠שָׁ֤ב הַ⁠גְּבוּל֙ חֹסָ֔ה ו⁠יהיו תֹצְאֹתָ֛י⁠ו הַ⁠יָּ֖מָּ⁠ה מֵ⁠חֶ֥בֶל אַכְזִֽיבָ⁠ה׃","wĕ⁠şá֤̌b ha⁠gĕ̇bẇl֙ háֽ⁠rámá֔h wĕ⁠ʻad-ʻi֖yr mibĕẕar-ẕò֑r wĕ⁠şá֤̌b ha⁠gĕ̇bẇl֙ ẖòsá֔h w⁠yhyw ţòẕĕʼòţá֛y⁠w ha⁠yá֖̇má̇⁠h mé⁠ẖe֥bel ʼakĕziֽybá⁠h׃"],[19,30,"וְ⁠עֻמָ֥ה וַ⁠אֲפֵ֖ק וּ⁠רְחֹ֑ב עָרִ֛ים עֶשְׂרִ֥ים וּ⁠שְׁתַּ֖יִם וְ⁠חַצְרֵי⁠הֶֽן׃","wĕ⁠ʻumá֥h wa⁠ʼàpé֖q ẇ⁠rĕẖò֑b ʻári֛ym ʻeşĕ̂ri֥ym ẇ⁠şĕ̌ţȧ֖yim wĕ⁠ẖaẕĕréy⁠heֽn׃"],[19,31,"זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵֽי־אָשֵׁ֖ר לְ⁠מִשְׁפְּחֹתָ֑⁠ם הֶ⁠עָרִ֥ים הָ⁠אֵ֖לֶּה וְ⁠חַצְרֵי⁠הֶֽן׃פ","zò֗ʼţ naẖàla֛ţ maté֥̇h bĕnéֽy-ʼáşé֖̌r lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m he⁠ʻári֥ym há⁠ʼé֖lėh wĕ⁠ẖaẕĕréy⁠heֽn׃p"],[19,32,"לִ⁠בְנֵ֣י נַפְתָּלִ֔י יָצָ֖א הַ⁠גּוֹרָ֣ל הַ⁠שִּׁשִּׁ֑י לִ⁠בְנֵ֥י נַפְתָּלִ֖י לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","li⁠bĕné֣y napĕţá̇li֔y yáẕá֖ʼ ha⁠ġwòrá֣l ha⁠şi̇̌şi֑̇̌y li⁠bĕné֥y napĕţá̇li֖y lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[19,33,"וַ⁠יְהִ֣י גְבוּלָ֗⁠ם מֵ⁠חֵ֨לֶף מֵֽ⁠אֵל֜וֹן בְּ⁠צַעֲנַנִּ֗ים וַ⁠אֲדָמִ֥י הַנֶּ֛קֶב וְ⁠יַבְנְאֵ֖ל עַד־לַקּ֑וּם וַ⁠יְהִ֥י תֹצְאֹתָ֖י⁠ו הַ⁠יַּרְדֵּֽן׃","wa⁠yĕhi֣y gĕbẇlá֗⁠m mé⁠ẖé֨lep méֽ⁠ʼél֜wòn bĕ̇⁠ẕaʻànani̇֗ym wa⁠ʼàdámi֥y hanė֛qeb wĕ⁠yabĕnĕʼé֖l ʻad-laq֑̇ẇm wa⁠yĕhi֥y ţòẕĕʼòţá֖y⁠w ha⁠yȧrĕdéֽ̇n׃"],[19,34,"וְ⁠שָׁ֨ב הַ⁠גְּב֥וּל יָ֨מָּ⁠ה֙ אַזְנ֣וֹת תָּב֔וֹר וְ⁠יָצָ֥א מִ⁠שָּׁ֖ם חוּקֹ֑קָ⁠ה וּ⁠פָגַ֨ע בִּ⁠זְבֻל֜וּן מִ⁠נֶּ֗גֶב וּ⁠בְ⁠אָשֵׁר֙ פָּגַ֣ע מִ⁠יָּ֔ם וּ⁠בִ֣⁠יהוּדָ֔ה הַ⁠יַּרְדֵּ֖ן מִזְרַ֥ח הַ⁠שָּֽׁמֶשׁ׃","wĕ⁠şá̌֨b ha⁠gĕ̇b֥ẇl yá֨má̇⁠h֙ ʼazĕn֣wòţ ţá̇b֔wòr wĕ⁠yáẕá֥ʼ mi⁠şá֖̇̌m ẖẇqò֑qá⁠h ẇ⁠pága֨ʻ bi̇⁠zĕbul֜ẇn mi⁠nė֗geb ẇ⁠bĕ⁠ʼáşé̌r֙ pá̇ga֣ʻ mi⁠yá̇֔m ẇ⁠bi֣⁠yhẇdá֔h ha⁠yȧrĕdé֖̇n mizĕra֥ẖ ha⁠şáֽ̇̌meş̌׃"],[19,35,"וְ⁠עָרֵ֖י מִבְצָ֑ר הַ⁠צִּדִּ֣ים צֵ֔ר וְ⁠חַמַּ֖ת רַקַּ֥ת וְ⁠כִנָּֽרֶת׃","wĕ⁠ʻáré֖y mibĕẕá֑r ha⁠ẕi̇di֣̇ym ẕé֔r wĕ⁠ẖamȧ֖ţ raqȧ֥ţ wĕ⁠kináֽ̇reţ׃"],[19,36,"וַ⁠אֲדָמָ֥ה וְ⁠הָ⁠רָמָ֖ה וְ⁠חָצֽוֹר׃","wa⁠ʼàdámá֥h wĕ⁠há⁠rámá֖h wĕ⁠ẖáẕֽwòr׃"],[19,37,"וְ⁠קֶ֥דֶשׁ וְ⁠אֶדְרֶ֖עִי וְ⁠עֵ֥ין חָצֽוֹר׃","wĕ⁠qe֥deş̌ wĕ⁠ʼedĕre֖ʻiy wĕ⁠ʻé֥yn ẖáẕֽwòr׃"],[19,38,"וְ⁠יִרְאוֹן֙ וּ⁠מִגְדַּל־אֵ֔ל חֳרֵ֥ם וּ⁠בֵית־עֲנָ֖ת וּ⁠בֵ֣ית שָׁ֑מֶשׁ עָרִ֥ים תְּשַֽׁע־עֶשְׂרֵ֖ה וְ⁠חַצְרֵי⁠הֶֽן׃","wĕ⁠yirĕʼwòn֙ ẇ⁠migĕdȧl-ʼé֔l ẖoré֥m ẇ⁠béyţ-ʻàná֖ţ ẇ⁠bé֣yţ şá֑̌meş̌ ʻári֥ym ţĕ̇şǎֽʻ-ʻeşĕ̂ré֖h wĕ⁠ẖaẕĕréy⁠heֽn׃"],[19,39,"זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵֽי־נַפְתָּלִ֖י לְ⁠מִשְׁפְּחֹתָ֑⁠ם הֶ⁠עָרִ֖ים וְ⁠חַצְרֵי⁠הֶֽן׃פ","zò֗ʼţ naẖàla֛ţ maté֥̇h bĕnéֽy-napĕţá̇li֖y lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m he⁠ʻári֖ym wĕ⁠ẖaẕĕréy⁠heֽn׃p"],[19,40,"לְ⁠מַטֵּ֥ה בְנֵי־דָ֖ן לְ⁠מִשְׁפְּחֹתָ֑⁠ם יָצָ֖א הַ⁠גּוֹרָ֥ל הַ⁠שְּׁבִיעִֽי׃","lĕ⁠maté֥̇h bĕnéy-dá֖n lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m yáẕá֖ʼ ha⁠ġwòrá֥l ha⁠şĕ̇̌biyʻiֽy׃"],[19,41,"וַ⁠יְהִ֖י גְּב֣וּל נַחֲלָתָ֑⁠ם צָרְעָ֥ה וְ⁠אֶשְׁתָּא֖וֹל וְ⁠עִ֥יר שָֽׁמֶשׁ׃","wa⁠yĕhi֖y gĕ̇b֣ẇl naẖàláţá֑⁠m ẕárĕʻá֥h wĕ⁠ʼeşĕ̌ţá̇ʼ֖wòl wĕ⁠ʻi֥yr şáֽ̌meş̌׃"],[19,42,"וְ⁠שַֽׁעֲלַבִּ֥ין וְ⁠אַיָּל֖וֹן וְ⁠יִתְלָֽה׃","wĕ⁠şǎֽʻàlabi֥̇yn wĕ⁠ʼayá̇l֖wòn wĕ⁠yiţĕláֽh׃"],[19,43,"וְ⁠אֵיל֥וֹן וְ⁠תִמְנָ֖תָ⁠ה וְ⁠עֶקְרֽוֹן׃","wĕ⁠ʼéyl֥wòn wĕ⁠ţimĕná֖ţá⁠h wĕ⁠ʻeqĕrֽwòn׃"],[19,44,"וְ⁠אֶלְתְּקֵ֥ה וְ⁠גִבְּת֖וֹן וּ⁠בַעֲלָֽת׃","wĕ⁠ʼelĕţĕ̇qé֥h wĕ⁠gibĕ̇ţ֖wòn ẇ⁠baʻàláֽţ׃"],[19,45,"וִ⁠יהֻ֥ד וּ⁠בְנֵֽי־בְרַ֖ק וְ⁠גַת־רִמּֽוֹן׃","wi⁠yhu֥d ẇ⁠bĕnéֽy-bĕra֖q wĕ⁠gaţ-riṁֽwòn׃"],[19,46,"וּ⁠מֵ֥י הַיַּרְק֖וֹן וְ⁠הָֽ⁠רַקּ֑וֹן עִֽם־הַ⁠גְּב֖וּל מ֥וּל יָפֽוֹ׃","ẇ⁠mé֥y hayȧrĕq֖wòn wĕ⁠háֽ⁠raq֑̇wòn ʻiֽm-ha⁠gĕ̇b֖ẇl m֥ẇl yápֽwò׃"],[19,47,"וַ⁠יֵּצֵ֥א גְבוּל־בְּנֵי־דָ֖ן מֵ⁠הֶ֑ם וַ⁠יַּעֲל֣וּ בְנֵֽי־דָ֠ן וַ⁠יִּלָּחֲמ֨וּ עִם־לֶ֜שֶׁם וַ⁠יִּלְכְּד֥וּ אוֹתָ֣⁠הּ ׀ וַ⁠יַּכּ֧וּ אוֹתָ֣⁠הּ לְ⁠פִי־חֶ֗רֶב וַ⁠יִּֽרְשׁ֤וּ אוֹתָ⁠הּ֙ וַ⁠יֵּ֣שְׁבוּ בָ֔⁠הּ וַ⁠יִּקְרְא֤וּ לְ⁠לֶ֨שֶׁם֙ דָּ֔ן כְּ⁠שֵׁ֖ם דָּ֥ן אֲבִי⁠הֶֽם׃","wa⁠yé̇ẕé֥ʼ gĕbẇl-bĕ̇néy-dá֖n mé⁠he֑m wa⁠yȧʻàl֣ẇ bĕnéֽy-dá֠n wa⁠yi̇lá̇ẖàm֨ẇ ʻim-le֜şěm wa⁠yi̇lĕkĕ̇d֥ẇ ʼwòţá֣⁠ḣ ׀ wa⁠yȧk֧̇ẇ ʼwòţá֣⁠ḣ lĕ⁠piy-ẖe֗reb wa⁠yiֽ̇rĕş֤̌ẇ ʼwòţá⁠ḣ֙ wa⁠yé֣̇şĕ̌bẇ bá֔⁠ḣ wa⁠yi̇qĕrĕʼ֤ẇ lĕ⁠le֨şěm֙ dá̇֔n kĕ̇⁠şé֖̌m dá֥̇n ʼàbiy⁠heֽm׃"],[19,48,"זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵי־דָ֖ן לְ⁠מִשְׁפְּחֹתָ֑⁠ם הֶֽ⁠עָרִ֥ים הָ⁠אֵ֖לֶּה וְ⁠חַצְרֵי⁠הֶֽן׃פ","zò֗ʼţ naẖàla֛ţ maté֥̇h bĕnéy-dá֖n lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m heֽ⁠ʻári֥ym há⁠ʼé֖lėh wĕ⁠ẖaẕĕréy⁠heֽn׃p"],[19,49,"וַ⁠יְכַלּ֥וּ לִ⁠נְחֹל־אֶת־הָ⁠אָ֖רֶץ לִ⁠גְבֽוּלֹתֶ֑י⁠הָ וַ⁠יִּתְּנ֨וּ בְנֵי־יִשְׂרָאֵ֧ל נַחֲלָ֛ה לִ⁠יהוֹשֻׁ֥עַ בִּן־נ֖וּן בְּ⁠תוֹכָֽ⁠ם׃","wa⁠yĕkal֥̇ẇ li⁠nĕẖòl-ʼeţ-há⁠ʼá֖reẕ li⁠gĕbֽẇlòţe֑y⁠há wa⁠yi̇ţĕ̇n֨ẇ bĕnéy-yişĕ̂ráʼé֧l naẖàlá֛h li⁠yhwòşǔ֥ʻa bi̇n-n֖ẇn bĕ̇⁠ţwòkáֽ⁠m׃"],[19,50,"עַל־פִּ֨י יְהוָ֜ה נָ֣תְנוּ ל֗⁠וֹ אֶת־הָ⁠עִיר֙ אֲשֶׁ֣ר שָׁאָ֔ל אֶת־תִּמְנַת־סֶ֖רַח בְּ⁠הַ֣ר אֶפְרָ֑יִם וַ⁠יִּבְנֶ֥ה אֶת־הָ⁠עִ֖יר וַ⁠יֵּ֥שֶׁב בָּֽ⁠הּ׃","ʻal-pi̇֨y yĕhwá֜h ná֣ţĕnẇ l֗⁠wò ʼeţ-há⁠ʻiyr֙ ʼàşě֣r şá̌ʼá֔l ʼeţ-ţi̇mĕnaţ-se֖raẖ bĕ̇⁠ha֣r ʼepĕrá֑yim wa⁠yi̇bĕne֥h ʼeţ-há⁠ʻi֖yr wa⁠yé֥̇şěb báֽ̇⁠ḣ׃"],[19,51,"אֵ֣לֶּה הַ⁠נְּחָלֹ֡ת אֲשֶׁ֣ר נִחֲל֣וּ אֶלְעָזָ֣ר הַ⁠כֹּהֵ֣ן ׀ וִ⁠יהוֹשֻׁ֪עַ בִּן־נ֟וּן וְ⁠רָאשֵׁ֣י הָֽ⁠אָב֣וֹת לְ⁠מַטּוֹת֩ בְּנֵי־יִשְׂרָאֵ֨ל ׀ בְּ⁠גוֹרָ֤ל ׀ בְּ⁠שִׁלֹה֙ לִ⁠פְנֵ֣י יְהוָ֔ה פֶּ֖תַח אֹ֣הֶל מוֹעֵ֑ד וַ⁠יְכַלּ֕וּ מֵֽ⁠חַלֵּ֖ק אֶת־הָ⁠אָֽרֶץ׃פ","ʼé֣lėh ha⁠nĕ̇ẖálò֡ţ ʼàşě֣r niẖàl֣ẇ ʼelĕʻázá֣r ha⁠kò̇hé֣n ׀ wi⁠yhwòşǔ֪ʻa bi̇n-n֟ẇn wĕ⁠ráʼşé֣̌y háֽ⁠ʼáb֣wòţ lĕ⁠maṫwòţ֩ bĕ̇néy-yişĕ̂ráʼé֨l ׀ bĕ̇⁠gwòrá֤l ׀ bĕ̇⁠şǐlòh֙ li⁠pĕné֣y yĕhwá֔h pė֖ţaẖ ʼò֣hel mwòʻé֑d wa⁠yĕkal̇֕ẇ méֽ⁠ẖalé֖̇q ʼeţ-há⁠ʼáֽreẕ׃p"],[20,1,"וַ⁠יְדַבֵּ֣ר יְהוָ֔ה אֶל־יְהוֹשֻׁ֖עַ לֵ⁠אמֹֽר׃","wa⁠yĕdabé֣̇r yĕhwá֔h ʼel-yĕhwòşǔ֖ʻa lé⁠ʼmòֽr׃"],[20,2,"דַּבֵּ֛ר אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר תְּנ֤וּ לָ⁠כֶם֙ אֶת־עָרֵ֣י הַ⁠מִּקְלָ֔ט אֲשֶׁר־דִּבַּ֥רְתִּי אֲלֵי⁠כֶ֖ם בְּ⁠יַד־מֹשֶֽׁה׃","dȧbé֛̇r ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r ţĕ̇n֤ẇ lá⁠kem֙ ʼeţ-ʻáré֣y ha⁠mi̇qĕlá֔t ʼàşěr-di̇bȧ֥rĕţi̇y ʼàléy⁠ke֖m bĕ̇⁠yad-mòşěֽh׃"],[20,3,"לָ⁠נ֥וּס שָׁ֨מָּ⁠ה֙ רוֹצֵ֔חַ מַכֵּה־נֶ֥פֶשׁ בִּ⁠שְׁגָגָ֖ה בִּ⁠בְלִי־דָ֑עַת וְ⁠הָי֤וּ לָ⁠כֶם֙ לְ⁠מִקְלָ֔ט מִ⁠גֹּאֵ֖ל הַ⁠דָּֽם׃","lá⁠n֥ẇs şá̌֨má̇⁠h֙ rwòẕé֔ẖa maké̇h-ne֥peş̌ bi̇⁠şĕ̌gágá֖h bi̇⁠bĕliy-dá֑ʻaţ wĕ⁠háy֤ẇ lá⁠kem֙ lĕ⁠miqĕlá֔t mi⁠gò̇ʼé֖l ha⁠dáֽ̇m׃"],[20,4,"וְ⁠נָ֞ס אֶל־אַחַ֣ת ׀ מֵ⁠הֶ⁠עָרִ֣ים הָ⁠אֵ֗לֶּה וְ⁠עָמַד֙ פֶּ֚תַח שַׁ֣עַר הָ⁠עִ֔יר וְ⁠דִבֶּ֛ר בְּ⁠אָזְנֵ֛י זִקְנֵ֥י־הָ⁠עִֽיר הַ⁠הִ֖יא אֶת־דְּבָרָ֑י⁠ו וְ⁠אָסְפ֨וּ אֹת֤⁠וֹ הָ⁠עִ֨ירָ⁠ה֙ אֲלֵי⁠הֶ֔ם וְ⁠נָתְנוּ־ל֥⁠וֹ מָק֖וֹם וְ⁠יָשַׁ֥ב עִמָּֽ⁠ם׃","wĕ⁠ná֞s ʼel-ʼaẖa֣ţ ׀ mé⁠he⁠ʻári֣ym há⁠ʼé֗lėh wĕ⁠ʻámad֙ pė֚ţaẖ şǎ֣ʻar há⁠ʻi֔yr wĕ⁠dibė֛r bĕ̇⁠ʼázĕné֛y ziqĕné֥y-há⁠ʻiֽyr ha⁠hi֖yʼ ʼeţ-dĕ̇bárá֑y⁠w wĕ⁠ʼásĕp֨ẇ ʼòţ֤⁠wò há⁠ʻi֨yrá⁠h֙ ʼàléy⁠he֔m wĕ⁠náţĕnẇ-l֥⁠wò máq֖wòm wĕ⁠yáşǎ֥b ʻimáֽ̇⁠m׃"],[20,5,"וְ⁠כִ֨י יִרְדֹּ֜ף גֹּאֵ֤ל הַ⁠דָּם֙ אַֽחֲרָ֔י⁠ו וְ⁠לֹֽא־יַסְגִּ֥רוּ אֶת־הָ⁠רֹצֵ֖חַ בְּ⁠יָד֑⁠וֹ כִּ֤י בִ⁠בְלִי־דַ֨עַת֙ הִכָּ֣ה אֶת־רֵעֵ֔⁠הוּ וְ⁠לֹֽא־שֹׂנֵ֥א ה֛וּא ל֖⁠וֹ מִ⁠תְּמ֥וֹל שִׁלְשֽׁוֹם׃","wĕ⁠ki֨y yirĕdò̇֜p gò̇ʼé֤l ha⁠dá̇m֙ ʼaֽẖàrá֔y⁠w wĕ⁠lòֽʼ-yasĕgi֥̇rẇ ʼeţ-há⁠ròẕé֖ẖa bĕ̇⁠yád֑⁠wò ki֤̇y bi⁠bĕliy-da֨ʻaţ֙ hiká֣̇h ʼeţ-réʻé֔⁠hẇ wĕ⁠lòֽʼ-şò̂né֥ʼ h֛ẇʼ l֖⁠wò mi⁠ţĕ̇m֥wòl şǐlĕşֽ̌wòm׃"],[20,6,"וְ⁠יָשַׁ֣ב ׀ בָּ⁠עִ֣יר הַ⁠הִ֗יא עַד־עָמְד֞⁠וֹ לִ⁠פְנֵ֤י הָֽ⁠עֵדָה֙ לַ⁠מִּשְׁפָּ֔ט עַד־מוֹת֙ הַ⁠כֹּהֵ֣ן הַ⁠גָּד֔וֹל אֲשֶׁ֥ר יִהְיֶ֖ה בַּ⁠יָּמִ֣ים הָ⁠הֵ֑ם אָ֣ז ׀ יָשׁ֣וּב הָ⁠רוֹצֵ֗חַ וּ⁠בָ֤א אֶל־עִיר⁠וֹ֙ וְ⁠אֶל־בֵּית֔⁠וֹ אֶל־הָ⁠עִ֖יר אֲשֶׁר־נָ֥ס מִ⁠שָּֽׁם׃","wĕ⁠yáşǎ֣b ׀ bá̇⁠ʻi֣yr ha⁠hi֗yʼ ʻad-ʻámĕd֞⁠wò li⁠pĕné֤y háֽ⁠ʻédáh֙ la⁠mi̇şĕ̌pá̇֔t ʻad-mwòţ֙ ha⁠kò̇hé֣n ha⁠gá̇d֔wòl ʼàşě֥r yihĕye֖h bȧ⁠yá̇mi֣ym há⁠hé֑m ʼá֣z ׀ yáş֣̌ẇb há⁠rwòẕé֗ẖa ẇ⁠bá֤ʼ ʼel-ʻiyr⁠wò֙ wĕ⁠ʼel-bé̇yţ֔⁠wò ʼel-há⁠ʻi֖yr ʼàşěr-ná֥s mi⁠şáֽ̇̌m׃"],[20,7,"וַ⁠יַּקְדִּ֜שׁוּ אֶת־קֶ֤דֶשׁ בַּ⁠גָּלִיל֙ בְּ⁠הַ֣ר נַפְתָּלִ֔י וְ⁠אֶת־שְׁכֶ֖ם בְּ⁠הַ֣ר אֶפְרָ֑יִם וְ⁠אֶת־קִרְיַ֥ת אַרְבַּ֛ע הִ֥יא חֶבְר֖וֹן בְּ⁠הַ֥ר יְהוּדָֽה׃","wa⁠yȧqĕdi̇֜ş̌ẇ ʼeţ-qe֤deş̌ bȧ⁠gá̇liyl֙ bĕ̇⁠ha֣r napĕţá̇li֔y wĕ⁠ʼeţ-şĕ̌ke֖m bĕ̇⁠ha֣r ʼepĕrá֑yim wĕ⁠ʼeţ-qirĕya֥ţ ʼarĕbȧ֛ʻ hi֥yʼ ẖebĕr֖wòn bĕ̇⁠ha֥r yĕhẇdáֽh׃"],[20,8,"וּ⁠מֵ⁠עֵ֜בֶר לְ⁠יַרְדֵּ֤ן יְרִיחוֹ֙ מִזְרָ֔חָ⁠ה נָתְנ֞וּ אֶת־בֶּ֧צֶר בַּ⁠מִּדְבָּ֛ר בַּ⁠מִּישֹׁ֖ר מִ⁠מַּטֵּ֣ה רְאוּבֵ֑ן וְ⁠אֶת־רָאמֹ֤ת בַּ⁠גִּלְעָד֙ מִ⁠מַּטֵּה־גָ֔ד וְ⁠אֶת־גלון בַּ⁠בָּשָׁ֖ן מִ⁠מַּטֵּ֥ה מְנַשֶּֽׁה׃","ẇ⁠mé⁠ʻé֜ber lĕ⁠yarĕdé֤̇n yĕriyẖwò֙ mizĕrá֔ẖá⁠h náţĕn֞ẇ ʼeţ-bė֧ẕer bȧ⁠mi̇dĕbá֛̇r bȧ⁠mi̇yşò֖̌r mi⁠mȧté֣̇h rĕʼẇbé֑n wĕ⁠ʼeţ-ráʼmò֤ţ bȧ⁠gi̇lĕʻád֙ mi⁠mȧté̇h-gá֔d wĕ⁠ʼeţ-glwn bȧ⁠bá̇şá֖̌n mi⁠mȧté֥̇h mĕnaşėֽ̌h׃"],[20,9,"אֵ֣לֶּה הָיוּ֩ עָרֵ֨י הַ⁠מּֽוּעָדָ֜ה לְ⁠כֹ֣ל ׀ בְּנֵ֣י יִשְׂרָאֵ֗ל וְ⁠לַ⁠גֵּר֙ הַ⁠גָּ֣ר בְּ⁠תוֹכָ֔⁠ם לָ⁠נ֣וּס שָׁ֔מָּ⁠ה כָּל־מַכֵּה־נֶ֖פֶשׁ בִּ⁠שְׁגָגָ֑ה וְ⁠לֹ֣א יָמ֗וּת בְּ⁠יַד֙ גֹּאֵ֣ל הַ⁠דָּ֔ם עַד־עָמְד֖⁠וֹ לִ⁠פְנֵ֥י הָ⁠עֵדָֽה׃פ","ʼé֣lėh háyẇ֩ ʻáré֨y ha⁠ṁֽẇʻádá֜h lĕ⁠kò֣l ׀ bĕ̇né֣y yişĕ̂ráʼé֗l wĕ⁠la⁠gé̇r֙ ha⁠gá֣̇r bĕ̇⁠ţwòká֔⁠m lá⁠n֣ẇs şá̌֔má̇⁠h ká̇l-maké̇h-ne֖peş̌ bi̇⁠şĕ̌gágá֑h wĕ⁠lò֣ʼ yám֗ẇţ bĕ̇⁠yad֙ gò̇ʼé֣l ha⁠dá̇֔m ʻad-ʻámĕd֖⁠wò li⁠pĕné֥y há⁠ʻédáֽh׃p"],[21,1,"וַֽ⁠יִּגְּשׁ֗וּ רָאשֵׁי֙ אֲב֣וֹת הַ⁠לְוִיִּ֔ם אֶל־אֶלְעָזָר֙ הַ⁠כֹּהֵ֔ן וְ⁠אֶל־יְהוֹשֻׁ֖עַ בִּן־נ֑וּן וְ⁠אֶל־רָאשֵׁ֛י אֲב֥וֹת הַ⁠מַּטּ֖וֹת לִ⁠בְנֵ֥י יִשְׂרָאֵֽל׃","waֽ⁠yi̇gĕ̇ş̌֗ẇ ráʼşé̌y֙ ʼàb֣wòţ ha⁠lĕwiyi̇֔m ʼel-ʼelĕʻázár֙ ha⁠kò̇hé֔n wĕ⁠ʼel-yĕhwòşǔ֖ʻa bi̇n-n֑ẇn wĕ⁠ʼel-ráʼşé֛̌y ʼàb֥wòţ ha⁠mȧṫ֖wòţ li⁠bĕné֥y yişĕ̂ráʼéֽl׃"],[21,2,"וַ⁠יְדַבְּר֨וּ אֲלֵי⁠הֶ֜ם בְּ⁠שִׁלֹ֗ה בְּ⁠אֶ֤רֶץ כְּנַ֨עַן֙ לֵ⁠אמֹ֔ר יְהוָה֙ צִוָּ֣ה בְ⁠יַד־מֹשֶׁ֔ה לָֽ⁠תֶת־לָ֥⁠נוּ עָרִ֖ים לָ⁠שָׁ֑בֶת וּ⁠מִגְרְשֵׁי⁠הֶ֖ן לִ⁠בְהֶמְתֵּֽ⁠נוּ׃","wa⁠yĕdabĕ̇r֨ẇ ʼàléy⁠he֜m bĕ̇⁠şǐlò֗h bĕ̇⁠ʼe֤reẕ kĕ̇na֨ʻan֙ lé⁠ʼmò֔r yĕhwáh֙ ẕiwá֣̇h bĕ⁠yad-mòşě֔h láֽ⁠ţeţ-lá֥⁠nẇ ʻári֖ym lá⁠şá֑̌beţ ẇ⁠migĕrĕşé̌y⁠he֖n li⁠bĕhemĕţéֽ̇⁠nẇ׃"],[21,3,"וַ⁠יִּתְּנ֨וּ בְנֵי־יִשְׂרָאֵ֧ל לַ⁠לְוִיִּ֛ם מִ⁠נַּחֲלָתָ֖⁠ם אֶל־פִּ֣י יְהוָ֑ה אֶת־הֶ⁠עָרִ֥ים הָ⁠אֵ֖לֶּה וְ⁠אֶת־מִגְרְשֵׁי⁠הֶֽן׃","wa⁠yi̇ţĕ̇n֨ẇ bĕnéy-yişĕ̂ráʼé֧l la⁠lĕwiyi֛̇m mi⁠nȧẖàláţá֖⁠m ʼel-pi֣̇y yĕhwá֑h ʼeţ-he⁠ʻári֥ym há⁠ʼé֖lėh wĕ⁠ʼeţ-migĕrĕşé̌y⁠heֽn׃"],[21,4,"וַ⁠יֵּצֵ֥א הַ⁠גּוֹרָ֖ל לְ⁠מִשְׁפְּחֹ֣ת הַ⁠קְּהָתִ֑י וַ⁠יְהִ֡י לִ⁠בְנֵי֩ אַהֲרֹ֨ן הַ⁠כֹּהֵ֜ן מִן־הַ⁠לְוִיִּ֗ם מִ⁠מַּטֵּ֣ה יְ֠הוּדָה וּ⁠מִ⁠מַּטֵּ֨ה הַ⁠שִּׁמְעֹנִ֜י וּ⁠מִ⁠מַּטֵּ֤ה בִנְיָמִן֙ בַּ⁠גּוֹרָ֔ל עָרִ֖ים שְׁלֹ֥שׁ עֶשְׂרֵֽה׃ס","wa⁠yé̇ẕé֥ʼ ha⁠ġwòrá֖l lĕ⁠mişĕ̌pĕ̇ẖò֣ţ ha⁠qĕ̇háţi֑y wa⁠yĕhi֡y li⁠bĕnéy֩ ʼahàrò֨n ha⁠kò̇hé֜n min-ha⁠lĕwiyi̇֗m mi⁠mȧté֣̇h yĕ֠hẇdáh ẇ⁠mi⁠mȧté̇֨h ha⁠şi̇̌mĕʻòni֜y ẇ⁠mi⁠mȧté֤̇h binĕyámin֙ bȧ⁠ġwòrá֔l ʻári֖ym şĕ̌lò֥ş̌ ʻeşĕ̂réֽh׃s"],[21,5,"וְ⁠לִ⁠בְנֵ֨י קְהָ֜ת הַ⁠נּוֹתָרִ֗ים מִ⁠מִּשְׁפְּחֹ֣ת מַטֵּֽה־אֶ֠פְרַיִם וּֽ⁠מִ⁠מַּטֵּה־דָ֞ן וּ⁠מֵ⁠חֲצִ֨י מַטֵּ֧ה מְנַשֶּׁ֛ה בַּ⁠גּוֹרָ֖ל עָרִ֥ים עָֽשֶׂר׃ס","wĕ⁠li⁠bĕné֨y qĕhá֜ţ ha⁠ṅwòţári֗ym mi⁠mi̇şĕ̌pĕ̇ẖò֣ţ matéֽ̇h-ʼe֠pĕrayim ẇֽ⁠mi⁠mȧté̇h-dá֞n ẇ⁠mé⁠ẖàẕi֨y maté֧̇h mĕnaşė֛̌h bȧ⁠ġwòrá֖l ʻári֥ym ʻáֽşêr׃s"],[21,6,"וְ⁠לִ⁠בְנֵ֣י גֵרְשׁ֗וֹן מִ⁠מִּשְׁפְּח֣וֹת מַטֵּֽה־יִשָּׂשכָ֣ר וּ⁠מִ⁠מַּטֵּֽה־אָ֠שֵׁר וּ⁠מִ⁠מַּטֵּ֨ה נַפְתָּלִ֜י וּ֠⁠מֵ⁠חֲצִי מַטֵּ֨ה מְנַשֶּׁ֤ה בַ⁠בָּשָׁן֙ בַּ⁠גּוֹרָ֔ל עָרִ֖ים שְׁלֹ֥שׁ עֶשְׂרֵֽה׃ס","wĕ⁠li⁠bĕné֣y gérĕş̌֗wòn mi⁠mi̇şĕ̌pĕ̇ẖ֣wòţ matéֽ̇h-yişá̇̂şká֣r ẇ⁠mi⁠mȧtéֽ̇h-ʼá֠şé̌r ẇ⁠mi⁠mȧté̇֨h napĕţá̇li֜y ẇ֠⁠mé⁠ẖàẕiy maté̇֨h mĕnaşė֤̌h ba⁠bá̇şá̌n֙ bȧ⁠ġwòrá֔l ʻári֖ym şĕ̌lò֥ş̌ ʻeşĕ̂réֽh׃s"],[21,7,"לִ⁠בְנֵ֨י מְרָרִ֜י לְ⁠מִשְׁפְּחֹתָ֗⁠ם מִ⁠מַּטֵּ֨ה רְאוּבֵ֤ן וּ⁠מִ⁠מַּטֵּה־גָד֙ וּ⁠מִ⁠מַּטֵּ֣ה זְבוּלֻ֔ן עָרִ֖ים שְׁתֵּ֥ים עֶשְׂרֵֽה׃","li⁠bĕné֨y mĕrári֜y lĕ⁠mişĕ̌pĕ̇ẖòţá֗⁠m mi⁠mȧté̇֨h rĕʼẇbé֤n ẇ⁠mi⁠mȧté̇h-gád֙ ẇ⁠mi⁠mȧté֣̇h zĕbẇlu֔n ʻári֖ym şĕ̌ţé֥̇ym ʻeşĕ̂réֽh׃"],[21,8,"וַ⁠יִּתְּנ֤וּ בְנֵֽי־יִשְׂרָאֵל֙ לַ⁠לְוִיִּ֔ם אֶת־הֶ⁠עָרִ֥ים הָ⁠אֵ֖לֶּה וְ⁠אֶת־מִגְרְשֵׁי⁠הֶ֑ן כַּ⁠אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה בְּ⁠יַד־מֹשֶׁ֖ה בַּ⁠גּוֹרָֽל׃פ","wa⁠yi̇ţĕ̇n֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ la⁠lĕwiyi̇֔m ʼeţ-he⁠ʻári֥ym há⁠ʼé֖lėh wĕ⁠ʼeţ-migĕrĕşé̌y⁠he֑n kȧ⁠ʼàşě֨r ẕiwá֧̇h yĕhwá֛h bĕ̇⁠yad-mòşě֖h bȧ⁠ġwòráֽl׃p"],[21,9,"וַֽ⁠יִּתְּנ֗וּ מִ⁠מַּטֵּה֙ בְּנֵ֣י יְהוּדָ֔ה וּ⁠מִ⁠מַּטֵּ֖ה בְּנֵ֣י שִׁמְע֑וֹן אֵ֚ת הֶֽ⁠עָרִ֣ים הָ⁠אֵ֔לֶּה אֲשֶׁר־יִקְרָ֥א אֶתְ⁠הֶ֖ן בְּ⁠שֵֽׁם׃","wֽa⁠yi̇ţĕ̇n֗ẇ mi⁠mȧté̇h֙ bĕ̇né֣y yĕhẇdá֔h ẇ⁠mi⁠mȧté֖̇h bĕ̇né֣y şǐmĕʻ֑wòn ʼé֚ţ heֽ⁠ʻári֣ym há⁠ʼé֔lėh ʼàşěr-yiqĕrá֥ʼ ʼeţĕ⁠he֖n bĕ̇⁠şéֽ̌m׃"],[21,10,"וַֽ⁠יְהִי֙ לִ⁠בְנֵ֣י אַהֲרֹ֔ן מִ⁠מִּשְׁפְּח֥וֹת הַ⁠קְּהָתִ֖י מִ⁠בְּנֵ֣י לֵוִ֑י כִּ֥י לָ⁠הֶ֛ם הָיָ֥ה הַ⁠גּוֹרָ֖ל רִיאשֹׁנָֽה׃","wֽa⁠yĕhiy֙ li⁠bĕné֣y ʼahàrò֔n mi⁠mi̇şĕ̌pĕ̇ẖ֥wòţ ha⁠qĕ̇háţi֖y mi⁠bĕ̇né֣y léwi֑y ki֥̇y lá⁠he֛m háyá֥h ha⁠ġwòrá֖l riyʼşò̌náֽh׃"],[21,11,"וַ⁠יִּתְּנ֨וּ לָ⁠הֶ֜ם אֶת־קִרְיַת֩ אַרְבַּ֨ע אֲבִ֧י הָֽ⁠עֲנ֛וֹק הִ֥יא חֶבְר֖וֹן בְּ⁠הַ֣ר יְהוּדָ֑ה וְ⁠אֶת־מִגְרָשֶׁ֖⁠הָ סְבִיבֹתֶֽי⁠הָ׃","wa⁠yi̇ţĕ̇n֨ẇ lá⁠he֜m ʼeţ-qirĕyaţ֩ ʼarĕbȧ֨ʻ ʼàbi֧y háֽ⁠ʻàn֛wòq hi֥yʼ ẖebĕr֖wòn bĕ̇⁠ha֣r yĕhẇdá֑h wĕ⁠ʼeţ-migĕráşě֖⁠há sĕbiybòţeֽy⁠há׃"],[21,12,"וְ⁠אֶת־שְׂדֵ֥ה הָ⁠עִ֖יר וְ⁠אֶת־חֲצֵרֶ֑י⁠הָ נָֽתְנ֛וּ לְ⁠כָלֵ֥ב בֶּן־יְפֻנֶּ֖ה בַּ⁠אֲחֻזָּתֽ⁠וֹ׃ס","wĕ⁠ʼeţ-şĕ̂dé֥h há⁠ʻi֖yr wĕ⁠ʼeţ-ẖàẕére֑y⁠há náֽţĕn֛ẇ lĕ⁠kálé֥b bėn-yĕpunė֖h bȧ⁠ʼàẖuzá̇ţֽ⁠wò׃s"],[21,13,"וְ⁠לִ⁠בְנֵ֣י ׀ אַהֲרֹ֣ן הַ⁠כֹּהֵ֗ן נָֽתְנוּ֙ אֶת־עִיר֙ מִקְלַ֣ט הָ⁠רֹצֵ֔חַ אֶת־חֶבְר֖וֹן וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ וְ⁠אֶת־לִבְנָ֖ה וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","wĕ⁠li⁠bĕné֣y ׀ ʼahàrò֣n ha⁠kò̇hé֗n náֽţĕnẇ֙ ʼeţ-ʻiyr֙ miqĕla֣t há⁠ròẕé֔ẖa ʼeţ-ẖebĕr֖wòn wĕ⁠ʼeţ-migĕráşě֑⁠há wĕ⁠ʼeţ-libĕná֖h wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,14,"וְ⁠אֶת־יַתִּר֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ וְ⁠אֶת־אֶשְׁתְּמֹ֖עַ וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","wĕ⁠ʼeţ-yaţi̇r֙ wĕ⁠ʼeţ-migĕráşě֔⁠há wĕ⁠ʼeţ-ʼeşĕ̌ţĕ̇mò֖ʻa wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,15,"וְ⁠אֶת־חֹלֹן֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ וְ⁠אֶת־דְּבִ֖ר וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","wĕ⁠ʼeţ-ẖòlòn֙ wĕ⁠ʼeţ-migĕráşě֔⁠há wĕ⁠ʼeţ-dĕ̇bi֖r wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,16,"וְ⁠אֶת־עַ֣יִן וְ⁠אֶת־מִגְרָשֶׁ֗⁠הָ וְ⁠אֶת־יֻטָּה֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ אֶת־בֵּ֥ית שֶׁ֖מֶשׁ וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֣ים תֵּ֔שַׁע מֵ⁠אֵ֕ת שְׁנֵ֥י הַ⁠שְּׁבָטִ֖ים הָ⁠אֵֽלֶּה׃פ","wĕ⁠ʼeţ-ʻa֣yin wĕ⁠ʼeţ-migĕráşě֗⁠há wĕ⁠ʼeţ-yutá̇h֙ wĕ⁠ʼeţ-migĕráşě֔⁠há ʼeţ-bé֥̇yţ şě֖meş̌ wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֣ym ţé̇֔şǎʻ mé⁠ʼé֕ţ şĕ̌né֥y ha⁠şĕ̇̌báti֖ym há⁠ʼéֽlėh׃p"],[21,17,"וּ⁠מִ⁠מַּטֵּ֣ה בִנְיָמִ֔ן אֶת־גִּבְע֖וֹן וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ אֶת־גֶּ֖בַע וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","ẇ⁠mi⁠mȧté֣̇h binĕyámi֔n ʼeţ-gi̇bĕʻ֖wòn wĕ⁠ʼeţ-migĕráşě֑⁠há ʼeţ-gė֖baʻ wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,18,"אֶת־עֲנָתוֹת֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ וְ⁠אֶת־עַלְמ֖וֹן וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים אַרְבַּֽע׃","ʼeţ-ʻànáţwòţ֙ wĕ⁠ʼeţ-migĕráşě֔⁠há wĕ⁠ʼeţ-ʻalĕm֖wòn wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym ʼarĕbȧֽʻ׃"],[21,19,"כָּל־עָרֵ֥י בְנֵֽי־אַהֲרֹ֖ן הַ⁠כֹּֽהֲנִ֑ים שְׁלֹשׁ־עֶשְׂרֵ֥ה עָרִ֖ים וּ⁠מִגְרְשֵׁי⁠הֶֽן׃ס","ká̇l-ʻáré֥y bĕnéֽy-ʼahàrò֖n ha⁠kòֽ̇hàni֑ym şĕ̌lòş̌-ʻeşĕ̂ré֥h ʻári֖ym ẇ⁠migĕrĕşé̌y⁠heֽn׃s"],[21,20,"וּ⁠לְ⁠מִשְׁפְּח֤וֹת בְּנֵֽי־קְהָת֙ הַ⁠לְוִיִּ֔ם הַ⁠נּוֹתָרִ֖ים מִ⁠בְּנֵ֣י קְהָ֑ת וַֽ⁠יְהִי֙ עָרֵ֣י גֽוֹרָלָ֔⁠ם מִ⁠מַּטֵּ֖ה אֶפְרָֽיִם׃","ẇ⁠lĕ⁠mişĕ̌pĕ̇ẖ֤wòţ bĕ̇néֽy-qĕháţ֙ ha⁠lĕwiyi̇֔m ha⁠ṅwòţári֖ym mi⁠bĕ̇né֣y qĕhá֑ţ waֽ⁠yĕhiy֙ ʻáré֣y gֽwòrálá֔⁠m mi⁠mȧté֖̇h ʼepĕráֽyim׃"],[21,21,"וַ⁠יִּתְּנ֨וּ לָ⁠הֶ֜ם אֶת־עִ֨יר מִקְלַ֧ט הָ⁠רֹצֵ֛חַ אֶת־שְׁכֶ֥ם וְ⁠אֶת־מִגְרָשֶׁ֖⁠הָ בְּ⁠הַ֣ר אֶפְרָ֑יִם וְ⁠אֶת־גֶּ֖זֶר וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","wa⁠yi̇ţĕ̇n֨ẇ lá⁠he֜m ʼeţ-ʻi֨yr miqĕla֧t há⁠ròẕé֛ẖa ʼeţ-şĕ̌ke֥m wĕ⁠ʼeţ-migĕráşě֖⁠há bĕ̇⁠ha֣r ʼepĕrá֑yim wĕ⁠ʼeţ-gė֖zer wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,22,"וְ⁠אֶת־קִבְצַ֨יִם֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ וְ⁠אֶת־בֵּ֥ית חוֹרֹ֖ן וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים אַרְבַּֽע׃ס","wĕ⁠ʼeţ-qibĕẕa֨yim֙ wĕ⁠ʼeţ-migĕráşě֔⁠há wĕ⁠ʼeţ-bé֥̇yţ ẖwòrò֖n wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym ʼarĕbȧֽʻ׃s"],[21,23,"וּ⁠מִ⁠מַּ֨טֵּה־דָ֔ן אֶֽת־אֶלְתְּקֵ֖א וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ אֶֽת־גִּבְּת֖וֹן וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","ẇ⁠mi⁠mȧ֨té̇h-dá֔n ʼeֽţ-ʼelĕţĕ̇qé֖ʼ wĕ⁠ʼeţ-migĕráşě֑⁠há ʼeֽţ-gi̇bĕ̇ţ֖wòn wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,24,"אֶת־אַיָּלוֹן֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ אֶת־גַּת־רִמּ֖וֹן וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים אַרְבַּֽע׃ס","ʼeţ-ʼayá̇lwòn֙ wĕ⁠ʼeţ-migĕráşě֔⁠há ʼeţ-gȧţ-riṁ֖wòn wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym ʼarĕbȧֽʻ׃s"],[21,25,"וּ⁠מִֽ⁠מַּחֲצִית֙ מַטֵּ֣ה מְנַשֶּׁ֔ה אֶת־תַּעְנַךְ֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ וְ⁠אֶת־גַּת־רִמּ֖וֹן וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים שְׁתָּֽיִם׃","ẇ⁠miֽ⁠mȧẖàẕiyţ֙ maté֣̇h mĕnaşė̌֔h ʼeţ-ţȧʻĕnakĕ֙ wĕ⁠ʼeţ-migĕráşě֔⁠há wĕ⁠ʼeţ-gȧţ-riṁ֖wòn wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym şĕ̌ţáֽ̇yim׃"],[21,26,"כָּל־עָרִ֥ים עֶ֖שֶׂר וּ⁠מִגְרְשֵׁי⁠הֶ֑ן לְ⁠מִשְׁפְּח֥וֹת בְּנֵֽי־קְהָ֖ת הַ⁠נּוֹתָרִֽים׃ס","ká̇l-ʻári֥ym ʻe֖şêr ẇ⁠migĕrĕşé̌y⁠he֑n lĕ⁠mişĕ̌pĕ̇ẖ֥wòţ bĕ̇néֽy-qĕhá֖ţ ha⁠ṅwòţáriֽym׃s"],[21,27,"וְ⁠לִ⁠בְנֵ֣י גֵרְשׁוֹן֮ מִ⁠מִּשְׁפְּחֹ֣ת הַ⁠לְוִיִּם֒ מֵ⁠חֲצִ֞י מַטֵּ֣ה מְנַשֶּׁ֗ה אֶת־עִיר֙ מִקְלַ֣ט הָ⁠רֹצֵ֔חַ אֶת־גלון בַּ⁠בָּשָׁן֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ וְ⁠אֶֽת־בְּעֶשְׁתְּרָ֖ה וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים שְׁתָּֽיִם׃ס","wĕ⁠li⁠bĕné֣y gérĕş̌wòn֮ mi⁠mi̇şĕ̌pĕ̇ẖò֣ţ ha⁠lĕwiyi̇m֒ mé⁠ẖàẕi֞y maté֣̇h mĕnaşė̌֗h ʼeţ-ʻiyr֙ miqĕla֣t há⁠ròẕé֔ẖa ʼeţ-glwn bȧ⁠bá̇şá̌n֙ wĕ⁠ʼeţ-migĕráşě֔⁠há wĕ⁠ʼeֽţ-bĕ̇ʻeşĕ̌ţĕ̇rá֖h wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym şĕ̌ţáֽ̇yim׃s"],[21,28,"וּ⁠מִ⁠מַּטֵּ֣ה יִשָּׂשכָ֔ר אֶת־קִשְׁי֖וֹן וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ אֶת־דָּֽבְרַ֖ת וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","ẇ⁠mi⁠mȧté֣̇h yişá̇̂şká֔r ʼeţ-qişĕ̌y֖wòn wĕ⁠ʼeţ-migĕráşě֑⁠há ʼeţ-dáֽ̇bĕra֖ţ wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,29,"אֶת־יַרְמוּת֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ אֶת־עֵ֥ין גַּנִּ֖ים וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים אַרְבַּֽע׃ס","ʼeţ-yarĕmẇţ֙ wĕ⁠ʼeţ-migĕráşě֔⁠há ʼeţ-ʻé֥yn gȧni֖̇ym wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym ʼarĕbȧֽʻ׃s"],[21,30,"וּ⁠מִ⁠מַּטֵּ֣ה אָשֵׁ֔ר אֶת־מִשְׁאָ֖ל וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ אֶת־עַבְדּ֖וֹן וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","ẇ⁠mi⁠mȧté֣̇h ʼáşé̌֔r ʼeţ-mişĕ̌ʼá֖l wĕ⁠ʼeţ-migĕráşě֑⁠há ʼeţ-ʻabĕḋ֖wòn wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,31,"אֶת־חֶלְקָת֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ וְ⁠אֶת־רְחֹ֖ב וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים אַרְבַּֽע׃ס","ʼeţ-ẖelĕqáţ֙ wĕ⁠ʼeţ-migĕráşě֔⁠há wĕ⁠ʼeţ-rĕẖò֖b wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym ʼarĕbȧֽʻ׃s"],[21,32,"וּ⁠מִ⁠מַּטֵּ֨ה נַפְתָּלִ֜י אֶת־עִ֣יר ׀ מִקְלַ֣ט הָֽ⁠רֹצֵ֗חַ אֶת־קֶ֨דֶשׁ בַּ⁠גָּלִ֤יל וְ⁠אֶת־מִגְרָשֶׁ֨⁠הָ֙ וְ⁠אֶת־חַמֹּ֥ת דֹּאר֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ וְ⁠אֶת־קַרְתָּ֖ן וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים שָׁלֹֽשׁ׃","ẇ⁠mi⁠mȧté̇֨h napĕţá̇li֜y ʼeţ-ʻi֣yr ׀ miqĕla֣t háֽ⁠ròẕé֗ẖa ʼeţ-qe֨deş̌ bȧ⁠gá̇li֤yl wĕ⁠ʼeţ-migĕráşě֨⁠há֙ wĕ⁠ʼeţ-ẖamò֥̇ţ dò̇ʼr֙ wĕ⁠ʼeţ-migĕráşě֔⁠há wĕ⁠ʼeţ-qarĕţá֖̇n wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym şá̌lòֽş̌׃"],[21,33,"כָּל־עָרֵ֥י הַ⁠גֵּרְשֻׁנִּ֖י לְ⁠מִשְׁפְּחֹתָ֑⁠ם שְׁלֹשׁ־עֶשְׂרֵ֥ה עִ֖יר וּ⁠מִגְרְשֵׁי⁠הֶֽן׃ס","ká̇l-ʻáré֥y ha⁠gé̇rĕşǔni֖̇y lĕ⁠mişĕ̌pĕ̇ẖòţá֑⁠m şĕ̌lòş̌-ʻeşĕ̂ré֥h ʻi֖yr ẇ⁠migĕrĕşé̌y⁠heֽn׃s"],[21,34,"וּ⁠לְ⁠מִשְׁפְּח֣וֹת בְּנֵֽי־מְרָרִי֮ הַ⁠לְוִיִּ֣ם הַ⁠נּוֹתָרִים֒ מֵ⁠אֵת֙ מַטֵּ֣ה זְבוּלֻ֔ן אֶֽת־יָקְנְעָ֖ם וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ אֶת־קַרְתָּ֖ה וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","ẇ⁠lĕ⁠mişĕ̌pĕ̇ẖ֣wòţ bĕ̇néֽy-mĕráriy֮ ha⁠lĕwiyi֣̇m ha⁠ṅwòţáriym֒ mé⁠ʼéţ֙ maté֣̇h zĕbẇlu֔n ʼeֽţ-yáqĕnĕʻá֖m wĕ⁠ʼeţ-migĕráşě֑⁠há ʼeţ-qarĕţá֖̇h wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,35,"אֶת־דִּמְנָה֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ אֶֽת־נַהֲלָ֖ל וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים אַרְבַּֽע׃","ʼeţ-di̇mĕnáh֙ wĕ⁠ʼeţ-migĕráşě֔⁠há ʼeֽţ-nahàlá֖l wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym ʼarĕbȧֽʻ׃"],[21,36,"וּ⁠מִ⁠מַּטֵּ֣ה רְאוּבֵ֔ן אֶת־בֶּ֖צֶר וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ וְ⁠אֶת־יַ֖הְצָ⁠ה וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","ẇ⁠mi⁠mȧté֣̇h rĕʼẇbé֔n ʼeţ-bė֖ẕer wĕ⁠ʼeţ-migĕráşě֑⁠há wĕ⁠ʼeţ-ya֖hĕẕá⁠h wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,37,"אֶת־קְדֵמוֹת֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ וְ⁠אֶת־מֵיפָ֖עַת וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ עָרִ֖ים אַרְבַּֽע׃ס","ʼeţ-qĕdémwòţ֙ wĕ⁠ʼeţ-migĕráşě֔⁠há wĕ⁠ʼeţ-méypá֖ʻaţ wĕ⁠ʼeţ-migĕráşě֑⁠há ʻári֖ym ʼarĕbȧֽʻ׃s"],[21,38,"וּ⁠מִ⁠מַּטֵּה־גָ֗ד אֶת־עִיר֙ מִקְלַ֣ט הָ⁠רֹצֵ֔חַ אֶת־רָמֹ֥ת בַּ⁠גִּלְעָ֖ד וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ וְ⁠אֶֽת־מַחֲנַ֖יִם וְ⁠אֶת־מִגְרָשֶֽׁ⁠הָ׃","ẇ⁠mi⁠mȧté̇h-gá֗d ʼeţ-ʻiyr֙ miqĕla֣t há⁠ròẕé֔ẖa ʼeţ-rámò֥ţ bȧ⁠gi̇lĕʻá֖d wĕ⁠ʼeţ-migĕráşě֑⁠há wĕ⁠ʼeֽţ-maẖàna֖yim wĕ⁠ʼeţ-migĕráşěֽ⁠há׃"],[21,39,"אֶת־חֶשְׁבּוֹן֙ וְ⁠אֶת־מִגְרָשֶׁ֔⁠הָ אֶת־יַעְזֵ֖ר וְ⁠אֶת־מִגְרָשֶׁ֑⁠הָ כָּל־עָרִ֖ים אַרְבַּֽע׃","ʼeţ-ẖeşĕ̌ḃwòn֙ wĕ⁠ʼeţ-migĕráşě֔⁠há ʼeţ-yaʻĕzé֖r wĕ⁠ʼeţ-migĕráşě֑⁠há ká̇l-ʻári֖ym ʼarĕbȧֽʻ׃"],[21,40,"כָּל־הֶ֨⁠עָרִ֜ים לִ⁠בְנֵ֤י מְרָרִי֙ לְ⁠מִשְׁפְּחֹתָ֔⁠ם הַ⁠נּוֹתָרִ֖ים מִ⁠מִּשְׁפְּח֣וֹת הַ⁠לְוִיִּ֑ם וַ⁠יְהִי֙ גּוֹרָלָ֔⁠ם עָרִ֖ים שְׁתֵּ֥ים עֶשְׂרֵֽה׃","ká̇l-he֨⁠ʻári֜ym li⁠bĕné֤y mĕráriy֙ lĕ⁠mişĕ̌pĕ̇ẖòţá֔⁠m ha⁠ṅwòţári֖ym mi⁠mi̇şĕ̌pĕ̇ẖ֣wòţ ha⁠lĕwiyi֑̇m wa⁠yĕhiy֙ ġwòrálá֔⁠m ʻári֖ym şĕ̌ţé֥̇ym ʻeşĕ̂réֽh׃"],[21,41,"כֹּ֚ל עָרֵ֣י הַ⁠לְוִיִּ֔ם בְּ⁠ת֖וֹךְ אֲחֻזַּ֣ת בְּנֵֽי־יִשְׂרָאֵ֑ל עָרִ֛ים אַרְבָּעִ֥ים וּ⁠שְׁמֹנֶ֖ה וּ⁠מִגְרְשֵׁי⁠הֶֽן׃","kò֚̇l ʻáré֣y ha⁠lĕwiyi̇֔m bĕ̇⁠ţ֖wòkĕ ʼàẖuzȧ֣ţ bĕ̇néֽy-yişĕ̂ráʼé֑l ʻári֛ym ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌mòne֖h ẇ⁠migĕrĕşé̌y⁠heֽn׃"],[21,42,"תִּֽהְיֶ֨ינָה֙ הֶ⁠עָרִ֣ים הָ⁠אֵ֔לֶּה עִ֣יר עִ֔יר וּ⁠מִגְרָשֶׁ֖י⁠הָ סְבִיבֹתֶ֑י⁠הָ כֵּ֖ן לְ⁠כָל־הֶ⁠עָרִ֥ים הָ⁠אֵֽלֶּה׃ס","ţiֽ̇hĕye֨ynáh֙ he⁠ʻári֣ym há⁠ʼé֔lėh ʻi֣yr ʻi֔yr ẇ⁠migĕráşě֖y⁠há sĕbiybòţe֑y⁠há ké֖̇n lĕ⁠kál-he⁠ʻári֥ym há⁠ʼéֽlėh׃s"],[21,43,"וַ⁠יִּתֵּ֤ן יְהוָה֙ לְ⁠יִשְׂרָאֵ֔ל אֶת־כָּל־הָ⁠אָ֔רֶץ אֲשֶׁ֥ר נִשְׁבַּ֖ע לָ⁠תֵ֣ת לַ⁠אֲבוֹתָ֑⁠ם וַ⁠יִּרָשׁ֖וּ⁠הָ וַ⁠יֵּ֥שְׁבוּ בָֽ⁠הּ׃","wa⁠yi̇ţé֤̇n yĕhwáh֙ lĕ⁠yişĕ̂ráʼé֔l ʼeţ-ká̇l-há⁠ʼá֔reẕ ʼàşě֥r nişĕ̌bȧ֖ʻ lá⁠ţé֣ţ la⁠ʼàbwòţá֑⁠m wa⁠yi̇ráş֖̌ẇ⁠há wa⁠yé֥̇şĕ̌bẇ báֽ⁠ḣ׃"],[21,44,"וַ⁠יָּ֨נַח יְהוָ֤ה לָ⁠הֶם֙ מִ⁠סָּבִ֔יב כְּ⁠כֹ֥ל אֲשֶׁר־נִשְׁבַּ֖ע לַ⁠אֲבוֹתָ֑⁠ם וְ⁠לֹא־עָ֨מַד אִ֤ישׁ בִּ⁠פְנֵי⁠הֶם֙ מִ⁠כָּל־אֹ֣יְבֵי⁠הֶ֔ם אֵ֚ת כָּל־אֹ֣יְבֵי⁠הֶ֔ם נָתַ֥ן יְהוָ֖ה בְּ⁠יָדָֽ⁠ם׃","wa⁠yá̇֨naẖ yĕhwá֤h lá⁠hem֙ mi⁠sá̇bi֔yb kĕ̇⁠kò֥l ʼàşěr-nişĕ̌bȧ֖ʻ la⁠ʼàbwòţá֑⁠m wĕ⁠lòʼ-ʻá֨mad ʼi֤yş̌ bi̇⁠pĕnéy⁠hem֙ mi⁠ká̇l-ʼò֣yĕbéy⁠he֔m ʼé֚ţ ká̇l-ʼò֣yĕbéy⁠he֔m náţa֥n yĕhwá֖h bĕ̇⁠yádáֽ⁠m׃"],[21,45,"לֹֽא־נָפַ֣ל דָּבָ֔ר מִ⁠כֹּל֙ הַ⁠דָּבָ֣ר הַ⁠טּ֔וֹב אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה אֶל־בֵּ֣ית יִשְׂרָאֵ֑ל הַ⁠כֹּ֖ל בָּֽא׃פ","lòֽʼ-nápa֣l dá̇bá֔r mi⁠kò̇l֙ ha⁠dá̇bá֣r ha⁠ṫ֔wòb ʼàşěr-di̇bė֥r yĕhwá֖h ʼel-bé֣̇yţ yişĕ̂ráʼé֑l ha⁠kò֖̇l báֽ̇ʼ׃p"],[22,1,"אָ֚ז יִקְרָ֣א יְהוֹשֻׁ֔עַ לָ⁠רֽאוּבֵנִ֖י וְ⁠לַ⁠גָּדִ֑י וְ⁠לַ⁠חֲצִ֖י מַטֵּ֥ה מְנַשֶּֽׁה׃","ʼá֚z yiqĕrá֣ʼ yĕhwòşǔ֔ʻa lá⁠rֽʼẇbéni֖y wĕ⁠la⁠gá̇di֑y wĕ⁠la⁠ẖàẕi֖y maté֥̇h mĕnaşėֽ̌h׃"],[22,2,"וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֔ם אַתֶּ֣ם שְׁמַרְתֶּ֔ם אֵ֚ת כָּל־אֲשֶׁ֣ר צִוָּ֣ה אֶתְ⁠כֶ֔ם מֹשֶׁ֖ה עֶ֣בֶד יְהוָ֑ה וַ⁠תִּשְׁמְע֣וּ בְ⁠קוֹלִ֔⁠י לְ⁠כֹ֥ל אֲשֶׁר־צִוִּ֖יתִי אֶתְ⁠כֶֽם׃","wa⁠yò֣̇ʼmer ʼàléy⁠he֔m ʼaţė֣m şĕ̌marĕţė֔m ʼé֚ţ ká̇l-ʼàşě֣r ẕiwá֣̇h ʼeţĕ⁠ke֔m mòşě֖h ʻe֣bed yĕhwá֑h wa⁠ţi̇şĕ̌mĕʻ֣ẇ bĕ⁠qwòli֔⁠y lĕ⁠kò֥l ʼàşěr-ẕiwi֖̇yţiy ʼeţĕ⁠keֽm׃"],[22,3,"לֹֽא־עֲזַבְתֶּ֣ם אֶת־אֲחֵי⁠כֶ֗ם זֶ֚ה יָמִ֣ים רַבִּ֔ים עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וּ⁠שְׁמַרְתֶּ֕ם אֶת־מִשְׁמֶ֕רֶת מִצְוַ֖ת יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","lòֽʼ-ʻàzabĕţė֣m ʼeţ-ʼàẖéy⁠ke֗m ze֚h yámi֣ym rabi̇֔ym ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h ẇ⁠şĕ̌marĕţė֕m ʼeţ-mişĕ̌me֕reţ miẕĕwa֖ţ yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[22,4,"וְ⁠עַתָּ֗ה הֵנִ֨יחַ יְהוָ֤ה אֱלֹֽהֵי⁠כֶם֙ לַֽ⁠אֲחֵי⁠כֶ֔ם כַּ⁠אֲשֶׁ֖ר דִּבֶּ֣ר לָ⁠הֶ֑ם וְ⁠עַתָּ֡ה פְּנוּ֩ וּ⁠לְכ֨וּ לָ⁠כֶ֜ם לְ⁠אָהֳלֵי⁠כֶ֗ם אֶל־אֶ֨רֶץ֙ אֲחֻזַּתְ⁠כֶ֔ם אֲשֶׁ֣ר ׀ נָתַ֣ן לָ⁠כֶ֗ם מֹשֶׁה֙ עֶ֣בֶד יְהוָ֔ה בְּ⁠עֵ֖בֶר הַ⁠יַּרְדֵּֽן׃","wĕ⁠ʻaţá̇֗h héni֨yẖa yĕhwá֤h ʼèlòֽhéy⁠kem֙ laֽ⁠ʼàẖéy⁠ke֔m kȧ⁠ʼàşě֖r di̇bė֣r lá⁠he֑m wĕ⁠ʻaţá̇֡h pĕ̇nẇ֩ ẇ⁠lĕk֨ẇ lá⁠ke֜m lĕ⁠ʼáholéy⁠ke֗m ʼel-ʼe֨reẕ֙ ʼàẖuzȧţĕ⁠ke֔m ʼàşě֣r ׀ náţa֣n lá⁠ke֗m mòşěh֙ ʻe֣bed yĕhwá֔h bĕ̇⁠ʻé֖ber ha⁠yȧrĕdéֽ̇n׃"],[22,5,"רַ֣ק ׀ שִׁמְר֣וּ מְאֹ֗ד לַ⁠עֲשׂ֨וֹת אֶת־הַ⁠מִּצְוָ֣ה וְ⁠אֶת־הַ⁠תּוֹרָה֮ אֲשֶׁ֣ר צִוָּ֣ה אֶתְ⁠כֶם֮ מֹשֶׁ֣ה עֶֽבֶד־יְהוָה֒ לְ֠⁠אַהֲבָה אֶת־יְהוָ֨ה אֱלֹֽהֵי⁠כֶ֜ם וְ⁠לָ⁠לֶ֧כֶת בְּ⁠כָל־דְּרָכָ֛י⁠ו וְ⁠לִ⁠שְׁמֹ֥ר מִצְוֺתָ֖י⁠ו וּ⁠לְ⁠דָבְקָה־ב֑⁠וֹ וּ⁠לְ⁠עָבְד֕⁠וֹ בְּ⁠כָל־לְבַבְ⁠כֶ֖ם וּ⁠בְ⁠כָל־נַפְשְׁ⁠כֶֽם׃","ra֣q ׀ şǐmĕr֣ẇ mĕʼò֗d la⁠ʻàş̂֨wòţ ʼeţ-ha⁠mi̇ẕĕwá֣h wĕ⁠ʼeţ-ha⁠ţ̇wòráh֮ ʼàşě֣r ẕiwá֣̇h ʼeţĕ⁠kem֮ mòşě֣h ʻeֽbed-yĕhwáh֒ lĕ֠⁠ʼahàbáh ʼeţ-yĕhwá֨h ʼèlòֽhéy⁠ke֜m wĕ⁠lá⁠le֧keţ bĕ̇⁠kál-dĕ̇ráká֛y⁠w wĕ⁠li⁠şĕ̌mò֥r miẕĕwֺţá֖y⁠w ẇ⁠lĕ⁠dábĕqáh-b֑⁠wò ẇ⁠lĕ⁠ʻábĕd֕⁠wò bĕ̇⁠kál-lĕbabĕ⁠ke֖m ẇ⁠bĕ⁠kál-napĕşĕ̌⁠keֽm׃"],[22,6,"וַֽ⁠יְבָרְכֵ֖⁠ם יְהוֹשֻׁ֑עַ וַֽ⁠יְשַׁלְּחֵ֔⁠ם וַ⁠יֵּלְכ֖וּ אֶל־אָהֳלֵי⁠הֶֽם׃ס","waֽ⁠yĕbárĕké֖⁠m yĕhwòşǔ֑ʻa waֽ⁠yĕşǎlĕ̇ẖé֔⁠m wa⁠yé̇lĕk֖ẇ ʼel-ʼáholéy⁠heֽm׃s"],[22,7,"וְ⁠לַ⁠חֲצִ֣י ׀ שֵׁ֣בֶט הַֽ⁠מְנַשֶּׁ֗ה נָתַ֣ן מֹשֶׁה֮ בַּ⁠בָּשָׁן֒ וּ⁠לְ⁠חֶצְי֗⁠וֹ נָתַ֤ן יְהוֹשֻׁ֨עַ֙ עִם־אֲחֵי⁠הֶ֔ם מ⁠עבר הַ⁠יַּרְדֵּ֖ן יָ֑מָּ⁠ה וְ֠⁠גַם כִּ֣י שִׁלְּחָ֧⁠ם יְהוֹשֻׁ֛עַ אֶל־אָהֳלֵי⁠הֶ֖ם וַ⁠יְבָרֲכֵֽ⁠ם׃","wĕ⁠la⁠ẖàẕi֣y ׀ şé֣̌bet haֽ⁠mĕnaşė̌֗h náţa֣n mòşěh֮ bȧ⁠bá̇şá̌n֒ ẇ⁠lĕ⁠ẖeẕĕy֗⁠wò náţa֤n yĕhwòşǔ֨ʻa֙ ʻim-ʼàẖéy⁠he֔m m⁠ʻbr ha⁠yȧrĕdé֖̇n yá֑má̇⁠h wĕ֠⁠gam ki֣̇y şǐlĕ̇ẖá֧⁠m yĕhwòşǔ֛ʻa ʼel-ʼáholéy⁠he֖m wa⁠yĕbáràkéֽ⁠m׃"],[22,8,"וַ⁠יֹּ֨אמֶר אֲלֵי⁠הֶ֜ם לֵ⁠אמֹ֗ר בִּ⁠נְכָסִ֨ים רַבִּ֜ים שׁ֤וּבוּ אֶל־אָֽהֳלֵי⁠כֶם֙ וּ⁠בְ⁠מִקְנֶ֣ה רַב־מְאֹ֔ד בְּ⁠כֶ֨סֶף וּ⁠בְ⁠זָהָ֜ב וּ⁠בִ⁠נְחֹ֧שֶׁת וּ⁠בְ⁠בַרְזֶ֛ל וּ⁠בִ⁠שְׂלָמ֖וֹת הַרְבֵּ֣ה מְאֹ֑ד חִלְק֥וּ שְׁלַל־אֹיְבֵי⁠כֶ֖ם עִם־אֲחֵי⁠כֶֽם׃פ","wa⁠yò̇֨ʼmer ʼàléy⁠he֜m lé⁠ʼmò֗r bi̇⁠nĕkási֨ym rabi̇֜ym ş֤̌ẇbẇ ʼel-ʼáֽholéy⁠kem֙ ẇ⁠bĕ⁠miqĕne֣h rab-mĕʼò֔d bĕ̇⁠ke֨sep ẇ⁠bĕ⁠záhá֜b ẇ⁠bi⁠nĕẖò֧şěţ ẇ⁠bĕ⁠barĕze֛l ẇ⁠bi⁠şĕ̂lám֖wòţ harĕbé֣̇h mĕʼò֑d ẖilĕq֥ẇ şĕ̌lal-ʼòyĕbéy⁠ke֖m ʻim-ʼàẖéy⁠keֽm׃p"],[22,9,"וַ⁠יָּשֻׁ֣בוּ וַ⁠יֵּלְכ֡וּ בְּנֵי־רְאוּבֵ֨ן וּ⁠בְנֵי־גָ֜ד וַ⁠חֲצִ֣י ׀ שֵׁ֣בֶט הַֽ⁠מְנַשֶּׁ֗ה מֵ⁠אֵת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל מִ⁠שִּׁלֹ֖ה אֲשֶׁ֣ר בְּ⁠אֶֽרֶץ־כְּנָ֑עַן לָ⁠לֶ֜כֶת אֶל־אֶ֣רֶץ הַ⁠גִּלְעָ֗ד אֶל־אֶ֤רֶץ אֲחֻזָּתָ⁠ם֙ אֲשֶׁ֣ר נֹֽאחֲזוּ־בָ֔⁠הּ עַל־פִּ֥י יְהוָ֖ה בְּ⁠יַד־מֹשֶֽׁה׃","wa⁠yá̇şǔ֣bẇ wa⁠yé̇lĕk֡ẇ bĕ̇néy-rĕʼẇbé֨n ẇ⁠bĕnéy-gá֜d wa⁠ẖàẕi֣y ׀ şé֣̌bet haֽ⁠mĕnaşė̌֗h mé⁠ʼéţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l mi⁠şi̇̌lò֖h ʼàşě֣r bĕ̇⁠ʼeֽreẕ-kĕ̇ná֑ʻan lá⁠le֜keţ ʼel-ʼe֣reẕ ha⁠gi̇lĕʻá֗d ʼel-ʼe֤reẕ ʼàẖuzá̇ţá⁠m֙ ʼàşě֣r nòֽʼẖàzẇ-bá֔⁠ḣ ʻal-pi֥̇y yĕhwá֖h bĕ̇⁠yad-mòşěֽh׃"],[22,10,"וַ⁠יָּבֹ֨אוּ֙ אֶל־גְּלִיל֣וֹת הַ⁠יַּרְדֵּ֔ן אֲשֶׁ֖ר בְּ⁠אֶ֣רֶץ כְּנָ֑עַן וַ⁠יִּבְנ֣וּ בְנֵי־רְאוּבֵ֣ן וּ⁠בְנֵי־גָ֡ד וַ⁠חֲצִ֣י שֵׁבֶט֩ הַֽ⁠מְנַשֶּׁ֨ה שָׁ֤ם מִזְבֵּ֨חַ֙ עַל־הַ⁠יַּרְדֵּ֔ן מִזְבֵּ֥חַ גָּד֖וֹל לְ⁠מַרְאֶֽה׃","wa⁠yá̇bò֨ʼẇ֙ ʼel-gĕ̇liyl֣wòţ ha⁠yȧrĕdé̇֔n ʼàşě֖r bĕ̇⁠ʼe֣reẕ kĕ̇ná֑ʻan wa⁠yi̇bĕn֣ẇ bĕnéy-rĕʼẇbé֣n ẇ⁠bĕnéy-gá֡d wa⁠ẖàẕi֣y şé̌bet֩ haֽ⁠mĕnaşė̌֨h şá֤̌m mizĕbé̇֨ẖa֙ ʻal-ha⁠yȧrĕdé̇֔n mizĕbé֥̇ẖa gá̇d֖wòl lĕ⁠marĕʼeֽh׃"],[22,11,"וַ⁠יִּשְׁמְע֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר הִנֵּ֣ה בָנ֣וּ בְנֵֽי־רְאוּבֵ֣ן וּ⁠בְנֵי־גָ֡ד וַ⁠חֲצִי֩ שֵׁ֨בֶט הַֽ⁠מְנַשֶּׁ֜ה אֶת־הַ⁠מִּזְבֵּ֗חַ אֶל־מוּל֙ אֶ֣רֶץ כְּנַ֔עַן אֶל־גְּלִילוֹת֙ הַ⁠יַּרְדֵּ֔ן אֶל־עֵ֖בֶר בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yi̇şĕ̌mĕʻ֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l lé⁠ʼmò֑r hiné֣̇h bán֣ẇ bĕnéֽy-rĕʼẇbé֣n ẇ⁠bĕnéy-gá֡d wa⁠ẖàẕiy֩ şé̌֨bet haֽ⁠mĕnaşė̌֜h ʼeţ-ha⁠mi̇zĕbé̇֗ẖa ʼel-mẇl֙ ʼe֣reẕ kĕ̇na֔ʻan ʼel-gĕ̇liylwòţ֙ ha⁠yȧrĕdé̇֔n ʼel-ʻé֖ber bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[22,12,"וַֽ⁠יִּשְׁמְע֖וּ בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּקָּ֨הֲל֜וּ כָּל־עֲדַ֤ת בְּנֵֽי־יִשְׂרָאֵל֙ שִׁלֹ֔ה לַ⁠עֲל֥וֹת עֲלֵי⁠הֶ֖ם לַ⁠צָּבָֽא׃פ","waֽ⁠yi̇şĕ̌mĕʻ֖ẇ bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yi̇qá̇֨hàl֜ẇ ká̇l-ʻàda֤ţ bĕ̇néֽy-yişĕ̂ráʼél֙ şǐlò֔h la⁠ʻàl֥wòţ ʻàléy⁠he֖m la⁠ẕá̇báֽʼ׃p"],[22,13,"וַ⁠יִּשְׁלְח֨וּ בְנֵֽי־יִשְׂרָאֵ֜ל אֶל־בְּנֵי־רְאוּבֵ֧ן וְ⁠אֶל־בְּנֵי־גָ֛ד וְ⁠אֶל־חֲצִ֥י שֵֽׁבֶט־מְנַשֶּׁ֖ה אֶל־אֶ֣רֶץ הַ⁠גִּלְעָ֑ד אֶת־פִּינְחָ֖ס בֶּן־אֶלְעָזָ֥ר הַ⁠כֹּהֵֽן׃","wa⁠yi̇şĕ̌lĕẖ֨ẇ bĕnéֽy-yişĕ̂ráʼé֜l ʼel-bĕ̇néy-rĕʼẇbé֧n wĕ⁠ʼel-bĕ̇néy-gá֛d wĕ⁠ʼel-ẖàẕi֥y şéֽ̌bet-mĕnaşė֖̌h ʼel-ʼe֣reẕ ha⁠gi̇lĕʻá֑d ʼeţ-pi̇ynĕẖá֖s bėn-ʼelĕʻázá֥r ha⁠kò̇héֽn׃"],[22,14,"וַ⁠עֲשָׂרָ֤ה נְשִׂאִים֙ עִמּ֔⁠וֹ נָשִׂ֨יא אֶחָ֜ד נָשִׂ֤יא אֶחָד֙ לְ⁠בֵ֣ית אָ֔ב לְ⁠כֹ֖ל מַטּ֣וֹת יִשְׂרָאֵ֑ל וְ⁠אִ֨ישׁ רֹ֧אשׁ בֵּית־אֲבוֹתָ֛⁠ם הֵ֖מָּה לְ⁠אַלְפֵ֥י יִשְׂרָאֵֽל׃","wa⁠ʻàşá̂rá֤h nĕşîʼiym֙ ʻiṁ֔⁠wò náşî֨yʼ ʼeẖá֜d náşî֤yʼ ʼeẖád֙ lĕ⁠bé֣yţ ʼá֔b lĕ⁠kò֖l maṫ֣wòţ yişĕ̂ráʼé֑l wĕ⁠ʼi֨yş̌ rò֧ʼş̌ bé̇yţ-ʼàbwòţá֛⁠m hé֖má̇h lĕ⁠ʼalĕpé֥y yişĕ̂ráʼéֽl׃"],[22,15,"וַ⁠יָּבֹ֜אוּ אֶל־בְּנֵי־רְאוּבֵ֧ן וְ⁠אֶל־בְּנֵי־גָ֛ד וְ⁠אֶל־חֲצִ֥י שֵֽׁבֶט־מְנַשֶּׁ֖ה אֶל־אֶ֣רֶץ הַ⁠גִּלְעָ֑ד וַ⁠יְדַבְּר֥וּ אִתָּ֖⁠ם לֵ⁠אמֹֽר׃","wa⁠yá̇bò֜ʼẇ ʼel-bĕ̇néy-rĕʼẇbé֧n wĕ⁠ʼel-bĕ̇néy-gá֛d wĕ⁠ʼel-ẖàẕi֥y şéֽ̌bet-mĕnaşė֖̌h ʼel-ʼe֣reẕ ha⁠gi̇lĕʻá֑d wa⁠yĕdabĕ̇r֥ẇ ʼiţá֖̇⁠m lé⁠ʼmòֽr׃"],[22,16,"כֹּ֣ה אָמְר֞וּ כֹּ֣ל ׀ עֲדַ֣ת יְהוָ֗ה מָֽה־הַ⁠מַּ֤עַל הַ⁠זֶּה֙ אֲשֶׁ֤ר מְעַלְתֶּם֙ בֵּ⁠אלֹהֵ֣י יִשְׂרָאֵ֔ל לָ⁠שׁ֣וּב הַ⁠יּ֔וֹם מֵ⁠אַחֲרֵ֖י יְהוָ֑ה בִּ⁠בְנֽוֹתְ⁠כֶ֤ם לָ⁠כֶם֙ מִזְבֵּ֔חַ לִ⁠מְרָדְ⁠כֶ֥ם הַ⁠יּ֖וֹם בַּ⁠יהוָֽה׃","kò֣̇h ʼámĕr֞ẇ kò֣̇l ׀ ʻàda֣ţ yĕhwá֗h máֽh-ha⁠mȧ֤ʻal ha⁠zėh֙ ʼàşě֤r mĕʻalĕţėm֙ bé̇⁠ʼlòhé֣y yişĕ̂ráʼé֔l lá⁠ş֣̌ẇb ha⁠ẏ֔wòm mé⁠ʼaẖàré֖y yĕhwá֑h bi̇⁠bĕnֽwòţĕ⁠ke֤m lá⁠kem֙ mizĕbé̇֔ẖa li⁠mĕrádĕ⁠ke֥m ha⁠ẏ֖wòm bȧ⁠yhwáֽh׃"],[22,17,"הַ⁠מְעַט־לָ֨⁠נוּ֙ אֶת־עֲוֺ֣ן פְּע֔וֹר אֲשֶׁ֤ר לֹֽא־הִטַּהַ֨רְנוּ֙ מִמֶּ֔⁠נּוּ עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וַ⁠יְהִ֥י הַ⁠נֶּ֖גֶף בַּ⁠עֲדַ֥ת יְהוָֽה׃","ha⁠mĕʻat-lá֨⁠nẇ֙ ʼeţ-ʻàwֺ֣n pĕ̇ʻ֔wòr ʼàşě֤r lòֽʼ-hitȧha֨rĕnẇ֙ mimė֔⁠ṅẇ ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h wa⁠yĕhi֥y ha⁠nė֖gep bȧ⁠ʻàda֥ţ yĕhwáֽh׃"],[22,18,"וְ⁠אַתֶּם֙ תָּשֻׁ֣בוּ הַ⁠יּ֔וֹם מֵ⁠אַחֲרֵ֖י יְהוָ֑ה וְ⁠הָיָ֗ה אַתֶּ֞ם תִּמְרְד֤וּ הַ⁠יּוֹם֙ בַּֽ⁠יהוָ֔ה וּ⁠מָחָ֕ר אֶֽל־כָּל־עֲדַ֥ת יִשְׂרָאֵ֖ל יִקְצֹֽף׃","wĕ⁠ʼaţėm֙ ţá̇şǔ֣bẇ ha⁠ẏ֔wòm mé⁠ʼaẖàré֖y yĕhwá֑h wĕ⁠háyá֗h ʼaţė֞m ţi̇mĕrĕd֤ẇ ha⁠ẏwòm֙ bȧֽ⁠yhwá֔h ẇ⁠máẖá֕r ʼeֽl-ká̇l-ʻàda֥ţ yişĕ̂ráʼé֖l yiqĕẕòֽp׃"],[22,19,"וְ⁠אַ֨ךְ אִם־טְמֵאָ֜ה אֶ֣רֶץ אֲחֻזַּתְ⁠כֶ֗ם עִבְר֨וּ לָ⁠כֶ֜ם אֶל־אֶ֨רֶץ אֲחֻזַּ֤ת יְהוָה֙ אֲשֶׁ֤ר שָֽׁכַן־שָׁם֙ מִשְׁכַּ֣ן יְהוָ֔ה וְ⁠הֵאָחֲז֖וּ בְּ⁠תוֹכֵ֑⁠נוּ וּ⁠בַֽ⁠יהוָ֣ה אַל־תִּמְרֹ֗דוּ וְ⁠אֹתָ֨⁠נוּ֙ אֶל־תִּמְרֹ֔דוּ בִּ⁠בְנֹֽתְ⁠כֶ֤ם לָ⁠כֶם֙ מִזְבֵּ֔חַ מִֽ⁠בַּלְעֲדֵ֔י מִזְבַּ֖ח יְהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","wĕ⁠ʼa֨kĕ ʼim-tĕméʼá֜h ʼe֣reẕ ʼàẖuzȧţĕ⁠ke֗m ʻibĕr֨ẇ lá⁠ke֜m ʼel-ʼe֨reẕ ʼàẖuzȧ֤ţ yĕhwáh֙ ʼàşě֤r şáֽ̌kan-şá̌m֙ mişĕ̌kȧ֣n yĕhwá֔h wĕ⁠héʼáẖàz֖ẇ bĕ̇⁠ţwòké֑⁠nẇ ẇ⁠baֽ⁠yhwá֣h ʼal-ţi̇mĕrò֗dẇ wĕ⁠ʼòţá֨⁠nẇ֙ ʼel-ţi̇mĕrò֔dẇ bi̇⁠bĕnòֽţĕ⁠ke֤m lá⁠kem֙ mizĕbé̇֔ẖa miֽ⁠bȧlĕʻàdé֔y mizĕbȧ֖ẖ yĕhwá֥h ʼèlòhéֽy⁠nẇ׃"],[22,20,"הֲ⁠ל֣וֹא ׀ עָכָ֣ן בֶּן־זֶ֗רַח מָ֤עַל מַ֨עַל֙ בַּ⁠חֵ֔רֶם וְ⁠עַֽל־כָּל־עֲדַ֥ת יִשְׂרָאֵ֖ל הָ֣יָה קָ֑צֶף וְ⁠הוּא֙ אִ֣ישׁ אֶחָ֔ד לֹ֥א גָוַ֖ע בַּ⁠עֲוֺנֽ⁠וֹ׃פ","hà⁠l֣wòʼ ׀ ʻáká֣n bėn-ze֗raẖ má֤ʻal ma֨ʻal֙ bȧ⁠ẖé֔rem wĕ⁠ʻaֽl-ká̇l-ʻàda֥ţ yişĕ̂ráʼé֖l há֣yáh qá֑ẕep wĕ⁠hẇʼ֙ ʼi֣yş̌ ʼeẖá֔d lò֥ʼ gáwa֖ʻ bȧ⁠ʻàwֺnֽ⁠wò׃p"],[22,21,"וַֽ⁠יַּעֲנוּ֙ בְּנֵי־רְאוּבֵ֣ן וּ⁠בְנֵי־גָ֔ד וַ⁠חֲצִ֖י שֵׁ֣בֶט הַֽ⁠מְנַשֶּׁ֑ה וַֽ⁠יְדַבְּר֔וּ אֶת־רָאשֵׁ֖י אַלְפֵ֥י יִשְׂרָאֵֽל׃","waֽ⁠yȧʻànẇ֙ bĕ̇néy-rĕʼẇbé֣n ẇ⁠bĕnéy-gá֔d wa⁠ẖàẕi֖y şé֣̌bet haֽ⁠mĕnaşė֑̌h waֽ⁠yĕdabĕ̇r֔ẇ ʼeţ-ráʼşé֖̌y ʼalĕpé֥y yişĕ̂ráʼéֽl׃"],[22,22,"אֵל֩ ׀ אֱלֹהִ֨ים ׀ יְהוָ֜ה אֵ֣ל ׀ אֱלֹהִ֤ים ׀ יְהוָה֙ ה֣וּא יֹדֵ֔עַ וְ⁠יִשְׂרָאֵ֖ל ה֣וּא יֵדָ֑ע אִם־בְּ⁠מֶ֤רֶד וְ⁠אִם־בְּ⁠מַ֨עַל֙ בַּֽ⁠יהוָ֔ה אַל־תּוֹשִׁיעֵ֖⁠נוּ הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","ʼél֩ ׀ ʼèlòhi֨ym ׀ yĕhwá֜h ʼé֣l ׀ ʼèlòhi֤ym ׀ yĕhwáh֙ h֣ẇʼ yòdé֔ʻa wĕ⁠yişĕ̂ráʼé֖l h֣ẇʼ yédá֑ʻ ʼim-bĕ̇⁠me֤red wĕ⁠ʼim-bĕ̇⁠ma֨ʻal֙ bȧֽ⁠yhwá֔h ʼal-ţ̇wòşǐyʻé֖⁠nẇ ha⁠ẏ֥wòm ha⁠zėֽh׃"],[22,23,"לִ⁠בְנ֥וֹת לָ֨⁠נוּ֙ מִזְבֵּ֔חַ לָ⁠שׁ֖וּב מֵ⁠אַחֲרֵ֣י יְהוָ֑ה וְ⁠אִם־לְ⁠הַעֲל֨וֹת עָלָ֜י⁠ו עוֹלָ֣ה וּ⁠מִנְחָ֗ה וְ⁠אִם־לַ⁠עֲשׂ֤וֹת עָלָי⁠ו֙ זִבְחֵ֣י שְׁלָמִ֔ים יְהוָ֖ה ה֥וּא יְבַקֵּֽשׁ׃","li⁠bĕn֥wòţ lá֨⁠nẇ֙ mizĕbé̇֔ẖa lá⁠ş֖̌ẇb mé⁠ʼaẖàré֣y yĕhwá֑h wĕ⁠ʼim-lĕ⁠haʻàl֨wòţ ʻálá֜y⁠w ʻwòlá֣h ẇ⁠minĕẖá֗h wĕ⁠ʼim-la⁠ʻàş֤̂wòţ ʻáláy⁠w֙ zibĕẖé֣y şĕ̌lámi֔ym yĕhwá֖h h֥ẇʼ yĕbaqéֽ̇ş̌׃"],[22,24,"וְ⁠אִם־לֹ֤א מִ⁠דְּאָגָה֙ מִ⁠דָּבָ֔ר עָשִׂ֥ינוּ אֶת־זֹ֖את לֵ⁠אמֹ֑ר מָחָ֗ר יֹאמְר֨וּ בְנֵי⁠כֶ֤ם לְ⁠בָנֵ֨י⁠נוּ֙ לֵ⁠אמֹ֔ר מַה־לָּ⁠כֶ֕ם וְ⁠לַֽ⁠יהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ʼim-lò֤ʼ mi⁠dĕ̇ʼágáh֙ mi⁠dá̇bá֔r ʻáşî֥ynẇ ʼeţ-zò֖ʼţ lé⁠ʼmò֑r máẖá֗r yòʼmĕr֨ẇ bĕnéy⁠ke֤m lĕ⁠báné֨y⁠nẇ֙ lé⁠ʼmò֔r mah-lá̇⁠ke֕m wĕ⁠laֽ⁠yhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[22,25,"וּ⁠גְב֣וּל נָֽתַן־יְ֠הוָה בֵּינֵ֨⁠נוּ וּ⁠בֵינֵי⁠כֶ֜ם בְּנֵי־רְאוּבֵ֤ן וּ⁠בְנֵי־גָד֙ אֶת־הַ⁠יַּרְדֵּ֔ן אֵין־לָ⁠כֶ֥ם חֵ֖לֶק בַּֽ⁠יהוָ֑ה וְ⁠הִשְׁבִּ֤יתוּ בְנֵי⁠כֶם֙ אֶת־בָּנֵ֔י⁠נוּ לְ⁠בִלְתִּ֖י יְרֹ֥א אֶת־יְהוָֽה׃","ẇ⁠gĕb֣ẇl náֽţan-yĕ֠hwáh bé̇yné֨⁠nẇ ẇ⁠béynéy⁠ke֜m bĕ̇néy-rĕʼẇbé֤n ẇ⁠bĕnéy-gád֙ ʼeţ-ha⁠yȧrĕdé̇֔n ʼéyn-lá⁠ke֥m ẖé֖leq bȧֽ⁠yhwá֑h wĕ⁠hişĕ̌bi֤̇yţẇ bĕnéy⁠kem֙ ʼeţ-bá̇né֔y⁠nẇ lĕ⁠bilĕţi֖̇y yĕrò֥ʼ ʼeţ-yĕhwáֽh׃"],[22,26,"וַ⁠נֹּ֕אמֶר נַעֲשֶׂה־נָּ֣א לָ֔⁠נוּ לִ⁠בְנ֖וֹת אֶת־הַ⁠מִּזְבֵּ֑חַ לֹ֥א לְ⁠עוֹלָ֖ה וְ⁠לֹ֥א לְ⁠זָֽבַח׃","wa⁠nò̇֕ʼmer naʻàşêh-ná֣̇ʼ lá֔⁠nẇ li⁠bĕn֖wòţ ʼeţ-ha⁠mi̇zĕbé֑̇ẖa lò֥ʼ lĕ⁠ʻwòlá֖h wĕ⁠lò֥ʼ lĕ⁠záֽbaẖ׃"],[22,27,"כִּי֩ עֵ֨ד ה֜וּא בֵּינֵ֣י⁠נוּ וּ⁠בֵינֵי⁠כֶ֗ם וּ⁠בֵ֣ין דֹּרוֹתֵי⁠נוּ֮ אַחֲרֵי⁠נוּ֒ לַ⁠עֲבֹ֞ד אֶת־עֲבֹדַ֤ת יְהוָה֙ לְ⁠פָנָ֔י⁠ו בְּ⁠עֹלוֹתֵ֥י⁠נוּ וּ⁠בִ⁠זְבָחֵ֖י⁠נוּ וּ⁠בִ⁠שְׁלָמֵ֑י⁠נוּ וְ⁠לֹא־יֹאמְר֨וּ בְנֵי⁠כֶ֤ם מָחָר֙ לְ⁠בָנֵ֔י⁠נוּ אֵין־לָ⁠כֶ֥ם חֵ֖לֶק בַּ⁠יהוָֽה׃","ki̇y֩ ʻé֨d h֜ẇʼ bé̇yné֣y⁠nẇ ẇ⁠béynéy⁠ke֗m ẇ⁠bé֣yn dò̇rwòţéy⁠nẇ֮ ʼaẖàréy⁠nẇ֒ la⁠ʻàbò֞d ʼeţ-ʻàbòda֤ţ yĕhwáh֙ lĕ⁠páná֔y⁠w bĕ̇⁠ʻòlwòţé֥y⁠nẇ ẇ⁠bi⁠zĕbáẖé֖y⁠nẇ ẇ⁠bi⁠şĕ̌lámé֑y⁠nẇ wĕ⁠lòʼ-yòʼmĕr֨ẇ bĕnéy⁠ke֤m máẖár֙ lĕ⁠báné֔y⁠nẇ ʼéyn-lá⁠ke֥m ẖé֖leq bȧ⁠yhwáֽh׃"],[22,28,"וַ⁠נֹּ֕אמֶר וְ⁠הָיָ֗ה כִּֽי־יֹאמְר֥וּ אֵלֵ֛י⁠נוּ וְ⁠אֶל־דֹּרֹתֵ֖י⁠נוּ מָחָ֑ר וְ⁠אָמַ֡רְנוּ רְא֣וּ אֶת־תַּבְנִית֩ מִזְבַּ֨ח יְהוָ֜ה אֲשֶׁר־עָשׂ֣וּ אֲבוֹתֵ֗י⁠נוּ לֹ֤א לְ⁠עוֹלָה֙ וְ⁠לֹ֣א לְ⁠זֶ֔בַח כִּי־עֵ֣ד ה֔וּא בֵּינֵ֖י⁠נוּ וּ⁠בֵינֵי⁠כֶֽם׃","wa⁠nò̇֕ʼmer wĕ⁠háyá֗h kiֽ̇y-yòʼmĕr֥ẇ ʼélé֛y⁠nẇ wĕ⁠ʼel-dò̇ròţé֖y⁠nẇ máẖá֑r wĕ⁠ʼáma֡rĕnẇ rĕʼ֣ẇ ʼeţ-ţȧbĕniyţ֩ mizĕbȧ֨ẖ yĕhwá֜h ʼàşěr-ʻáş֣̂ẇ ʼàbwòţé֗y⁠nẇ lò֤ʼ lĕ⁠ʻwòláh֙ wĕ⁠lò֣ʼ lĕ⁠ze֔baẖ ki̇y-ʻé֣d h֔ẇʼ bé̇yné֖y⁠nẇ ẇ⁠béynéy⁠keֽm׃"],[22,29,"חָלִילָ⁠ה֩ לָּ֨⁠נוּ מִמֶּ֜⁠נּוּ לִ⁠מְרֹ֣ד בַּֽ⁠יהוָ֗ה וְ⁠לָ⁠שׁ֤וּב הַ⁠יּוֹם֙ מֵ⁠אַחֲרֵ֣י יְהוָ֔ה לִ⁠בְנ֣וֹת מִזְבֵּ֔חַ לְ⁠עֹלָ֖ה לְ⁠מִנְחָ֣ה וּ⁠לְ⁠זָ֑בַח מִ⁠לְּ⁠בַ֗ד מִזְבַּח֙ יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ אֲשֶׁ֖ר לִ⁠פְנֵ֥י מִשְׁכָּנֽ⁠וֹ׃פ","ẖáliylá⁠h֩ lá̇֨⁠nẇ mimė֜⁠ṅẇ li⁠mĕrò֣d bȧֽ⁠yhwá֗h wĕ⁠lá⁠ş֤̌ẇb ha⁠ẏwòm֙ mé⁠ʼaẖàré֣y yĕhwá֔h li⁠bĕn֣wòţ mizĕbé̇֔ẖa lĕ⁠ʻòlá֖h lĕ⁠minĕẖá֣h ẇ⁠lĕ⁠zá֑baẖ mi⁠lĕ̇⁠ba֗d mizĕbȧẖ֙ yĕhwá֣h ʼèlòhé֔y⁠nẇ ʼàşě֖r li⁠pĕné֥y mişĕ̌ká̇nֽ⁠wò׃p"],[22,30,"וַ⁠יִּשְׁמַ֞ע פִּֽינְחָ֣ס הַ⁠כֹּהֵ֗ן וּ⁠נְשִׂיאֵ֨י הָ⁠עֵדָ֜ה וְ⁠רָאשֵׁ֨י אַלְפֵ֤י יִשְׂרָאֵל֙ אֲשֶׁ֣ר אִתּ֔⁠וֹ אֶת־הַ֨⁠דְּבָרִ֔ים אֲשֶׁ֧ר דִּבְּר֛וּ בְּנֵי־רְאוּבֵ֥ן וּ⁠בְנֵי־גָ֖ד וּ⁠בְנֵ֣י מְנַשֶּׁ֑ה וַ⁠יִּיטַ֖ב בְּ⁠עֵינֵי⁠הֶֽם׃","wa⁠yi̇şĕ̌ma֞ʻ piֽ̇ynĕẖá֣s ha⁠kò̇hé֗n ẇ⁠nĕşîyʼé֨y há⁠ʻédá֜h wĕ⁠ráʼşé̌֨y ʼalĕpé֤y yişĕ̂ráʼél֙ ʼàşě֣r ʼiţ̇֔⁠wò ʼeţ-ha֨⁠dĕ̇bári֔ym ʼàşě֧r di̇bĕ̇r֛ẇ bĕ̇néy-rĕʼẇbé֥n ẇ⁠bĕnéy-gá֖d ẇ⁠bĕné֣y mĕnaşė֑̌h wa⁠yi̇yta֖b bĕ̇⁠ʻéynéy⁠heֽm׃"],[22,31,"וַ⁠יֹּ֣אמֶר פִּֽינְחָ֣ס בֶּן־אֶלְעָזָ֣ר הַ⁠כֹּהֵ֡ן אֶל־בְּנֵי־רְאוּבֵ֨ן וְ⁠אֶל־בְּנֵי־גָ֜ד וְ⁠אֶל־בְּנֵ֣י מְנַשֶּׁ֗ה הַ⁠יּ֤וֹם ׀ יָדַ֨עְנוּ֙ כִּֽי־בְ⁠תוֹכֵ֣⁠נוּ יְהוָ֔ה אֲשֶׁ֛ר לֹֽא־מְעַלְתֶּ֥ם בַּֽ⁠יהוָ֖ה הַ⁠מַּ֣עַל הַ⁠זֶּ֑ה אָ֗ז הִצַּלְתֶּ֛ם אֶת־בְּנֵ֥י יִשְׂרָאֵ֖ל מִ⁠יַּ֥ד יְהוָֽה׃","wa⁠yò֣̇ʼmer piֽ̇ynĕẖá֣s bėn-ʼelĕʻázá֣r ha⁠kò̇hé֡n ʼel-bĕ̇néy-rĕʼẇbé֨n wĕ⁠ʼel-bĕ̇néy-gá֜d wĕ⁠ʼel-bĕ̇né֣y mĕnaşė̌֗h ha⁠ẏ֤wòm ׀ yáda֨ʻĕnẇ֙ kiֽ̇y-bĕ⁠ţwòké֣⁠nẇ yĕhwá֔h ʼàşě֛r lòֽʼ-mĕʻalĕţė֥m bȧֽ⁠yhwá֖h ha⁠mȧ֣ʻal ha⁠zė֑h ʼá֗z hiẕȧlĕţė֛m ʼeţ-bĕ̇né֥y yişĕ̂ráʼé֖l mi⁠yȧ֥d yĕhwáֽh׃"],[22,32,"וַ⁠יָּ֣שָׁב פִּֽינְחָ֣ס בֶּן־אֶלְעָזָ֣ר הַ⁠כֹּהֵ֣ן ׀ וְ⁠הַ⁠נְּשִׂיאִ֡ים מֵ⁠אֵ֣ת בְּנֵֽי־רְאוּבֵן֩ וּ⁠מֵ⁠אֵ֨ת בְּנֵי־גָ֜ד מֵ⁠אֶ֧רֶץ הַ⁠גִּלְעָ֛ד אֶל־אֶ֥רֶץ כְּנַ֖עַן אֶל־בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יָּשִׁ֥בוּ אוֹתָ֖⁠ם דָּבָֽר׃","wa⁠yá֣̇şá̌b piֽ̇ynĕẖá֣s bėn-ʼelĕʻázá֣r ha⁠kò̇hé֣n ׀ wĕ⁠ha⁠nĕ̇şîyʼi֡ym mé⁠ʼé֣ţ bĕ̇néֽy-rĕʼẇbén֩ ẇ⁠mé⁠ʼé֨ţ bĕ̇néy-gá֜d mé⁠ʼe֧reẕ ha⁠gi̇lĕʻá֛d ʼel-ʼe֥reẕ kĕ̇na֖ʻan ʼel-bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yá̇şǐ֥bẇ ʼwòţá֖⁠m dá̇báֽr׃"],[22,33,"וַ⁠יִּיטַ֣ב הַ⁠דָּבָ֗ר בְּ⁠עֵינֵי֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יְבָרֲכ֥וּ אֱלֹהִ֖ים בְּנֵ֣י יִשְׂרָאֵ֑ל וְ⁠לֹ֣א אָמְר֗וּ לַ⁠עֲל֤וֹת עֲלֵי⁠הֶם֙ לַ⁠צָּבָ֔א לְ⁠שַׁחֵת֙ אֶת־הָ⁠אָ֔רֶץ אֲשֶׁ֛ר בְּנֵי־רְאוּבֵ֥ן וּ⁠בְנֵי־גָ֖ד יֹשְׁבִ֥ים בָּֽ⁠הּ׃","wa⁠yi̇yta֣b ha⁠dá̇bá֗r bĕ̇⁠ʻéynéy֙ bĕ̇né֣y yişĕ̂ráʼé֔l wa⁠yĕbáràk֥ẇ ʼèlòhi֖ym bĕ̇né֣y yişĕ̂ráʼé֑l wĕ⁠lò֣ʼ ʼámĕr֗ẇ la⁠ʻàl֤wòţ ʻàléy⁠hem֙ la⁠ẕá̇bá֔ʼ lĕ⁠şǎẖéţ֙ ʼeţ-há⁠ʼá֔reẕ ʼàşě֛r bĕ̇néy-rĕʼẇbé֥n ẇ⁠bĕnéy-gá֖d yòşĕ̌bi֥ym báֽ̇⁠ḣ׃"],[22,34,"וַֽ⁠יִּקְרְא֛וּ בְּנֵי־רְאוּבֵ֥ן וּ⁠בְנֵי־גָ֖ד לַ⁠מִּזְבֵּ֑חַ כִּ֣י עֵ֥ד הוּא֙ בֵּֽינֹתֵ֔י⁠נוּ כִּ֥י יְהוָ֖ה הָ⁠אֱלֹהִֽים׃פ","waֽ⁠yi̇qĕrĕʼ֛ẇ bĕ̇néy-rĕʼẇbé֥n ẇ⁠bĕnéy-gá֖d la⁠mi̇zĕbé֑̇ẖa ki֣̇y ʻé֥d hẇʼ֙ béֽ̇ynòţé֔y⁠nẇ ki֥̇y yĕhwá֖h há⁠ʼèlòhiֽym׃p"],[23,1,"וַֽ⁠יְהִי֙ מִ⁠יָּמִ֣ים רַבִּ֔ים אַ֠חֲרֵי אֲשֶׁר־הֵנִ֨יחַ יְהוָ֧ה לְ⁠יִשְׂרָאֵ֛ל מִ⁠כָּל־אֹיְבֵי⁠הֶ֖ם מִ⁠סָּבִ֑יב וִ⁠יהוֹשֻׁ֣עַ זָקֵ֔ן בָּ֖א בַּ⁠יָּמִֽים׃","wֽa⁠yĕhiy֙ mi⁠yá̇mi֣ym rabi̇֔ym ʼa֠ẖàréy ʼàşěr-héni֨yẖa yĕhwá֧h lĕ⁠yişĕ̂ráʼé֛l mi⁠ká̇l-ʼòyĕbéy⁠he֖m mi⁠sá̇bi֑yb wi⁠yhwòşǔ֣ʻa záqé֔n bá֖̇ʼ bȧ⁠yá̇miֽym׃"],[23,2,"וַ⁠יִּקְרָ֤א יְהוֹשֻׁ֨עַ֙ לְ⁠כָל־יִשְׂרָאֵ֔ל לִ⁠זְקֵנָי⁠ו֙ וּ⁠לְ⁠רָאשָׁ֔י⁠ו וּ⁠לְ⁠שֹׁפְטָ֖י⁠ו וּ⁠לְ⁠שֹֽׁטְרָ֑י⁠ו וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם אֲנִ֣י זָקַ֔נְתִּי בָּ֖אתִי בַּ⁠יָּמִֽים׃","wa⁠yi̇qĕrá֤ʼ yĕhwòşǔ֨ʻa֙ lĕ⁠kál-yişĕ̂ráʼé֔l li⁠zĕqénáy⁠w֙ ẇ⁠lĕ⁠ráʼşá̌֔y⁠w ẇ⁠lĕ⁠şò̌pĕtá֖y⁠w ẇ⁠lĕ⁠şòֽ̌tĕrá֑y⁠w wa⁠yò֣̇ʼmer ʼàlé⁠he֔m ʼàni֣y záqa֔nĕţi̇y bá֖̇ʼţiy bȧ⁠yá̇miֽym׃"],[23,3,"וְ⁠אַתֶּ֣ם רְאִיתֶ֗ם אֵת֩ כָּל־אֲשֶׁ֨ר עָשָׂ֜ה יְהוָ֧ה אֱלֹהֵי⁠כֶ֛ם לְ⁠כָל־הַ⁠גּוֹיִ֥ם הָ⁠אֵ֖לֶּה מִ⁠פְּנֵי⁠כֶ֑ם כִּ֚י יְהוָ֣ה אֱלֹהֵי⁠כֶ֔ם ה֖וּא הַ⁠נִּלְחָ֥ם לָ⁠כֶֽם׃","wĕ⁠ʼaţė֣m rĕʼiyţe֗m ʼéţ֩ ká̇l-ʼàşě֨r ʻáşá̂֜h yĕhwá֧h ʼèlòhéy⁠ke֛m lĕ⁠kál-ha⁠ġwòyi֥m há⁠ʼé֖lėh mi⁠pĕ̇néy⁠ke֑m ki֚̇y yĕhwá֣h ʼèlòhéy⁠ke֔m h֖ẇʼ ha⁠ni̇lĕẖá֥m lá⁠keֽm׃"],[23,4,"רְאוּ֩ הִפַּ֨לְתִּי לָ⁠כֶ֜ם אֶֽת־הַ֠⁠גּוֹיִם הַ⁠נִּשְׁאָרִ֥ים הָ⁠אֵ֛לֶּה בְּ⁠נַחֲלָ֖ה לְ⁠שִׁבְטֵי⁠כֶ֑ם מִן־הַ⁠יַּרְדֵּ֗ן וְ⁠כָל־הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר הִכְרַ֔תִּי וְ⁠הַ⁠יָּ֥ם הַ⁠גָּד֖וֹל מְב֥וֹא הַ⁠שָּֽׁמֶשׁ׃","rĕʼẇ֩ hipȧ֨lĕţi̇y lá⁠ke֜m ʼeֽţ-ha֠⁠ġwòyim ha⁠ni̇şĕ̌ʼári֥ym há⁠ʼé֛lėh bĕ̇⁠naẖàlá֖h lĕ⁠şǐbĕtéy⁠ke֑m min-ha⁠yȧrĕdé̇֗n wĕ⁠kál-ha⁠ġwòyim֙ ʼàşě֣r hikĕra֔ţi̇y wĕ⁠ha⁠yá֥̇m ha⁠gá̇d֖wòl mĕb֥wòʼ ha⁠şáֽ̇̌meş̌׃"],[23,5,"וַ⁠יהוָ֣ה אֱלֹֽהֵי⁠כֶ֗ם ה֚וּא יֶהְדֳּפֵ֣⁠ם מִ⁠פְּנֵי⁠כֶ֔ם וְ⁠הוֹרִ֥ישׁ אֹתָ֖⁠ם מִ⁠לִּ⁠פְנֵי⁠כֶ֑ם וִֽ⁠ירִשְׁתֶּם֙ אֶת־אַרְצָ֔⁠ם כַּ⁠אֲשֶׁ֥ר דִּבֶּ֛ר יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם לָ⁠כֶֽם׃","wa⁠yhwá֣h ʼèlòֽhéy⁠ke֗m h֚ẇʼ yehĕdȯpé֣⁠m mi⁠pĕ̇néy⁠ke֔m wĕ⁠hwòri֥yş̌ ʼòţá֖⁠m mi⁠li̇⁠pĕnéy⁠ke֑m wiֽ⁠yrişĕ̌ţėm֙ ʼeţ-ʼarĕẕá֔⁠m kȧ⁠ʼàşě֥r di̇bė֛r yĕhwá֥h ʼèlòhéy⁠ke֖m lá⁠keֽm׃"],[23,6,"וַ⁠חֲזַקְתֶּ֣ם מְאֹ֔ד לִ⁠שְׁמֹ֣ר וְ⁠לַ⁠עֲשׂ֔וֹת אֵ֚ת כָּל־הַ⁠כָּת֔וּב בְּ⁠סֵ֖פֶר תּוֹרַ֣ת מֹשֶׁ֑ה לְ⁠בִלְתִּ֥י סוּר־מִמֶּ֖⁠נּוּ יָמִ֥ין וּ⁠שְׂמֹֽאול׃","wa⁠ẖàzaqĕţė֣m mĕʼò֔d li⁠şĕ̌mò֣r wĕ⁠la⁠ʻàş̂֔wòţ ʼé֚ţ ká̇l-ha⁠ká̇ţ֔ẇb bĕ̇⁠sé֖per ţ̇wòra֣ţ mòşě֑h lĕ⁠bilĕţi֥̇y sẇr-mimė֖⁠ṅẇ yámi֥yn ẇ⁠şĕ̂mòֽʼwl׃"],[23,7,"לְ⁠בִלְתִּי־בוֹא֙ בַּ⁠גּוֹיִ֣ם הָ⁠אֵ֔לֶּה הַ⁠נִּשְׁאָרִ֥ים הָ⁠אֵ֖לֶּה אִתְּ⁠כֶ֑ם וּ⁠בְ⁠שֵׁ֨ם אֱלֹהֵי⁠הֶ֤ם לֹא־תַזְכִּ֨ירוּ֙ וְ⁠לֹ֣א תַשְׁבִּ֔יעוּ וְ⁠לֹ֣א תַעַבְד֔וּ⁠ם וְ⁠לֹ֥א תִֽשְׁתַּחֲו֖וּ לָ⁠הֶֽם׃","lĕ⁠bilĕţi̇y-bwòʼ֙ bȧ⁠ġwòyi֣m há⁠ʼé֔lėh ha⁠ni̇şĕ̌ʼári֥ym há⁠ʼé֖lėh ʼiţĕ̇⁠ke֑m ẇ⁠bĕ⁠şé̌֨m ʼèlòhéy⁠he֤m lòʼ-ţazĕki̇֨yrẇ֙ wĕ⁠lò֣ʼ ţaşĕ̌bi̇֔yʻẇ wĕ⁠lò֣ʼ ţaʻabĕd֔ẇ⁠m wĕ⁠lò֥ʼ ţiֽşĕ̌ţȧẖàw֖ẇ lá⁠heֽm׃"],[23,8,"כִּ֛י אִם־בַּ⁠יהוָ֥ה אֱלֹהֵי⁠כֶ֖ם תִּדְבָּ֑קוּ כַּ⁠אֲשֶׁ֣ר עֲשִׂיתֶ֔ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","ki֛̇y ʼim-bȧ⁠yhwá֥h ʼèlòhéy⁠ke֖m ţi̇dĕbá֑̇qẇ kȧ⁠ʼàşě֣r ʻàşîyţe֔m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[23,9,"וַ⁠יּ֤וֹרֶשׁ יְהוָה֙ מִ⁠פְּנֵי⁠כֶ֔ם גּוֹיִ֖ם גְּדֹלִ֣ים וַ⁠עֲצוּמִ֑ים וְ⁠אַתֶּ֗ם לֹא־עָ֤מַד אִישׁ֙ בִּ⁠פְנֵי⁠כֶ֔ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠ẏ֤wòreş̌ yĕhwáh֙ mi⁠pĕ̇néy⁠ke֔m ġwòyi֖m gĕ̇dòli֣ym wa⁠ʻàẕẇmi֑ym wĕ⁠ʼaţė֗m lòʼ-ʻá֤mad ʼiyş̌֙ bi̇⁠pĕnéy⁠ke֔m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[23,10,"אִישׁ־אֶחָ֥ד מִ⁠כֶּ֖ם יִרְדָּף־אָ֑לֶף כִּ֣י ׀ יְהוָ֣ה אֱלֹהֵי⁠כֶ֗ם ה֚וּא הַ⁠נִּלְחָ֣ם לָ⁠כֶ֔ם כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר לָ⁠כֶֽם׃","ʼiyş̌-ʼeẖá֥d mi⁠kė֖m yirĕdá̇p-ʼá֑lep ki֣̇y ׀ yĕhwá֣h ʼèlòhéy⁠ke֗m h֚ẇʼ ha⁠ni̇lĕẖá֣m lá⁠ke֔m kȧ⁠ʼàşě֖r di̇bė֥r lá⁠keֽm׃"],[23,11,"וְ⁠נִשְׁמַרְתֶּ֥ם מְאֹ֖ד לְ⁠נַפְשֹֽׁתֵי⁠כֶ֑ם לְ⁠אַהֲבָ֖ה אֶת־יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠nişĕ̌marĕţė֥m mĕʼò֖d lĕ⁠napĕşòֽ̌ţéy⁠ke֑m lĕ⁠ʼahàbá֖h ʼeţ-yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[23,12,"כִּ֣י ׀ אִם־שׁ֣וֹב תָּשׁ֗וּבוּ וּ⁠דְבַקְתֶּם֙ בְּ⁠יֶ֨תֶר֙ הַ⁠גּוֹיִ֣ם הָ⁠אֵ֔לֶּה הַ⁠נִּשְׁאָרִ֥ים הָ⁠אֵ֖לֶּה אִתְּ⁠כֶ֑ם וְ⁠הִֽתְחַתַּנְתֶּ֥ם בָּ⁠הֶ֛ם וּ⁠בָאתֶ֥ם בָּ⁠הֶ֖ם וְ⁠הֵ֥ם בָּ⁠כֶֽם׃","ki֣̇y ׀ ʼim-ş֣̌wòb ţá̇ş̌֗ẇbẇ ẇ⁠dĕbaqĕţėm֙ bĕ̇⁠ye֨ţer֙ ha⁠ġwòyi֣m há⁠ʼé֔lėh ha⁠ni̇şĕ̌ʼári֥ym há⁠ʼé֖lėh ʼiţĕ̇⁠ke֑m wĕ⁠hiֽţĕẖaţȧnĕţė֥m bá̇⁠he֛m ẇ⁠báʼţe֥m bá̇⁠he֖m wĕ⁠hé֥m bá̇⁠keֽm׃"],[23,13,"יָד֨וֹעַ֙ תֵּֽדְע֔וּ כִּי֩ לֹ֨א יוֹסִ֜יף יְהוָ֣ה אֱלֹהֵי⁠כֶ֗ם לְ⁠הוֹרִ֛ישׁ אֶת־הַ⁠גּוֹיִ֥ם הָ⁠אֵ֖לֶּה מִ⁠לִּ⁠פְנֵי⁠כֶ֑ם וְ⁠הָי֨וּ לָ⁠כֶ֜ם לְ⁠פַ֣ח וּ⁠לְ⁠מוֹקֵ֗שׁ וּ⁠לְ⁠שֹׁטֵ֤ט בְּ⁠צִדֵּי⁠כֶם֙ וְ⁠לִ⁠צְנִנִ֣ים בְּ⁠עֵינֵי⁠כֶ֔ם עַד־אֲבָדְ⁠כֶ֗ם מֵ֠⁠עַל הָ⁠אֲדָמָ֤ה הַ⁠טּוֹבָה֙ הַ⁠זֹּ֔את אֲשֶׁר֙ נָתַ֣ן לָ⁠כֶ֔ם יְהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","yád֨wòʻa֙ ţéֽ̇dĕʻ֔ẇ ki̇y֩ lò֨ʼ ywòsi֜yp yĕhwá֣h ʼèlòhéy⁠ke֗m lĕ⁠hwòri֛yş̌ ʼeţ-ha⁠ġwòyi֥m há⁠ʼé֖lėh mi⁠li̇⁠pĕnéy⁠ke֑m wĕ⁠háy֨ẇ lá⁠ke֜m lĕ⁠pa֣ẖ ẇ⁠lĕ⁠mwòqé֗ş̌ ẇ⁠lĕ⁠şò̌té֤t bĕ̇⁠ẕidé̇y⁠kem֙ wĕ⁠li⁠ẕĕnini֣ym bĕ̇⁠ʻéynéy⁠ke֔m ʻad-ʼàbádĕ⁠ke֗m mé֠⁠ʻal há⁠ʼàdámá֤h ha⁠ṫwòbáh֙ ha⁠zò̇֔ʼţ ʼàşěr֙ náţa֣n lá⁠ke֔m yĕhwá֖h ʼèlòhéy⁠keֽm׃"],[23,14,"וְ⁠הִנֵּ֨ה אָנֹכִ֤י הוֹלֵךְ֙ הַ⁠יּ֔וֹם בְּ⁠דֶ֖רֶךְ כָּל־הָ⁠אָ֑רֶץ וִ⁠ידַעְתֶּ֞ם בְּ⁠כָל־לְבַבְ⁠כֶ֣ם וּ⁠בְ⁠כָל־נַפְשְׁ⁠כֶ֗ם כִּ֣י לֹֽא־נָפַל֩ דָּבָ֨ר אֶחָ֜ד מִ⁠כֹּ֣ל ׀ הַ⁠דְּבָרִ֣ים הַ⁠טּוֹבִ֗ים אֲשֶׁ֨ר דִּבֶּ֜ר יְהוָ֤ה אֱלֹהֵי⁠כֶם֙ עֲלֵי⁠כֶ֔ם הַ⁠כֹּל֙ בָּ֣אוּ לָ⁠כֶ֔ם לֹֽא־נָפַ֥ל מִמֶּ֖⁠נּוּ דָּבָ֥ר אֶחָֽד׃","wĕ⁠hiné̇֨h ʼánòki֤y hwòlékĕ֙ ha⁠ẏ֔wòm bĕ̇⁠de֖rekĕ ká̇l-há⁠ʼá֑reẕ wi⁠ydaʻĕţė֞m bĕ̇⁠kál-lĕbabĕ⁠ke֣m ẇ⁠bĕ⁠kál-napĕşĕ̌⁠ke֗m ki֣̇y lòֽʼ-nápal֩ dá̇bá֨r ʼeẖá֜d mi⁠kò֣̇l ׀ ha⁠dĕ̇bári֣ym ha⁠ṫwòbi֗ym ʼàşě֨r di̇bė֜r yĕhwá֤h ʼèlòhéy⁠kem֙ ʻàléy⁠ke֔m ha⁠kò̇l֙ bá֣̇ʼẇ lá⁠ke֔m lòֽʼ-nápa֥l mimė֖⁠ṅẇ dá̇bá֥r ʼeẖáֽd׃"],[23,15,"וְ⁠הָיָ֗ה כַּ⁠אֲשֶׁר־בָּ֤א עֲלֵי⁠כֶם֙ כָּל־הַ⁠דָּבָ֣ר הַ⁠טּ֔וֹב אֲשֶׁ֥ר דִּבֶּ֛ר יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם אֲלֵי⁠כֶ֑ם כֵּן֩ יָבִ֨יא יְהוָ֜ה עֲלֵי⁠כֶ֗ם אֵ֚ת כָּל־הַ⁠דָּבָ֣ר הָ⁠רָ֔ע עַד־הַשְׁמִיד֣⁠וֹ אוֹתְ⁠כֶ֗ם מֵ֠⁠עַל הָ⁠אֲדָמָ֤ה הַ⁠טּוֹבָה֙ הַ⁠זֹּ֔את אֲשֶׁר֙ נָתַ֣ן לָ⁠כֶ֔ם יְהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠háyá֗h kȧ⁠ʼàşěr-bá֤̇ʼ ʻàléy⁠kem֙ ká̇l-ha⁠dá̇bá֣r ha⁠ṫ֔wòb ʼàşě֥r di̇bė֛r yĕhwá֥h ʼèlòhéy⁠ke֖m ʼàléy⁠ke֑m ké̇n֩ yábi֨yʼ yĕhwá֜h ʻàléy⁠ke֗m ʼé֚ţ ká̇l-ha⁠dá̇bá֣r há⁠rá֔ʻ ʻad-haşĕ̌miyd֣⁠wò ʼwòţĕ⁠ke֗m mé֠⁠ʻal há⁠ʼàdámá֤h ha⁠ṫwòbáh֙ ha⁠zò̇֔ʼţ ʼàşěr֙ náţa֣n lá⁠ke֔m yĕhwá֖h ʼèlòhéy⁠keֽm׃"],[23,16,"בְּ֠⁠עָבְרְ⁠כֶם אֶת־בְּרִ֨ית יְהוָ֥ה אֱלֹהֵי⁠כֶם֮ אֲשֶׁ֣ר צִוָּ֣ה אֶתְ⁠כֶם֒ וַ⁠הֲלַכְתֶּ֗ם וַ⁠עֲבַדְתֶּם֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וְ⁠הִשְׁתַּחֲוִיתֶ֖ם לָ⁠הֶ֑ם וְ⁠חָרָ֤ה אַף־יְהוָה֙ בָּ⁠כֶ֔ם וַ⁠אֲבַדְתֶּ֣ם מְהֵרָ֔ה מֵ⁠עַל֙ הָ⁠אָ֣רֶץ הַ⁠טּוֹבָ֔ה אֲשֶׁ֖ר נָתַ֥ן לָ⁠כֶֽם׃פ","bĕ̇֠⁠ʻábĕrĕ⁠kem ʼeţ-bĕ̇ri֨yţ yĕhwá֥h ʼèlòhéy⁠kem֮ ʼàşě֣r ẕiwá֣̇h ʼeţĕ⁠kem֒ wa⁠hàlakĕţė֗m wa⁠ʻàbadĕţėm֙ ʼèlòhi֣ym ʼàẖéri֔ym wĕ⁠hişĕ̌ţȧẖàwiyţe֖m lá⁠he֑m wĕ⁠ẖárá֤h ʼap-yĕhwáh֙ bá̇⁠ke֔m wa⁠ʼàbadĕţė֣m mĕhérá֔h mé⁠ʻal֙ há⁠ʼá֣reẕ ha⁠ṫwòbá֔h ʼàşě֖r náţa֥n lá⁠keֽm׃p"],[24,1,"וַ⁠יֶּאֶסֹ֧ף יְהוֹשֻׁ֛עַ אֶת־כָּל־שִׁבְטֵ֥י יִשְׂרָאֵ֖ל שְׁכֶ֑מָ⁠ה וַ⁠יִּקְרָא֩ לְ⁠זִקְנֵ֨י יִשְׂרָאֵ֜ל וּ⁠לְ⁠רָאשָׁ֗י⁠ו וּ⁠לְ⁠שֹֽׁפְטָי⁠ו֙ וּ⁠לְ⁠שֹׁ֣טְרָ֔י⁠ו וַ⁠יִּֽתְיַצְּב֖וּ לִ⁠פְנֵ֥י הָ⁠אֱלֹהִֽים׃","wa⁠yėʼesò֧p yĕhwòşǔ֛ʻa ʼeţ-ká̇l-şǐbĕté֥y yişĕ̂ráʼé֖l şĕ̌ke֑má⁠h wa⁠yi̇qĕráʼ֩ lĕ⁠ziqĕné֨y yişĕ̂ráʼé֜l ẇ⁠lĕ⁠ráʼşá̌֗y⁠w ẇ⁠lĕ⁠şòֽ̌pĕtáy⁠w֙ ẇ⁠lĕ⁠şò֣̌tĕrá֔y⁠w wa⁠yiֽ̇ţĕyaẕĕ̇b֖ẇ li⁠pĕné֥y há⁠ʼèlòhiֽym׃"],[24,2,"וַ⁠יֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֶל־כָּל־הָ⁠עָ֗ם כֹּֽה־אָמַ֣ר יְהוָה֮ אֱלֹהֵ֣י יִשְׂרָאֵל֒ בְּ⁠עֵ֣בֶר הַ⁠נָּהָ֗ר יָשְׁב֤וּ אֲבֽוֹתֵי⁠כֶם֙ מֵֽ⁠עוֹלָ֔ם תֶּ֛רַח אֲבִ֥י אַבְרָהָ֖ם וַ⁠אֲבִ֣י נָח֑וֹר וַ⁠יַּעַבְד֖וּ אֱלֹהִ֥ים אֲחֵרִֽים׃","wa⁠yò̇֨ʼmer yĕhwòşǔ֜ʻa ʼel-ká̇l-há⁠ʻá֗m kòֽ̇h-ʼáma֣r yĕhwáh֮ ʼèlòhé֣y yişĕ̂ráʼél֒ bĕ̇⁠ʻé֣ber ha⁠ná̇há֗r yáşĕ̌b֤ẇ ʼàbֽwòţéy⁠kem֙ méֽ⁠ʻwòlá֔m ţė֛raẖ ʼàbi֥y ʼabĕráhá֖m wa⁠ʼàbi֣y náẖ֑wòr wa⁠yȧʻabĕd֖ẇ ʼèlòhi֥ym ʼàẖériֽym׃"],[24,3,"וָ֠⁠אֶקַּח אֶת־אֲבִי⁠כֶ֤ם אֶת־אַבְרָהָם֙ מֵ⁠עֵ֣בֶר הַ⁠נָּהָ֔ר וָ⁠אוֹלֵ֥ךְ אוֹת֖⁠וֹ בְּ⁠כָל־אֶ֣רֶץ כְּנָ֑עַן ו⁠ארב אֶת־זַרְע֔⁠וֹ וָֽ⁠אֶתֶּן־ל֖⁠וֹ אֶת־יִצְחָֽק׃","wá֠⁠ʼeqȧẖ ʼeţ-ʼàbiy⁠ke֤m ʼeţ-ʼabĕráhám֙ mé⁠ʻé֣ber ha⁠ná̇há֔r wá⁠ʼwòlé֥kĕ ʼwòţ֖⁠wò bĕ̇⁠kál-ʼe֣reẕ kĕ̇ná֑ʻan w⁠ʼrb ʼeţ-zarĕʻ֔⁠wò wáֽ⁠ʼeţėn-l֖⁠wò ʼeţ-yiẕĕẖáֽq׃"],[24,4,"וָ⁠אֶתֵּ֣ן לְ⁠יִצְחָ֔ק אֶֽת־יַעֲקֹ֖ב וְ⁠אֶת־עֵשָׂ֑ו וָ⁠אֶתֵּ֨ן לְ⁠עֵשָׂ֜ו אֶת־הַ֤ר שֵׂעִיר֙ לָ⁠רֶ֣שֶׁת אוֹת֔⁠וֹ וְ⁠יַעֲקֹ֥ב וּ⁠בָנָ֖י⁠ו יָרְד֥וּ מִצְרָֽיִם׃","wá⁠ʼeţé֣̇n lĕ⁠yiẕĕẖá֔q ʼeֽţ-yaʻàqò֖b wĕ⁠ʼeţ-ʻéşá֑̂w wá⁠ʼeţé̇֨n lĕ⁠ʻéşá̂֜w ʼeţ-ha֤r şé̂ʻiyr֙ lá⁠re֣şěţ ʼwòţ֔⁠wò wĕ⁠yaʻàqò֥b ẇ⁠báná֖y⁠w yárĕd֥ẇ miẕĕráֽyim׃"],[24,5,"וָ⁠אֶשְׁלַ֞ח אֶת־מֹשֶׁ֤ה וְ⁠אֶֽת־אַהֲרֹן֙ וָ⁠אֶגֹּ֣ף אֶת־מִצְרַ֔יִם כַּ⁠אֲשֶׁ֥ר עָשִׂ֖יתִי בְּ⁠קִרְבּ֑⁠וֹ וְ⁠אַחַ֖ר הוֹצֵ֥אתִי אֶתְ⁠כֶֽם׃","wá⁠ʼeşĕ̌la֞ẖ ʼeţ-mòşě֤h wĕ⁠ʼeֽţ-ʼahàròn֙ wá⁠ʼegò֣̇p ʼeţ-miẕĕra֔yim kȧ⁠ʼàşě֥r ʻáşî֖yţiy bĕ̇⁠qirĕḃ֑⁠wò wĕ⁠ʼaẖa֖r hwòẕé֥ʼţiy ʼeţĕ⁠keֽm׃"],[24,6,"וָֽ⁠אוֹצִ֤יא אֶת־אֲבֽוֹתֵי⁠כֶם֙ מִ⁠מִּצְרַ֔יִם וַ⁠תָּבֹ֖אוּ הַ⁠יָּ֑מָּ⁠ה וַ⁠יִּרְדְּפ֨וּ מִצְרַ֜יִם אַחֲרֵ֧י אֲבוֹתֵי⁠כֶ֛ם בְּ⁠רֶ֥כֶב וּ⁠בְ⁠פָרָשִׁ֖ים יַם־סֽוּף׃","wáֽ⁠ʼwòẕi֤yʼ ʼeţ-ʼàbֽwòţéy⁠kem֙ mi⁠mi̇ẕĕra֔yim wa⁠ţá̇bò֖ʼẇ ha⁠yá֑̇má̇⁠h wa⁠yi̇rĕdĕ̇p֨ẇ miẕĕra֜yim ʼaẖàré֧y ʼàbwòţéy⁠ke֛m bĕ̇⁠re֥keb ẇ⁠bĕ⁠páráşǐ֖ym yam-sֽẇp׃"],[24,7,"וַ⁠יִּצְעֲק֣וּ אֶל־יְהוָ֗ה וַ⁠יָּ֨שֶׂם מַֽאֲפֵ֜ל בֵּינֵי⁠כֶ֣ם ׀ וּ⁠בֵ֣ין הַ⁠מִּצְרִ֗ים וַ⁠יָּבֵ֨א עָלָ֤י⁠ו אֶת־הַ⁠יָּם֙ וַ⁠יְכַסֵּ֔⁠הוּ וַ⁠תִּרְאֶ֨ינָה֙ עֵינֵי⁠כֶ֔ם אֵ֥ת אֲשֶׁר־עָשִׂ֖יתִי בְּ⁠מִצְרָ֑יִם וַ⁠תֵּשְׁב֥וּ בַ⁠מִּדְבָּ֖ר יָמִ֥ים רַבִּֽים׃","wa⁠yi̇ẕĕʻàq֣ẇ ʼel-yĕhwá֗h wa⁠yá̇֨şêm mֽaʼàpé֜l bé̇ynéy⁠ke֣m ׀ ẇ⁠bé֣yn ha⁠mi̇ẕĕri֗ym wa⁠yá̇bé֨ʼ ʻálá֤y⁠w ʼeţ-ha⁠yá̇m֙ wa⁠yĕkasé̇֔⁠hẇ wa⁠ţi̇rĕʼe֨ynáh֙ ʻéynéy⁠ke֔m ʼé֥ţ ʼàşěr-ʻáşî֖yţiy bĕ̇⁠miẕĕrá֑yim wa⁠ţé̇şĕ̌b֥ẇ ba⁠mi̇dĕbá֖̇r yámi֥ym rabiֽ̇ym׃"],[24,8,"ו⁠אבא⁠ה אֶתְ⁠כֶ֗ם אֶל־אֶ֤רֶץ הָ⁠אֱמֹרִי֙ הַ⁠יּוֹשֵׁב֙ בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֔ן וַ⁠יִּֽלָּחֲמ֖וּ אִתְּ⁠כֶ֑ם וָ⁠אֶתֵּ֨ן אוֹתָ֤⁠ם בְּ⁠יֶדְ⁠כֶם֙ וַ⁠תִּֽירְשׁ֣וּ אֶת־אַרְצָ֔⁠ם וָ⁠אַשְׁמִידֵ֖⁠ם מִ⁠פְּנֵי⁠כֶֽם׃","w⁠ʼbʼ⁠h ʼeţĕ⁠ke֗m ʼel-ʼe֤reẕ há⁠ʼèmòriy֙ ha⁠ẏwòşé̌b֙ bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé̇֔n wa⁠yiֽ̇lá̇ẖàm֖ẇ ʼiţĕ̇⁠ke֑m wá⁠ʼeţé̇֨n ʼwòţá֤⁠m bĕ̇⁠yedĕ⁠kem֙ wa⁠ţiֽ̇yrĕş֣̌ẇ ʼeţ-ʼarĕẕá֔⁠m wá⁠ʼaşĕ̌miydé֖⁠m mi⁠pĕ̇néy⁠keֽm׃"],[24,9,"וַ⁠יָּ֨קָם בָּלָ֤ק בֶּן־צִפּוֹר֙ מֶ֣לֶךְ מוֹאָ֔ב וַ⁠יִּלָּ֖חֶם בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יִּשְׁלַ֗ח וַ⁠יִּקְרָ֛א לְ⁠בִלְעָ֥ם בֶּן־בְּע֖וֹר לְ⁠קַלֵּ֥ל אֶתְ⁠כֶֽם׃","wa⁠yá̇֨qám bá̇lá֤q bėn-ẕiṗwòr֙ me֣lekĕ mwòʼá֔b wa⁠yi̇lá֖̇ẖem bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yi̇şĕ̌la֗ẖ wa⁠yi̇qĕrá֛ʼ lĕ⁠bilĕʻá֥m bėn-bĕ̇ʻ֖wòr lĕ⁠qalé֥̇l ʼeţĕ⁠keֽm׃"],[24,10,"וְ⁠לֹ֥א אָבִ֖יתִי לִ⁠שְׁמֹ֣עַ לְ⁠בִלְעָ֑ם וַ⁠יְבָ֤רֶךְ בָּרוֹךְ֙ אֶתְ⁠כֶ֔ם וָ⁠אַצִּ֥ל אֶתְ⁠כֶ֖ם מִ⁠יָּדֽ⁠וֹ׃","wĕ⁠lò֥ʼ ʼábi֖yţiy li⁠şĕ̌mò֣ʻa lĕ⁠bilĕʻá֑m wa⁠yĕbá֤rekĕ bá̇rwòkĕ֙ ʼeţĕ⁠ke֔m wá⁠ʼaẕi֥̇l ʼeţĕ⁠ke֖m mi⁠yá̇dֽ⁠wò׃"],[24,11,"וַ⁠תַּעַבְר֣וּ אֶת־הַ⁠יַּרְדֵּן֮ וַ⁠תָּבֹ֣אוּ אֶל־יְרִיחוֹ֒ וַ⁠יִּלָּחֲמ֣וּ בָ⁠כֶ֣ם בַּעֲלֵֽי־יְ֠רִיחוֹ הָֽ⁠אֱמֹרִ֨י וְ⁠הַ⁠פְּרִזִּ֜י וְ⁠הַֽ⁠כְּנַעֲנִ֗י וְ⁠הַֽ⁠חִתִּי֙ וְ⁠הַ⁠גִּרְגָּשִׁ֔י הַֽ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִ֑י וָ⁠אֶתֵּ֥ן אוֹתָ֖⁠ם בְּ⁠יֶדְ⁠כֶֽם׃","wa⁠ţȧʻabĕr֣ẇ ʼeţ-ha⁠yȧrĕdé̇n֮ wa⁠ţá̇bò֣ʼẇ ʼel-yĕriyẖwò֒ wa⁠yi̇lá̇ẖàm֣ẇ bá⁠ke֣m bȧʻàléֽy-yĕ֠riyẖwò háֽ⁠ʼèmòri֨y wĕ⁠ha⁠pĕ̇rizi̇֜y wĕ⁠haֽ⁠kĕ̇naʻàni֗y wĕ⁠hֽa⁠ẖiţi̇y֙ wĕ⁠ha⁠gi̇rĕgá̇şǐ֔y hֽa⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsi֑y wá⁠ʼeţé֥̇n ʼwòţá֖⁠m bĕ̇⁠yedĕ⁠keֽm׃"],[24,12,"וָ⁠אֶשְׁלַ֤ח לִ⁠פְנֵי⁠כֶם֙ אֶת־הַ⁠צִּרְעָ֔ה וַ⁠תְּגָ֤רֶשׁ אוֹתָ⁠ם֙ מִ⁠פְּנֵי⁠כֶ֔ם שְׁנֵ֖י מַלְכֵ֣י הָ⁠אֱמֹרִ֑י לֹ֥א בְ⁠חַרְבְּ⁠ךָ֖ וְ⁠לֹ֥א בְ⁠קַשְׁתֶּֽ⁠ךָ׃","wá⁠ʼeşĕ̌la֤ẖ li⁠pĕnéy⁠kem֙ ʼeţ-ha⁠ẕi̇rĕʻá֔h wa⁠ţĕ̇gá֤reş̌ ʼwòţá⁠m֙ mi⁠pĕ̇néy⁠ke֔m şĕ̌né֖y malĕké֣y há⁠ʼèmòri֑y lò֥ʼ bĕ⁠ẖarĕbĕ̇⁠ká֖ wĕ⁠lò֥ʼ bĕ⁠qaşĕ̌ţėֽ⁠ká׃"],[24,13,"וָ⁠אֶתֵּ֨ן לָ⁠כֶ֜ם אֶ֣רֶץ ׀ אֲשֶׁ֧ר לֹֽא־יָגַ֣עְתָּ בָּ֗⁠הּ וְ⁠עָרִים֙ אֲשֶׁ֣ר לֹא־בְנִיתֶ֔ם וַ⁠תֵּשְׁב֖וּ בָּ⁠הֶ֑ם כְּרָמִ֤ים וְ⁠זֵיתִים֙ אֲשֶׁ֣ר לֹֽא־נְטַעְתֶּ֔ם אַתֶּ֖ם אֹכְלִֽים׃","wá⁠ʼeţé̇֨n lá⁠ke֜m ʼe֣reẕ ׀ ʼàşě֧r lòֽʼ-yága֣ʻĕţá̇ bá̇֗⁠ḣ wĕ⁠ʻáriym֙ ʼàşě֣r lòʼ-bĕniyţe֔m wa⁠ţé̇şĕ̌b֖ẇ bá̇⁠he֑m kĕ̇rámi֤ym wĕ⁠zéyţiym֙ ʼàşě֣r lòֽʼ-nĕtaʻĕţė֔m ʼaţė֖m ʼòkĕliֽym׃"],[24,14,"וְ⁠עַתָּ֞ה יְר֧אוּ אֶת־יְהוָ֛ה וְ⁠עִבְד֥וּ אֹת֖⁠וֹ בְּ⁠תָמִ֣ים וּ⁠בֶֽ⁠אֱמֶ֑ת וְ⁠הָסִ֣ירוּ אֶת־אֱלֹהִ֗ים אֲשֶׁר֩ עָבְד֨וּ אֲבוֹתֵי⁠כֶ֜ם בְּ⁠עֵ֤בֶר הַ⁠נָּהָר֙ וּ⁠בְ⁠מִצְרַ֔יִם וְ⁠עִבְד֖וּ אֶת־יְהוָֽה׃","wĕ⁠ʻaţá̇֞h yĕr֧ʼẇ ʼeţ-yĕhwá֛h wĕ⁠ʻibĕd֥ẇ ʼòţ֖⁠wò bĕ̇⁠ţámi֣ym ẇ⁠beֽ⁠ʼème֑ţ wĕ⁠hási֣yrẇ ʼeţ-ʼèlòhi֗ym ʼàşěr֩ ʻábĕd֨ẇ ʼàbwòţéy⁠ke֜m bĕ̇⁠ʻé֤ber ha⁠ná̇hár֙ ẇ⁠bĕ⁠miẕĕra֔yim wĕ⁠ʻibĕd֖ẇ ʼeţ-yĕhwáֽh׃"],[24,15,"וְ⁠אִם֩ רַ֨ע בְּֽ⁠עֵינֵי⁠כֶ֜ם לַ⁠עֲבֹ֣ד אֶת־יְהוָ֗ה בַּחֲר֨וּ לָ⁠כֶ֣ם הַ⁠יּוֹם֮ אֶת־מִ֣י תַעֲבֹדוּ⁠ן֒ אִ֣ם אֶת־אֱלֹהִ֞ים אֲשֶׁר־עָבְד֣וּ אֲבוֹתֵי⁠כֶ֗ם אֲשֶׁר֙ ב⁠עבר הַ⁠נָּהָ֔ר וְ⁠אִם֙ אֶת־אֱלֹהֵ֣י הָ⁠אֱמֹרִ֔י אֲשֶׁ֥ר אַתֶּ֖ם יֹשְׁבִ֣ים בְּ⁠אַרְצָ֑⁠ם וְ⁠אָנֹכִ֣י וּ⁠בֵיתִ֔⁠י נַעֲבֹ֖ד אֶת־יְהוָֽה׃פ","wĕ⁠ʼim֩ ra֨ʻ bĕֽ̇⁠ʻéynéy⁠ke֜m la⁠ʻàbò֣d ʼeţ-yĕhwá֗h bȧẖàr֨ẇ lá⁠ke֣m ha⁠ẏwòm֮ ʼeţ-mi֣y ţaʻàbòdẇ⁠n֒ ʼi֣m ʼeţ-ʼèlòhi֞ym ʼàşěr-ʻábĕd֣ẇ ʼàbwòţéy⁠ke֗m ʼàşěr֙ b⁠ʻbr ha⁠ná̇há֔r wĕ⁠ʼim֙ ʼeţ-ʼèlòhé֣y há⁠ʼèmòri֔y ʼàşě֥r ʼaţė֖m yòşĕ̌bi֣ym bĕ̇⁠ʼarĕẕá֑⁠m wĕ⁠ʼánòki֣y ẇ⁠béyţi֔⁠y naʻàbò֖d ʼeţ-yĕhwáֽh׃p"],[24,16,"וַ⁠יַּ֤עַן הָ⁠עָם֙ וַ⁠יֹּ֔אמֶר חָלִ֣ילָ⁠ה לָּ֔⁠נוּ מֵ⁠עֲזֹ֖ב אֶת־יְהוָ֑ה לַ⁠עֲבֹ֖ד אֱלֹהִ֥ים אֲחֵרִֽים׃","wa⁠yȧ֤ʻan há⁠ʻám֙ wa⁠yò̇֔ʼmer ẖáli֣ylá⁠h lá̇֔⁠nẇ mé⁠ʻàzò֖b ʼeţ-yĕhwá֑h la⁠ʻàbò֖d ʼèlòhi֥ym ʼàẖériֽym׃"],[24,17,"כִּ֚י יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ הוּא֩ הַ⁠מַּעֲלֶ֨ה אֹתָ֧⁠נוּ וְ⁠אֶת־אֲבוֹתֵ֛י⁠נוּ מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם מִ⁠בֵּ֣ית עֲבָדִ֑ים וַ⁠אֲשֶׁ֧ר עָשָׂ֣ה לְ⁠עֵינֵ֗י⁠נוּ אֶת־הָ⁠אֹת֤וֹת הַ⁠גְּדֹלוֹת֙ הָ⁠אֵ֔לֶּה וַֽ⁠יִּשְׁמְרֵ֗⁠נוּ בְּ⁠כָל־הַ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר הָלַ֣כְנוּ בָ֔⁠הּ וּ⁠בְ⁠כֹל֙ הָֽ⁠עַמִּ֔ים אֲשֶׁ֥ר עָבַ֖רְנוּ בְּ⁠קִרְבָּֽ⁠ם׃","ki֚̇y yĕhwá֣h ʼèlòhé֔y⁠nẇ hẇʼ֩ ha⁠mȧʻàle֨h ʼòţá֧⁠nẇ wĕ⁠ʼeţ-ʼàbwòţé֛y⁠nẇ mé⁠ʼe֥reẕ miẕĕra֖yim mi⁠bé֣̇yţ ʻàbádi֑ym wa⁠ʼàşě֧r ʻáşá֣̂h lĕ⁠ʻéyné֗y⁠nẇ ʼeţ-há⁠ʼòţ֤wòţ ha⁠gĕ̇dòlwòţ֙ há⁠ʼé֔lėh waֽ⁠yi̇şĕ̌mĕré֗⁠nẇ bĕ̇⁠kál-ha⁠dė֨rekĕ֙ ʼàşě֣r hála֣kĕnẇ bá֔⁠ḣ ẇ⁠bĕ⁠kòl֙ háֽ⁠ʻami̇֔ym ʼàşě֥r ʻába֖rĕnẇ bĕ̇⁠qirĕbáֽ̇⁠m׃"],[24,18,"וַ⁠יְגָ֨רֶשׁ יְהוָ֜ה אֶת־כָּל־הָ⁠עַמִּ֗ים וְ⁠אֶת־הָ⁠אֱמֹרִ֛י יֹשֵׁ֥ב הָ⁠אָ֖רֶץ מִ⁠פָּנֵ֑י⁠נוּ גַּם־אֲנַ֨חְנוּ֙ נַעֲבֹ֣ד אֶת־יְהוָ֔ה כִּי־ה֖וּא אֱלֹהֵֽי⁠נוּ׃ס","wa⁠yĕgá֨reş̌ yĕhwá֜h ʼeţ-ká̇l-há⁠ʻami̇֗ym wĕ⁠ʼeţ-há⁠ʼèmòri֛y yòşé֥̌b há⁠ʼá֖reẕ mi⁠pá̇né֑y⁠nẇ gȧm-ʼàna֨ẖĕnẇ֙ naʻàbò֣d ʼeţ-yĕhwá֔h ki̇y-h֖ẇʼ ʼèlòhéֽy⁠nẇ׃s"],[24,19,"וַ⁠יֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֶל־הָ⁠עָ֗ם לֹ֤א תֽוּכְלוּ֙ לַ⁠עֲבֹ֣ד אֶת־יְהוָ֔ה כִּֽי־אֱלֹהִ֥ים קְדֹשִׁ֖ים ה֑וּא אֵֽל־קַנּ֣וֹא ה֔וּא לֹֽא־יִשָּׂ֥א לְ⁠פִשְׁעֲ⁠כֶ֖ם וּ⁠לְ⁠חַטֹּאותֵי⁠כֶֽם׃","wa⁠yò̇֨ʼmer yĕhwòşǔ֜ʻa ʼel-há⁠ʻá֗m lò֤ʼ ţֽẇkĕlẇ֙ la⁠ʻàbò֣d ʼeţ-yĕhwá֔h kiֽ̇y-ʼèlòhi֥ym qĕdòşǐ֖ym h֑ẇʼ ʼéֽl-qaṅ֣wòʼ h֔ẇʼ lòֽʼ-yişá֥̇̂ʼ lĕ⁠pişĕ̌ʻà⁠ke֖m ẇ⁠lĕ⁠ẖatò̇ʼwţéy⁠keֽm׃"],[24,20,"כִּ֤י תַֽעַזְבוּ֙ אֶת־יְהוָ֔ה וַ⁠עֲבַדְתֶּ֖ם אֱלֹהֵ֣י נֵכָ֑ר וְ⁠שָׁ֨ב וְ⁠הֵרַ֤ע לָ⁠כֶם֙ וְ⁠כִלָּ֣ה אֶתְ⁠כֶ֔ם אַחֲרֵ֖י אֲשֶׁר־הֵיטִ֥יב לָ⁠כֶֽם׃","ki֤̇y ţaֽʻazĕbẇ֙ ʼeţ-yĕhwá֔h wa⁠ʻàbadĕţė֖m ʼèlòhé֣y néká֑r wĕ⁠şá̌֨b wĕ⁠héra֤ʻ lá⁠kem֙ wĕ⁠kilá֣̇h ʼeţĕ⁠ke֔m ʼaẖàré֖y ʼàşěr-héyti֥yb lá⁠keֽm׃"],[24,21,"וַ⁠יֹּ֥אמֶר הָ⁠עָ֖ם אֶל־יְהוֹשֻׁ֑עַ לֹ֕א כִּ֥י אֶת־יְהוָ֖ה נַעֲבֹֽד׃","wa⁠yò֥̇ʼmer há⁠ʻá֖m ʼel-yĕhwòşǔ֑ʻa lò֕ʼ ki֥̇y ʼeţ-yĕhwá֖h naʻàbòֽd׃"],[24,22,"וַ⁠יֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֶל־הָ⁠עָ֗ם עֵדִ֤ים אַתֶּם֙ בָּ⁠כֶ֔ם כִּֽי־אַתֶּ֞ם בְּחַרְתֶּ֥ם לָ⁠כֶ֛ם אֶת־יְהוָ֖ה לַ⁠עֲבֹ֣ד אוֹת֑⁠וֹ וַ⁠יֹּאמְר֖וּ עֵדִֽים׃","wa⁠yò̇֨ʼmer yĕhwòşǔ֜ʻa ʼel-há⁠ʻá֗m ʻédi֤ym ʼaţėm֙ bá̇⁠ke֔m kiֽ̇y-ʼaţė֞m bĕ̇ẖarĕţė֥m lá⁠ke֛m ʼeţ-yĕhwá֖h la⁠ʻàbò֣d ʼwòţ֑⁠wò wa⁠yò̇ʼmĕr֖ẇ ʻédiֽym׃"],[24,23,"וְ⁠עַתָּ֕ה הָסִ֛ירוּ אֶת־אֱלֹהֵ֥י הַ⁠נֵּכָ֖ר אֲשֶׁ֣ר בְּ⁠קִרְבְּ⁠כֶ֑ם וְ⁠הַטּוּ֙ אֶת־לְבַבְ⁠כֶ֔ם אֶל־יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ʻaţá̇֕h hási֛yrẇ ʼeţ-ʼèlòhé֥y ha⁠né̇ká֖r ʼàşě֣r bĕ̇⁠qirĕbĕ̇⁠ke֑m wĕ⁠haṫẇ֙ ʼeţ-lĕbabĕ⁠ke֔m ʼel-yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[24,24,"וַ⁠יֹּאמְר֥וּ הָ⁠עָ֖ם אֶל־יְהוֹשֻׁ֑עַ אֶת־יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ נַעֲבֹ֔ד וּ⁠בְ⁠קוֹל֖⁠וֹ נִשְׁמָֽע׃","wa⁠yò̇ʼmĕr֥ẇ há⁠ʻá֖m ʼel-yĕhwòşǔ֑ʻa ʼeţ-yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ naʻàbò֔d ẇ⁠bĕ⁠qwòl֖⁠wò nişĕ̌máֽʻ׃"],[24,25,"וַ⁠יִּכְרֹ֨ת יְהוֹשֻׁ֧עַ בְּרִ֛ית לָ⁠עָ֖ם בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וַ⁠יָּ֥שֶׂם ל֛⁠וֹ חֹ֥ק וּ⁠מִשְׁפָּ֖ט בִּ⁠שְׁכֶֽם׃","wa⁠yi̇kĕrò֨ţ yĕhwòşǔ֧ʻa bĕ̇ri֛yţ lá⁠ʻá֖m bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ wa⁠yá֥̇şêm l֛⁠wò ẖò֥q ẇ⁠mişĕ̌pá֖̇t bi̇⁠şĕ̌keֽm׃"],[24,26,"וַ⁠יִּכְתֹּ֤ב יְהוֹשֻׁ֨עַ֙ אֶת־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה בְּ⁠סֵ֖פֶר תּוֹרַ֣ת אֱלֹהִ֑ים וַ⁠יִּקַּח֙ אֶ֣בֶן גְּדוֹלָ֔ה וַ⁠יְקִימֶ֣⁠הָ שָּׁ֔ם תַּ֚חַת הָֽ⁠אַלָּ֔ה אֲשֶׁ֖ר בְּ⁠מִקְדַּ֥שׁ יְהוָֽה׃ס","wa⁠yi̇kĕţò֤̇b yĕhwòşǔ֨ʻa֙ ʼeţ-ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh bĕ̇⁠sé֖per ţ̇wòra֣ţ ʼèlòhi֑ym wa⁠yi̇qȧẖ֙ ʼe֣ben gĕ̇dwòlá֔h wa⁠yĕqiyme֣⁠há şá̇̌֔m ţȧ֚ẖaţ háֽ⁠ʼalá̇֔h ʼàşě֖r bĕ̇⁠miqĕdȧ֥ş̌ yĕhwáֽh׃s"],[24,27,"וַ⁠יֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֶל־כָּל־הָ⁠עָ֗ם הִנֵּ֨ה הָ⁠אֶ֤בֶן הַ⁠זֹּאת֙ תִּֽהְיֶה־בָּ֣⁠נוּ לְ⁠עֵדָ֔ה כִּֽי־הִ֣יא שָׁמְעָ֗ה אֵ֚ת כָּל־אִמְרֵ֣י יְהוָ֔ה אֲשֶׁ֥ר דִּבֶּ֖ר עִמָּ֑⁠נוּ וְ⁠הָיְתָ֤ה בָ⁠כֶם֙ לְ⁠עֵדָ֔ה פֶּֽן־תְּכַחֲשׁ֖וּ⁠ן בֵּ⁠אלֹהֵי⁠כֶֽם׃","wa⁠yò̇֨ʼmer yĕhwòşǔ֜ʻa ʼel-ká̇l-há⁠ʻá֗m hiné̇֨h há⁠ʼe֤ben ha⁠zò̇ʼţ֙ ţiֽ̇hĕyeh-bá֣̇⁠nẇ lĕ⁠ʻédá֔h kiֽ̇y-hi֣yʼ şá̌mĕʻá֗h ʼé֚ţ ká̇l-ʼimĕré֣y yĕhwá֔h ʼàşě֥r di̇bė֖r ʻimá֑̇⁠nẇ wĕ⁠háyĕţá֤h bá⁠kem֙ lĕ⁠ʻédá֔h pėֽn-ţĕ̇kaẖàş֖̌ẇ⁠n bé̇⁠ʼlòhéy⁠keֽm׃"],[24,28,"וַ⁠יְשַׁלַּ֤ח יְהוֹשֻׁ֨עַ֙ אֶת־הָ⁠עָ֔ם אִ֖ישׁ לְ⁠נַחֲלָתֽ⁠וֹ׃פ","wa⁠yĕşǎlȧ֤ẖ yĕhwòşǔ֨ʻa֙ ʼeţ-há⁠ʻá֔m ʼi֖yş̌ lĕ⁠naẖàláţֽ⁠wò׃p"],[24,29,"וַ⁠יְהִ֗י אַֽחֲרֵי֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וַ⁠יָּ֛מָת יְהוֹשֻׁ֥עַ בִּן־נ֖וּן עֶ֣בֶד יְהוָ֑ה בֶּן־מֵאָ֥ה וָ⁠עֶ֖שֶׂר שָׁנִֽים׃","wa⁠yĕhi֗y ʼֽaẖàréy֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh wa⁠yá֛̇máţ yĕhwòşǔ֥ʻa bi̇n-n֖ẇn ʻe֣bed yĕhwá֑h bėn-méʼá֥h wá⁠ʻe֖şêr şá̌niֽym׃"],[24,30,"וַ⁠יִּקְבְּר֤וּ אֹת⁠וֹ֙ בִּ⁠גְב֣וּל נַחֲלָת֔⁠וֹ בְּ⁠תִמְנַת־סֶ֖רַח אֲשֶׁ֣ר בְּ⁠הַר־אֶפְרָ֑יִם מִ⁠צְּפ֖וֹן לְ⁠הַר־גָּֽעַשׁ׃","wa⁠yi̇qĕbĕ̇r֤ẇ ʼòţ⁠wò֙ bi̇⁠gĕb֣ẇl naẖàláţ֔⁠wò bĕ̇⁠ţimĕnaţ-se֖raẖ ʼàşě֣r bĕ̇⁠har-ʼepĕrá֑yim mi⁠ẕĕ̇p֖wòn lĕ⁠har-gáֽ̇ʻaş̌׃"],[24,31,"וַ⁠יַּעֲבֹ֤ד יִשְׂרָאֵל֙ אֶת־יְהוָ֔ה כֹּ֖ל יְמֵ֣י יְהוֹשֻׁ֑עַ וְ⁠כֹ֣ל ׀ יְמֵ֣י הַ⁠זְּקֵנִ֗ים אֲשֶׁ֨ר הֶאֱרִ֤יכוּ יָמִים֙ אַחֲרֵ֣י יְהוֹשֻׁ֔עַ וַ⁠אֲשֶׁ֣ר יָדְע֗וּ אֵ֚ת כָּל־מַעֲשֵׂ֣ה יְהוָ֔ה אֲשֶׁ֥ר עָשָׂ֖ה לְ⁠יִשְׂרָאֵֽל׃","wa⁠yȧʻàbò֤d yişĕ̂ráʼél֙ ʼeţ-yĕhwá֔h kò֖̇l yĕmé֣y yĕhwòşǔ֑ʻa wĕ⁠kò֣l ׀ yĕmé֣y ha⁠zĕ̇qéni֗ym ʼàşě֨r heʼèri֤ykẇ yámiym֙ ʼaẖàré֣y yĕhwòşǔ֔ʻa wa⁠ʼàşě֣r yádĕʻ֗ẇ ʼé֚ţ ká̇l-maʻàşé֣̂h yĕhwá֔h ʼàşě֥r ʻáşá֖̂h lĕ⁠yişĕ̂ráʼéֽl׃"],[24,32,"וְ⁠אֶת־עַצְמ֣וֹת י֠וֹסֵף אֲשֶׁר־הֶעֱל֨וּ בְנֵי־יִשְׂרָאֵ֥ל ׀ מִ⁠מִּצְרַיִם֮ קָבְר֣וּ בִ⁠שְׁכֶם֒ בְּ⁠חֶלְקַ֣ת הַ⁠שָּׂדֶ֗ה אֲשֶׁ֨ר קָנָ֧ה יַעֲקֹ֛ב מֵ⁠אֵ֛ת בְּנֵֽי־חֲמ֥וֹר אֲבִֽי־שְׁכֶ֖ם בְּ⁠מֵאָ֣ה קְשִׂיטָ֑ה וַ⁠יִּֽהְי֥וּ לִ⁠בְנֵֽי־יוֹסֵ֖ף לְ⁠נַחֲלָֽה׃","wĕ⁠ʼeţ-ʻaẕĕm֣wòţ y֠wòsép ʼàşěr-heʻèl֨ẇ bĕnéy-yişĕ̂ráʼé֥l ׀ mi⁠mi̇ẕĕrayim֮ qábĕr֣ẇ bi⁠şĕ̌kem֒ bĕ̇⁠ẖelĕqa֣ţ ha⁠şá̇̂de֗h ʼàşě֨r qáná֧h yaʻàqò֛b mé⁠ʼé֛ţ bĕ̇néֽy-ẖàm֥wòr ʼàbiֽy-şĕ̌ke֖m bĕ̇⁠méʼá֣h qĕşîytá֑h wa⁠yiֽ̇hĕy֥ẇ li⁠bĕnéֽy-ywòsé֖p lĕ⁠naẖàláֽh׃"],[24,33,"וְ⁠אֶלְעָזָ֥ר בֶּֽן־אַהֲרֹ֖ן מֵ֑ת וַ⁠יִּקְבְּר֣וּ אֹת֗⁠וֹ בְּ⁠גִבְעַת֙ פִּֽינְחָ֣ס בְּנ֔⁠וֹ אֲשֶׁ֥ר נִתַּן־ל֖⁠וֹ בְּ⁠הַ֥ר אֶפְרָֽיִם׃","wĕ⁠ʼelĕʻázá֥r bėֽn-ʼahàrò֖n mé֑ţ wa⁠yi̇qĕbĕ̇r֣ẇ ʼòţ֗⁠wò bĕ̇⁠gibĕʻaţ֙ piֽ̇ynĕẖá֣s bĕ̇n֔⁠wò ʼàşě֥r niţȧn-l֖⁠wò bĕ̇⁠ha֥r ʼepĕráֽyim׃"]]}};